#[derive(Debug, PartialEq, Eq)]
pub(crate) struct LambdaBodyEntry {
    pub(crate) span: Span,
    pub(crate) elaborator_executions: usize,
}

#[cfg(all(test, feature = "surface"))]
thread_local! {
    static LAMBDA_BODY_ENTRIES:
        std::cell::RefCell<Option<(String, Vec<LambdaBodyEntry>)>> =
        const { std::cell::RefCell::new(None) };
}

#[cfg(all(test, feature = "surface"))]
pub(crate) fn reset_lambda_body_entries(module_path: &str) {
    LAMBDA_BODY_ENTRIES.with(|entries| {
        *entries.borrow_mut() = Some((module_path.to_owned(), Vec::new()));
    });
}

#[cfg(all(test, feature = "surface"))]
pub(crate) fn take_lambda_body_entries() -> Vec<LambdaBodyEntry> {
    LAMBDA_BODY_ENTRIES.with(|entries| {
        entries
            .borrow_mut()
            .take()
            .map(|(_, entries)| entries)
            .unwrap_or_default()
    })
}

#[cfg(all(test, feature = "surface"))]
pub(crate) fn record_lambda_body_entry(span: Span, tcx: &TypeCtx<'_, '_, crate::ast::Lowered>) {
    LAMBDA_BODY_ENTRIES.with(|entries| {
        let mut entries = entries.borrow_mut();
        let Some((module_path, entries)) = entries.as_mut() else {
            return;
        };
        if *module_path != tcx.env.module_path {
            return;
        }
        entries.push(LambdaBodyEntry {
            span,
            elaborator_executions: tcx.env.memo.user_elaborator_template_executions(),
        });
    });
}

