#[cfg(feature = "surface")]
#[derive(Clone)]
enum OwnerBoundType {
    Plain(InternedType<crate::ast::Lowered>),
    Retained {
        owner: crate::ast::TypeGoalOwner,
        ty: ScopedType,
    },
    Diagnostic {
        solver: Box<Self>,
        written: InternedType<crate::ast::Lowered>,
    },
}

#[cfg(feature = "surface")]
impl OwnerBoundType {
    fn ty(&self) -> &InternedType<crate::ast::Lowered> {
        match self {
            Self::Plain(ty) => ty,
            Self::Retained { ty, .. } => ty.ty(),
            Self::Diagnostic { solver, .. } => solver.ty(),
        }
    }

    fn with_diagnostic(self, written: Option<InternedType<crate::ast::Lowered>>) -> Self {
        match written {
            Some(written) => Self::Diagnostic {
                solver: Box::new(self),
                written,
            },
            None => self,
        }
    }

    fn into_scoped(
        self,
        owner: crate::ast::TypeGoalOwner,
        store: &GoalStore,
        span: Span,
    ) -> Result<ScopedType, Error> {
        // Progress, publication, and returned values consume only the solver
        // type. A written view is meaningful only for one expected equation.
        self.into_scoped_parts(owner, store, span)
            .map(|(solver, _written)| solver)
    }

    fn into_expected_equation_operand(
        self,
        owner: crate::ast::TypeGoalOwner,
        store: &GoalStore,
        span: Span,
    ) -> Result<ExpectedEquationOperand, Error> {
        // This is the sole conversion that may carry written vocabulary into
        // the GoalStore, and the operand is consumed by that one equation.
        let (solver, written) = self.into_scoped_parts(owner, store, span)?;
        Ok(match written {
            Some(written) => ExpectedEquationOperand::with_written(solver, written),
            None => ExpectedEquationOperand::solver(solver),
        })
    }

    fn into_scoped_parts(
        self,
        owner: crate::ast::TypeGoalOwner,
        store: &GoalStore,
        span: Span,
    ) -> Result<(ScopedType, Option<InternedType<crate::ast::Lowered>>), Error> {
        match self {
            Self::Plain(ty) => store
                .scoped_type(owner, ty, span)
                .map(|solver| (solver, None)),
            Self::Retained {
                owner: destination,
                ty,
            } => store
                .use_retained_type_at(destination, owner, ty, span)
                .map(|solver| (solver, None)),
            Self::Diagnostic { solver, written } => {
                let (solver, nested) = solver.into_scoped_parts(owner, store, span)?;
                assert!(
                    nested.is_none(),
                    "an owner-bound type retained nested diagnostic wrappers"
                );
                Ok((solver, Some(written)))
            }
        }
    }
}

#[cfg(feature = "surface")]
enum OwnerBoundSynth {
    Value {
        ty: OwnerBoundType,
        inferred_type_arg_suffix: usize,
    },
    FunctionScheme {
        ty: OwnerBoundType,
        inferred_type_arg_suffix: usize,
    },
}

#[cfg(feature = "surface")]
impl OwnerBoundSynth {
    fn ty(&self) -> &OwnerBoundType {
        match self {
            Self::Value { ty, .. } | Self::FunctionScheme { ty, .. } => ty,
        }
    }

    fn into_synth(
        self,
        owner: crate::ast::TypeGoalOwner,
        store: &GoalStore,
        span: Span,
    ) -> Result<Synth<crate::ast::Lowered>, Error> {
        Ok(match self {
            Self::Value {
                ty,
                inferred_type_arg_suffix,
            } => Synth::value_interned(ty.into_scoped(owner, store, span)?.ty().clone())
                .with_inferred_type_arg_suffix(inferred_type_arg_suffix),
            Self::FunctionScheme {
                ty,
                inferred_type_arg_suffix,
            } => Synth::complete_scheme_interned(ty.into_scoped(owner, store, span)?.ty().clone())
                .with_inferred_type_arg_suffix(inferred_type_arg_suffix),
        })
    }
}

