#[cfg(feature = "surface")]
struct EquationSnapshot {
    found: InternedType<crate::ast::Lowered>,
    expected: InternedType<crate::ast::Lowered>,
}

#[cfg(feature = "surface")]
impl EquationSnapshot {
    fn zonked(
        store: &GoalStore,
        delta: &GoalDelta,
        found: ScopedType,
        expected: ScopedType,
        tcx: &TypeCtx<'_, '_, crate::ast::Lowered>,
    ) -> Result<Self, Error> {
        Ok(Self {
            found: store
                .zonk_for_progress(delta, found, tcx)?
                .into_interned_type(),
            expected: store
                .zonk_for_progress(delta, expected, tcx)?
                .into_interned_type(),
        })
    }

    fn differs_from(&self, other: &Self) -> bool {
        self.found.identity_is_canonical() != other.found.identity_is_canonical()
            || self.found.as_type() != other.found.as_type()
            || self.expected.identity_is_canonical() != other.expected.identity_is_canonical()
            || self.expected.as_type() != other.expected.as_type()
    }
}

