// large resumable states out of each heap-driver frame.
enum OrdinaryCallContinuation<'m> {
    Advancing(Box<AdvancingOrdinaryCall<'m>>),
    Selecting(Box<SelectingOrdinaryCall<'m>>),
    AdvancingLayer(AdvancingOrdinaryLayer<'m>),
    Successor(OrdinaryChildContinuation<'m>),
    AwaitingExpected(Box<CompletedPathUnitGoalCall<'m>>),
    AwaitingReturnedForall {
        completed: Box<CompletedPathUnitGoalCall<'m>>,
        split_after: usize,
    },
}

#[cfg(feature = "surface")]
impl OrdinaryCallContinuation<'_> {
    fn result_inferred_type_arg_suffix(&self) -> usize {
        match self {
            Self::Advancing(advancing) => advancing.result_inferred_type_arg_suffix,
            Self::Selecting(selecting) => selecting.result_inferred_type_arg_suffix,
            Self::AdvancingLayer(layer) => layer.advancing.result_inferred_type_arg_suffix,
            Self::Successor(successor) => successor.cursor.result_inferred_type_arg_suffix(),
            Self::AwaitingExpected(completed) | Self::AwaitingReturnedForall { completed, .. } => {
                completed.result_inferred_type_arg_suffix
            }
        }
    }

    fn open_goal_call(&self) -> Option<&OpenGoalCall<'_>> {
        let mut continuation = self;
        loop {
            match continuation {
                Self::Advancing(advancing) => return Some(&advancing.call),
                Self::Selecting(selecting) => return Some(&selecting.call),
                Self::AdvancingLayer(layer) => return Some(&layer.advancing.call),
                Self::Successor(successor) => match &successor.cursor.planned {
                    PlannedOrdinaryValue::Call(next) => continuation = next,
                    _ => return None,
                },
                Self::AwaitingExpected(completed)
                | Self::AwaitingReturnedForall { completed, .. } => {
                    return Some(&completed.call);
                }
            }
        }
    }

    fn user_elaborator_transcript(&self) -> Option<&UserElaboratorCallTranscript> {
        self.open_goal_call()?.user_elaborator_transcript.as_ref()
    }

    fn carries_action_parent_terminal_public_layer(&self) -> bool {
        let Some(call) = self.open_goal_call() else {
            return false;
        };
        call.user_elaborator_transcript
            .as_ref()
            .is_some_and(UserElaboratorCallTranscript::terminal_public_layer_in_flight)
            && !call.goal_occurrences.is_empty()
            && call
                .goal_occurrences
                .iter()
                .all(|occurrence| match occurrence {
                    None => true,
                    Some(occurrence) => matches!(
                        occurrence.ty().as_type(),
                        crate::ast::Type::Goal { goal, args, .. }
                            if args.is_empty() && goal.owner() != call.owner
                    ),
                })
    }
}

#[cfg(feature = "surface")]
impl OrdinaryValueCursor<'_> {
    fn result_inferred_type_arg_suffix(&self) -> usize {
        match &self.planned {
            PlannedOrdinaryValue::Call(call) => call.result_inferred_type_arg_suffix(),
            PlannedOrdinaryValue::UserElaborator(call) => match &call.state {
                PlannedUserElaboratorCallState::Advancing(call) => {
                    call.result_inferred_type_arg_suffix()
                }
                PlannedUserElaboratorCallState::Completed {
                    inferred_type_arg_suffix,
                    ..
                }
                | PlannedUserElaboratorCallState::Ready {
                    inferred_type_arg_suffix,
                    ..
                } => *inferred_type_arg_suffix,
                PlannedUserElaboratorCallState::Fills(_) => 0,
            },
            _ => 0,
        }
    }
}

