#[cfg(all(test, feature = "surface"))]
#[derive(Clone, Copy, Debug, Default)]
struct CompletionWork {
    created: usize,
    resumed: usize,
    live: usize,
    peak_live: usize,
    origin_visits: usize,
    visitor_calls: usize,
    visited_nodes: usize,
    // Initial storage plus observed growth rounds, not allocator calls: one
    // retained node may append several children between capacity samples.
    visitor_storage_growth_rounds: usize,
    peak_visitor_capacity: usize,
    driver_steps: usize,
    mode_advances: usize,
    final_retries: usize,
    rec_order_entry_forwards: usize,
    transport_refreshes: usize,
    generic_pending_entries: usize,
    rec_order_forward_checks: usize,
    rec_order_forward_gathers: usize,
    max_chain_contributing_edges: usize,
    source_records_created: usize,
    source_records_live: usize,
    source_records_peak: usize,
    producer_sweeps: usize,
}

#[cfg(all(test, feature = "surface"))]
thread_local! {
    static COMPLETION_WORK: std::cell::RefCell<CompletionWork> = std::cell::RefCell::new(CompletionWork::default());
}

#[cfg(all(test, feature = "surface"))]
fn record_completion_work(update: impl FnOnce(&mut CompletionWork)) {
    COMPLETION_WORK.with(|work| update(&mut work.borrow_mut()));
}

#[cfg(all(test, feature = "surface"))]
impl Drop for RetainedCompletionWait {
    fn drop(&mut self) {
        record_completion_work(|work| work.live -= 1);
    }
}

