#[cfg(feature = "surface")]
impl CompletedInFrame {
    fn scoped(&self) -> &ScopedType {
        match self {
            Self::Value(ty, _) | Self::FunctionScheme(ty, _) => ty,
            Self::UserElaboratorCall { output, .. } => output,
        }
    }

    fn inferred_type_arg_suffix(&self) -> usize {
        match self {
            Self::Value(_, suffix) | Self::FunctionScheme(_, suffix) => *suffix,
            Self::UserElaboratorCall {
                inferred_type_arg_suffix,
                ..
            } => *inferred_type_arg_suffix,
        }
    }
}

#[cfg(feature = "surface")]
/// One Lowered value premise and its owner-bound expected occurrence.
///
/// Keeping the source tree directly makes the family dispatch exhaustive over
/// `Expr<Lowered>` instead of copying phase-specific syntax into another enum.
struct OrdinaryValueCursor<'m> {
    source: &'m crate::ast::Expr<crate::ast::Lowered>,
    expected: Option<OwnerBoundType>,
    planned: PlannedOrdinaryValue<'m>,
}

#[cfg(feature = "surface")]
enum CompletionNode<'a, 'm> {
    Value(&'a OrdinaryValueCursor<'m>),
    Lambda(&'a PlannedOrdinaryLambda<'m>),
    Call(&'a OrdinaryCallContinuation<'m>),
}

#[cfg(feature = "surface")]
impl<'m> OrdinaryValueCursor<'m> {
    /// Walk retained derivations, not source expressions. Each origin keeps its
    /// own delta: a parent marker never summarizes another child's authority.
    fn visit_completion_waits(
        &self,
        mut visit: impl FnMut(
            super::goals::CompletionWait,
            &super::goals::GoalDelta,
        ) -> Result<bool, Error>,
    ) -> Result<bool, Error> {
        let mut nodes = vec![CompletionNode::Value(self)];
        #[cfg(test)]
        let mut capacity = nodes.capacity();
        #[cfg(test)]
        record_completion_work(|work| {
            work.visitor_calls += 1;
            work.visitor_storage_growth_rounds += 1;
            work.peak_visitor_capacity = work.peak_visitor_capacity.max(capacity);
        });
        while let Some(node) = nodes.pop() {
            #[cfg(test)]
            record_completion_work(|work| work.visited_nodes += 1);
            match node {
                CompletionNode::Lambda(lambda) => match &lambda.state {
                    OrdinaryLambdaState::Body { body, .. } => {
                        nodes.push(CompletionNode::Value(&body.cursor));
                    }
                    OrdinaryLambdaState::BodyComplete {
                        lambda_owners,
                        completion_wait: Some(wait),
                        ..
                    } => {
                        let origin = lambda_owners.owners.last().expect("retained lambda owner");
                        #[cfg(test)]
                        record_completion_work(|work| work.origin_visits += 1);
                        if visit(wait.0, origin.completion_delta())? {
                            return Ok(true);
                        }
                    }
                    OrdinaryLambdaState::BodyComplete {
                        completion_wait: None,
                        ..
                    }
                    | OrdinaryLambdaState::Unselected => {}
                },
                CompletionNode::Call(call) => {
                    let open = match call {
                        OrdinaryCallContinuation::Advancing(advancing)
                        | OrdinaryCallContinuation::AdvancingLayer(AdvancingOrdinaryLayer {
                            advancing,
                            ..
                        }) => {
                            for pending in &advancing.pending {
                                nodes.push(CompletionNode::Value(&pending.child.cursor));
                            }
                            Some(&advancing.call)
                        }
                        OrdinaryCallContinuation::Selecting(selecting) => {
                            if let Some(probe) = &selecting.probe {
                                nodes.push(CompletionNode::Value(&probe.child.cursor));
                            }
                            for selected in &selecting.selected {
                                if let OrdinaryCallValue::Retained(child) = &selected.value {
                                    nodes.push(CompletionNode::Value(&child.cursor));
                                }
                            }
                            Some(&selecting.call)
                        }
                        OrdinaryCallContinuation::Successor(child) => {
                            nodes.push(CompletionNode::Value(&child.cursor));
                            None
                        }
                        OrdinaryCallContinuation::AwaitingExpected(completed)
                        | OrdinaryCallContinuation::AwaitingReturnedForall { completed, .. } => {
                            Some(&completed.call)
                        }
                    };
                    if let Some(immediate) = open.and_then(|call| call.immediate_lambda.as_ref())
                        && let ImmediateLambdaBodyState::Advancing(lambda) = &immediate.body
                    {
                        nodes.push(CompletionNode::Lambda(lambda));
                    }
                }
                CompletionNode::Value(cursor) => match &cursor.planned {
                    PlannedOrdinaryValue::Lambda(lambda) => {
                        nodes.push(CompletionNode::Lambda(lambda))
                    }
                    PlannedOrdinaryValue::Call(call) => nodes.push(CompletionNode::Call(call)),
                    PlannedOrdinaryValue::UserElaborator(call) => match &call.state {
                        PlannedUserElaboratorCallState::Advancing(call) => {
                            nodes.push(CompletionNode::Call(call))
                        }
                        PlannedUserElaboratorCallState::Fills(state) => {
                            state.push_completion_nodes(&mut nodes)
                        }
                        PlannedUserElaboratorCallState::Completed { .. }
                        | PlannedUserElaboratorCallState::Ready { .. } => {}
                    },
                    PlannedOrdinaryValue::PendingRecOrderSource(child)
                    | PlannedOrdinaryValue::Let(LetContinuation::Prefix(child))
                    | PlannedOrdinaryValue::Let(LetContinuation::Body { body: child, .. })
                    | PlannedOrdinaryValue::Sequence(SequenceContinuation::Prefix(child))
                    | PlannedOrdinaryValue::Sequence(SequenceContinuation::Body(child))
                    | PlannedOrdinaryValue::ComputedCall(ComputedCallContinuation::Callee(child))
                    | PlannedOrdinaryValue::ComputedCall(ComputedCallContinuation::Application {
                        application: child,
                        ..
                    })
                    | PlannedOrdinaryValue::Field(FieldContinuation::Receiver(child))
                    | PlannedOrdinaryValue::Field(FieldContinuation::UpdateValues {
                        current: child,
                        ..
                    }) => nodes.push(CompletionNode::Value(&child.cursor)),
                    PlannedOrdinaryValue::RecOrder(continuation) => match continuation {
                        RecOrderContinuation::OrdinaryBypass(child)
                        | RecOrderContinuation::ExpectedBody(child)
                        | RecOrderContinuation::ExpectedValue { value: child, .. }
                        | RecOrderContinuation::SynthesizedValue(child)
                        | RecOrderContinuation::SynthesizedBody { body: child, .. } => {
                            nodes.push(CompletionNode::Value(&child.cursor))
                        }
                        RecOrderContinuation::FunctionShell(shell) => match shell.state.as_ref() {
                            Some(RecOrderFunctionShellState::Body(child))
                            | Some(RecOrderFunctionShellState::Value { value: child, .. }) => {
                                nodes.push(CompletionNode::Value(&child.cursor))
                            }
                            None => {}
                        },
                        RecOrderContinuation::Selected(_) => {}
                    },
                    PlannedOrdinaryValue::RecQuote(continuation) => {
                        let child = match continuation {
                            RecQuoteContinuation::Operand(child)
                            | RecQuoteContinuation::Value(child)
                            | RecQuoteContinuation::Callback(child) => child,
                        };
                        nodes.push(CompletionNode::Value(&child.cursor));
                    }
                    PlannedOrdinaryValue::Leaf(_)
                    | PlannedOrdinaryValue::PendingRecOrderPath
                    | PlannedOrdinaryValue::Literal
                    | PlannedOrdinaryValue::ConnectedCall { .. }
                    | PlannedOrdinaryValue::ComputedCall(
                        ComputedCallContinuation::PlannedLambda(_),
                    )
                    | PlannedOrdinaryValue::Recursive(_) => {}
                },
            }
            #[cfg(test)]
            if nodes.capacity() != capacity {
                capacity = nodes.capacity();
                record_completion_work(|work| {
                    work.visitor_storage_growth_rounds += 1;
                    work.peak_visitor_capacity = work.peak_visitor_capacity.max(capacity);
                });
            }
        }
        Ok(false)
    }

    fn completion_changed(&self, store: &GoalStore) -> Result<bool, Error> {
        self.visit_completion_waits(|wait, delta| {
            store.completion_wait_changed(wait, delta, self.source.span())
        })
    }

    fn has_completion_wait(&self) -> bool {
        self.visit_completion_waits(|_, _| Ok(true))
            .expect("infallible wait visit")
    }

    fn require_completion_outside(
        &self,
        boundary: crate::ast::TypeGoalOwner,
        store: &GoalStore,
    ) -> Result<(), Error> {
        self.visit_completion_waits(|wait, delta| {
            store.validate_completion_wait_origin(wait, delta, self.source.span())?;
            assert!(
                !store.completion_wait_changed(wait, delta, self.source.span())?,
                "a source barrier tested stale completion evidence"
            );
            if !store.completion_wait_outside_boundary(wait, boundary, self.source.span())? {
                return Err(store.completion_wait_error(wait, self.source.span()));
            }
            Ok(false)
        })?;
        Ok(())
    }
}

#[cfg(feature = "surface")]
impl<'m> OrdinaryValueCursor<'m> {
    fn retain_lambda_binders(
        sig: &'m crate::ast::Signature<crate::ast::Lowered>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Vec<super::RetainedTypeBinder<'m>> {
        let mark = tcx.save();
        let retained = sig
            .params
            .iter()
            .filter_map(|param| match param {
                crate::ast::SignatureParam::Type(param) => {
                    Some(tcx.push_retained_type_param(param))
                }
                crate::ast::SignatureParam::Value(_) => None,
            })
            .collect();
        tcx.restore(mark);
        retained
    }

    fn lambda_lexical_slices(
        sig: &crate::ast::Signature<crate::ast::Lowered>,
    ) -> Vec<LambdaLexicalSlice> {
        let mut slices = vec![LambdaLexicalSlice {
            binder_range: 0..0,
            value_range: 0..0,
            includes_return: false,
        }];
        let mut binder_end = 0usize;
        let mut value_end = 0usize;
        for group in sig.canonical_group_refs() {
            match group {
                crate::ast::SignatureGroupRef::Type(params) => {
                    let binder_start = binder_end;
                    binder_end += params.len();
                    slices.push(LambdaLexicalSlice {
                        binder_range: binder_start..binder_end,
                        value_range: value_end..value_end,
                        includes_return: false,
                    });
                }
                crate::ast::SignatureGroupRef::Value(params) => {
                    value_end += params.len();
                    slices
                        .last_mut()
                        .expect("a lambda signature has an ambient lexical slice")
                        .value_range
                        .end = value_end;
                }
            }
        }
        slices
            .last_mut()
            .expect("a lambda signature has an ambient lexical slice")
            .includes_return = true;
        assert_eq!(
            binder_end,
            sig.params
                .iter()
                .filter(|param| matches!(param, crate::ast::SignatureParam::Type(_)))
                .count()
        );
        assert_eq!(value_end, sig.value_param_count());
        slices
    }

    fn reserve_lambda_owner_chain(
        source_span: Span,
        sig: &'m crate::ast::Signature<crate::ast::Lowered>,
        header: &mut super::annotation_plan::LambdaHeaderPlan<'m>,
        retained_binders: &[super::RetainedTypeBinder<'m>],
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OpenLambdaOwnerChain<'m>, Error> {
        let slices = Self::lambda_lexical_slices(sig);
        header.require_admitted_in_source_order()?;

        // Every logical slice keeps one persistent exact scope prefix. Only
        // slices that own solver state, plus the ambient and body endpoints,
        // become physical GoalStore owners.
        let mut scope = frontier
            .store()
            .owner_scope_snapshot(frontier.owner(), source_span)?;
        let mut slice_scopes = Vec::with_capacity(slices.len());
        #[cfg(test)]
        let scope_work_before = super::persistent_exact::persistent_exact_work();
        for slice in &slices {
            scope = scope.with_retained_binders(&retained_binders[slice.binder_range.clone()]);
            slice_scopes.push(scope.clone());
        }
        #[cfg(test)]
        let scope_work_after = super::persistent_exact::persistent_exact_work();
        let physical_slices = slices
            .iter()
            .enumerate()
            .filter_map(|(index, slice)| {
                (index == 0
                    || index + 1 == slices.len()
                    || header.annotation_slice_needs_owner(
                        slice.value_range.clone(),
                        slice.includes_return,
                    ))
                .then_some(index)
            })
            .collect::<Vec<_>>();
        #[cfg(test)]
        record_lambda_owner_work(
            slices.len(),
            physical_slices.len(),
            retained_binders.len(),
            scope_work_after
                .0
                .checked_sub(scope_work_before.0)
                .expect("persistent scope work counter moved backwards"),
            scope_work_after
                .1
                .checked_sub(scope_work_before.1)
                .expect("persistent ancestry counter moved backwards"),
        );
        let mut owner_for_slice = Vec::with_capacity(slices.len());
        let mut physical_index = 0usize;
        for logical_index in 0..slices.len() {
            while physical_slices[physical_index] < logical_index {
                physical_index += 1;
            }
            owner_for_slice.push(physical_index);
        }

        let outer = &slices[0];
        let (reservation, ()) =
            frontier.reserve_lambda_lexical_child_with(&[], source_span, |store, owner| {
                header.reserve_annotation_slice(
                    outer.value_range.clone(),
                    outer.includes_return,
                    store,
                    owner,
                    &slice_scopes[0],
                    tcx,
                )
            })?;
        let mut owners = vec![frontier.open_ordinary_child(reservation)?];

        for (owner_index, &slice_index) in physical_slices.iter().enumerate().skip(1) {
            let preceding_slice = physical_slices[owner_index - 1];
            let logical_range = preceding_slice + 1..slice_index + 1;
            let binder_start = slices[logical_range.start].binder_range.start;
            let binder_end = slices[slice_index].binder_range.end;
            let binders = &retained_binders[binder_start..binder_end];
            let (reservation, ()) = {
                let parent = owners
                    .last_mut()
                    .expect("a lambda owner chain lost its parent");
                let mut parent_frontier = frontier.ordinary_child_frontier(parent);
                parent_frontier.reserve_ordinary_lexical_child_with(
                    binders,
                    source_span,
                    |store, owner| {
                        for logical_index in logical_range.clone() {
                            let slice = &slices[logical_index];
                            header.reserve_annotation_slice(
                                slice.value_range.clone(),
                                slice.includes_return,
                                store,
                                owner,
                                &slice_scopes[logical_index],
                                tcx,
                            )?;
                        }
                        Ok(())
                    },
                )?
            };
            let child = {
                let parent = owners
                    .last_mut()
                    .expect("a lambda owner chain lost its parent");
                let parent_frontier = frontier.ordinary_child_frontier(parent);
                parent_frontier.open_ordinary_child(reservation)?
            };
            owners.push(child);
        }
        assert_eq!(owners.len(), physical_slices.len());
        Ok(OpenLambdaOwnerChain {
            owners,
            slices,
            owner_for_slice,
            slice_scopes,
        })
    }

    fn retain_owner_bound_type_at_prefix(
        ty: OwnerBoundType,
        scope: &RigidScope,
        span: Span,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OwnerBoundType, Error> {
        let (solver, written) = match ty {
            OwnerBoundType::Diagnostic { solver, written } => (*solver, Some(written)),
            solver => (solver, None),
        };
        let solver = match solver {
            OwnerBoundType::Plain(ty) => {
                prepare_owner_bound_type_at_prefix(frontier, ty, span, Some(scope), tcx)?
            }
            retained @ OwnerBoundType::Retained { .. } => retained,
            OwnerBoundType::Diagnostic { .. } => {
                unreachable!("an owner-bound type retained nested diagnostic wrappers")
            }
        };
        let (store, owner, delta, _publication) = frontier.parts_mut();
        let scoped = match solver {
            OwnerBoundType::Plain(ty) => store.scoped_type_at_lexical_prefix(scope, ty),
            retained @ OwnerBoundType::Retained { .. } => {
                retained.into_scoped(owner, store, span)?
            }
            OwnerBoundType::Diagnostic { .. } => {
                unreachable!("an owner-bound type retained nested diagnostic wrappers")
            }
        };
        let scoped = store.zonk_for_progress(delta, scoped, tcx)?;
        Ok(OwnerBoundType::Retained { owner, ty: scoped }.with_diagnostic(written))
    }

    fn retain_lambda_value_types_at_prefixes(
        source_span: Span,
        retained_binders: &[super::RetainedTypeBinder<'m>],
        mut value_types: Vec<OwnerBoundType>,
        owners: &mut OpenLambdaOwnerChain<'m>,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<Vec<OwnerBoundType>, Error> {
        assert_eq!(
            value_types.len(),
            owners
                .slices
                .last()
                .map_or(0, |slice| slice.value_range.end),
            "a lambda owner chain received the wrong value-type count"
        );
        let mark = tcx.save();
        let prepared = (|| {
            for (slice_index, slice) in owners.slices.iter().enumerate() {
                for binder in &retained_binders[slice.binder_range.clone()] {
                    tcx.push_retained_type_binder(binder);
                }
                for value_index in slice.value_range.clone() {
                    let ty = value_types[value_index].clone();
                    let owner_index = owners.owner_for_slice[slice_index];
                    let scope = owners.slice_scopes[slice_index].clone();
                    let owner = owners
                        .owners
                        .get_mut(owner_index)
                        .expect("a lambda lexical slice lost its owner");
                    let mut owner_frontier = frontier.ordinary_child_frontier(owner);
                    value_types[value_index] = Self::retain_owner_bound_type_at_prefix(
                        ty,
                        &scope,
                        source_span,
                        &mut owner_frontier,
                        tcx,
                    )?;
                }
            }
            Ok::<(), Error>(())
        })();
        tcx.restore(mark);
        prepared?;
        Ok(value_types)
    }

    fn new(source: &'m crate::ast::Expr<crate::ast::Lowered>, expected: OwnerBoundType) -> Self {
        let planned = if matches!(
            source,
            crate::ast::Expr::StrLit { .. }
                | crate::ast::Expr::IntLit { .. }
                | crate::ast::Expr::FloatLit { .. }
                | crate::ast::Expr::BoolLit { .. }
        ) {
            PlannedOrdinaryValue::Literal
        } else {
            PlannedOrdinaryValue::Recursive(OrdinaryRecursiveFamily::ComputedCall)
        };
        Self {
            source,
            expected: Some(expected),
            planned,
        }
    }

    fn seed(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryValueSeed<'m>, Error> {
        Ok(match source {
            crate::ast::Expr::BlockCall { ext, .. } => match *ext {},
            crate::ast::Expr::Path { .. } if tcx.is_pending_rec_order_path(source) => {
                OrdinaryValueSeed::PendingRecOrderPath
            }
            crate::ast::Expr::Path { .. } | crate::ast::Expr::Unit { .. } => {
                OrdinaryValueSeed::Leaf(
                    PreparedOrdinaryValue::path_or_unit(source, tcx)?
                        .expect("Path/Unit planning must produce a prepared leaf"),
                )
            }
            crate::ast::Expr::StrLit { .. }
            | crate::ast::Expr::IntLit { .. }
            | crate::ast::Expr::FloatLit { .. }
            | crate::ast::Expr::BoolLit { .. } => OrdinaryValueSeed::Literal,
            crate::ast::Expr::Call {
                callee,
                args,
                meta: _,
                ..
            } => {
                if let crate::ast::Expr::FnExpr { sig, ret_ty, .. } = callee.as_ref() {
                    let mut header = super::annotation_plan::plan_lowered_lambda_header(
                        sig,
                        ret_ty.as_ref(),
                        tcx,
                    )?;
                    if header.requires_immediate_selection() {
                        return Ok(OrdinaryValueSeed::ImmediateLambdaCall {
                            callee,
                            args: call_arg_refs(args),
                            header,
                        });
                    }
                    header.promote_ambient_lexical(tcx);
                    return Ok(OrdinaryValueSeed::ComputedLambdaCall { header });
                }
                if let Some(selected) =
                    select_path_unit_call_chain(callee, args, source.site(), tcx)
                    && selected.layers.has_retained_type_only_goal()
                {
                    let SelectedPathUnitCallChain {
                        direct_callee,
                        layers,
                    } = selected;
                    let direct = PreparedDirectCallee::path(direct_callee, tcx)?
                        .expect("a connected Path/Unit chain has one direct path callee");
                    return Ok(OrdinaryValueSeed::ConnectedCall { direct, layers });
                }
                let Some(direct) = PreparedDirectCallee::path(callee, tcx)? else {
                    return Ok(OrdinaryValueSeed::Recursive(
                        OrdinaryRecursiveFamily::ComputedCall,
                    ));
                };
                let args = call_arg_refs(args);
                OrdinaryValueSeed::DirectSelecting {
                    direct,
                    args,
                    regular_ufcs: None,
                }
            }
            crate::ast::Expr::Ufcs {
                occurrence: _,
                receiver,
                callee_segments,
                callee_span,
                args,
                flavor,
                bang: None,
                meta,
                ext,
            } => {
                let direct =
                    PreparedDirectCallee::path_segments(callee_segments, *callee_span, tcx)?;
                let args = call_arg_refs(args);
                let effective_args = effective_rec_order_args(&args, tcx);
                let selection_args = effective_args.as_deref().unwrap_or(&args);
                let spliced = splice_ufcs_arg_refs_interned(
                    &direct.synth.ty,
                    receiver,
                    &args,
                    selection_args,
                    *flavor,
                    meta.span,
                    &tcx.env.alias_ctx(),
                )?;
                let normalized = crate::ast::Expr::synth_call(
                    crate::ast::Expr::Path {
                        occurrence: crate::ast::ExpressionOccurrence::fresh(),
                        segments: callee_segments.to_vec(),
                        meta: crate::ast::Meta::new(*callee_span),
                        ext: (),
                    },
                    spliced
                        .iter()
                        .copied()
                        .map(owned_call_arg_from_ref)
                        .collect(),
                    meta.span,
                )
                .with_fresh_occurrence();
                OrdinaryValueSeed::DirectSelecting {
                    direct,
                    args: spliced,
                    regular_ufcs: Some((*ext, normalized)),
                }
            }
            crate::ast::Expr::FnExpr { sig, ret_ty, .. } => {
                let mut header =
                    super::annotation_plan::plan_lowered_lambda_header(sig, ret_ty.as_ref(), tcx)?;
                header.promote_ambient_lexical(tcx);
                OrdinaryValueSeed::Lambda(OrdinaryLambdaSeed { header })
            }
            crate::ast::Expr::Let { .. } => {
                OrdinaryValueSeed::Recursive(OrdinaryRecursiveFamily::Let)
            }
            crate::ast::Expr::Seq { .. } => {
                OrdinaryValueSeed::Recursive(OrdinaryRecursiveFamily::Sequence)
            }
            crate::ast::Expr::Elaborator { .. } => {
                OrdinaryValueSeed::Recursive(OrdinaryRecursiveFamily::Field)
            }
            crate::ast::Expr::RecOrder { .. } => {
                OrdinaryValueSeed::Recursive(OrdinaryRecursiveFamily::RecOrder)
            }
            crate::ast::Expr::RecQuote { plan, .. } => {
                if let crate::ast::RecQuotePlan::Expansion { value, .. } = plan.as_ref() {
                    tcx.elaborations.register_rec_quote_sources(value);
                }
                OrdinaryValueSeed::Recursive(OrdinaryRecursiveFamily::RecQuote)
            }
            crate::ast::Expr::UserElaborator { .. }
            | crate::ast::Expr::Ufcs { bang: Some(_), .. } => OrdinaryValueSeed::UserElaborator(
                crate::pass::typecheck_full::prepare_user_elaborator_action(source, tcx)?,
            ),
            crate::ast::Expr::RecCall { ext, .. }
            | crate::ast::Expr::RowLet { ext, .. }
            | crate::ast::Expr::Tuple { ext, .. }
            | crate::ast::Expr::FnPlaceholder { ext, .. }
            | crate::ast::Expr::LabelValue { ext, .. }
            | crate::ast::Expr::OpChain { ext, .. }
            | crate::ast::Expr::EnrichedTuple { ext, .. }
            | crate::ast::Expr::EnrichedProject { ext, .. }
            | crate::ast::Expr::EnrichedInject { ext, .. }
            | crate::ast::Expr::EnrichedMatch { ext, .. }
            | crate::ast::Expr::EnrichedConditional { ext, .. }
            | crate::ast::Expr::EnrichedRecord { ext, .. }
            | crate::ast::Expr::EnrichedFieldGet { ext, .. }
            | crate::ast::Expr::LowHostCall { ext, .. }
            | crate::ast::Expr::LowModuleCall { ext, .. }
            | crate::ast::Expr::LowQualifiedModuleCall { ext, .. }
            | crate::ast::Expr::LowQualifiedNewtypeMember { ext, .. }
            | crate::ast::Expr::LowNewtypeCtor { ext, .. }
            | crate::ast::Expr::LowNewtypeProj { ext, .. }
            | crate::ast::Expr::LowClosureCall { ext, .. }
            | crate::ast::Expr::LowIndirectCall { ext, .. }
            | crate::ast::Expr::LowTypeApplication { ext, .. }
            | crate::ast::Expr::LowAbsurdCall { ext, .. }
            | crate::ast::Expr::LowCpsProjectorApply { ext, .. }
            | crate::ast::Expr::LowBoundRef { ext, .. }
            | crate::ast::Expr::LowHostFnValueRef { ext, .. }
            | crate::ast::Expr::LowModuleFnValueRef { ext, .. } => match *ext {},
        })
    }

    fn plan(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        seed: OrdinaryValueSeed<'m>,
        store: &mut GoalStore,
        owner: crate::ast::TypeGoalOwner,
        tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<PlannedOrdinaryValue<'m>, Error> {
        Ok(match seed {
            OrdinaryValueSeed::Leaf(prepared) => PlannedOrdinaryValue::Leaf(PlannedOrdinaryLeaf {
                prepared,
                equation_progress: EquationProgress::Initial,
            }),
            OrdinaryValueSeed::PendingRecOrderPath => PlannedOrdinaryValue::PendingRecOrderPath,
            OrdinaryValueSeed::Literal => PlannedOrdinaryValue::Literal,
            OrdinaryValueSeed::ConnectedCall { .. } => {
                unreachable!("connected calls are selected while reserving their real owner")
            }
            OrdinaryValueSeed::Lambda(OrdinaryLambdaSeed { header }) => {
                PlannedOrdinaryValue::Lambda(PlannedOrdinaryLambda {
                    header,
                    retained_binders: Vec::new(),
                    state: OrdinaryLambdaState::Unselected,
                })
            }
            OrdinaryValueSeed::DirectSelecting {
                direct,
                args,
                regular_ufcs,
            } => {
                let call_site = regular_ufcs
                    .as_ref()
                    .map_or_else(|| source.site(), |(_, call)| call.site());
                let mut selecting = open_selecting_goal_call(
                    &direct.synth,
                    args,
                    None,
                    regular_ufcs,
                    0,
                    direct.span,
                    call_site,
                    EmptyCallMode::ImplicitUnit,
                    None,
                    store,
                    owner,
                    tcx,
                )?;
                selecting.direct = Some(direct);
                PlannedOrdinaryValue::Call(OrdinaryCallContinuation::Selecting(Box::new(selecting)))
            }
            OrdinaryValueSeed::ImmediateLambdaCall {
                callee,
                args,
                header,
            } => match plan_immediate_lambda_call(
                callee,
                args,
                header,
                source.site(),
                store,
                owner,
                tcx,
            )? {
                ImmediateLambdaPlanOutcome::Selected(selecting) => {
                    PlannedOrdinaryValue::Call(OrdinaryCallContinuation::Selecting(selecting))
                }
                ImmediateLambdaPlanOutcome::Declined(header) => PlannedOrdinaryValue::ComputedCall(
                    ComputedCallContinuation::PlannedLambda(header),
                ),
            },
            OrdinaryValueSeed::ComputedLambdaCall { header } => {
                PlannedOrdinaryValue::ComputedCall(ComputedCallContinuation::PlannedLambda(header))
            }
            OrdinaryValueSeed::UserElaborator(action) => {
                let span = action.span();
                let callee = Synth::complete_scheme_interned(action.call_ty().clone());
                let args = action.args().to_vec();
                let terminal_type_layer =
                    action.terminal_type_only_layer().map(|(ordinal, params)| {
                        UserElaboratorTerminalTypeLayerCapability {
                            action: action.node_id(),
                            source_span: span,
                            ordinal,
                            params: params.to_vec(),
                        }
                    });
                let transcript = Some(UserElaboratorCallTranscript {
                    action: action.node_id(),
                    source_span: span,
                    layers: Vec::new(),
                    next_source_index: 0,
                    terminal_type_layer,
                });
                let selecting = open_selecting_goal_call(
                    &callee,
                    args,
                    None,
                    None,
                    0,
                    span,
                    source.site(),
                    EmptyCallMode::ImplicitUnit,
                    transcript,
                    store,
                    owner,
                    tcx,
                )?;
                let call = OrdinaryCallContinuation::Selecting(Box::new(selecting));
                if action.schedule() == crate::ast::ElaboratorSchedule::Fills {
                    return Ok(PlannedOrdinaryValue::UserElaborator(
                        PlannedUserElaboratorCall {
                            action: None,
                            state: PlannedUserElaboratorCallState::Fills(Box::new(
                                fills::MarkedCallState::project(action, call),
                            )),
                        },
                    ));
                }
                PlannedOrdinaryValue::UserElaborator(PlannedUserElaboratorCall {
                    action: Some(action),
                    state: PlannedUserElaboratorCallState::Advancing(call),
                })
            }
            OrdinaryValueSeed::DeferredRecOrder(resolution) => {
                PlannedOrdinaryValue::RecOrder(RecOrderContinuation::Selected(resolution))
            }
            OrdinaryValueSeed::Recursive(family) => PlannedOrdinaryValue::Recursive(family),
        })
    }

    fn bind(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: OwnerBoundType,
        planned: PlannedOrdinaryValue<'m>,
    ) -> Self {
        Self {
            source,
            expected: Some(expected),
            planned,
        }
    }

    fn bind_synth(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        planned: PlannedOrdinaryValue<'m>,
    ) -> Self {
        Self {
            source,
            expected: None,
            planned,
        }
    }

    fn carries_action_parent_terminal_public_layer(&self) -> bool {
        matches!(
            &self.planned,
            PlannedOrdinaryValue::Call(call)
                if call.carries_action_parent_terminal_public_layer()
        )
    }

    /// Whether standalone synthesis has consumed everything it can and the
    /// cursor is now waiting only for its enclosing value slot.  Width
    /// selection for a flat call uses this boundary to classify the source as
    /// one expectation-dependent argument without abandoning or replaying the
    /// already-open retained premise.
    fn awaits_expected(&self) -> bool {
        let mut cursor = self;
        loop {
            if cursor.expected.is_some() {
                return false;
            }
            match &cursor.planned {
                PlannedOrdinaryValue::UserElaborator(PlannedUserElaboratorCall {
                    state: PlannedUserElaboratorCallState::Fills(state),
                    ..
                }) => return state.awaits_expected(),
                PlannedOrdinaryValue::PendingRecOrderPath
                | PlannedOrdinaryValue::Literal
                | PlannedOrdinaryValue::Lambda(PlannedOrdinaryLambda {
                    state: OrdinaryLambdaState::Unselected,
                    ..
                })
                | PlannedOrdinaryValue::Call(
                    OrdinaryCallContinuation::AwaitingExpected(_)
                    | OrdinaryCallContinuation::AwaitingReturnedForall { .. },
                )
                | PlannedOrdinaryValue::UserElaborator(PlannedUserElaboratorCall {
                    state:
                        PlannedUserElaboratorCallState::Completed {
                            expected_application: UserElaboratorExpectedApplication::Absent,
                            ..
                        },
                    ..
                })
                | PlannedOrdinaryValue::UserElaborator(PlannedUserElaboratorCall {
                    state:
                        PlannedUserElaboratorCallState::Advancing(
                            OrdinaryCallContinuation::AwaitingExpected(_)
                            | OrdinaryCallContinuation::AwaitingReturnedForall { .. },
                        ),
                    ..
                }) => return true,
                PlannedOrdinaryValue::Lambda(PlannedOrdinaryLambda {
                    state:
                        OrdinaryLambdaState::Body {
                            body,
                            selection:
                                OrdinaryLambdaSelection::Synthesizing {
                                    annotated_return: None,
                                },
                            ..
                        },
                    ..
                })
                | PlannedOrdinaryValue::Let(LetContinuation::Body { body, .. })
                | PlannedOrdinaryValue::Sequence(SequenceContinuation::Body(body)) => {
                    cursor = body.cursor.as_ref();
                }
                PlannedOrdinaryValue::Call(OrdinaryCallContinuation::Successor(child))
                | PlannedOrdinaryValue::UserElaborator(PlannedUserElaboratorCall {
                    state:
                        PlannedUserElaboratorCallState::Advancing(OrdinaryCallContinuation::Successor(
                            child,
                        )),
                    ..
                })
                | PlannedOrdinaryValue::ComputedCall(ComputedCallContinuation::Application {
                    application: child,
                    ..
                }) => cursor = child.cursor.as_ref(),
                PlannedOrdinaryValue::Leaf(_)
                | PlannedOrdinaryValue::PendingRecOrderSource(_)
                | PlannedOrdinaryValue::ConnectedCall { .. }
                | PlannedOrdinaryValue::Lambda(_)
                | PlannedOrdinaryValue::Call(_)
                | PlannedOrdinaryValue::Let(_)
                | PlannedOrdinaryValue::Sequence(_)
                | PlannedOrdinaryValue::Field(_)
                | PlannedOrdinaryValue::ComputedCall(_)
                | PlannedOrdinaryValue::UserElaborator(_)
                | PlannedOrdinaryValue::RecOrder(_)
                | PlannedOrdinaryValue::RecQuote(_)
                | PlannedOrdinaryValue::Recursive(_) => return false,
            }
        }
    }

    /// Whether this source is already known to occupy exactly one value slot
    /// and therefore needs that slot before its first retained child step.
    fn needs_selected_width_one_expectation(&self) -> bool {
        match &self.planned {
            PlannedOrdinaryValue::PendingRecOrderPath => self.expected.is_none(),
            PlannedOrdinaryValue::Leaf(leaf) => leaf.prepared.synth.is_scheme,
            PlannedOrdinaryValue::Lambda(PlannedOrdinaryLambda {
                state: OrdinaryLambdaState::Unselected,
                ..
            })
            | PlannedOrdinaryValue::Lambda(PlannedOrdinaryLambda {
                state:
                    OrdinaryLambdaState::Body {
                        selection: OrdinaryLambdaSelection::Synthesizing { .. },
                        ..
                    },
                ..
            }) => self.expected.is_none(),
            PlannedOrdinaryValue::Literal
            | PlannedOrdinaryValue::PendingRecOrderSource(_)
            | PlannedOrdinaryValue::ConnectedCall { .. }
            | PlannedOrdinaryValue::Call(_)
            | PlannedOrdinaryValue::Lambda(_)
            | PlannedOrdinaryValue::Let(_)
            | PlannedOrdinaryValue::Sequence(_)
            | PlannedOrdinaryValue::Field(_)
            | PlannedOrdinaryValue::ComputedCall(_)
            | PlannedOrdinaryValue::UserElaborator(_)
            | PlannedOrdinaryValue::RecOrder(_)
            | PlannedOrdinaryValue::RecQuote(_)
            | PlannedOrdinaryValue::Recursive(_) => false,
        }
    }

    /// Attach the enclosing slot once to a cursor that reached
    /// [`Self::awaits_expected`].  Any already-created tail/application child
    /// receives the same occurrence; earlier children stay closed and are not
    /// replayed.
    fn supply_expected(&mut self, expected: OwnerBoundType) {
        assert!(
            self.awaits_expected(),
            "an expected type was supplied before standalone synthesis reached its boundary"
        );
        let mut cursor = self;
        loop {
            assert!(
                cursor.expected.is_none(),
                "an expected type was attached twice along one continuation chain"
            );
            cursor.expected = Some(expected.clone());
            match &mut cursor.planned {
                PlannedOrdinaryValue::UserElaborator(PlannedUserElaboratorCall {
                    state: PlannedUserElaboratorCallState::Fills(state),
                    ..
                }) => {
                    state.supply_expected();
                    return;
                }
                PlannedOrdinaryValue::Let(LetContinuation::Body { body, .. })
                | PlannedOrdinaryValue::Sequence(SequenceContinuation::Body(body)) => {
                    cursor = body.cursor.as_mut();
                }
                PlannedOrdinaryValue::ComputedCall(ComputedCallContinuation::Application {
                    application: child,
                    ..
                })
                | PlannedOrdinaryValue::Call(OrdinaryCallContinuation::Successor(child))
                | PlannedOrdinaryValue::UserElaborator(PlannedUserElaboratorCall {
                    state:
                        PlannedUserElaboratorCallState::Advancing(OrdinaryCallContinuation::Successor(
                            child,
                        )),
                    ..
                }) => cursor = child.cursor.as_mut(),
                PlannedOrdinaryValue::UserElaborator(PlannedUserElaboratorCall {
                    state:
                        PlannedUserElaboratorCallState::Completed {
                            expected_application,
                            ..
                        },
                    ..
                }) => {
                    assert_eq!(
                        *expected_application,
                        UserElaboratorExpectedApplication::Absent,
                        "a completed elaborator call accepted a second expectation"
                    );
                    *expected_application = UserElaboratorExpectedApplication::Deferred;
                    return;
                }
                PlannedOrdinaryValue::PendingRecOrderPath
                | PlannedOrdinaryValue::Literal
                | PlannedOrdinaryValue::Lambda(PlannedOrdinaryLambda {
                    state: OrdinaryLambdaState::Unselected,
                    ..
                })
                | PlannedOrdinaryValue::Lambda(PlannedOrdinaryLambda {
                    state:
                        OrdinaryLambdaState::Body {
                            selection:
                                OrdinaryLambdaSelection::Synthesizing {
                                    annotated_return: None,
                                },
                            ..
                        },
                    ..
                })
                | PlannedOrdinaryValue::Call(
                    OrdinaryCallContinuation::AwaitingExpected(_)
                    | OrdinaryCallContinuation::AwaitingReturnedForall { .. },
                )
                | PlannedOrdinaryValue::UserElaborator(PlannedUserElaboratorCall {
                    state:
                        PlannedUserElaboratorCallState::Advancing(
                            OrdinaryCallContinuation::AwaitingExpected(_)
                            | OrdinaryCallContinuation::AwaitingReturnedForall { .. },
                        ),
                    ..
                }) => return,
                PlannedOrdinaryValue::Leaf(_)
                | PlannedOrdinaryValue::PendingRecOrderSource(_)
                | PlannedOrdinaryValue::ConnectedCall { .. }
                | PlannedOrdinaryValue::Lambda(_)
                | PlannedOrdinaryValue::Call(_)
                | PlannedOrdinaryValue::Let(_)
                | PlannedOrdinaryValue::Sequence(_)
                | PlannedOrdinaryValue::Field(_)
                | PlannedOrdinaryValue::ComputedCall(_)
                | PlannedOrdinaryValue::UserElaborator(_)
                | PlannedOrdinaryValue::RecOrder(_)
                | PlannedOrdinaryValue::RecQuote(_)
                | PlannedOrdinaryValue::Recursive(_) => {
                    unreachable!("the awaiting-expected classifier and consumer diverged")
                }
            }
        }
    }

    fn advance_nonrecursive(
        self,
        mode: frontier::FrontierMode,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryValueAdvance<'m>, Error> {
        let Self {
            source,
            expected,
            planned,
        } = self;
        match planned {
            PlannedOrdinaryValue::Leaf(leaf) => {
                Self::advance_planned_leaf(source, expected, leaf, mode, frontier, tcx)
            }
            PlannedOrdinaryValue::Literal => Self {
                source,
                expected,
                planned: PlannedOrdinaryValue::Literal,
            }
            .advance_literal(mode, frontier, tcx),
            PlannedOrdinaryValue::ConnectedCall {
                direct,
                layers,
                chain,
            } => {
                Self::advance_connected_call(source, expected, direct, layers, chain, frontier, tcx)
            }
            PlannedOrdinaryValue::PendingRecOrderPath
            | PlannedOrdinaryValue::PendingRecOrderSource(_)
            | PlannedOrdinaryValue::Call(_)
            | PlannedOrdinaryValue::Lambda(_)
            | PlannedOrdinaryValue::Let(_)
            | PlannedOrdinaryValue::Sequence(_)
            | PlannedOrdinaryValue::Field(_)
            | PlannedOrdinaryValue::ComputedCall(_)
            | PlannedOrdinaryValue::UserElaborator(_)
            | PlannedOrdinaryValue::RecOrder(_)
            | PlannedOrdinaryValue::RecQuote(_)
            | PlannedOrdinaryValue::Recursive(_) => {
                unreachable!("a recursive ordinary family bypassed the heap driver")
            }
        }
    }

    fn advance_step(
        self,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
        frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryDriverStep<'m>, Error> {
        #[cfg(test)]
        record_completion_work(|work| work.driver_steps += 1);
        let Self {
            source,
            expected,
            planned,
        } = self;
        match planned {
            PlannedOrdinaryValue::Call(continuation) => {
                Self::advance_call_step(source, expected, continuation, mode, demand, frontier, tcx)
            }
            PlannedOrdinaryValue::PendingRecOrderPath => Self::advance_pending_rec_order_path_step(
                source, expected, None, mode, frontier, tcx,
            ),
            PlannedOrdinaryValue::PendingRecOrderSource(child) => {
                Self::advance_pending_rec_order_path_step(
                    source,
                    expected,
                    Some(child),
                    mode,
                    frontier,
                    tcx,
                )
            }
            PlannedOrdinaryValue::Lambda(lambda) => {
                Self::advance_lambda_step(source, expected, lambda, mode, frontier, tcx)
            }
            PlannedOrdinaryValue::Let(continuation) => Self::advance_let_step(
                source,
                expected,
                Some(continuation),
                mode,
                demand,
                frontier,
                tcx,
            ),
            PlannedOrdinaryValue::Sequence(continuation) => Self::advance_sequence_step(
                source,
                expected,
                Some(continuation),
                mode,
                demand,
                frontier,
                tcx,
            ),
            PlannedOrdinaryValue::Field(continuation) => Self::advance_field_step(
                source,
                expected,
                Some(continuation),
                mode,
                demand,
                frontier,
                tcx,
            ),
            PlannedOrdinaryValue::ComputedCall(continuation) => Self::advance_computed_call_step(
                source,
                expected,
                Some(continuation),
                mode,
                demand,
                frontier,
                tcx,
            ),
            PlannedOrdinaryValue::UserElaborator(continuation) => {
                Self::advance_user_elaborator_step(
                    source,
                    expected,
                    continuation,
                    mode,
                    demand,
                    frontier,
                    tcx,
                )
            }
            PlannedOrdinaryValue::RecOrder(continuation) => Self::advance_rec_order_step(
                source,
                expected,
                Some(continuation),
                mode,
                demand,
                frontier,
                tcx,
            ),
            PlannedOrdinaryValue::RecQuote(continuation) => Self::advance_rec_quote_step(
                source,
                expected,
                Some(continuation),
                mode,
                frontier,
                tcx,
            ),
            PlannedOrdinaryValue::Recursive(OrdinaryRecursiveFamily::Let) => {
                Self::advance_let_step(source, expected, None, mode, demand, frontier, tcx)
            }
            PlannedOrdinaryValue::Recursive(OrdinaryRecursiveFamily::Sequence) => {
                Self::advance_sequence_step(source, expected, None, mode, demand, frontier, tcx)
            }
            PlannedOrdinaryValue::Recursive(OrdinaryRecursiveFamily::Field) => {
                Self::advance_field_step(source, expected, None, mode, demand, frontier, tcx)
            }
            PlannedOrdinaryValue::Recursive(OrdinaryRecursiveFamily::ComputedCall) => {
                Self::advance_computed_call_step(
                    source, expected, None, mode, demand, frontier, tcx,
                )
            }
            PlannedOrdinaryValue::Recursive(OrdinaryRecursiveFamily::RecOrder) => {
                Self::advance_rec_order_step(source, expected, None, mode, demand, frontier, tcx)
            }
            PlannedOrdinaryValue::Recursive(OrdinaryRecursiveFamily::RecQuote) => {
                Self::advance_rec_quote_step(source, expected, None, mode, frontier, tcx)
            }
            planned @ (PlannedOrdinaryValue::Leaf(_)
            | PlannedOrdinaryValue::Literal
            | PlannedOrdinaryValue::ConnectedCall { .. }) => Self {
                source,
                expected,
                planned,
            }
            .advance_nonrecursive(mode, frontier, tcx)
            .map(OrdinaryDriverStep::Ready),
        }
    }

    fn advance_connected_call(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        direct: PreparedDirectCallee,
        layers: SelectedPathUnitCallLayers<'m>,
        chain: UnpreparedConnectedCallChain<'m>,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryValueAdvance<'m>, Error> {
        let last = layers
            .len()
            .checked_sub(1)
            .expect("a connected ordinary call has at least one layer");
        let chain = chain.prepare(tcx)?;
        let goal_owner = frontier.goal_owner();
        let mut direct = Some(direct);
        let mut retained_callee = None;
        let mut plans = chain.plans.into_iter();

        for (index, layer) in layers.iter().copied().enumerate().take(last) {
            let linked = plans
                .next()
                .expect("each connected non-final layer has one preplanned call");
            let (plan, outgoing) = linked.consume(retained_callee.take(), goal_owner);
            let outgoing = outgoing.expect("each connected non-final call has one successor");
            let (reservation, ()) = frontier.reserve_connected_call_child_with(
                layer.call_site.span,
                tcx,
                |_store, _owner| Ok(()),
            )?;
            let mut child = frontier.open_ordinary_child(reservation)?;
            if index == 0 {
                direct
                    .take()
                    .expect("the innermost connected layer has one direct callee")
                    .stage_type(
                        child.owner(),
                        frontier.store(),
                        child.publication_mut(),
                        tcx,
                    )?;
            }
            let completed = {
                let mut child_frontier = frontier.connected_call_child_frontier(&mut child);
                plan.advance(&mut child_frontier, None, tcx)?
            };
            child.publication_mut().record_position_type(
                completed.call.call_site.span,
                completed.result.clone(),
                tcx.in_scope_type_param_presentation(),
            );
            if tcx
                .elaborations
                .captures_rec_quote_source(completed.call.call_site.id)
            {
                child.publication_mut().record_rec_quote_source_type(
                    completed.call.call_site.id,
                    completed.result.clone(),
                    false,
                );
            }
            let mut closed = frontier.close_ordinary_child(
                child,
                vec![(completed.result, GoalEscape::ToOwner(goal_owner))],
                tcx,
            )?;
            assert_eq!(
                closed.len(),
                1,
                "a connected non-final call returned an unexpected output count"
            );
            let ClosedGoalOutput::Retained(output) = closed.remove(0) else {
                unreachable!("a connected non-final call must retain its result")
            };
            assert_eq!(
                output.destination(),
                goal_owner,
                "a connected non-final call targeted another inference owner"
            );
            retained_callee = Some(outgoing.seal(
                completed.result_inferred_type_arg_suffix,
                goal_owner,
                output.into_scoped_type(),
            ));
        }

        let final_linked = plans.next().expect("a connected chain has one final call");
        assert!(
            plans.next().is_none(),
            "a connected chain produced surplus preplanned calls"
        );
        let (final_plan, outgoing) = final_linked.consume(retained_callee.take(), goal_owner);
        assert!(
            outgoing.is_none(),
            "the final connected call unexpectedly retained a successor"
        );
        if let Some(direct) = direct.take() {
            let (store, owner, publication) = frontier.publication_mut();
            direct.stage_type(owner, store, publication, tcx)?;
        }
        let completed = final_plan.advance(frontier, None, tcx)?;
        if let Some(expected) = expected {
            let result_owner = frontier.owner();
            let mut gather = frontier.begin_gather(source.span(), tcx)?;
            let store = frontier.store();
            let actual = OwnerBoundType::Retained {
                owner: result_owner,
                ty: completed.result.clone(),
            }
            .into_scoped(gather.owner(), store, source.span())?;
            let expected =
                expected.into_expected_equation_operand(gather.owner(), store, source.span())?;
            store.constrain_equation(gather.delta_mut(), actual, expected, source.span(), tcx)?;
            frontier.close_gather(gather, tcx)?;
        }
        let result =
            CompletedInFrame::Value(completed.result, completed.result_inferred_type_arg_suffix);
        Self::stage_expression_type(source, &result, frontier, tcx);
        Ok(OrdinaryValueAdvance::Complete(result))
    }

    fn begin_rec_order_value(
        plan: &'m crate::ast::RecOrderPlan<crate::ast::Lowered>,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryChildContinuation<'m>, Error> {
        match plan.annotation.as_ref() {
            Some(annotation) => {
                let lexical = super::annotation_plan::PlanningLexicalView::borrowed(tcx);
                let annotation_plan = super::annotation_plan::plan_source_annotation(
                    annotation, tcx, &lexical, false,
                )?;
                drop(lexical);
                Self::begin_annotated_child(
                    plan.value.as_ref(),
                    annotation,
                    annotation_plan,
                    frontier,
                    tcx,
                )
            }
            None => Self::begin_child(plan.value.as_ref(), None, frontier, tcx),
        }
    }

    fn begin_rec_order_bypass(
        plan: &'m crate::ast::RecOrderPlan<crate::ast::Lowered>,
        expected: Option<&OwnerBoundType>,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryChildContinuation<'m>, Error> {
        if plan.annotation.is_some() {
            Self::begin_rec_order_value(plan, frontier, tcx)
        } else {
            Self::begin_child(plan.value.as_ref(), expected.cloned(), frontier, tcx)
        }
    }

    fn rec_order_function_shell_input_span(
        plan: &crate::ast::RecOrderPlan<crate::ast::Lowered>,
    ) -> Option<Span> {
        if plan.disposition != RecOrderDisposition::Ordered(RecOrderTypeFlow::ExpectedFromBody) {
            return None;
        }
        let annotation = plan.annotation.as_ref()?;
        let crate::ast::Type::Function {
            param,
            ret,
            abi_arity: 1,
            ..
        } = annotation
        else {
            unreachable!(
                "an ExpectedFromBody recursive-order annotation must be the generated one-hole function shell"
            )
        };
        let crate::ast::Type::Infer { meta, .. } = param.as_ref() else {
            unreachable!(
                "an ExpectedFromBody function shell must have one inferred input at its root"
            )
        };
        if ret.as_ref() != &plan.runtime_ty || super::type_contains_infer(ret) {
            unreachable!(
                "an ExpectedFromBody function shell must return its concrete recursive-order runtime type"
            )
        }
        Some(meta.span)
    }

    fn rec_order_function_shell(
        plan: &crate::ast::RecOrderPlan<crate::ast::Lowered>,
        input_span: Span,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<InternedType<crate::ast::Lowered>, Error> {
        let input = frontier.reserve_goal_in_live_delta(
            crate::ast::Kind::Star,
            GoalSolutionPolicy::PolytypeAllowed,
            GoalOrigin::named(plan.body.span(), GoalRole::TypeArgument, "result"),
        )?;
        let owner = frontier.owner();
        #[cfg(test)]
        update_rec_order_function_shell_work(|work| {
            work.reserved_input_goals += 1;
            if work.first_owner.is_none() {
                work.first_owner = Some(owner);
            } else if work.second_owner.is_none() {
                work.second_owner = Some(owner);
            }
        });
        let input = frontier
            .store()
            .scoped_goal_at(input, Vec::new(), owner, input_span)?;
        let result = frontier.store().scoped_type(
            owner,
            tcx.intern_type(&plan.runtime_ty),
            plan.runtime_ty.span(),
        )?;
        let binding = input
            .projected_binary_peer(
                &result,
                super::ScopedTypeBinaryKind::Function { abi_arity: 1 },
                plan.annotation
                    .as_ref()
                    .expect("a function shell has its exact annotation")
                    .span(),
            )
            .expect("one owner-local function shell has compatible rigid scopes");
        let mut binding = binding.into_interned_type();
        #[cfg(test)]
        update_rec_order_function_shell_work(|work| work.interned_shells += 1);
        if let crate::ast::Expr::Path { segments, meta, .. } = plan.value.as_ref()
            && let [segment] = segments.as_slice()
            && let Some((index, lexical, _)) = tcx.lookup_value_binding_with_index(segment.as_str())
        {
            let retained = tcx.capture_retained_local_type(index);
            let (store, owner, delta, _publication) = frontier.parts_mut();
            let lexical = match retained {
                Some(retained) => retained.at_owner(owner, store, &lexical, meta.span, tcx)?,
                None => store.scoped_type(owner, lexical, meta.span)?,
            };
            if let Some(lexical) = store.try_zonk_goal_free(delta, lexical, tcx)?
                && matches!(lexical.ty().as_type(), crate::ast::Type::Function { .. })
            {
                let shell = store.scoped_type(owner, binding.clone(), input_span)?;
                store.constrain_equation(
                    delta,
                    shell.clone(),
                    ExpectedEquationOperand::solver(lexical),
                    meta.span,
                    tcx,
                )?;
                // Child premises cannot read this frame's uncommitted solution.
                binding = store
                    .require_goal_free_after_delta(delta, shell, tcx)?
                    .into_interned_type();
            }
        }
        Ok(binding)
    }

    fn begin_rec_order_flow(
        plan: &'m crate::ast::RecOrderPlan<crate::ast::Lowered>,
        flow: RecOrderTypeFlow,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<RecOrderContinuation<'m>, Error> {
        match flow {
            RecOrderTypeFlow::ExpectedFromBody => {
                let mark = tcx.save();
                if let Some(input_span) = Self::rec_order_function_shell_input_span(plan) {
                    let binding = Self::rec_order_function_shell(plan, input_span, frontier, tcx)?;
                    tcx.push_value_interned(plan.name.clone(), binding.clone());
                    let body = Self::begin_child(
                        plan.body.as_ref(),
                        Some(OwnerBoundType::Plain(tcx.intern_type(&plan.runtime_ty))),
                        frontier,
                        tcx,
                    );
                    tcx.restore(mark);
                    let body = body?;
                    #[cfg(test)]
                    update_rec_order_function_shell_work(|work| work.box_allocations += 1);
                    return Ok(RecOrderContinuation::FunctionShell(Box::new(
                        RecOrderFunctionShellContinuation {
                            binding,
                            state: Some(RecOrderFunctionShellState::Body(body)),
                        },
                    )));
                }
                tcx.push_pending_rec_order(
                    plan.name.clone(),
                    plan.value.as_ref(),
                    plan.value.span(),
                );
                let body = Self::begin_child(
                    plan.body.as_ref(),
                    Some(OwnerBoundType::Plain(tcx.intern_type(&plan.runtime_ty))),
                    frontier,
                    tcx,
                );
                tcx.restore(mark);
                Ok(RecOrderContinuation::ExpectedBody(body?))
            }
            RecOrderTypeFlow::SynthesizedValue | RecOrderTypeFlow::ElaboratedValue => {
                Ok(RecOrderContinuation::SynthesizedValue(
                    Self::begin_rec_order_value(plan, frontier, tcx)?,
                ))
            }
        }
    }

    fn advance_rec_quote_step(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        continuation: Option<RecQuoteContinuation<'m>>,
        mode: frontier::FrontierMode,
        frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryDriverStep<'m>, Error> {
        use crate::ast::{RecQuotePlan, Type};
        let crate::ast::Expr::RecQuote { plan, ext, .. } = source else {
            unreachable!("a recursive quotation cursor changed source family")
        };
        let continuation = match continuation {
            Some(continuation) => continuation,
            None => match plan.as_ref() {
                RecQuotePlan::Operand {
                    public_ty,
                    runtime_ty,
                    computation,
                } => {
                    if let (Some(public_ty), Some(expected)) = (public_ty, expected.clone()) {
                        let (store, owner, delta, _) = frontier.parts_mut();
                        let public =
                            store.scoped_type(owner, tcx.intern_type(public_ty), source.span())?;
                        let expected =
                            expected.into_expected_equation_operand(owner, store, source.span())?;
                        store.constrain_equation(delta, public, expected, source.span(), tcx)?;
                    }
                    let computation_expected = match public_ty {
                        Some(public_ty) => {
                            let callback = Type::synth_function(
                                vec![public_ty.clone()],
                                runtime_ty.clone(),
                                source.span(),
                            );
                            let computation_ty = Type::synth_function(
                                vec![callback],
                                runtime_ty.clone(),
                                source.span(),
                            );
                            Some(OwnerBoundType::Plain(tcx.intern_type(&computation_ty)))
                        }
                        None => match expected.clone() {
                            Some(expected) => {
                                use super::goals::ScopedTypeBinaryKind;
                                let owner = frontier.owner();
                                let store = frontier.store();
                                let public = expected.into_scoped(owner, store, source.span())?;
                                let runtime = store.scoped_type(
                                    owner,
                                    tcx.intern_type(runtime_ty),
                                    source.span(),
                                )?;
                                let kind = ScopedTypeBinaryKind::Function { abi_arity: 1 };
                                let callback = public
                                    .projected_binary_peer(&runtime, kind, source.span())
                                    .expect("local CPS expectation shares its owner scope");
                                let computation = callback
                                    .projected_binary_peer(&runtime, kind, source.span())
                                    .expect("local CPS expectation shares its owner scope");
                                Some(OwnerBoundType::Retained {
                                    owner,
                                    ty: computation,
                                })
                            }
                            None => None,
                        },
                    };
                    RecQuoteContinuation::Operand(Self::begin_child(
                        computation,
                        computation_expected,
                        frontier,
                        tcx,
                    )?)
                }
                RecQuotePlan::Expansion { continuation, .. } => RecQuoteContinuation::Callback(
                    Self::begin_child(continuation, None, frontier, tcx)?,
                ),
            },
        };
        let (child, is_callback, is_operand) = match continuation {
            RecQuoteContinuation::Operand(child) => (child, false, true),
            RecQuoteContinuation::Callback(child) => (child, true, false),
            RecQuoteContinuation::Value(child) => (child, false, false),
        };
        Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
            child,
            inherited_mode: mode,
            demand: if is_callback {
                OrdinaryCompletionDemand::ImmediateCallee
            } else {
                OrdinaryCompletionDemand::GoalFreeValue
            },
            handoff: OrdinaryDriverHandoff::Current(Box::new(move |advance, frontier, tcx| {
                match advance {
                    OrdinaryChildAdvance::Pending(child) => {
                        let continuation = if is_operand {
                            RecQuoteContinuation::Operand(child)
                        } else if is_callback {
                            RecQuoteContinuation::Callback(child)
                        } else {
                            RecQuoteContinuation::Value(child)
                        };
                        Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::pending(
                            Self {
                                source,
                                expected,
                                planned: PlannedOrdinaryValue::RecQuote(continuation),
                            },
                        )))
                    }
                    OrdinaryChildAdvance::Complete(completed) => {
                        let public_is_scheme =
                            matches!(completed, CompletedInFrame::FunctionScheme(..));
                        let public_type = completed.scoped().clone();
                        let actual = match plan.as_ref() {
                            RecQuotePlan::Operand {
                                public_ty: Some(public_ty),
                                ..
                            } => frontier.store().scoped_type(
                                frontier.owner(),
                                tcx.intern_type(public_ty),
                                source.span(),
                            )?,
                            RecQuotePlan::Operand {
                                public_ty: None,
                                runtime_ty,
                                ..
                            } => {
                                use super::goals::ScopedTypeEdge;
                                let callback = public_type
                                    .projected_structural_child(ScopedTypeEdge::FunctionParam)
                                    .expect(
                                        "closed quotation computation has a continuation parameter",
                                    );
                                let public = callback
                                    .projected_structural_child(ScopedTypeEdge::FunctionParam)
                                    .expect("closed quotation continuation has a public input");
                                let output = public_type
                                    .projected_structural_child(ScopedTypeEdge::FunctionReturn)
                                    .expect("closed quotation computation has a runtime output");
                                let callback_output = callback
                                    .projected_structural_child(ScopedTypeEdge::FunctionReturn)
                                    .expect("closed quotation continuation has a runtime output");
                                let (store, owner, delta, _) = frontier.parts_mut();
                                let runtime = store.scoped_type(
                                    owner,
                                    tcx.intern_type(runtime_ty),
                                    source.span(),
                                )?;
                                store.constrain_equation(
                                    delta,
                                    output,
                                    runtime.clone().into(),
                                    source.span(),
                                    tcx,
                                )?;
                                store.constrain_equation(
                                    delta,
                                    callback_output,
                                    runtime.into(),
                                    source.span(),
                                    tcx,
                                )?;
                                public
                            }
                            RecQuotePlan::Expansion {
                                runtime_ty, value, ..
                            } => {
                                if is_callback {
                                    use super::goals::ScopedTypeEdge;
                                    let input = public_type.projected_structural_child(ScopedTypeEdge::FunctionParam)
                                        .expect("a recursive quotation continuation has an ordinary function header");
                                    let output = public_type.projected_structural_child(ScopedTypeEdge::FunctionReturn)
                                        .expect("a recursive quotation continuation has an ordinary function result");
                                    let (store, owner, delta, _) = frontier.parts_mut();
                                    let runtime =
                                        OwnerBoundType::Plain(tcx.intern_type(runtime_ty))
                                            .into_expected_equation_operand(
                                                owner,
                                                store,
                                                source.span(),
                                            )?;
                                    store.constrain_equation(
                                        delta,
                                        output,
                                        runtime,
                                        source.span(),
                                        tcx,
                                    )?;
                                    let child = Self::begin_child(
                                        value,
                                        Some(OwnerBoundType::Retained {
                                            owner: frontier.owner(),
                                            ty: input,
                                        }),
                                        frontier,
                                        tcx,
                                    )?;
                                    return Ok(OrdinaryDriverStep::Continue(Box::new(
                                        move |frontier, tcx| {
                                            Self::advance_rec_quote_step(
                                                source,
                                                expected,
                                                Some(RecQuoteContinuation::Value(child)),
                                                mode,
                                                frontier,
                                                tcx,
                                            )
                                        },
                                    )));
                                }
                                frontier.store().scoped_type(
                                    frontier.owner(),
                                    tcx.intern_type(runtime_ty),
                                    source.span(),
                                )?
                            }
                        };
                        if let Some(expected) = expected {
                            let (store, owner, delta, _) = frontier.parts_mut();
                            let expected = expected.into_expected_equation_operand(
                                owner,
                                store,
                                source.span(),
                            )?;
                            store.constrain_equation(
                                delta,
                                actual.clone(),
                                expected,
                                source.span(),
                                tcx,
                            )?;
                        }
                        if let crate::ast::RecQuotePlan::Expansion {
                            continuation,
                            value,
                            ..
                        } = plan.as_ref()
                        {
                            let (store, _, publication) = frontier.publication_mut();
                            publication.record_rec_quote_expansion(
                                store,
                                *ext,
                                value.site().id,
                                continuation.as_ref().clone(),
                                public_type,
                                public_is_scheme,
                                actual.clone(),
                                tcx.in_scope_type_param_binders(),
                            );
                        }
                        let completed = CompletedInFrame::Value(actual, 0);
                        Self::stage_expression_type(source, &completed, frontier, tcx);
                        Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::Complete(
                            completed,
                        )))
                    }
                }
            })),
            scope_exit: OrdinaryDriverScopeExit::None,
        }))
    }

    fn advance_rec_order_step(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        continuation: Option<RecOrderContinuation<'m>>,
        mode: frontier::FrontierMode,
        _demand: OrdinaryCompletionDemand,
        frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryDriverStep<'m>, Error> {
        let crate::ast::Expr::RecOrder { plan, .. } = source else {
            unreachable!("the recursive-order continuation received another expression family")
        };
        let continuation = match continuation {
            Some(RecOrderContinuation::Selected(DeferredTailResolution::OrdinaryBypass)) => {
                let value = Self::begin_rec_order_bypass(plan, expected.as_ref(), frontier, tcx)?;
                RecOrderContinuation::OrdinaryBypass(value)
            }
            Some(RecOrderContinuation::Selected(DeferredTailResolution::Lifted(flow))) => {
                let RecOrderDisposition::DeferredTail { lifted_flow, .. } = plan.disposition else {
                    unreachable!("a selected deferred-tail flow reached an ordered carrier")
                };
                assert_eq!(
                    flow, lifted_flow,
                    "a checked recipe changed the carrier's authored lifted flow"
                );
                Self::begin_rec_order_flow(plan, flow, frontier, tcx)?
            }
            Some(continuation) => continuation,
            None => match plan.disposition {
                RecOrderDisposition::Ordered(flow) => {
                    Self::begin_rec_order_flow(plan, flow, frontier, tcx)?
                }
                RecOrderDisposition::DeferredTail {
                    requirement: RecOrderTailRequirement::Optional,
                    ..
                } => RecOrderContinuation::OrdinaryBypass(Self::begin_rec_order_bypass(
                    plan,
                    expected.as_ref(),
                    frontier,
                    tcx,
                )?),
                RecOrderDisposition::DeferredTail { .. } => {
                    return Err(crate::pass::typecheck_full::deferred_rec_tail_error(
                        source.span(),
                    ));
                }
            },
        };
        match continuation {
            RecOrderContinuation::Selected(_) => {
                unreachable!("a selected deferred-tail carrier was retained without consumption")
            }
            RecOrderContinuation::OrdinaryBypass(value) => {
                Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
                    child: value,
                    inherited_mode: mode,
                    demand: OrdinaryCompletionDemand::GoalFreeValue,
                    handoff: OrdinaryDriverHandoff::Current(Box::new(
                        move |advance, frontier, tcx| match advance {
                            OrdinaryChildAdvance::Pending(value) => {
                                if mode == frontier::FrontierMode::Final
                                    && !value.is_completion_wait()
                                {
                                    unreachable!(
                                        "an ordinary deferred-tail value remained pending after Final"
                                    )
                                }
                                Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::pending(
                                    Self {
                                        source,
                                        expected,
                                        planned: PlannedOrdinaryValue::RecOrder(
                                            RecOrderContinuation::OrdinaryBypass(value),
                                        ),
                                    },
                                )))
                            }
                            OrdinaryChildAdvance::Complete(completed) => {
                                Self::finish_deferred_rec_order_bypass(
                                    source, expected, completed, frontier, tcx,
                                )
                                .map(OrdinaryDriverStep::Ready)
                            }
                        },
                    )),
                    scope_exit: OrdinaryDriverScopeExit::None,
                }))
            }
            RecOrderContinuation::FunctionShell(mut continuation) => {
                let state = continuation
                    .state
                    .take()
                    .expect("a retained function shell has one active state");
                match state {
                    RecOrderFunctionShellState::Body(body) => {
                        #[cfg(test)]
                        update_rec_order_function_shell_work(|work| work.body_advances += 1);
                        let mark = tcx.save();
                        tcx.push_value_interned(plan.name.clone(), continuation.binding.clone());
                        Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
                            child: body,
                            inherited_mode: mode,
                            demand: OrdinaryCompletionDemand::GoalFreeValue,
                            handoff: OrdinaryDriverHandoff::Current(Box::new(
                                move |advance, frontier, tcx| match advance {
                                    OrdinaryChildAdvance::Pending(body) => {
                                        if mode == frontier::FrontierMode::Final
                                            && !body.is_completion_wait()
                                        {
                                            unreachable!(
                                                "a function-shell recursive-order body remained pending after Final"
                                            )
                                        }
                                        continuation.state =
                                            Some(RecOrderFunctionShellState::Body(body));
                                        Ok(OrdinaryDriverStep::Ready(
                                            OrdinaryValueAdvance::pending(Self {
                                                source,
                                                expected,
                                                planned: PlannedOrdinaryValue::RecOrder(
                                                    RecOrderContinuation::FunctionShell(
                                                        continuation,
                                                    ),
                                                ),
                                            }),
                                        ))
                                    }
                                    OrdinaryChildAdvance::Complete(completed) => {
                                        let (owner, shell) = {
                                            let (store, owner, delta, _publication) =
                                                frontier.parts_mut();
                                            let shell = store.scoped_type(
                                                owner,
                                                continuation.binding.clone(),
                                                plan.annotation
                                                    .as_ref()
                                                    .expect(
                                                        "a function shell retains its annotation",
                                                    )
                                                    .span(),
                                            )?;
                                            let shell = store
                                                .require_goal_free_after_delta(delta, shell, tcx)?;
                                            (owner, shell)
                                        };
                                        let value = Self::begin_child(
                                            plan.value.as_ref(),
                                            Some(OwnerBoundType::Retained { owner, ty: shell }),
                                            frontier,
                                            tcx,
                                        )?;
                                        continuation.state =
                                            Some(RecOrderFunctionShellState::Value {
                                                body: completed,
                                                value,
                                            });
                                        Self::advance_rec_order_step(
                                            source,
                                            expected,
                                            Some(RecOrderContinuation::FunctionShell(continuation)),
                                            mode,
                                            OrdinaryCompletionDemand::GoalFreeValue,
                                            frontier,
                                            tcx,
                                        )
                                    }
                                },
                            )),
                            scope_exit: OrdinaryDriverScopeExit::RestoreBeforeResume(mark),
                        }))
                    }
                    RecOrderFunctionShellState::Value { body, value } => {
                        #[cfg(test)]
                        update_rec_order_function_shell_work(|work| work.value_advances += 1);
                        Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
                            child: value,
                            inherited_mode: mode,
                            demand: OrdinaryCompletionDemand::GoalFreeValue,
                            handoff: OrdinaryDriverHandoff::Current(Box::new(
                                move |advance, frontier, tcx| match advance {
                                    OrdinaryChildAdvance::Pending(value) => {
                                        if mode == frontier::FrontierMode::Final
                                            && !value.is_completion_wait()
                                        {
                                            unreachable!(
                                                "a function-shell recursive-order source remained pending after Final"
                                            )
                                        }
                                        continuation.state =
                                            Some(RecOrderFunctionShellState::Value { body, value });
                                        Ok(OrdinaryDriverStep::Ready(
                                            OrdinaryValueAdvance::pending(Self {
                                                source,
                                                expected,
                                                planned: PlannedOrdinaryValue::RecOrder(
                                                    RecOrderContinuation::FunctionShell(
                                                        continuation,
                                                    ),
                                                ),
                                            }),
                                        ))
                                    }
                                    OrdinaryChildAdvance::Complete(_) => {
                                        let binding = frontier.store().scoped_type(
                                            frontier.owner(),
                                            continuation.binding,
                                            plan.annotation
                                                .as_ref()
                                                .expect("a function shell retains its annotation")
                                                .span(),
                                        )?;
                                        Self::finish_rec_order(
                                            source,
                                            expected,
                                            Some(binding),
                                            body,
                                            frontier,
                                            tcx,
                                        )
                                        .map(OrdinaryDriverStep::Ready)
                                    }
                                },
                            )),
                            scope_exit: OrdinaryDriverScopeExit::None,
                        }))
                    }
                }
            }
            RecOrderContinuation::ExpectedBody(body) => {
                let mark = tcx.save();
                let pending = tcx.push_pending_rec_order(
                    plan.name.clone(),
                    plan.value.as_ref(),
                    plan.value.span(),
                );
                Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
                    child: body,
                    inherited_mode: mode,
                    demand: OrdinaryCompletionDemand::GoalFreeValue,
                    handoff: OrdinaryDriverHandoff::Current(Box::new(
                        move |advance, frontier, tcx| match advance {
                            OrdinaryChildAdvance::Pending(body) => Ok(
                                OrdinaryDriverStep::AfterScope(Box::new(move |_frontier, _tcx| {
                                    if mode == frontier::FrontierMode::Final
                                        && !body.is_completion_wait()
                                    {
                                        unreachable!(
                                            "a recursive-order body remained pending after Final"
                                        )
                                    }
                                    Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::pending(
                                        Self {
                                            source,
                                            expected,
                                            planned: PlannedOrdinaryValue::RecOrder(
                                                RecOrderContinuation::ExpectedBody(body),
                                            ),
                                        },
                                    )))
                                })),
                            ),
                            OrdinaryChildAdvance::Complete(completed) => {
                                let direct = tcx.pending_rec_order_state(pending);
                                if !matches!(direct, PendingRecOrderState::Pending) {
                                    frontier.stage_rec_order(plan.value.as_ref(), direct, tcx)?;
                                }
                                let observation =
                                    OrdinaryFrontierReentry::take_rec_order_observation(
                                        frontier,
                                        plan.value.as_ref(),
                                        tcx,
                                    );
                                Ok(OrdinaryDriverStep::AfterScope(Box::new(
                                    move |frontier, tcx| {
                                        let observation = observation?;
                                        let Some((binding, source_checked)) = observation else {
                                            unreachable!(
                                                "recursive ordering binder `{}` was not classified at its generated use site",
                                                plan.name
                                            )
                                        };
                                        let Some(binding) = binding else {
                                            return Self::finish_rec_order(
                                                source, expected, None, completed, frontier, tcx,
                                            )
                                            .map(OrdinaryDriverStep::Ready);
                                        };
                                        if source_checked {
                                            return Self::finish_rec_order(
                                                source,
                                                expected,
                                                Some(binding),
                                                completed,
                                                frontier,
                                                tcx,
                                            )
                                            .map(OrdinaryDriverStep::Ready);
                                        }
                                        let mark = tcx.save();
                                        tcx.push_pending_rec_order(
                                            plan.name.clone(),
                                            plan.value.as_ref(),
                                            plan.value.span(),
                                        );
                                        let value = Self::begin_child(
                                            plan.value.as_ref(),
                                            Some(OwnerBoundType::Retained {
                                                owner: frontier.owner(),
                                                ty: binding.clone(),
                                            }),
                                            frontier,
                                            tcx,
                                        );
                                        tcx.restore(mark);
                                        Self::advance_rec_order_step(
                                            source,
                                            expected,
                                            Some(RecOrderContinuation::ExpectedValue {
                                                binding,
                                                body: completed,
                                                value: value?,
                                            }),
                                            mode,
                                            OrdinaryCompletionDemand::GoalFreeValue,
                                            frontier,
                                            tcx,
                                        )
                                    },
                                )))
                            }
                        },
                    )),
                    scope_exit: OrdinaryDriverScopeExit::RestoreAfterResume(mark),
                }))
            }
            RecOrderContinuation::ExpectedValue {
                binding,
                body,
                value,
            } => {
                let mark = tcx.save();
                tcx.push_pending_rec_order(
                    plan.name.clone(),
                    plan.value.as_ref(),
                    plan.value.span(),
                );
                Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
                    child: value,
                    inherited_mode: mode,
                    demand: OrdinaryCompletionDemand::GoalFreeValue,
                    handoff: OrdinaryDriverHandoff::Current(Box::new(
                        move |advance, frontier, tcx| match advance {
                            OrdinaryChildAdvance::Pending(value) => {
                                if mode == frontier::FrontierMode::Final
                                    && !value.is_completion_wait()
                                {
                                    unreachable!(
                                        "a recursive-order source remained pending after Final"
                                    )
                                }
                                Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::pending(
                                    Self {
                                        source,
                                        expected,
                                        planned: PlannedOrdinaryValue::RecOrder(
                                            RecOrderContinuation::ExpectedValue {
                                                binding,
                                                body,
                                                value,
                                            },
                                        ),
                                    },
                                )))
                            }
                            OrdinaryChildAdvance::Complete(_) => Self::finish_rec_order(
                                source,
                                expected,
                                Some(binding),
                                body,
                                frontier,
                                tcx,
                            )
                            .map(OrdinaryDriverStep::Ready),
                        },
                    )),
                    scope_exit: OrdinaryDriverScopeExit::RestoreBeforeResume(mark),
                }))
            }
            RecOrderContinuation::SynthesizedValue(mut value) => {
                value.child.mark_independent_source();
                Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
                    child: value,
                    inherited_mode: mode,
                    demand: OrdinaryCompletionDemand::GoalFreeValue,
                    handoff: OrdinaryDriverHandoff::Current(Box::new(
                        move |advance, frontier, tcx| match advance {
                            OrdinaryChildAdvance::Pending(value) => {
                                if mode == frontier::FrontierMode::Final
                                    && !value.is_completion_wait()
                                {
                                    unreachable!(
                                        "a synthesized recursive-order value remained pending after Final"
                                    )
                                }
                                Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::pending(
                                    Self {
                                        source,
                                        expected,
                                        planned: PlannedOrdinaryValue::RecOrder(
                                            RecOrderContinuation::SynthesizedValue(value),
                                        ),
                                    },
                                )))
                            }
                            OrdinaryChildAdvance::Complete(completed) => {
                                let binding = if plan.disposition
                                    == RecOrderDisposition::Ordered(
                                        RecOrderTypeFlow::ElaboratedValue,
                                    ) {
                                    frontier.store().scoped_type(
                                        frontier.owner(),
                                        tcx.intern_type(&plan.runtime_ty),
                                        source.span(),
                                    )?
                                } else {
                                    completed.scoped().clone()
                                };
                                let mark = tcx.save();
                                tcx.push_value_interned(plan.name.clone(), binding.ty().clone());
                                let body = Self::begin_child(
                                    plan.body.as_ref(),
                                    Some(OwnerBoundType::Plain(tcx.intern_type(&plan.runtime_ty))),
                                    frontier,
                                    tcx,
                                );
                                tcx.restore(mark);
                                Self::advance_rec_order_step(
                                    source,
                                    expected,
                                    Some(RecOrderContinuation::SynthesizedBody {
                                        binding,
                                        body: body?,
                                    }),
                                    mode,
                                    OrdinaryCompletionDemand::GoalFreeValue,
                                    frontier,
                                    tcx,
                                )
                            }
                        },
                    )),
                    scope_exit: OrdinaryDriverScopeExit::None,
                }))
            }
            RecOrderContinuation::SynthesizedBody { binding, body } => {
                let mark = tcx.save();
                tcx.push_value_interned(plan.name.clone(), binding.ty().clone());
                Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
                    child: body,
                    inherited_mode: mode,
                    demand: OrdinaryCompletionDemand::GoalFreeValue,
                    handoff: OrdinaryDriverHandoff::Current(Box::new(
                        move |advance, frontier, tcx| match advance {
                            OrdinaryChildAdvance::Pending(body) => {
                                if mode == frontier::FrontierMode::Final
                                    && !body.is_completion_wait()
                                {
                                    unreachable!(
                                        "a synthesized recursive-order body remained pending after Final"
                                    )
                                }
                                Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::pending(
                                    Self {
                                        source,
                                        expected,
                                        planned: PlannedOrdinaryValue::RecOrder(
                                            RecOrderContinuation::SynthesizedBody { binding, body },
                                        ),
                                    },
                                )))
                            }
                            OrdinaryChildAdvance::Complete(completed) => Self::finish_rec_order(
                                source,
                                expected,
                                Some(binding),
                                completed,
                                frontier,
                                tcx,
                            )
                            .map(OrdinaryDriverStep::Ready),
                        },
                    )),
                    scope_exit: OrdinaryDriverScopeExit::RestoreBeforeResume(mark),
                }))
            }
        }
    }

    fn finish_deferred_rec_order_bypass(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        completed: CompletedInFrame,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryValueAdvance<'m>, Error> {
        let crate::ast::Expr::RecOrder { plan, ext, .. } = source else {
            unreachable!("a deferred-tail bypass received another expression family")
        };
        assert!(
            matches!(
                plan.disposition,
                RecOrderDisposition::DeferredTail {
                    requirement: RecOrderTailRequirement::Optional,
                    ..
                }
            ),
            "only an optional deferred-tail carrier may bypass its wrapper"
        );
        if let Some(expected) = expected {
            let (store, owner, delta, _publication) = frontier.parts_mut();
            let expected = expected.into_expected_equation_operand(owner, store, source.span())?;
            store.constrain_equation(
                delta,
                completed.scoped().clone(),
                expected,
                source.span(),
                tcx,
            )?;
        }
        {
            let (store, _owner, publication) = frontier.publication_mut();
            publication.record_lowered_elaboration(store, *ext, plan.value.as_ref().clone());
        }
        Self::stage_expression_type(source, &completed, frontier, tcx);
        Ok(OrdinaryValueAdvance::Complete(completed))
    }

    fn finish_rec_order(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        binding: Option<ScopedType>,
        // Completing the retained body is the proof that `plan.runtime_ty`
        // was checked.  Keep the enclosing expected occurrence when one was
        // supplied so its owner and rigid scope remain intact.
        _completed: CompletedInFrame,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryValueAdvance<'m>, Error> {
        let crate::ast::Expr::RecOrder { plan, ext, .. } = source else {
            unreachable!("recursive-order completion received another expression family")
        };
        let runtime = frontier.store().scoped_type(
            frontier.owner(),
            tcx.intern_type(&plan.runtime_ty),
            source.span(),
        )?;
        let actual = if let Some(expected) = expected {
            let (store, owner, delta, _publication) = frontier.parts_mut();
            let expected = expected.into_expected_equation_operand(owner, store, source.span())?;
            let completed_solver = expected.solver_type().clone();
            store.constrain_equation(delta, runtime, expected, source.span(), tcx)?;
            completed_solver
        } else {
            runtime
        };
        {
            let (store, _owner, publication) = frontier.publication_mut();
            if let Some(binding) = binding {
                publication.record_rec_order_binding(
                    store,
                    *ext,
                    crate::ast::Expr::Let {
                        occurrence: crate::ast::ExpressionOccurrence::fresh(),
                        name: plan.name.clone(),
                        name_span: plan.value.span(),
                        ty: None,
                        pattern: (),
                        value: plan.value.clone(),
                        body: plan.body.clone(),
                        meta: crate::ast::Meta::new(source.span()),
                    },
                    binding,
                );
            } else {
                publication.record_lowered_elaboration(store, *ext, plan.body.as_ref().clone());
            }
        }
        let completed = CompletedInFrame::Value(actual, 0);
        Self::stage_expression_type(source, &completed, frontier, tcx);
        Ok(OrdinaryValueAdvance::Complete(completed))
    }

    fn advance_pending_rec_order_path_step(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        retained: Option<OrdinaryChildContinuation<'m>>,
        mode: frontier::FrontierMode,
        frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryDriverStep<'m>, Error> {
        if mode != frontier::FrontierMode::Final || expected.is_none() {
            return Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::Pending(
                Box::new(Self {
                    source,
                    expected,
                    planned: PlannedOrdinaryValue::PendingRecOrderPath,
                }),
            )));
        }
        let expected = expected.expect("the pending recursive-order path was checked above");
        let effective_source = tcx.effective_rec_order_source(source);
        assert!(
            !std::ptr::eq(effective_source, source),
            "a pending recursive-order path did not retain its source"
        );
        let child = match retained {
            Some(child) => child,
            None => {
                #[cfg(test)]
                record_rec_order_source_visit();
                let child =
                    Self::begin_child(effective_source, Some(expected.clone()), frontier, tcx)?;
                let header = expected.clone().into_scoped(
                    frontier.owner(),
                    frontier.store(),
                    source.span(),
                )?;
                frontier.record_rec_order_entry(effective_source, child.child.owner(), header);
                child
            }
        };
        Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
            child,
            inherited_mode: frontier::FrontierMode::Final,
            demand: OrdinaryCompletionDemand::GoalFreeValue,
            handoff: OrdinaryDriverHandoff::Current(Box::new(move |result, frontier, tcx| {
                let completed = match result {
                    OrdinaryChildAdvance::Complete(completed) => completed,
                    OrdinaryChildAdvance::Pending(child) => {
                        assert!(
                            child.is_completion_wait(),
                            "a recursive-order source remained mode-pending after Final"
                        );
                        return Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::Waiting(
                            Box::new(Self {
                                source,
                                expected: Some(expected),
                                planned: PlannedOrdinaryValue::PendingRecOrderSource(child),
                            }),
                        )));
                    }
                };
                frontier.stage_rec_order(
                    effective_source,
                    PendingRecOrderState::Runtime {
                        exact_ty: expected.ty().clone(),
                        source_checked: true,
                    },
                    tcx,
                )?;
                Self::stage_expression_type(source, &completed, frontier, tcx);
                Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::Complete(
                    completed,
                )))
            })),
            scope_exit: OrdinaryDriverScopeExit::None,
        }))
    }

    fn advance_planned_leaf(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        mut leaf: PlannedOrdinaryLeaf<'m>,
        mode: frontier::FrontierMode,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryValueAdvance<'m>, Error> {
        leaf.prepared
            .validate_expected(expected.as_ref().map(OwnerBoundType::ty), tcx)?;
        if let Some(expected_type) = expected.as_ref() {
            let (actual, expected_equation, scoped_expected) = {
                let (store, owner, _delta, _publication) = frontier.parts_mut();
                let actual = leaf.prepared.scoped_type(owner, store, tcx)?;
                let expected_equation = expected_type.clone().into_expected_equation_operand(
                    owner,
                    store,
                    source.span(),
                )?;
                let scoped_expected = expected_equation.solver_type().clone();
                (actual, expected_equation, scoped_expected)
            };
            let retry_snapshot = match &leaf.equation_progress {
                EquationProgress::Initial => None,
                EquationProgress::AwaitingProgress(previous) => {
                    let (store, _owner, delta, _publication) = frontier.parts_mut();
                    let snapshot = EquationSnapshot::zonked(
                        store,
                        delta,
                        actual.clone(),
                        scoped_expected.clone(),
                        tcx,
                    )?;
                    if !previous.differs_from(&snapshot) {
                        if mode == frontier::FrontierMode::Final {
                            let _ =
                                store.require_goal_free_after_delta(delta, actual.clone(), tcx)?;
                            let _ = store.require_goal_free_after_delta(
                                delta,
                                scoped_expected.clone(),
                                tcx,
                            )?;
                            unreachable!(
                                "a deferred prepared-leaf equation had two goal-free sides"
                            )
                        }
                        return Ok(OrdinaryValueAdvance::pending(Self {
                            source,
                            expected,
                            planned: PlannedOrdinaryValue::Leaf(leaf),
                        }));
                    }
                    Some(snapshot)
                }
            };
            #[cfg(test)]
            record_retained_leaf_equation();
            let outcome = {
                let (store, _owner, delta, _publication) = frontier.parts_mut();
                store.try_constrain_retained_leaf_equation(
                    delta,
                    actual.clone(),
                    expected_equation,
                    source.span(),
                    tcx,
                )?
            };
            if outcome == CloseReadyEquationConstraint::Deferred {
                if mode == frontier::FrontierMode::Final {
                    let (store, _owner, delta, _publication) = frontier.parts_mut();
                    let _ = store.require_goal_free_after_delta(delta, actual, tcx)?;
                    let _ = store.require_goal_free_after_delta(delta, scoped_expected, tcx)?;
                    unreachable!("a deferred prepared-leaf equation had two goal-free sides")
                }
                let snapshot = if let Some(snapshot) = retry_snapshot {
                    snapshot
                } else {
                    let (store, _owner, delta, _publication) = frontier.parts_mut();
                    EquationSnapshot::zonked(store, delta, actual, scoped_expected, tcx)?
                };
                leaf.equation_progress = EquationProgress::AwaitingProgress(snapshot);
                return Ok(OrdinaryValueAdvance::pending(Self {
                    source,
                    expected,
                    planned: PlannedOrdinaryValue::Leaf(leaf),
                }));
            }
        }
        let (store, owner, _delta, publication) = frontier.parts_mut();
        let completed = leaf
            .prepared
            .stage_validated(owner, store, publication, tcx)?;
        Ok(OrdinaryValueAdvance::Complete(completed))
    }

    fn selected_source_expectation(
        selecting: &mut SelectingOrdinaryCall<'m>,
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        width: usize,
        ends_packet: bool,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<(OwnerBoundType, usize, usize), Error> {
        let fills_layer = selecting.selected_slots + width >= selecting.value_slots || ends_packet;
        let expected = selecting
            .call
            .select_value_width(source, width, fills_layer, tcx);
        let selected_slots_after = if fills_layer {
            selecting.value_slots
        } else {
            selecting.selected_slots + width
        };
        let selected_expanded_slots_after = (selecting.selected_expanded_slots
            + selected_slots_after.saturating_sub(selecting.selected_slots))
        .min(selecting.expanded_value_slots);
        let expected = prepare_expected_value_packet(frontier, expected, source.span(), tcx)?;
        Ok((
            expected,
            selected_slots_after,
            selected_expanded_slots_after,
        ))
    }

    fn current_source_ends_written_packet(
        selecting: &SelectingOrdinaryCall<'m>,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<bool, Error> {
        let goal_owner = frontier.goal_owner();
        assert_eq!(
            selecting.call.owner, goal_owner,
            "call-packet selection read constraints through another inference owner"
        );
        let effective_candidates = effective_rec_order_args(&selecting.candidates, tcx);
        let candidates = effective_candidates
            .as_deref()
            .unwrap_or(&selecting.candidates);
        if let Some(immediate) = selecting.call.immediate_lambda.as_ref()
            && immediate.may_flatten_into_next_declared_layer()
        {
            let next = immediate
                .next_declared_layer()
                .expect("a declared-layer lookahead lost its next layer");
            #[cfg(all(test, feature = "surface"))]
            record_semantic_successor_advance();
            if source_ends_written_value_packet(
                candidates,
                selecting.next_candidate,
                !next.binders.is_empty(),
            ) {
                return Ok(true);
            }
            let suffix = &candidates[selecting.next_candidate + 1..];
            let mut reserved = 0;
            for layer in &immediate.layers[immediate.current_layer + 1..] {
                let prefix = explicit_type_arg_prefix_len(&suffix[reserved..], layer.binders.len());
                reserved += prefix;
                if matches!(suffix.get(reserved), Some(CallArgRef::Value(_))) {
                    reserved += 1;
                }
                if reserved == suffix.len() {
                    break;
                }
            }
            return Ok(reserved == suffix.len());
        }
        let result = selecting.call.result_type(goal_owner);
        let call_site = selecting.call.call_site;
        let ambient_binders = tcx.in_scope_type_param_binders();
        let aliases = tcx.binder_alias_ctx(&ambient_binders);
        let (head, head_identity_canonical) = super::aliases::unfold_and_qualify_state(
            result.as_type(),
            &aliases,
            result.identity_is_canonical(),
        );
        let progressed_result = match head {
            head @ crate::ast::Type::Forall { .. } => {
                InternedType::fresh_with_identity(head, head_identity_canonical)
            }
            head @ crate::ast::Type::Goal { .. } => {
                // A syntactically leading Forall is already decisive, even
                // when its body retains other goals. Only a goal at the head
                // needs the current delta: isolate that occurrence before
                // zonking so no goal is re-scoped beneath a lexical Forall.
                let (store, _owner, delta, _publication) = frontier.parts_mut();
                let head = store.scoped_type(
                    goal_owner,
                    InternedType::fresh_with_identity(head, head_identity_canonical),
                    call_site.span,
                )?;
                store
                    .zonk_for_progress(delta, head, tcx)?
                    .into_interned_type()
            }
            head => InternedType::fresh_with_identity(head, head_identity_canonical),
        };
        #[cfg(all(test, feature = "surface"))]
        record_semantic_successor_advance();
        let successor = SemanticCallCursor::from_type(&progressed_result, tcx);
        Ok(source_ends_semantic_packet(
            candidates,
            selecting.next_candidate,
            successor.as_ref(),
        ))
    }

    #[allow(clippy::too_many_arguments)] // transition owns the complete successor-call handoff
    fn begin_selected_successor(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        call_site: crate::ast::ExpressionSite,
        callee: OwnerBoundSynth,
        args: Vec<CallArgRef<'m, crate::ast::Lowered>>,
        slot_offset: usize,
        transcript: Option<UserElaboratorCallTranscript>,
        expected: Option<OwnerBoundType>,
        empty_call_mode: EmptyCallMode,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryChildContinuation<'m>, Error> {
        reject_invalid_polymorphic_non_function_application(
            callee.ty().ty(),
            &args,
            call_site,
            tcx,
        )?;
        let (reservation, planned) =
            frontier.reserve_ordinary_child_with(source.span(), tcx, |store, owner| {
                let callee = callee.into_synth(owner, store, source.span())?;
                open_selecting_goal_call(
                    &callee,
                    args,
                    None,
                    None,
                    slot_offset,
                    source.span(),
                    call_site,
                    empty_call_mode,
                    transcript,
                    store,
                    owner,
                    tcx,
                )
                .map(|selecting| {
                    PlannedOrdinaryValue::Call(OrdinaryCallContinuation::Selecting(Box::new(
                        selecting,
                    )))
                })
            })?;
        let cursor = match expected {
            Some(expected) => Self::bind(source, expected, planned),
            None => Self::bind_synth(source, planned),
        };
        let child = frontier.open_ordinary_child(reservation)?;
        Ok(OrdinaryChildContinuation {
            child,
            cursor: Box::new(cursor),
            next_mode: frontier::FrontierMode::ExpectedOnly,
            suspension: OrdinarySuspension::Mode,
        })
    }

    fn arm_contextual_returned_forall(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        mut advancing: Box<AdvancingOrdinaryCall<'m>>,
        split_after: usize,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<Box<AdvancingOrdinaryCall<'m>>, Error> {
        let mut immediate = advancing
            .call
            .immediate_lambda
            .take()
            .expect("a contextual returned-Forall handoff lost its immediate lambda");
        assert!(
            matches!(immediate.body, ImmediateLambdaBodyState::Complete { .. })
                && advancing.pending_expected_result.is_none(),
            "a contextual returned-Forall handoff preceded body completion"
        );
        let expected = immediate
            .outer_expected
            .take()
            .expect("a contextual returned-Forall handoff lost its expected type");
        let returned = advancing.result.clone();
        {
            let (_store, _owner, publication) = frontier.publication_mut();
            publication.record_call_split(advancing.call.call_site, split_after);
        }
        let returned_owner = frontier.owner();
        let successor = Self::begin_selected_successor(
            source,
            advancing.call.call_site,
            OwnerBoundSynth::FunctionScheme {
                ty: OwnerBoundType::Retained {
                    owner: returned_owner,
                    ty: returned,
                },
                inferred_type_arg_suffix: advancing.result_inferred_type_arg_suffix,
            },
            Vec::new(),
            split_after,
            advancing.call.user_elaborator_transcript.take(),
            Some(expected),
            EmptyCallMode::ResidualTypeApplication,
            frontier,
            tcx,
        )?;
        advancing.pending.insert(
            0,
            PendingOrdinaryCallChild {
                child: successor,
                role: PendingOrdinaryChildRole::ContextualReturnedForall,
            },
        );
        Ok(advancing)
    }

    fn completed_selected_call(
        mut completed: Box<CompletedPathUnitGoalCall<'m>>,
    ) -> CompletedInFrame {
        match completed.call.user_elaborator_transcript.take() {
            Some(transcript) => CompletedInFrame::UserElaboratorCall {
                output: completed.result,
                inferred_type_arg_suffix: completed.result_inferred_type_arg_suffix,
                transcript,
            },
            None => {
                CompletedInFrame::Value(completed.result, completed.result_inferred_type_arg_suffix)
            }
        }
    }

    fn completed_retained_callable(
        completed: Box<CompletedPathUnitGoalCall<'m>>,
        progress: RetainedCallableProgress,
    ) -> CompletedInFrame {
        match (Self::completed_selected_call(completed), progress) {
            (
                CompletedInFrame::Value(output, inferred_type_arg_suffix),
                RetainedCallableProgress::Function | RetainedCallableProgress::PolymorphicValue,
            ) => CompletedInFrame::Value(output, inferred_type_arg_suffix),
            (
                CompletedInFrame::Value(output, inferred_type_arg_suffix),
                RetainedCallableProgress::FunctionScheme,
            ) => CompletedInFrame::FunctionScheme(output, inferred_type_arg_suffix),
            (completed @ CompletedInFrame::UserElaboratorCall { .. }, _) => completed,
            (CompletedInFrame::FunctionScheme(_, _), _) => {
                unreachable!("a selected call was already classified as a function scheme")
            }
        }
    }

    fn retain_callable_progress(
        result: &mut ScopedType,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<Option<RetainedCallableProgress>, Error> {
        let (progressed, scheme_summary) = {
            let (store, _owner, delta, _publication) = frontier.parts_mut();
            let progressed = store.zonk_for_progress(delta, result.clone(), tcx)?;
            #[cfg(test)]
            super::kind_scheme::record_retained_frontier_consumer();
            let scheme_summary =
                store.classify_complete_function_scheme(&progressed, delta, tcx)?;
            (progressed, scheme_summary)
        };
        let ambient_binders = tcx.in_scope_type_param_binders();
        let (head, _) = super::aliases::unfold_and_qualify_state(
            progressed.ty().as_type(),
            &tcx.binder_alias_ctx(&ambient_binders),
            progressed.ty().identity_is_canonical(),
        );
        let progress = match head {
            crate::ast::Type::Function { .. } => RetainedCallableProgress::Function,
            crate::ast::Type::Forall { .. } if scheme_summary.is_complete() => {
                RetainedCallableProgress::FunctionScheme
            }
            crate::ast::Type::Forall { .. } => RetainedCallableProgress::PolymorphicValue,
            _ => return Ok(None),
        };
        *result = progressed;
        Ok(Some(progress))
    }

    #[allow(clippy::too_many_arguments)]
    fn begin_next_immediate_value_layer(
        mut completed: Box<CompletedPathUnitGoalCall<'m>>,
        remaining: Vec<CallArgRef<'m, crate::ast::Lowered>>,
        transition: DeclaredValueTransition,
        split_after: usize,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<SelectingOrdinaryCall<'m>, Error> {
        let mut immediate = *completed
            .call
            .immediate_lambda
            .take()
            .expect("a declared-layer transition lost its immediate lambda");
        let next_ordinal = transition.next_ordinal;
        assert_eq!(
            next_ordinal,
            immediate.current_layer + 1,
            "a declared value transition skipped a layer"
        );

        let OpenGoalCall {
            owner,
            shape,
            replacements,
            goal_occurrences: _,
            remaining_param: _,
            result_canonical,
            residual_eta_staged,
            callee_span,
            call_site,
            slot_offset: _,
            user_elaborator_transcript,
            immediate_lambda: _,
        } = completed.call;
        assert_eq!(
            owner,
            frontier.goal_owner(),
            "a declared-layer transition changed inference owners"
        );
        immediate
            .completed_layers
            .push(ImmediateLambdaLayerInstantiation {
                ordinal: immediate.current_layer,
                binders: shape.binders,
                replacements,
                output: completed.result,
                result_canonical,
            });
        immediate.current_layer = next_ordinal;

        let effective_remaining = effective_rec_order_args(&remaining, tcx);
        let selection_remaining = effective_remaining.as_deref().unwrap_or(&remaining);
        let selected =
            immediate.select_layer(next_ordinal, selection_remaining, call_site, owner, tcx)?;
        let partial_type_only = selected.explicit_prefix > 0
            && selected.explicit_prefix < immediate.layers[next_ordinal].binders.len()
            && selected.explicit_prefix == selection_remaining.len();
        assert!(
            !partial_type_only,
            "a partial declared type prefix must use the residual transition"
        );
        let activated = immediate.activate_layer(
            next_ordinal,
            selection_remaining,
            selected.explicit_prefix,
            call_site,
            owner,
            |reserved, diagnostic_span, occurrence_span| {
                frontier.activate_reserved_goal(reserved, diagnostic_span, occurrence_span)
            },
        )?;
        let (type_args, _) = selection_remaining.split_at(selected.explicit_prefix);
        let (_, candidates) = remaining.split_at(selected.explicit_prefix);
        let layer = &immediate.layers[next_ordinal];
        let next_shape = GoalCallShape {
            binders: layer.binders.clone(),
            param: activated.param,
            ret: activated.result.clone_type(),
            result_requirement_source: activated.result.requirement_source().cloned(),
            abi_arity: layer.parameter_range.len(),
            has_value_layer: true,
            type_args: type_args.to_vec(),
            value_args: Vec::new(),
            explicit_prefix: selected.explicit_prefix,
            identity_canonical: false,
            result_is_pre_residual: false,
        };
        let mut call = OpenGoalCall::begin_at_slot_offset_with_activated_binders(
            next_shape,
            owner,
            callee_span,
            call_site,
            split_after,
            user_elaborator_transcript,
            activated.binder_occurrences,
            frontier.store(),
            tcx,
        )?;
        call.residual_eta_staged = residual_eta_staged;
        if let ImmediateLambdaBodyState::Complete { actual } = &immediate.body {
            let current_output =
                prepare_owner_bound_type(frontier, call.result_type(owner), call_site.span, tcx)?
                    .into_scoped(frontier.owner(), frontier.store(), call_site.span)?;
            let residuals = instantiated_immediate_lambda_residuals(
                &call,
                &immediate,
                actual,
                &current_output,
                frontier.owner(),
                frontier,
                tcx,
            )?;
            constrain_immediate_lambda_residuals(
                frontier,
                residuals,
                immediate.completed_layers.len(),
                call_site.span,
                tcx,
            )?;
        }
        call.immediate_lambda = Some(Box::new(immediate));
        Ok(SelectingOrdinaryCall {
            direct: None,
            call,
            candidates: candidates.to_vec(),
            next_candidate: 0,
            selected_slots: 0,
            value_slots: selected.width.capacity,
            selected_expanded_slots: 0,
            expanded_value_slots: selected.width.structural,
            selected: Vec::new(),
            probe: None,
            result_inferred_type_arg_suffix: 0,
            regular_ufcs: None,
        })
    }

    fn begin_ready_user_elaborator_terminal_public_layer(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        completed: &mut CompletedPathUnitGoalCall<'m>,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<Option<OrdinaryChildContinuation<'m>>, Error> {
        let Some(transcript) = completed.call.user_elaborator_transcript.as_ref() else {
            return Ok(None);
        };
        if !transcript.terminal_public_layer_ready() {
            return Ok(None);
        }
        let terminal = transcript
            .terminal_type_layer
            .as_ref()
            .expect("a ready terminal public layer retains its capability");
        assert_eq!(
            terminal.action, transcript.action,
            "an elaborator terminal layer crossed action identities"
        );
        assert_eq!(
            terminal.source_span,
            source.span(),
            "an elaborator terminal layer crossed source actions"
        );

        let returned = {
            let (store, _owner, delta, _publication) = frontier.parts_mut();
            store.zonk_for_progress(delta, completed.result.clone(), tcx)?
        };
        #[cfg(test)]
        if super::type_contains_goal(returned.ty().as_type()) {
            update_terminal_public_layer_work(|work| work.open_body_observations += 1);
        }
        let ambient_binders = tcx.in_scope_type_param_binders();
        let aliases = tcx.binder_alias_ctx(&ambient_binders);
        let (returned_head, _) = super::aliases::unfold_and_qualify_state(
            returned.ty().as_type(),
            &aliases,
            returned.ty().identity_is_canonical(),
        );
        if !matches!(returned_head, crate::ast::Type::Forall { .. }) {
            return Ok(None);
        }

        let split_after = completed.call.next_slot_offset();
        let (returned_params, _) = peel_forall_prefix(&returned_head);
        assert_eq!(
            returned_params.len(),
            terminal.params.len(),
            "an elaborator terminal successor changed binder arity"
        );
        for (returned, declared) in returned_params.iter().zip(&terminal.params) {
            assert_eq!(
                returned.effective_kind(),
                declared.effective_kind(),
                "an elaborator terminal successor changed binder kind"
            );
        }
        let callee = Synth::complete_scheme_interned(returned.ty().clone());
        let Some(preflight) = preflight_general_goal_call_layer(
            &callee,
            &[],
            EmptyCallMode::ResidualTypeApplication,
            tcx,
        )?
        else {
            return Err(non_function_call_error(&callee.ty, source.span(), tcx));
        };
        assert!(
            preflight.shape.result_is_pre_residual
                && !preflight.shape.has_value_layer
                && preflight.shape.type_args.is_empty()
                && preflight.shape.value_args.is_empty()
                && preflight.candidates.is_empty(),
            "an elaborator terminal preflight admitted a value or residual source"
        );
        assert_eq!(
            preflight.shape.binders.len(),
            terminal.params.len(),
            "an elaborator terminal preflight changed binder arity"
        );
        for (selected, declared) in preflight.shape.binders.iter().zip(&terminal.params) {
            assert_eq!(
                selected.effective_kind(),
                declared.effective_kind(),
                "an elaborator terminal preflight changed binder kind"
            );
        }

        let expected = match expected {
            Some(expected) => {
                let goal_free = {
                    let (store, owner, delta, _publication) = frontier.parts_mut();
                    let scoped = expected.clone().into_scoped(owner, store, source.span())?;
                    store.try_zonk_goal_free(delta, scoped, tcx)?.is_some()
                };
                goal_free.then_some(expected)
            }
            None => None,
        };

        #[cfg(test)]
        let parent_goal_count_before = frontier
            .store()
            .owner_goal_count_for_test(frontier.owner(), source.span());
        let mut parent_goals = Vec::with_capacity(preflight.shape.binders.len());
        for binder in &preflight.shape.binders {
            parent_goals.push(frontier.reserve_goal_in_live_delta(
                binder.effective_kind(),
                GoalSolutionPolicy::PolytypeAllowed,
                GoalOrigin::contextual_returned_forall(source.span(), binder.name.clone()),
            )?);
        }
        #[cfg(test)]
        {
            let parent_goal_count_after = frontier
                .store()
                .owner_goal_count_for_test(frontier.owner(), source.span());
            update_terminal_public_layer_work(|work| {
                work.reserved_slots += parent_goals.len();
                work.parent_goal_growth += parent_goal_count_after - parent_goal_count_before;
            });
        }
        {
            let (_store, _owner, publication) = frontier.publication_mut();
            publication.record_call_split(completed.call.call_site, split_after);
        }
        let transcript = completed
            .call
            .user_elaborator_transcript
            .take()
            .expect("the terminal successor retained its transcript");
        let returned_owner = frontier.owner();
        Self::begin_user_elaborator_terminal_public_layer(
            source,
            expected,
            OwnerBoundSynth::FunctionScheme {
                ty: OwnerBoundType::Retained {
                    owner: returned_owner,
                    ty: returned,
                },
                inferred_type_arg_suffix: 0,
            },
            preflight,
            parent_goals,
            split_after,
            transcript,
            frontier,
            tcx,
        )
        .map(Some)
    }

    #[allow(clippy::too_many_arguments)] // transition carries one complete selected-layer state
    fn prepare_finished_selected_layer(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        mut completed: Box<CompletedPathUnitGoalCall<'m>>,
        remaining: Vec<CallArgRef<'m, crate::ast::Lowered>>,
        split_after: usize,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<FinishedSelectedLayer<'m>, Error> {
        let declared_transition = completed
            .call
            .immediate_lambda
            .as_ref()
            .and_then(|immediate| immediate.declared_value_transition(&remaining, tcx));
        if let Some(transition) = declared_transition {
            {
                let (_store, _owner, publication) = frontier.publication_mut();
                publication.record_call_split(completed.call.call_site, split_after);
            }
            let selecting = Self::begin_next_immediate_value_layer(
                completed,
                remaining,
                transition,
                split_after,
                frontier,
                tcx,
            )?;
            return Ok(FinishedSelectedLayer::Selecting(Box::new(selecting)));
        }
        if remaining.is_empty() {
            if let Some(successor) = Self::begin_ready_user_elaborator_terminal_public_layer(
                source,
                expected.clone(),
                &mut completed,
                frontier,
                tcx,
            )? {
                return Ok(FinishedSelectedLayer::Successor(successor));
            }
            let completed_immediate = completed.call.immediate_lambda.as_ref();
            let post_body_expected = completed_immediate.and_then(|immediate| {
                assert!(
                    matches!(immediate.body, ImmediateLambdaBodyState::Complete { .. })
                        && matches!(
                                source,
                                crate::ast::Expr::Call { callee, .. }
                                    if std::ptr::eq(callee.as_ref(), immediate.source)
                        ),
                    "a post-body expectation crossed immediate lambda lifecycles"
                );
                immediate.outer_expected.clone()
            });
            assert!(
                post_body_expected.is_none() || expected.is_some(),
                "a completed immediate lambda lost its enclosing expected type"
            );
            let returned = {
                let (store, _owner, delta, _publication) = frontier.parts_mut();
                if post_body_expected.is_some() {
                    Some(store.zonk_for_progress(delta, completed.result.clone(), tcx)?)
                } else {
                    store.try_zonk_goal_free(delta, completed.result.clone(), tcx)?
                }
            };
            if let Some(returned) = returned {
                let ambient_binders = tcx.in_scope_type_param_binders();
                let aliases = tcx.binder_alias_ctx(&ambient_binders);
                let (returned_head, _returned_canonical) = super::aliases::unfold_and_qualify_state(
                    returned.ty().as_type(),
                    &aliases,
                    returned.ty().identity_is_canonical(),
                );
                let effective_expected = post_body_expected.as_ref().or_else(|| {
                    completed_immediate
                        .is_none()
                        .then_some(expected.as_ref())
                        .flatten()
                });
                let progressed_expected = if let Some(expected) = effective_expected {
                    let (store, owner, delta, _publication) = frontier.parts_mut();
                    let expected = expected.clone().into_scoped(owner, store, source.span())?;
                    Some(store.zonk_for_progress(delta, expected, tcx)?)
                } else {
                    None
                };
                let expected_head = progressed_expected.as_ref().map(|expected| {
                    super::aliases::unfold_and_qualify_state(
                        expected.ty().as_type(),
                        &aliases,
                        expected.ty().identity_is_canonical(),
                    )
                    .0
                });
                let expected_is_open_whole_goal = matches!(
                    expected_head.as_ref(),
                    Some(crate::ast::Type::Goal { args, .. }) if args.is_empty()
                );
                let contextual_instantiation = expected_head.as_ref().is_some_and(|expected| {
                    !matches!(expected, crate::ast::Type::Forall { .. })
                        && !matches!(expected, crate::ast::Type::Goal { args, .. } if args.is_empty())
                });
                if matches!(returned_head, crate::ast::Type::Forall { .. })
                    && expected_is_open_whole_goal
                    && mode != frontier::FrontierMode::Final
                {
                    return Ok(FinishedSelectedLayer::Ready(OrdinaryValueAdvance::pending(
                        Self {
                            source,
                            expected,
                            planned: PlannedOrdinaryValue::Call(
                                OrdinaryCallContinuation::AwaitingReturnedForall {
                                    completed,
                                    split_after,
                                },
                            ),
                        },
                    )));
                }
                if matches!(returned_head, crate::ast::Type::Forall { .. })
                    && (matches!(expected_head, Some(crate::ast::Type::Forall { .. }))
                        || expected_is_open_whole_goal)
                {
                    if post_body_expected.is_some() {
                        let expected = completed
                            .call
                            .immediate_lambda
                            .as_mut()
                            .and_then(|immediate| immediate.outer_expected.take())
                            .expect("a post-body returned-Forall equation lost its expectation");
                        let advancing = Box::new(AdvancingOrdinaryCall {
                            call: completed.call,
                            result: completed.result,
                            result_inferred_type_arg_suffix: completed
                                .result_inferred_type_arg_suffix,
                            destination: frontier.owner(),
                            pending: Vec::new(),
                            pending_expected_result: Some(PendingExpectedResult::new(expected)),
                        });
                        return Ok(FinishedSelectedLayer::Advancing(AdvancingOrdinaryLayer {
                            advancing,
                            remaining: Vec::new(),
                            split_after,
                        }));
                    }
                    let expected = effective_expected
                        .expect("a whole returned-Forall equation has an expected type");
                    assert!(
                        try_apply_expected_equation(
                            frontier,
                            completed.result.clone(),
                            expected,
                            source.span(),
                            tcx,
                        )?,
                        "a goal-free returned Forall and its ready whole expectation must close"
                    );
                }
                if matches!(returned_head, crate::ast::Type::Forall { .. })
                    && contextual_instantiation
                {
                    {
                        let (_store, _owner, publication) = frontier.publication_mut();
                        publication.record_call_split(completed.call.call_site, split_after);
                    }
                    if post_body_expected.is_some() {
                        let marker = completed
                            .call
                            .immediate_lambda
                            .take()
                            .expect("a contextual successor lost its immediate marker");
                        assert!(
                            matches!(marker.body, ImmediateLambdaBodyState::Complete { .. })
                                && marker.outer_expected.is_some(),
                            "a contextual successor consumed an incomplete immediate lambda"
                        );
                    }
                    let returned_owner = frontier.owner();
                    let successor = Self::begin_selected_successor(
                        source,
                        completed.call.call_site,
                        OwnerBoundSynth::FunctionScheme {
                            ty: OwnerBoundType::Retained {
                                owner: returned_owner,
                                ty: returned,
                            },
                            inferred_type_arg_suffix: completed.result_inferred_type_arg_suffix,
                        },
                        Vec::new(),
                        split_after,
                        completed.call.user_elaborator_transcript.take(),
                        effective_expected.cloned(),
                        EmptyCallMode::ResidualTypeApplication,
                        frontier,
                        tcx,
                    )?;
                    return Ok(FinishedSelectedLayer::Successor(successor));
                }
            }
            let retained_callable =
                if expected.is_none() && demand == OrdinaryCompletionDemand::ImmediateCallee {
                    Self::retain_callable_progress(&mut completed.result, frontier, tcx)?
                } else {
                    None
                };
            {
                let (_store, _owner, publication) = frontier.publication_mut();
                match retained_callable {
                    Some(RetainedCallableProgress::FunctionScheme) => {
                        publication.record_scoped_function_scheme_position_type(
                            source.span(),
                            completed.result.clone(),
                            tcx.in_scope_type_param_presentation(),
                        );
                    }
                    Some(
                        RetainedCallableProgress::Function
                        | RetainedCallableProgress::PolymorphicValue,
                    )
                    | None => {
                        publication.record_position_type(
                            source.span(),
                            completed.result.clone(),
                            tcx.in_scope_type_param_presentation(),
                        );
                    }
                }
                if completed.call.shape.has_written_type_only()
                    || completed.call.shape.result_is_pre_residual
                {
                    completed
                        .call
                        .stage_residual_eta_once(completed.result.clone(), publication);
                }
            }
            if let Some(progress) = retained_callable {
                return Ok(FinishedSelectedLayer::Ready(
                    OrdinaryValueAdvance::Complete(Self::completed_retained_callable(
                        completed, progress,
                    )),
                ));
            }
            if expected.is_none() || demand == OrdinaryCompletionDemand::PublicHeader {
                let goal_free = {
                    let (store, _owner, delta, _publication) = frontier.parts_mut();
                    store
                        .try_zonk_goal_free(delta, completed.result.clone(), tcx)?
                        .is_some()
                };
                if !goal_free {
                    if mode.executes_relation_actions()
                        && completed.call.user_elaborator_transcript.is_some()
                    {
                        let transcript = completed
                            .call
                            .user_elaborator_transcript
                            .take()
                            .expect("the elaborator transcript was checked above");
                        return Ok(FinishedSelectedLayer::Ready(
                            OrdinaryValueAdvance::Complete(CompletedInFrame::UserElaboratorCall {
                                output: completed.result,
                                inferred_type_arg_suffix: completed.result_inferred_type_arg_suffix,
                                transcript,
                            }),
                        ));
                    }
                    if mode == frontier::FrontierMode::Final {
                        let (store, _owner, delta, _publication) = frontier.parts_mut();
                        let _ =
                            store.require_goal_free_after_delta(delta, completed.result, tcx)?;
                        unreachable!("a selected final call remained unresolved after Final")
                    }
                    return Ok(FinishedSelectedLayer::Ready(OrdinaryValueAdvance::pending(
                        Self {
                            source,
                            expected,
                            planned: PlannedOrdinaryValue::Call(
                                OrdinaryCallContinuation::AwaitingExpected(completed),
                            ),
                        },
                    )));
                }
            }
            return Ok(FinishedSelectedLayer::Ready(
                OrdinaryValueAdvance::Complete(Self::completed_selected_call(completed)),
            ));
        }

        {
            let (_store, _owner, publication) = frontier.publication_mut();
            publication.record_call_split(completed.call.call_site, split_after);
        }
        // The completed layer may have solved goals that occur in its return
        // type.  A flat-call successor must inspect that progressed type, not
        // the pre-solution spelling retained by the open call; otherwise a
        // concrete non-function result is reported as the internal `_` goal
        // and a concrete function result can lose its selected call shape.
        let progressed = {
            let (store, _owner, delta, _publication) = frontier.parts_mut();
            store.zonk_for_progress(delta, completed.result.clone(), tcx)?
        };
        let successor_owner = frontier.owner();
        let successor = Self::begin_selected_successor(
            source,
            completed.call.call_site,
            OwnerBoundSynth::Value {
                ty: OwnerBoundType::Retained {
                    owner: successor_owner,
                    ty: progressed,
                },
                inferred_type_arg_suffix: completed.result_inferred_type_arg_suffix,
            },
            remaining,
            split_after,
            completed.call.user_elaborator_transcript.take(),
            expected.clone(),
            EmptyCallMode::ImplicitUnit,
            frontier,
            tcx,
        )?;
        Ok(FinishedSelectedLayer::Successor(successor))
    }

    fn finish_selected_layer_step(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        completion: SelectedLayerCompletion<'m>,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
        frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryDriverStep<'m>, Error> {
        let SelectedLayerCompletion {
            completed,
            remaining,
            split_after,
        } = completion;
        match Self::prepare_finished_selected_layer(
            source,
            expected.clone(),
            completed,
            remaining,
            split_after,
            mode,
            demand,
            frontier,
            tcx,
        )? {
            FinishedSelectedLayer::Ready(advanced) => Ok(OrdinaryDriverStep::Ready(advanced)),
            FinishedSelectedLayer::Selecting(selecting) => Self::advance_selecting_call_step(
                source, expected, selecting, mode, demand, frontier, tcx,
            ),
            FinishedSelectedLayer::Advancing(layer) => Self::advance_selected_layer_step(
                source, expected, layer, mode, demand, frontier, tcx,
            ),
            FinishedSelectedLayer::Successor(successor) => {
                if matches!(
                    &successor.cursor.planned,
                    PlannedOrdinaryValue::Call(call)
                        if call.user_elaborator_transcript().is_some()
                ) {
                    // The elaborator wrapper owns cross-layer state (including marked projected
                    // sources). Yield the successor before entering it so that state migrates to
                    // the next layer even when the whole successor could otherwise close in one
                    // driver turn.
                    return Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::pending(
                        Self {
                            source,
                            expected,
                            planned: PlannedOrdinaryValue::Call(
                                OrdinaryCallContinuation::Successor(successor),
                            ),
                        },
                    )));
                }
                Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
                    child: successor,
                    inherited_mode: mode,
                    demand,
                    handoff: OrdinaryDriverHandoff::Current(Box::new(
                        move |result, _frontier, _tcx| {
                            let advanced = match result {
                                OrdinaryChildAdvance::Complete(completed) => {
                                    OrdinaryValueAdvance::Complete(completed)
                                }
                                OrdinaryChildAdvance::Pending(successor) => {
                                    OrdinaryValueAdvance::pending(Self {
                                        source,
                                        expected,
                                        planned: PlannedOrdinaryValue::Call(
                                            OrdinaryCallContinuation::Successor(successor),
                                        ),
                                    })
                                }
                            };
                            Ok(OrdinaryDriverStep::Ready(advanced))
                        },
                    )),
                    scope_exit: OrdinaryDriverScopeExit::None,
                }))
            }
        }
    }

    fn advance_selected_layer_step(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        layer: AdvancingOrdinaryLayer<'m>,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
        frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryDriverStep<'m>, Error> {
        let AdvancingOrdinaryLayer {
            advancing,
            remaining,
            split_after,
        } = layer;
        let declared_transition = advancing
            .call
            .immediate_lambda
            .as_ref()
            .and_then(|immediate| immediate.declared_value_transition(&remaining, tcx));
        let contextual_returned_forall_boundary = remaining
            .is_empty()
            .then_some(ContextualReturnedForallBoundary);
        advance_general_goal_call_mode_driver(
            frontier,
            advancing,
            mode,
            declared_transition,
            contextual_returned_forall_boundary,
            tcx,
            Box::new(move |advanced, frontier, tcx| match advanced {
                GeneralGoalCallAdvance::Pending(advancing) => Ok(OrdinaryDriverStep::Ready(
                    OrdinaryValueAdvance::pending(Self {
                        source,
                        expected,
                        planned: PlannedOrdinaryValue::Call(
                            OrdinaryCallContinuation::AdvancingLayer(AdvancingOrdinaryLayer {
                                advancing,
                                remaining,
                                split_after,
                            }),
                        ),
                    }),
                )),
                GeneralGoalCallAdvance::Complete(completed) => Self::finish_selected_layer_step(
                    source,
                    expected,
                    SelectedLayerCompletion {
                        completed,
                        remaining,
                        split_after,
                    },
                    mode,
                    demand,
                    frontier,
                    tcx,
                ),
                GeneralGoalCallAdvance::ContextualReturnedForall(pending) => {
                    assert!(
                        declared_transition.is_none() && remaining.is_empty(),
                        "a contextual returned-Forall crossed a declared value layer"
                    );
                    let advancing = Self::arm_contextual_returned_forall(
                        source,
                        pending,
                        split_after,
                        frontier,
                        tcx,
                    )?;
                    Ok(OrdinaryDriverStep::Continue(Box::new(
                        move |frontier, tcx| {
                            Self::advance_selected_layer_step(
                                source,
                                expected,
                                AdvancingOrdinaryLayer {
                                    advancing,
                                    remaining,
                                    split_after,
                                },
                                mode,
                                demand,
                                frontier,
                                tcx,
                            )
                        },
                    )))
                }
            }),
        )
    }

    #[allow(clippy::never_loop)] // one child step must return to the heap driver; `break` enters the shared finalization path
    fn poll_selecting_call(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        mut selecting: Box<SelectingOrdinaryCall<'m>>,
        mode: frontier::FrontierMode,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<SelectingOrdinaryCallAdvance<'m>, Error> {
        let needs_immediate_reservation =
            selecting
                .call
                .immediate_lambda
                .as_ref()
                .is_some_and(|immediate| {
                    matches!(immediate.body, ImmediateLambdaBodyState::NeedsReservation)
                });
        if needs_immediate_reservation {
            let immediate = selecting
                .call
                .immediate_lambda
                .as_ref()
                .expect("an immediate reservation transition lost its lambda");
            let source_span = immediate.source.span();
            let mut header = selecting
                .call
                .immediate_lambda
                .as_mut()
                .expect("an immediate reservation transition lost its lambda")
                .header
                .take()
                .expect("an immediate lambda lost its source header plan");
            let sig = match selecting
                .call
                .immediate_lambda
                .as_ref()
                .expect("an immediate reservation transition lost its lambda")
                .source
            {
                crate::ast::Expr::FnExpr { sig, .. } => sig,
                _ => unreachable!("an immediate lambda retained another source family"),
            };
            let retained_binders = Self::retain_lambda_binders(sig, tcx);
            let lambda_owners = Self::reserve_lambda_owner_chain(
                source_span,
                sig,
                &mut header,
                &retained_binders,
                frontier,
                tcx,
            )?;
            let immediate = selecting
                .call
                .immediate_lambda
                .as_mut()
                .expect("an immediate reservation transition lost its lambda");
            immediate.header = Some(header);
            immediate.retained_binders = Some(retained_binders);
            immediate.body = ImmediateLambdaBodyState::AwaitingEvidence(lambda_owners);
        }
        if let Some(direct) = selecting.direct.take() {
            let (store, owner, publication) = frontier.publication_mut();
            direct.stage_type(owner, store, publication, tcx)?;
        }
        if let Some((node_id, replacement)) = selecting.regular_ufcs.take() {
            let (store, _owner, publication) = frontier.publication_mut();
            publication.record_lowered_elaboration(store, node_id, replacement);
        }

        if selecting.value_slots == 0 && !selecting.candidates.is_empty() {
            return Err(
                Error::type_(source.span(), "too many arguments in this call").with_help(
                    "spell the zero-argument application before applying the returned function",
                ),
            );
        }

        while selecting.selected_slots < selecting.value_slots {
            let (probe, probe_mode) = match selecting.probe.take() {
                Some(probe) => (probe, mode),
                None => {
                    let Some(candidate) =
                        selecting.candidates.get(selecting.next_candidate).copied()
                    else {
                        break;
                    };
                    let CallArgRef::Value(candidate) = candidate else {
                        return Err(Error::type_(
                            candidate.span(),
                            "expected a value argument here, got a type argument",
                        ));
                    };
                    let packet_final =
                        Self::current_source_ends_written_packet(&selecting, frontier, tcx)?;
                    let remaining_slots = selecting.value_slots - selecting.selected_slots;
                    // Structural-flat packets are deterministic: every
                    // non-final source owns one slot, while the final source
                    // owns the packet's remaining right-spine. Supplying that
                    // exact expectation before probing lets a nested call use
                    // known leaves without searching alternative suffixes.
                    let selected_width = if packet_final { remaining_slots } else { 1 };
                    let expanded_start = selecting.selected_expanded_slots;
                    let (expected, selected_slots_after, selected_expanded_slots_after) =
                        Self::selected_source_expectation(
                            &mut selecting,
                            candidate,
                            selected_width,
                            packet_final,
                            frontier,
                            tcx,
                        )?;
                    let immediate_evidence = selecting
                        .call
                        .immediate_lambda
                        .as_ref()
                        .and_then(|immediate| immediate.evidence_in(expected.ty().as_type()));
                    let preselected = Some(PreselectedOrdinaryValue {
                        expected,
                        immediate_evidence,
                        expanded_start,
                        selected_slots_after,
                        selected_expanded_slots_after,
                    });
                    let child_expected = preselected.as_ref().and_then(|preselected| {
                        preselected
                            .immediate_evidence
                            .is_none()
                            .then(|| preselected.expected.clone())
                    });
                    let child = Self::begin_child(candidate, child_expected, frontier, tcx)?;
                    if let PlannedOrdinaryValue::Lambda(lambda) = &child.cursor.planned
                        && let Some(expected) = child.cursor.expected.as_ref()
                        && let Some(written) =
                            lambda.header.complete_written_type(candidate.span(), tcx)?
                    {
                        let (store, owner, delta, _) = frontier.parts_mut();
                        let written = store.scoped_type(owner, written, candidate.span())?;
                        let expected = expected.clone().into_expected_equation_operand(
                            owner,
                            store,
                            candidate.span(),
                        )?;
                        store.constrain_equation(
                            delta,
                            written,
                            expected,
                            candidate.span(),
                            tcx,
                        )?;
                    }
                    (
                        SelectingOrdinaryValue { child, preselected },
                        frontier::FrontierMode::ExpectedOnly,
                    )
                }
            };
            let candidate = match selecting.candidates[selecting.next_candidate] {
                CallArgRef::Value(candidate) => candidate,
                CallArgRef::Type(_) => {
                    unreachable!("a selecting value probe lost its source expression")
                }
            };
            let SelectingOrdinaryValue {
                mut child,
                preselected,
            } = probe;
            let has_immediate_evidence = preselected
                .as_ref()
                .is_some_and(|selected| selected.immediate_evidence.is_some());
            if child.cursor.needs_selected_width_one_expectation() && !has_immediate_evidence {
                let (
                    selected_expected,
                    immediate_evidence,
                    expanded_start,
                    selected_slots_after,
                    selected_expanded_slots_after,
                ) = match preselected {
                    Some(preselected) => (
                        preselected.expected,
                        preselected.immediate_evidence,
                        preselected.expanded_start,
                        preselected.selected_slots_after,
                        preselected.selected_expanded_slots_after,
                    ),
                    None => {
                        let expanded_start = selecting.selected_expanded_slots;
                        let packet_final =
                            Self::current_source_ends_written_packet(&selecting, frontier, tcx)?;
                        let (
                            selected_expected,
                            selected_slots_after,
                            selected_expanded_slots_after,
                        ) = Self::selected_source_expectation(
                            &mut selecting,
                            candidate,
                            1,
                            packet_final,
                            frontier,
                            tcx,
                        )?;
                        (
                            selected_expected,
                            None,
                            expanded_start,
                            selected_slots_after,
                            selected_expanded_slots_after,
                        )
                    }
                };
                if child.cursor.expected.is_none() {
                    if child.cursor.awaits_expected() {
                        child.cursor.supply_expected(selected_expected.clone());
                    } else {
                        child.cursor.expected = Some(selected_expected.clone());
                    }
                }
                child.next_mode = frontier::FrontierMode::ExpectedOnly;
                return Ok(SelectingOrdinaryCallAdvance::Descend {
                    child,
                    inherited_mode: frontier::FrontierMode::ExpectedOnly,
                    resume: SelectingOrdinaryCallResume::Preselected {
                        selecting,
                        candidate,
                        expected: selected_expected,
                        immediate_evidence,
                        expanded_start,
                        selected_slots_after,
                        selected_expanded_slots_after,
                    },
                });
            }
            return Ok(SelectingOrdinaryCallAdvance::Descend {
                child,
                inherited_mode: probe_mode,
                resume: SelectingOrdinaryCallResume::Probe {
                    selecting,
                    candidate,
                    preselected,
                },
            });
        }

        let mut selecting = *selecting;
        if selecting.selected_slots < selecting.value_slots && selecting.candidates.is_empty() {
            let split_after = selecting.call.next_slot_offset();
            let immediate_unit_evidence = if selecting.call.shape.has_implicit_unit_value() {
                selecting
                    .call
                    .immediate_lambda
                    .as_ref()
                    .and_then(|immediate| {
                        immediate.evidence_in(selecting.call.remaining_param.solver.as_type())
                    })
            } else {
                None
            };
            let is_immediate = selecting.call.immediate_lambda.is_some();
            let returned = selecting.call.result_type(frontier.goal_owner());
            let ambient_binders = tcx.in_scope_type_param_binders();
            let (returned_head, _) = super::aliases::unfold_and_qualify_state(
                returned.as_type(),
                &tcx.binder_alias_ctx(&ambient_binders),
                returned.identity_is_canonical(),
            );
            let returned_forall = matches!(returned_head, crate::ast::Type::Forall { .. });
            let pending_expected_result = (!is_immediate && !returned_forall)
                .then(|| expected.clone())
                .flatten()
                .map(PendingExpectedResult::new);
            if let Some(immediate) = selecting.call.immediate_lambda.as_mut() {
                immediate.outer_expected = expected.clone();
            }
            let mut completed = advance_path_unit_goal_call(
                frontier,
                selecting.call,
                Vec::new(),
                selecting.result_inferred_type_arg_suffix,
                None,
                tcx,
            )?;
            if let Some(immediate_unit_evidence) = immediate_unit_evidence {
                completed
                    .call
                    .immediate_lambda
                    .as_mut()
                    .expect("implicit Unit evidence outlived its direct lambda")
                    .mark_observed(&immediate_unit_evidence);
            }
            let advancing = AdvancingOrdinaryCall {
                call: completed.call,
                result: completed.result,
                result_inferred_type_arg_suffix: completed.result_inferred_type_arg_suffix,
                destination: frontier.owner(),
                pending: Vec::new(),
                pending_expected_result,
            };
            return Ok(SelectingOrdinaryCallAdvance::Layer(
                AdvancingOrdinaryLayer {
                    advancing: Box::new(advancing),
                    remaining: Vec::new(),
                    split_after,
                },
            ));
        }
        if selecting.selected_slots < selecting.value_slots {
            return Err(Error::type_(
                source.span(),
                "too few arguments in this call",
            ));
        }

        let remaining = selecting.candidates[selecting.next_candidate..].to_vec();
        let split_after = selecting.call.next_slot_offset();
        let returned_forall = if remaining.is_empty() {
            let returned = selecting.call.result_type(frontier.goal_owner());
            let ambient_binders = tcx.in_scope_type_param_binders();
            let (head, _) = super::aliases::unfold_and_qualify_state(
                returned.as_type(),
                &tcx.binder_alias_ctx(&ambient_binders),
                returned.identity_is_canonical(),
            );
            matches!(head, crate::ast::Type::Forall { .. })
        } else {
            false
        };
        let is_immediate = selecting.call.immediate_lambda.is_some();
        let expected_result = (remaining.is_empty() && !returned_forall && !is_immediate)
            .then(|| expected.clone())
            .flatten();
        if let Some(immediate) = selecting.call.immediate_lambda.as_mut() {
            immediate.outer_expected = remaining.is_empty().then(|| expected.clone()).flatten();
        }
        let advancing = begin_general_goal_call(
            frontier,
            selecting.call,
            selecting.selected,
            selecting.result_inferred_type_arg_suffix,
            expected_result,
            tcx,
        )?;
        Ok(SelectingOrdinaryCallAdvance::Layer(
            AdvancingOrdinaryLayer {
                advancing: Box::new(advancing),
                remaining,
                split_after,
            },
        ))
    }

    #[allow(clippy::too_many_arguments)]
    fn resume_selecting_call(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        resume: SelectingOrdinaryCallResume<'m>,
        result: OrdinaryChildAdvance<'m>,
        mode: frontier::FrontierMode,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<SelectingOrdinaryCallAdvance<'m>, Error> {
        let selecting = match resume {
            SelectingOrdinaryCallResume::Preselected {
                mut selecting,
                candidate,
                expected: selected_expected,
                immediate_evidence,
                expanded_start,
                selected_slots_after,
                selected_expanded_slots_after,
            } => {
                let value = match result {
                    OrdinaryChildAdvance::Complete(output) => OrdinaryCallValue::Completed {
                        source: candidate,
                        output,
                    },
                    OrdinaryChildAdvance::Pending(child) => OrdinaryCallValue::Retained(child),
                };
                selecting.selected.push(SelectedOrdinaryCallValue {
                    value,
                    expected: selected_expected,
                    immediate_evidence,
                    expanded_start,
                    expanded_width: selected_expanded_slots_after - expanded_start,
                });
                selecting.selected_slots = selected_slots_after;
                selecting.selected_expanded_slots = selected_expanded_slots_after;
                selecting.next_candidate += 1;
                selecting
            }
            SelectingOrdinaryCallResume::Probe {
                mut selecting,
                candidate,
                preselected,
            } => match result {
                OrdinaryChildAdvance::Pending(mut child) => {
                    if let Some(preselected) = preselected {
                        selecting.selected.push(SelectedOrdinaryCallValue {
                            value: OrdinaryCallValue::Retained(child),
                            expected: preselected.expected,
                            immediate_evidence: preselected.immediate_evidence,
                            expanded_start: preselected.expanded_start,
                            expanded_width: preselected.selected_expanded_slots_after
                                - preselected.expanded_start,
                        });
                        selecting.selected_slots = preselected.selected_slots_after;
                        selecting.selected_expanded_slots =
                            preselected.selected_expanded_slots_after;
                        selecting.next_candidate += 1;
                        selecting
                    } else if child.cursor.awaits_expected() {
                        let expanded_start = selecting.selected_expanded_slots;
                        let packet_final =
                            Self::current_source_ends_written_packet(&selecting, frontier, tcx)?;
                        let (
                            selected_expected,
                            selected_slots_after,
                            selected_expanded_slots_after,
                        ) = Self::selected_source_expectation(
                            &mut selecting,
                            candidate,
                            1,
                            packet_final,
                            frontier,
                            tcx,
                        )?;
                        child.cursor.supply_expected(selected_expected.clone());
                        child.next_mode = frontier::FrontierMode::ExpectedOnly;
                        selecting.selected.push(SelectedOrdinaryCallValue {
                            value: OrdinaryCallValue::Retained(child),
                            expected: selected_expected,
                            immediate_evidence: None,
                            expanded_start,
                            expanded_width: selected_expanded_slots_after - expanded_start,
                        });
                        selecting.selected_slots = selected_slots_after;
                        selecting.selected_expanded_slots = selected_expanded_slots_after;
                        selecting.next_candidate += 1;
                        selecting
                    } else {
                        selecting.probe = Some(SelectingOrdinaryValue {
                            child,
                            preselected: None,
                        });
                        return Ok(SelectingOrdinaryCallAdvance::Ready(
                            OrdinaryValueAdvance::pending(Self {
                                source,
                                expected,
                                planned: PlannedOrdinaryValue::Call(
                                    OrdinaryCallContinuation::Selecting(selecting),
                                ),
                            }),
                        ));
                    }
                }
                OrdinaryChildAdvance::Complete(completed) => {
                    let (
                        selected_expected,
                        immediate_evidence,
                        expanded_start,
                        selected_slots_after,
                        selected_expanded_slots_after,
                    ) = match preselected {
                        Some(preselected) => (
                            preselected.expected,
                            preselected.immediate_evidence,
                            preselected.expanded_start,
                            preselected.selected_slots_after,
                            preselected.selected_expanded_slots_after,
                        ),
                        None => {
                            let packet_final = Self::current_source_ends_written_packet(
                                &selecting, frontier, tcx,
                            )?;
                            let remaining_slots = selecting.value_slots - selecting.selected_slots;
                            let width = if packet_final { remaining_slots } else { 1 };
                            let expanded_start = selecting.selected_expanded_slots;
                            let (
                                selected_expected,
                                selected_slots_after,
                                selected_expanded_slots_after,
                            ) = Self::selected_source_expectation(
                                &mut selecting,
                                candidate,
                                width,
                                packet_final,
                                frontier,
                                tcx,
                            )?;
                            let immediate_evidence = selecting
                                .call
                                .immediate_lambda
                                .as_ref()
                                .and_then(|immediate| {
                                    immediate.evidence_in(selected_expected.ty().as_type())
                                });
                            (
                                selected_expected,
                                immediate_evidence,
                                expanded_start,
                                selected_slots_after,
                                selected_expanded_slots_after,
                            )
                        }
                    };
                    if matches!(completed, CompletedInFrame::FunctionScheme(_, _)) {
                        let ambient_binders = tcx.in_scope_type_param_binders();
                        let (expected_head, _) = super::aliases::unfold_and_qualify_state(
                            selected_expected.ty().as_type(),
                            &tcx.binder_alias_ctx(&ambient_binders),
                            selected_expected.ty().identity_is_canonical(),
                        );
                        let expected_accepts_scheme = matches!(
                            expected_head,
                            crate::ast::Type::Forall { .. } | crate::ast::Type::Goal { .. }
                        );
                        let evidence_accepts_scheme =
                            immediate_evidence.as_deref().is_some_and(|evidence| {
                                ImmediateLambdaCall::accepts_function_scheme_evidence(
                                    &selected_expected,
                                    evidence,
                                )
                            });
                        if !expected_accepts_scheme && !evidence_accepts_scheme {
                            return Err(super::types::scheme_in_mono_position(candidate.span()));
                        }
                    }
                    selecting.selected.push(SelectedOrdinaryCallValue {
                        value: OrdinaryCallValue::Completed {
                            source: candidate,
                            output: completed,
                        },
                        expected: selected_expected,
                        immediate_evidence,
                        expanded_start,
                        expanded_width: selected_expanded_slots_after - expanded_start,
                    });
                    selecting.selected_slots = selected_slots_after;
                    selecting.selected_expanded_slots = selected_expanded_slots_after;
                    selecting.next_candidate += 1;
                    selecting
                }
            },
        };
        Self::poll_selecting_call(source, expected, selecting, mode, frontier, tcx)
    }

    fn selecting_call_driver_step(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
        advance: SelectingOrdinaryCallAdvance<'m>,
        frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryDriverStep<'m>, Error> {
        match advance {
            SelectingOrdinaryCallAdvance::Ready(advanced) => {
                Ok(OrdinaryDriverStep::Ready(advanced))
            }
            SelectingOrdinaryCallAdvance::Layer(layer) => Self::advance_selected_layer_step(
                source, expected, layer, mode, demand, frontier, tcx,
            ),
            SelectingOrdinaryCallAdvance::Descend {
                child,
                inherited_mode,
                resume,
            } => Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
                child,
                inherited_mode,
                demand: OrdinaryCompletionDemand::GoalFreeValue,
                handoff: OrdinaryDriverHandoff::Current(Box::new(move |result, frontier, tcx| {
                    let advance = Self::resume_selecting_call(
                        source,
                        expected.clone(),
                        resume,
                        result,
                        mode,
                        frontier,
                        tcx,
                    )?;
                    Self::selecting_call_driver_step(
                        source, expected, mode, demand, advance, frontier, tcx,
                    )
                })),
                scope_exit: OrdinaryDriverScopeExit::None,
            })),
        }
    }

    fn advance_selecting_call_step(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        selecting: Box<SelectingOrdinaryCall<'m>>,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
        frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryDriverStep<'m>, Error> {
        let advance =
            Self::poll_selecting_call(source, expected.clone(), selecting, mode, frontier, tcx)?;
        Self::selecting_call_driver_step(source, expected, mode, demand, advance, frontier, tcx)
    }

    fn advance_call_step(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        continuation: OrdinaryCallContinuation<'m>,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
        frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryDriverStep<'m>, Error> {
        match continuation {
            OrdinaryCallContinuation::Selecting(selecting) => Self::advance_selecting_call_step(
                source, expected, selecting, mode, demand, frontier, tcx,
            ),
            OrdinaryCallContinuation::AdvancingLayer(layer) => Self::advance_selected_layer_step(
                source, expected, layer, mode, demand, frontier, tcx,
            ),
            OrdinaryCallContinuation::Successor(child) => {
                Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
                    child,
                    inherited_mode: mode,
                    demand,
                    handoff: OrdinaryDriverHandoff::Current(Box::new(
                        move |result, _frontier, _tcx| {
                            let advanced = match result {
                                OrdinaryChildAdvance::Complete(completed) => {
                                    OrdinaryValueAdvance::Complete(completed)
                                }
                                OrdinaryChildAdvance::Pending(successor) => {
                                    OrdinaryValueAdvance::pending(Self {
                                        source,
                                        expected,
                                        planned: PlannedOrdinaryValue::Call(
                                            OrdinaryCallContinuation::Successor(successor),
                                        ),
                                    })
                                }
                            };
                            Ok(OrdinaryDriverStep::Ready(advanced))
                        },
                    )),
                    scope_exit: OrdinaryDriverScopeExit::None,
                }))
            }
            continuation => Self::advance_single_layer_call_step(
                source,
                expected,
                continuation,
                mode,
                demand,
                frontier,
                tcx,
            ),
        }
    }

    fn advance_single_layer_call_step(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        continuation: OrdinaryCallContinuation<'m>,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
        frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryDriverStep<'m>, Error> {
        let advancing = match continuation {
            OrdinaryCallContinuation::Advancing(advancing) => advancing,
            OrdinaryCallContinuation::AwaitingReturnedForall {
                completed,
                split_after,
            } => {
                return Self::finish_selected_layer_step(
                    source,
                    expected,
                    SelectedLayerCompletion {
                        completed,
                        remaining: Vec::new(),
                        split_after,
                    },
                    mode,
                    demand,
                    frontier,
                    tcx,
                );
            }
            OrdinaryCallContinuation::Selecting(_)
            | OrdinaryCallContinuation::AdvancingLayer(_)
            | OrdinaryCallContinuation::Successor(_) => {
                unreachable!("a layered call reached the single-layer dispatcher")
            }
            OrdinaryCallContinuation::AwaitingExpected(completed) => {
                let Some(expected_equation) = expected.clone() else {
                    return Self::finish_awaiting_expected_without_expected(
                        source, completed, mode, demand, frontier, tcx,
                    )
                    .map(OrdinaryDriverStep::Ready);
                };
                Box::new(AdvancingOrdinaryCall {
                    call: completed.call,
                    result: completed.result,
                    result_inferred_type_arg_suffix: completed.result_inferred_type_arg_suffix,
                    destination: frontier.owner(),
                    pending: Vec::new(),
                    pending_expected_result: Some(PendingExpectedResult::new(expected_equation)),
                })
            }
        };
        Self::advance_single_layer_advancing_step(
            source, expected, advancing, mode, demand, frontier, tcx,
        )
    }

    fn advance_single_layer_advancing_step(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        advancing: Box<AdvancingOrdinaryCall<'m>>,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
        frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryDriverStep<'m>, Error> {
        advance_general_goal_call_mode_driver(
            frontier,
            advancing,
            mode,
            None,
            Some(ContextualReturnedForallBoundary),
            tcx,
            Box::new(move |advanced, frontier, tcx| match advanced {
                GeneralGoalCallAdvance::Pending(advancing) => Ok(OrdinaryDriverStep::Ready(
                    OrdinaryValueAdvance::pending(Self {
                        source,
                        expected,
                        planned: PlannedOrdinaryValue::Call(OrdinaryCallContinuation::Advancing(
                            advancing,
                        )),
                    }),
                )),
                GeneralGoalCallAdvance::Complete(completed) => Self::finish_completed_single_layer(
                    source, expected, completed, mode, demand, frontier, tcx,
                )
                .map(OrdinaryDriverStep::Ready),
                GeneralGoalCallAdvance::ContextualReturnedForall(pending) => {
                    let split_after = pending.call.next_slot_offset();
                    let advancing = Self::arm_contextual_returned_forall(
                        source,
                        pending,
                        split_after,
                        frontier,
                        tcx,
                    )?;
                    Ok(OrdinaryDriverStep::Continue(Box::new(
                        move |frontier, tcx| {
                            Self::advance_single_layer_advancing_step(
                                source, expected, advancing, mode, demand, frontier, tcx,
                            )
                        },
                    )))
                }
            }),
        )
    }

    fn finish_awaiting_expected_without_expected(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        mut completed: Box<CompletedPathUnitGoalCall<'m>>,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryValueAdvance<'m>, Error> {
        if let Some(successor) = Self::begin_ready_user_elaborator_terminal_public_layer(
            source,
            None,
            &mut completed,
            frontier,
            tcx,
        )? {
            return Ok(OrdinaryValueAdvance::pending(Self {
                source,
                expected: None,
                planned: PlannedOrdinaryValue::Call(OrdinaryCallContinuation::Successor(successor)),
            }));
        }
        if demand == OrdinaryCompletionDemand::ImmediateCallee
            && let Some(progress) =
                Self::retain_callable_progress(&mut completed.result, frontier, tcx)?
        {
            return Ok(OrdinaryValueAdvance::Complete(
                Self::completed_retained_callable(completed, progress),
            ));
        }
        if mode.executes_relation_actions() && completed.call.user_elaborator_transcript.is_some() {
            let transcript = completed
                .call
                .user_elaborator_transcript
                .take()
                .expect("the elaborator transcript was checked above");
            return Ok(OrdinaryValueAdvance::Complete(
                CompletedInFrame::UserElaboratorCall {
                    output: completed.result,
                    inferred_type_arg_suffix: completed.result_inferred_type_arg_suffix,
                    transcript,
                },
            ));
        }
        if mode == frontier::FrontierMode::Final {
            let (store, _owner, delta, _publication) = frontier.parts_mut();
            let _ = store.require_goal_free_after_delta(delta, completed.result, tcx)?;
            unreachable!("a call waiting for an expected type had a goal-free final result")
        }
        Ok(OrdinaryValueAdvance::pending(Self {
            source,
            expected: None,
            planned: PlannedOrdinaryValue::Call(OrdinaryCallContinuation::AwaitingExpected(
                completed,
            )),
        }))
    }

    fn finish_completed_single_layer(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        mut completed: Box<CompletedPathUnitGoalCall<'m>>,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryValueAdvance<'m>, Error> {
        if let Some(successor) = Self::begin_ready_user_elaborator_terminal_public_layer(
            source,
            expected.clone(),
            &mut completed,
            frontier,
            tcx,
        )? {
            return Ok(OrdinaryValueAdvance::pending(Self {
                source,
                expected,
                planned: PlannedOrdinaryValue::Call(OrdinaryCallContinuation::Successor(successor)),
            }));
        }
        if expected.is_none() || demand == OrdinaryCompletionDemand::PublicHeader {
            let goal_free = {
                let (store, _owner, delta, _publication) = frontier.parts_mut();
                store
                    .try_zonk_goal_free(delta, completed.result.clone(), tcx)?
                    .is_some()
            };
            if !goal_free {
                if demand == OrdinaryCompletionDemand::ImmediateCallee
                    && let Some(progress) =
                        Self::retain_callable_progress(&mut completed.result, frontier, tcx)?
                {
                    return Ok(OrdinaryValueAdvance::Complete(
                        Self::completed_retained_callable(completed, progress),
                    ));
                }
                if mode.executes_relation_actions()
                    && completed.call.user_elaborator_transcript.is_some()
                {
                    let transcript = completed
                        .call
                        .user_elaborator_transcript
                        .take()
                        .expect("the elaborator transcript was checked above");
                    return Ok(OrdinaryValueAdvance::Complete(
                        CompletedInFrame::UserElaboratorCall {
                            output: completed.result,
                            inferred_type_arg_suffix: completed.result_inferred_type_arg_suffix,
                            transcript,
                        },
                    ));
                }
                if mode == frontier::FrontierMode::Final {
                    let (store, _owner, delta, _publication) = frontier.parts_mut();
                    let _ = store.require_goal_free_after_delta(delta, completed.result, tcx)?;
                    unreachable!(
                        "a synthesized call had a goal-free result after readiness declined"
                    )
                }
                return Ok(OrdinaryValueAdvance::pending(Self {
                    source,
                    expected,
                    planned: PlannedOrdinaryValue::Call(
                        OrdinaryCallContinuation::AwaitingExpected(completed),
                    ),
                }));
            }
        }
        if completed.call.shape.result_is_pre_residual {
            let (_store, _owner, publication) = frontier.publication_mut();
            completed
                .call
                .stage_residual_eta_once(completed.result.clone(), publication);
        }
        Ok(OrdinaryValueAdvance::Complete(
            Self::completed_selected_call(completed),
        ))
    }

    fn finish_user_elaborator_state(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        continuation: PlannedUserElaboratorCall<'m>,
        mode: frontier::FrontierMode,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryValueAdvance<'m>, Error> {
        let PlannedUserElaboratorCall { mut action, state } = continuation;
        if let PlannedUserElaboratorCallState::Ready {
            action: ready,
            output,
            inferred_type_arg_suffix,
            expected_application,
        } = state
        {
            assert!(
                action.is_none(),
                "a preflighted elaborator action retained its consumed preparation"
            );
            assert!(
                mode.executes_actions(),
                "a preflighted elaborator action resumed before Final"
            );
            return Self::finish_ready_user_elaborator(
                source,
                expected.as_ref(),
                ready,
                output,
                inferred_type_arg_suffix,
                expected_application,
                true,
                frontier,
                tcx,
            );
        }
        let state = match state {
            state @ PlannedUserElaboratorCallState::Completed { .. } => state,
            PlannedUserElaboratorCallState::Fills(_) => {
                unreachable!("a fills elaborator bypassed the heap driver")
            }
            PlannedUserElaboratorCallState::Advancing(_) => {
                unreachable!("an advancing elaborator call bypassed the heap driver")
            }
            PlannedUserElaboratorCallState::Ready { .. } => {
                unreachable!("the preflighted action returned above")
            }
        };
        let PlannedUserElaboratorCallState::Completed {
            output,
            inferred_type_arg_suffix,
            transcript,
            expected_application,
        } = state
        else {
            unreachable!("the elaborator call state was normalized above")
        };
        assert!(
            !transcript.terminal_public_layer_in_flight(),
            "an elaborator terminal public layer bypassed the heap driver"
        );

        let prepared = action
            .as_ref()
            .expect("a completed elaborator call retains its prepared action");

        let expected_application = Self::retry_deferred_user_elaborator_expected(
            expected.as_ref(),
            &output,
            expected_application,
            source.span(),
            frontier,
            tcx,
        )?;

        let final_mode = mode.is_final_check();
        let proposal_mode = mode == frontier::FrontierMode::RelationProbe;
        let typed = {
            let (store, _owner, delta, _publication) = frontier.parts_mut();
            let mut layers = Vec::with_capacity(transcript.layers.len());
            let mut pending = false;
            for (layer_index, layer) in transcript.layers.iter().enumerate() {
                let mut type_slots = Vec::with_capacity(layer.type_slots.len());
                for (slot_index, slot) in layer.type_slots.iter().enumerate() {
                    let optional_absence =
                        prepared.optional_type_slot_can_be_absent(layer_index, slot_index);
                    let Some(slot) = slot else {
                        assert!(
                            optional_absence,
                            "a required elaborator ABI dependency skipped inference allocation"
                        );
                        type_slots.push(crate::pass::typecheck_full::TypedUserElaboratorTypeSlot {
                            resolved: None,
                            occurrence: None,
                        });
                        continue;
                    };
                    let occurrence = store.zonk_for_progress(delta, slot.clone(), tcx)?;
                    match store.try_zonk_goal_free(delta, slot.clone(), tcx)? {
                        Some(closed) => type_slots.push(
                            crate::pass::typecheck_full::TypedUserElaboratorTypeSlot {
                                resolved: Some(closed.ty().clone()),
                                occurrence: Some(occurrence.ty().clone()),
                            },
                        ),
                        None if optional_absence => type_slots.push(
                            crate::pass::typecheck_full::TypedUserElaboratorTypeSlot {
                                resolved: None,
                                occurrence: Some(occurrence.ty().clone()),
                            },
                        ),
                        None if !final_mode => pending = true,
                        None => {
                            let param = prepared.type_slot_param(layer_index, slot_index);
                            return Err(Error::type_(
                                source.span(),
                                format!(
                                    "cannot infer type argument `[{}]` of this elaborator call",
                                    param.name
                                ),
                            ));
                        }
                    }
                }
                let mut sources = Vec::with_capacity(layer.sources.len());
                for source in &layer.sources {
                    match store.try_zonk_goal_free(delta, source.expected.clone(), tcx)? {
                        Some(closed) => sources.push(
                            crate::pass::typecheck_full::TypedUserElaboratorCallSource {
                                source_index: source.source_index,
                                source: source.source.clone(),
                                expanded_start: source.expanded_start,
                                expanded_width: source.expanded_width,
                                expected: closed.ty().clone(),
                            },
                        ),
                        None if !final_mode => pending = true,
                        None => {
                            let _ = store.require_goal_free_after_delta(
                                delta,
                                source.expected.clone(),
                                tcx,
                            )?;
                            unreachable!("an elaborator source type closed after rejection")
                        }
                    }
                }
                layers.push(crate::pass::typecheck_full::TypedUserElaboratorCallLayer {
                    type_slots,
                    sources,
                    value_layer_consumed: layer.value_layer_consumed,
                });
            }
            let result = store.try_zonk_goal_free(delta, output.clone(), tcx)?;
            pending |= result.is_none() && !(final_mode || proposal_mode);
            if pending {
                None
            } else {
                Some(crate::pass::typecheck_full::TypedUserElaboratorCall {
                    layers,
                    result_ty: result.map(|closed| closed.ty().clone()),
                })
            }
        };
        let Some(typed) = typed else {
            return Ok(OrdinaryValueAdvance::pending(Self {
                source,
                expected,
                planned: PlannedOrdinaryValue::UserElaborator(PlannedUserElaboratorCall {
                    action,
                    state: PlannedUserElaboratorCallState::Completed {
                        output,
                        inferred_type_arg_suffix,
                        transcript,
                        expected_application,
                    },
                }),
            }));
        };

        let output_is_closed = {
            let (store, _owner, delta, _publication) = frontier.parts_mut();
            store
                .try_zonk_goal_free(delta, output.clone(), tcx)?
                .is_some()
        };
        let ready = action
            .take()
            .expect("a ready elaborator call consumes its prepared action")
            .into_ready(typed, tcx)?;
        if ready.schedule() == crate::ast::ElaboratorSchedule::Fills {
            let marked = fills::MarkedCallState::ready(
                ready,
                output,
                inferred_type_arg_suffix,
                expected_application,
            );
            if !mode.executes_relation_actions() {
                return Ok(OrdinaryValueAdvance::pending(Self {
                    source,
                    expected,
                    planned: PlannedOrdinaryValue::UserElaborator(PlannedUserElaboratorCall {
                        action: None,
                        state: PlannedUserElaboratorCallState::Fills(Box::new(marked)),
                    }),
                }));
            }
            return Self::finish_ready_fills_user_elaborator(
                source,
                expected.as_ref(),
                marked,
                frontier,
                tcx,
            );
        }
        if !output_is_closed && !mode.executes_relation_actions() {
            return Ok(OrdinaryValueAdvance::pending(Self {
                source,
                expected,
                planned: PlannedOrdinaryValue::UserElaborator(PlannedUserElaboratorCall {
                    action: None,
                    state: PlannedUserElaboratorCallState::Ready {
                        action: ready,
                        output,
                        inferred_type_arg_suffix,
                        expected_application,
                    },
                }),
            }));
        }
        Self::finish_ready_user_elaborator(
            source,
            expected.as_ref(),
            ready,
            output,
            inferred_type_arg_suffix,
            expected_application,
            !output_is_closed,
            frontier,
            tcx,
        )
    }

    #[allow(clippy::too_many_arguments)] // one terminal-layer handoff carries the complete retained preflight state
    fn begin_user_elaborator_terminal_public_layer(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        callee: OwnerBoundSynth,
        preflight: GeneralGoalCallPreflight<'m>,
        parent_goals: Vec<crate::ast::TypeGoalRef>,
        split_after: usize,
        transcript: UserElaboratorCallTranscript,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryChildContinuation<'m>, Error> {
        let parent_owner = frontier.owner();
        let span = source.span();
        let preflighted_callee = callee.ty().ty().clone();
        #[cfg(test)]
        let child_has_expected = expected.is_some();
        let (reservation, selecting) =
            frontier.reserve_ordinary_child_with(span, tcx, |store, owner| {
                assert_eq!(
                    store.owner_parent(owner, span)?,
                    Some(parent_owner),
                    "an elaborator terminal successor opened outside its action owner"
                );
                let retained_callee = callee.into_synth(owner, store, span)?;
                assert_eq!(
                    retained_callee.ty.as_type(),
                    preflighted_callee.as_type(),
                    "an elaborator terminal callee changed while entering its child"
                );
                assert_eq!(
                    retained_callee.ty.identity_is_canonical(),
                    preflighted_callee.identity_is_canonical(),
                    "an elaborator terminal callee changed canonical identity in its child"
                );
                let GeneralGoalCallPreflight {
                    shape,
                    value_slots,
                    expanded_value_slots,
                    candidates,
                    result_inferred_type_arg_suffix,
                } = preflight;
                assert_eq!(
                    shape.binders.len(),
                    parent_goals.len(),
                    "an elaborator terminal layer retained the wrong parent-goal count"
                );
                let occurrences = shape
                    .binders
                    .iter()
                    .zip(parent_goals)
                    .map(|(binder, goal)| {
                        assert_eq!(
                            goal.owner(),
                            parent_owner,
                            "an elaborator terminal binder was reserved outside its action parent"
                        );
                        store
                            .scoped_goal_at(goal, Vec::new(), owner, binder.span)
                            .map(Some)
                    })
                    .collect::<Result<Vec<_>, Error>>()?;
                let call = OpenGoalCall::begin_at_slot_offset_with_activated_binders(
                    shape,
                    owner,
                    span,
                    source.site(),
                    split_after,
                    Some(transcript),
                    occurrences,
                    store,
                    tcx,
                )?;
                let selecting = finish_open_preflighted_selecting_goal_call(
                    call,
                    None,
                    None,
                    None,
                    value_slots,
                    expanded_value_slots,
                    candidates,
                    result_inferred_type_arg_suffix,
                    tcx,
                )?;
                assert_eq!(
                    selecting.call.owner, owner,
                    "an elaborator terminal selector allocated through another child owner"
                );
                #[cfg(test)]
                {
                    let child_goal_count = store.owner_goal_count_for_test(owner, span);
                    update_terminal_public_layer_work(|work| {
                        work.child_opens += 1;
                        work.child_goal_count += child_goal_count;
                        work.expected_children += usize::from(child_has_expected);
                        work.synthesized_children += usize::from(!child_has_expected);
                        work.last_parent = Some(parent_owner);
                        work.last_child = Some(owner);
                    });
                }
                Ok(selecting)
            })?;
        assert_eq!(
            selecting.call.slot_offset, split_after,
            "an elaborator terminal selector lost its predecessor call link"
        );
        let planned =
            PlannedOrdinaryValue::Call(OrdinaryCallContinuation::Selecting(Box::new(selecting)));
        let cursor = match expected {
            Some(expected) => Self::bind(source, expected, planned),
            None => Self::bind_synth(source, planned),
        };
        Ok(OrdinaryChildContinuation {
            child: frontier.open_ordinary_child(reservation)?,
            cursor: Box::new(cursor),
            next_mode: frontier::FrontierMode::ExpectedOnly,
            suspension: OrdinarySuspension::Mode,
        })
    }

    fn descend_user_elaborator_successor(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        successor: OrdinaryChildContinuation<'m>,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
    ) -> OrdinaryDriverStep<'m> {
        OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
            child: successor,
            inherited_mode: mode,
            demand,
            handoff: OrdinaryDriverHandoff::Current(Box::new(move |result, _frontier, _tcx| {
                let advanced = match result {
                    OrdinaryChildAdvance::Complete(completed) => {
                        OrdinaryValueAdvance::Complete(completed)
                    }
                    OrdinaryChildAdvance::Pending(successor) => {
                        OrdinaryValueAdvance::pending(Self {
                            source,
                            expected,
                            planned: PlannedOrdinaryValue::Call(
                                OrdinaryCallContinuation::Successor(successor),
                            ),
                        })
                    }
                };
                Ok(OrdinaryDriverStep::Ready(advanced))
            })),
            scope_exit: OrdinaryDriverScopeExit::None,
        })
    }

    fn resume_advancing_user_elaborator(
        expected: Option<OwnerBoundType>,
        mut action: Option<crate::pass::typecheck_full::PreparedUserElaboratorAction<'m>>,
        mut projection: Option<fills::MarkedProjection<'m>>,
        call_expected: Option<OwnerBoundType>,
        mode: frontier::FrontierMode,
        advanced: OrdinaryValueAdvance<'m>,
    ) -> ResumedUserElaboratorCall<'m> {
        let state = match advanced {
            OrdinaryValueAdvance::Pending(cursor) | OrdinaryValueAdvance::Waiting(cursor) => {
                let Self {
                    source: pending_source,
                    expected: pending_expected,
                    planned,
                } = *cursor;
                let PlannedOrdinaryValue::Call(call) = planned else {
                    unreachable!("the shared call selector returned another value family")
                };
                assert_eq!(
                    pending_expected.is_some(),
                    call_expected.is_some(),
                    "the shared call selector changed its attached expectation while pending"
                );
                let terminal_successor = matches!(
                    &call,
                    OrdinaryCallContinuation::Successor(successor)
                        if successor
                            .cursor
                            .carries_action_parent_terminal_public_layer()
                );
                let call = match call {
                    OrdinaryCallContinuation::Successor(successor) if terminal_successor => {
                        OrdinaryCallContinuation::Successor(successor)
                    }
                    OrdinaryCallContinuation::Successor(mut successor) => {
                        let Self {
                            source: successor_source,
                            expected: successor_expected,
                            planned: successor_planned,
                        } = *successor.cursor;
                        let PlannedOrdinaryValue::Call(successor_call) = successor_planned else {
                            unreachable!("an elaborator call successor changed expression family")
                        };
                        let prepared = action
                            .as_ref()
                            .expect("an elaborator successor lost its prepared action");
                        let transcript = successor_call
                            .user_elaborator_transcript()
                            .expect("an elaborator action migrated into an unrelated successor");
                        assert_eq!(
                            transcript.action,
                            prepared.node_id(),
                            "an elaborator successor crossed action identities"
                        );
                        assert_eq!(
                            transcript.source_span,
                            pending_source.span(),
                            "an elaborator successor crossed source actions"
                        );
                        assert!(
                            !transcript.layers.is_empty(),
                            "an elaborator successor skipped its preceding declaration layer"
                        );
                        let continuation = match projection.take() {
                            Some(projection) => PlannedUserElaboratorCall {
                                action: None,
                                state: PlannedUserElaboratorCallState::Fills(Box::new(
                                    fills::MarkedCallState::project_with(
                                        action.take().expect(
                                            "a projecting elaborator successor lost its action",
                                        ),
                                        successor_call,
                                        projection,
                                    ),
                                )),
                            },
                            None => PlannedUserElaboratorCall {
                                action,
                                state: PlannedUserElaboratorCallState::Advancing(successor_call),
                            },
                        };
                        successor.cursor = Box::new(Self {
                            source: successor_source,
                            expected: successor_expected,
                            planned: PlannedOrdinaryValue::UserElaborator(continuation),
                        });
                        if mode.executes_relation_actions() {
                            #[cfg(test)]
                            update_final_elaborator_successor_work(|work| {
                                work.migrated_descents += 1;
                            });
                            return ResumedUserElaboratorCall::DescendMigrated(successor);
                        }
                        #[cfg(test)]
                        update_final_elaborator_successor_work(|work| {
                            work.earlier_nonterminal_yields += 1;
                        });
                        return ResumedUserElaboratorCall::Ready(OrdinaryValueAdvance::pending(
                            Self {
                                source: pending_source,
                                expected,
                                planned: PlannedOrdinaryValue::Call(
                                    OrdinaryCallContinuation::Successor(successor),
                                ),
                            },
                        ));
                    }
                    call => call,
                };
                let continuation = match projection.take() {
                    Some(projection) => PlannedUserElaboratorCall {
                        action: None,
                        state: PlannedUserElaboratorCallState::Fills(Box::new(
                            fills::MarkedCallState::project_with(
                                action
                                    .take()
                                    .expect("a projecting elaborator lost its action"),
                                call,
                                projection,
                            ),
                        )),
                    },
                    None => PlannedUserElaboratorCall {
                        action,
                        state: PlannedUserElaboratorCallState::Advancing(call),
                    },
                };
                if terminal_successor && mode.executes_relation_actions() {
                    #[cfg(test)]
                    update_final_elaborator_successor_work(|work| {
                        work.terminal_continues += 1;
                    });
                    return ResumedUserElaboratorCall::Continue(continuation);
                }
                #[cfg(test)]
                if terminal_successor {
                    update_final_elaborator_successor_work(|work| {
                        work.earlier_terminal_yields += 1;
                    });
                }
                return ResumedUserElaboratorCall::Ready(OrdinaryValueAdvance::pending(Self {
                    source: pending_source,
                    expected,
                    planned: PlannedOrdinaryValue::UserElaborator(continuation),
                }));
            }
            OrdinaryValueAdvance::Complete(CompletedInFrame::UserElaboratorCall {
                output,
                inferred_type_arg_suffix,
                mut transcript,
            }) => {
                if transcript.terminal_public_layer_fulfilled() {
                    let prepared = action
                        .as_ref()
                        .expect("a completed terminal layer lost its elaborator action");
                    transcript.finish_terminal_public_layer(prepared.node_id(), prepared.span());
                }
                let expected_application = if expected.is_none() {
                    UserElaboratorExpectedApplication::Absent
                } else if call_expected.is_some() {
                    UserElaboratorExpectedApplication::Applied
                } else {
                    UserElaboratorExpectedApplication::Deferred
                };
                if let Some(projection) = projection.take() {
                    return ResumedUserElaboratorCall::Continue(PlannedUserElaboratorCall {
                        action: None,
                        state: PlannedUserElaboratorCallState::Fills(Box::new(
                            fills::MarkedCallState::completed(
                                action
                                    .take()
                                    .expect("a projected completion lost its action"),
                                output,
                                inferred_type_arg_suffix,
                                transcript,
                                expected_application,
                                projection,
                            ),
                        )),
                    });
                }
                PlannedUserElaboratorCallState::Completed {
                    output,
                    inferred_type_arg_suffix,
                    transcript,
                    expected_application,
                }
            }
            OrdinaryValueAdvance::Complete(_) => {
                unreachable!("an elaborator call lost its typed completion transcript")
            }
        };
        ResumedUserElaboratorCall::Continue(PlannedUserElaboratorCall { action, state })
    }

    fn retry_deferred_user_elaborator_expected(
        expected: Option<&OwnerBoundType>,
        output: &ScopedType,
        expected_application: UserElaboratorExpectedApplication,
        span: Span,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<UserElaboratorExpectedApplication, Error> {
        if expected_application != UserElaboratorExpectedApplication::Deferred {
            return Ok(expected_application);
        }
        let expected = expected.expect("a deferred elaborator expectation lost its cursor type");
        Ok(
            if try_apply_expected_equation(frontier, output.clone(), expected, span, tcx)? {
                UserElaboratorExpectedApplication::Applied
            } else {
                UserElaboratorExpectedApplication::Deferred
            },
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn continue_projected_adoption_after_producer(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        ready: crate::pass::typecheck_full::ReadyProjectedUserElaboratorAction<'m>,
        checked: fills::ProjectedCheckedResult,
        adoption: fills::FillAdoption,
        mut projection: fills::MarkedProjection<'m>,
        output: ScopedType,
        inferred_type_arg_suffix: usize,
        expected_application: UserElaboratorExpectedApplication,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
        frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryDriverStep<'m>, Error> {
        if let Some(request) = projection.next_ready_producer_close(source.span(), frontier, tcx)? {
            let owner = request.parent;
            return Ok(OrdinaryDriverStep::AtAncestor {
                owner,
                resume: Box::new(move |producer_frontier, tcx| {
                    projection.close_ready_producer(
                        request,
                        source.span(),
                        producer_frontier,
                        tcx,
                    )?;
                    Ok(Box::new(move |frontier, tcx| {
                        Self::continue_projected_adoption_after_producer(
                            source,
                            expected,
                            ready,
                            checked,
                            adoption,
                            projection,
                            output,
                            inferred_type_arg_suffix,
                            expected_application,
                            mode,
                            demand,
                            frontier,
                            tcx,
                        )
                    }))
                }),
            });
        }
        let continuation = PlannedUserElaboratorCall {
            action: None,
            state: PlannedUserElaboratorCallState::Fills(Box::new(
                fills::MarkedCallState::adopting_fills(
                    ready,
                    checked,
                    adoption,
                    projection,
                    output,
                    inferred_type_arg_suffix,
                    expected_application,
                ),
            )),
        };
        Self::advance_user_elaborator_step(
            source,
            expected,
            continuation,
            mode,
            demand,
            frontier,
            tcx,
        )
    }

    fn advance_user_elaborator_step(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        continuation: PlannedUserElaboratorCall<'m>,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
        frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryDriverStep<'m>, Error> {
        let PlannedUserElaboratorCall { action, state } = continuation;
        let (mut action, call, mut marked_projection) = match state {
            PlannedUserElaboratorCallState::Fills(state) => match state.into_advance() {
                fills::MarkedCallPhase::Project {
                    action: marked_action,
                    call,
                    projection,
                } => (Some(marked_action), call, Some(projection)),
                fills::MarkedCallPhase::Completed {
                    action,
                    output,
                    inferred_type_arg_suffix,
                    transcript,
                    mut expected_application,
                    mut projection,
                } => {
                    if let Some(request) =
                        projection.advance_declared_headers(action.span(), frontier, tcx)?
                    {
                        let owner = request.parent;
                        return Ok(OrdinaryDriverStep::AtAncestor {
                            owner,
                            resume: Box::new(move |header_frontier, tcx| {
                                projection.resume_declared_header(
                                    request,
                                    action.span(),
                                    header_frontier,
                                    tcx,
                                )?;
                                let continuation = PlannedUserElaboratorCall {
                                    action: None,
                                    state: PlannedUserElaboratorCallState::Fills(Box::new(
                                        fills::MarkedCallState::completed(
                                            action,
                                            output,
                                            inferred_type_arg_suffix,
                                            transcript,
                                            expected_application,
                                            projection,
                                        ),
                                    )),
                                };
                                Ok(Box::new(move |frontier, tcx| {
                                    Self::advance_user_elaborator_step(
                                        source,
                                        expected,
                                        continuation,
                                        mode,
                                        demand,
                                        frontier,
                                        tcx,
                                    )
                                }))
                            }),
                        });
                    }
                    expected_application = Self::retry_deferred_user_elaborator_expected(
                        expected.as_ref(),
                        &output,
                        expected_application,
                        source.span(),
                        frontier,
                        tcx,
                    )?;
                    let (declared_inputs, frozen_residual) =
                        projection.declared_inputs(&action, &transcript, frontier, tcx)?;
                    projection.retain_transcript(transcript);
                    let (proof, fills) = projection.capabilities();
                    let ready = action.into_projected_ready(
                        declared_inputs,
                        frozen_residual,
                        proof,
                        fills,
                        tcx,
                    )?;
                    let evaluation = crate::pass::typecheck_full::evaluate_ready_projected_user_elaborator_action(ready, tcx)?;
                    let (ready, checked, returned_context) = crate::pass::typecheck_full::prevalidate_ready_projected_user_elaborator_action(evaluation)?;
                    projection.resolve_deferred_rec_tails(
                        &checked,
                        ready.has_residual_abstraction(),
                        source.span(),
                    )?;
                    let adoption = projection.prepare_adoption(
                        &returned_context,
                        source.span(),
                        frontier,
                        tcx,
                    )?;
                    let continuation = PlannedUserElaboratorCall {
                        action: None,
                        state: PlannedUserElaboratorCallState::Fills(Box::new(
                            fills::MarkedCallState::adopting_fills(
                                ready,
                                checked,
                                adoption,
                                projection,
                                output,
                                inferred_type_arg_suffix,
                                expected_application,
                            ),
                        )),
                    };
                    return Ok(OrdinaryDriverStep::Continue(Box::new(
                        move |frontier, tcx| {
                            Self::advance_user_elaborator_step(
                                source,
                                expected,
                                continuation,
                                mode,
                                demand,
                                frontier,
                                tcx,
                            )
                        },
                    )));
                }
                fills::MarkedCallPhase::AdoptingFills {
                    ready,
                    checked,
                    mut adoption,
                    mut projection,
                    output,
                    inferred_type_arg_suffix,
                    mut expected_application,
                } => {
                    expected_application = Self::retry_deferred_user_elaborator_expected(
                        expected.as_ref(),
                        &output,
                        expected_application,
                        source.span(),
                        frontier,
                        tcx,
                    )?;
                    let advance = adoption.advance(
                        &mut projection,
                        &checked,
                        &output,
                        mode,
                        source.span(),
                        frontier,
                        tcx,
                    )?;
                    if matches!(&advance, fills::FillAdoptionAdvance::Complete) {
                        let residual_binders = ready.residual_lexical_binders().cloned().collect();
                        let materialized = projection.materialize(
                            checked,
                            output,
                            residual_binders,
                            source.span(),
                            frontier,
                            tcx,
                        )?;
                        let obligation = crate::pass::typecheck_full::materialize_ready_projected_user_elaborator_action(
                            ready,
                            materialized.typed,
                            materialized.checked,
                            materialized.public_terminal_result,
                            materialized.checked_result,
                            materialized.sources,
                            materialized.quoted_public_recipe,
                            tcx,
                        )?;
                        match expected_application {
                            UserElaboratorExpectedApplication::Absent => {
                                assert!(expected.is_none())
                            }
                            UserElaboratorExpectedApplication::Applied => {
                                assert!(expected.is_some())
                            }
                            UserElaboratorExpectedApplication::Deferred => {
                                let expected = expected.as_ref().expect(
                                    "a deferred fills elaborator expectation lost its type",
                                );
                                assert!(try_apply_expected_equation(
                                    frontier,
                                    materialized.public_residual_result.clone(),
                                    expected,
                                    source.span(),
                                    tcx,
                                )?);
                            }
                        }
                        let closed_result = materialized.public_residual_result;
                        let (_store, _owner, _delta, publication) = frontier.parts_mut();
                        publication.record_position_type(
                            source.span(),
                            closed_result.clone(),
                            tcx.in_scope_type_param_presentation(),
                        );
                        publication.record_user_elaborator(obligation);
                        return Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::Complete(
                            CompletedInFrame::Value(closed_result, inferred_type_arg_suffix),
                        )));
                    }
                    let request = match advance {
                        fills::FillAdoptionAdvance::Producer(request) => Some(request),
                        fills::FillAdoptionAdvance::Pending => None,
                        fills::FillAdoptionAdvance::BarrierApplied => {
                            return Self::continue_projected_adoption_after_producer(
                                source,
                                expected,
                                ready,
                                checked,
                                adoption,
                                projection,
                                output,
                                inferred_type_arg_suffix,
                                expected_application,
                                mode,
                                demand,
                                frontier,
                                tcx,
                            );
                        }
                        fills::FillAdoptionAdvance::Complete => {
                            unreachable!("a completed fills adoption skipped materialization")
                        }
                    };
                    if let Some(request) = request {
                        let owner = request.parent;
                        return Ok(OrdinaryDriverStep::AtAncestor {
                            owner,
                            resume: Box::new(move |producer_frontier, tcx| {
                                let resumed =
                                    projection.resume_producer(request, producer_frontier, tcx)?;
                                Ok(Box::new(move |frontier, tcx| {
                                    let accept_immediately =
                                        adoption.accepts_resumed_producer_immediately();
                                    if accept_immediately {
                                        projection.accept_resumed_producer(
                                            &resumed,
                                            source.span(),
                                            frontier,
                                            tcx,
                                        )?;
                                    }
                                    adoption.record_producer(&resumed);
                                    if accept_immediately {
                                        return Self::continue_projected_adoption_after_producer(
                                            source,
                                            expected,
                                            ready,
                                            checked,
                                            adoption,
                                            projection,
                                            output,
                                            inferred_type_arg_suffix,
                                            expected_application,
                                            mode,
                                            demand,
                                            frontier,
                                            tcx,
                                        );
                                    }
                                    let continuation = PlannedUserElaboratorCall {
                                        action: None,
                                        state: PlannedUserElaboratorCallState::Fills(Box::new(
                                            fills::MarkedCallState::adopting_fills(
                                                ready,
                                                checked,
                                                adoption,
                                                projection,
                                                output,
                                                inferred_type_arg_suffix,
                                                expected_application,
                                            ),
                                        )),
                                    };
                                    Self::advance_user_elaborator_step(
                                        source,
                                        expected,
                                        continuation,
                                        mode,
                                        demand,
                                        frontier,
                                        tcx,
                                    )
                                }))
                            }),
                        });
                    }
                    return Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::pending(
                        Self {
                            source,
                            expected,
                            planned: PlannedOrdinaryValue::UserElaborator(
                                PlannedUserElaboratorCall {
                                    action: None,
                                    state: PlannedUserElaboratorCallState::Fills(Box::new(
                                        fills::MarkedCallState::adopting_fills(
                                            ready,
                                            checked,
                                            adoption,
                                            projection,
                                            output,
                                            inferred_type_arg_suffix,
                                            expected_application,
                                        ),
                                    )),
                                },
                            ),
                        },
                    )));
                }
                fills::MarkedCallPhase::Ready {
                    ready,
                    output,
                    inferred_type_arg_suffix,
                    expected_application,
                } => {
                    return Self::finish_ready_fills_user_elaborator(
                        source,
                        expected.as_ref(),
                        fills::MarkedCallState::ready(
                            ready,
                            output,
                            inferred_type_arg_suffix,
                            expected_application,
                        ),
                        frontier,
                        tcx,
                    )
                    .map(OrdinaryDriverStep::Ready);
                }
            },
            PlannedUserElaboratorCallState::Advancing(call) => (action, call, None),
            state => {
                return Self::finish_user_elaborator_state(
                    source,
                    expected,
                    PlannedUserElaboratorCall { action, state },
                    mode,
                    frontier,
                    tcx,
                )
                .map(OrdinaryDriverStep::Ready);
            }
        };
        assert!(
            action.is_some(),
            "an advancing elaborator call lost its prepared action"
        );
        let call_expected = match &call {
            OrdinaryCallContinuation::Successor(successor)
                if successor
                    .cursor
                    .carries_action_parent_terminal_public_layer() =>
            {
                successor.cursor.expected.clone()
            }
            _ => expected.clone(),
        };
        let step = if marked_projection.is_some() {
            match call {
                OrdinaryCallContinuation::Selecting(selecting) => {
                    let mut advance = Self::poll_selecting_call(
                        source,
                        call_expected.clone(),
                        selecting,
                        mode,
                        frontier,
                        tcx,
                    )?;
                    let mut projection = marked_projection
                        .take()
                        .expect("a projecting fills call lost its projection");
                    loop {
                        match fills::stage_projected_descent(
                            advance,
                            &mut projection,
                            frontier,
                            tcx,
                        )? {
                            fills::ProjectedDescentGate::Staged { resume, completed } => {
                                advance = Self::resume_selecting_call(
                                    source,
                                    call_expected.clone(),
                                    resume,
                                    OrdinaryChildAdvance::Complete(completed),
                                    mode,
                                    frontier,
                                    tcx,
                                )?;
                            }
                            fills::ProjectedDescentGate::Ordinary(ordinary) => {
                                advance = ordinary;
                                break;
                            }
                        }
                    }
                    let advanced = match advance {
                        SelectingOrdinaryCallAdvance::Layer(layer) => {
                            OrdinaryValueAdvance::pending(Self {
                                source,
                                expected: call_expected.clone(),
                                planned: PlannedOrdinaryValue::Call(
                                    OrdinaryCallContinuation::AdvancingLayer(layer),
                                ),
                            })
                        }
                        SelectingOrdinaryCallAdvance::Ready(advanced) => advanced,
                        SelectingOrdinaryCallAdvance::Descend { .. } => {
                            unreachable!("a marked selecting descent escaped projection staging")
                        }
                    };
                    match Self::resume_advancing_user_elaborator(
                        expected.clone(),
                        action.take(),
                        Some(projection),
                        call_expected,
                        mode,
                        advanced,
                    ) {
                        ResumedUserElaboratorCall::Ready(advanced) => {
                            return Ok(OrdinaryDriverStep::Ready(advanced));
                        }
                        ResumedUserElaboratorCall::DescendMigrated(_) => unreachable!(
                            "a marked selecting step produced a migrated call successor"
                        ),
                        ResumedUserElaboratorCall::Continue(_) => unreachable!(
                            "a marked selecting step completed outside its selected layer"
                        ),
                    }
                }
                OrdinaryCallContinuation::Successor(successor)
                    if successor
                        .cursor
                        .carries_action_parent_terminal_public_layer() =>
                {
                    Self::advance_call_step(
                        source,
                        call_expected.clone(),
                        OrdinaryCallContinuation::Successor(successor),
                        mode,
                        demand,
                        frontier,
                        tcx,
                    )?
                }
                OrdinaryCallContinuation::Successor(mut successor) => {
                    // A successor can finish its entire next public layer in one driver turn. Move
                    // the marked state into that child before descent so every consumed value
                    // source crosses the projection gate even when the child never yields Pending.
                    let Self {
                        source: successor_source,
                        expected: successor_expected,
                        planned: successor_planned,
                    } = *successor.cursor;
                    let PlannedOrdinaryValue::Call(successor_call) = successor_planned else {
                        unreachable!("an elaborator call successor changed expression family")
                    };
                    let prepared = action
                        .as_ref()
                        .expect("a projecting elaborator successor lost its action");
                    let transcript = successor_call
                        .user_elaborator_transcript()
                        .expect("an elaborator action migrated into an unrelated successor");
                    assert_eq!(
                        transcript.action,
                        prepared.node_id(),
                        "an elaborator successor crossed action identities"
                    );
                    assert_eq!(
                        transcript.source_span,
                        source.span(),
                        "an elaborator successor crossed source actions"
                    );
                    assert!(
                        !transcript.layers.is_empty(),
                        "an elaborator successor skipped its preceding declaration layer"
                    );
                    successor.cursor = Box::new(Self {
                        source: successor_source,
                        expected: successor_expected,
                        planned: PlannedOrdinaryValue::UserElaborator(PlannedUserElaboratorCall {
                            action: None,
                            state: PlannedUserElaboratorCallState::Fills(Box::new(
                                fills::MarkedCallState::project_with(
                                    action.take().expect(
                                        "a projecting elaborator successor lost its action",
                                    ),
                                    successor_call,
                                    marked_projection.take().expect(
                                        "a projecting elaborator successor lost its projection",
                                    ),
                                ),
                            )),
                        }),
                    });
                    return Ok(Self::descend_user_elaborator_successor(
                        source, expected, successor, mode, demand,
                    ));
                }
                call => Self::advance_call_step(
                    source,
                    call_expected.clone(),
                    call,
                    mode,
                    demand,
                    frontier,
                    tcx,
                )?,
            }
        } else {
            Self::advance_call_step(
                source,
                call_expected.clone(),
                call,
                mode,
                demand,
                frontier,
                tcx,
            )?
        };
        step.and_then(
            frontier,
            tcx,
            Box::new(
                move |advanced, _frontier, _tcx| match Self::resume_advancing_user_elaborator(
                    expected.clone(),
                    action,
                    marked_projection,
                    call_expected,
                    mode,
                    advanced,
                ) {
                    ResumedUserElaboratorCall::Ready(advanced) => {
                        Ok(OrdinaryDriverStep::Ready(advanced))
                    }
                    ResumedUserElaboratorCall::DescendMigrated(successor) => {
                        Ok(Self::descend_user_elaborator_successor(
                            source, expected, successor, mode, demand,
                        ))
                    }
                    ResumedUserElaboratorCall::Continue(continuation) => Ok(
                        OrdinaryDriverStep::Continue(Box::new(move |frontier, tcx| {
                            Self::advance_user_elaborator_step(
                                source,
                                expected,
                                continuation,
                                mode,
                                demand,
                                frontier,
                                tcx,
                            )
                        })),
                    ),
                },
            ),
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn finish_ready_user_elaborator(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<&OwnerBoundType>,
        ready: crate::pass::typecheck_full::ReadyUserElaboratorAction,
        output: ScopedType,
        inferred_type_arg_suffix: usize,
        expected_application: UserElaboratorExpectedApplication,
        must_evaluate: bool,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryValueAdvance<'m>, Error> {
        let (obligation, closed_result) = if must_evaluate {
            let (store, owner, delta, _publication) = frontier.parts_mut();
            let (obligation, exact_ty) =
                crate::pass::typecheck_full::evaluate_ready_user_elaborator_action(ready, tcx)?;
            let exact = store.scoped_type(owner, exact_ty, source.span())?;
            store.constrain(delta, output.clone(), exact, source.span(), tcx)?;
            let closed = store.require_goal_free_after_delta(delta, output, tcx)?;
            (obligation, closed)
        } else {
            let (store, _owner, delta, _publication) = frontier.parts_mut();
            let closed = store
                .try_zonk_goal_free(delta, output, tcx)?
                .expect("a deferred elaborator action has a goal-free result");
            (
                crate::pass::typecheck_full::defer_ready_user_elaborator_action(ready),
                closed,
            )
        };
        match expected_application {
            UserElaboratorExpectedApplication::Absent => assert!(
                expected.is_none(),
                "an absent elaborator expectation retained a cursor type"
            ),
            UserElaboratorExpectedApplication::Applied => assert!(
                expected.is_some(),
                "an applied elaborator expectation lost its cursor type"
            ),
            UserElaboratorExpectedApplication::Deferred => {
                let expected =
                    expected.expect("a deferred elaborator expectation lost its cursor type");
                assert!(
                    try_apply_expected_equation(
                        frontier,
                        closed_result.clone(),
                        expected,
                        source.span(),
                        tcx,
                    )?,
                    "a goal-free elaborator result left its expected equation deferred"
                );
            }
        }
        {
            let (_store, _owner, _delta, publication) = frontier.parts_mut();
            publication.record_position_type(
                source.span(),
                closed_result.clone(),
                tcx.in_scope_type_param_presentation(),
            );
            publication.record_user_elaborator(obligation);
        }
        Ok(OrdinaryValueAdvance::Complete(CompletedInFrame::Value(
            closed_result,
            inferred_type_arg_suffix,
        )))
    }

    fn finish_ready_fills_user_elaborator(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<&OwnerBoundType>,
        marked: fills::MarkedCallState,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryValueAdvance<'m>, Error> {
        let fills::MarkedCallPhase::Ready {
            ready,
            output,
            inferred_type_arg_suffix,
            expected_application,
        } = marked.into_advance()
        else {
            unreachable!("a projecting fills elaborator reached marked evaluation")
        };
        let (proof, context) = crate::normalization::fresh_fills_capability_values();
        let evaluation = crate::pass::typecheck_full::evaluate_ready_fills_user_elaborator_action(
            ready, proof, context, tcx,
        )?;
        let (obligation, exact_ty, returned_context) =
            crate::pass::typecheck_full::complete_ready_fills_user_elaborator_action(evaluation)?;
        let closed_result = {
            let (store, owner, delta, _publication) = frontier.parts_mut();
            let exact = store.scoped_type(owner, exact_ty, source.span())?;
            store.constrain(delta, output.clone(), exact, source.span(), tcx)?;
            store.require_goal_free_after_delta(delta, output, tcx)?
        };
        match expected_application {
            UserElaboratorExpectedApplication::Absent => assert!(expected.is_none()),
            UserElaboratorExpectedApplication::Applied => assert!(expected.is_some()),
            UserElaboratorExpectedApplication::Deferred => {
                let expected =
                    expected.expect("a deferred fills elaborator expectation lost its type");
                assert!(try_apply_expected_equation(
                    frontier,
                    closed_result.clone(),
                    expected,
                    source.span(),
                    tcx,
                )?);
            }
        }
        let _relations = returned_context.relations_in_source_order();
        let (_store, _owner, _delta, publication) = frontier.parts_mut();
        publication.record_position_type(
            source.span(),
            closed_result.clone(),
            tcx.in_scope_type_param_presentation(),
        );
        publication.record_user_elaborator(obligation);
        Ok(OrdinaryValueAdvance::Complete(CompletedInFrame::Value(
            closed_result,
            inferred_type_arg_suffix,
        )))
    }

    #[allow(clippy::too_many_arguments)]
    fn prepare_reserved_lambda_body(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        mut lambda_owners: OpenLambdaOwnerChain<'m>,
        header: &mut super::annotation_plan::LambdaHeaderPlan<'m>,
        selection: OrdinaryLambdaSelection,
        value_param_types: Vec<OwnerBoundType>,
        retained_binders: &[super::RetainedTypeBinder<'m>],
        ambient_binders: crate::pass::typecheck_full::TypeBinderScope,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<PreparedOrdinaryLambdaBody<'m>, Error> {
        let crate::ast::Expr::FnExpr { sig, ret_ty, .. } = source else {
            unreachable!("a reserved ordinary lambda retained another expression family")
        };
        let mark = tcx.save();
        let prepared = (|| {
            let value_param_types = Self::retain_lambda_value_types_at_prefixes(
                source.span(),
                retained_binders,
                value_param_types,
                &mut lambda_owners,
                frontier,
                tcx,
            )?;
            let mut lambda_frontier =
                frontier.ordinary_child_frontier(lambda_owners.innermost_mut());
            let (selection, value_param_types) = prepare_ordinary_lambda_header(
                source,
                sig,
                ret_ty.as_ref(),
                header,
                selection,
                value_param_types,
                retained_binders,
                &mut lambda_frontier,
                tcx,
            )?;
            let body_expected = match &selection {
                OrdinaryLambdaSelection::Check { body_type } => Some(body_type.clone()),
                OrdinaryLambdaSelection::Synthesizing { annotated_return }
                | OrdinaryLambdaSelection::Synth { annotated_return } => {
                    annotated_return.clone().map(OwnerBoundType::Plain)
                }
            };
            Ok((selection, value_param_types, body_expected))
        })();
        tcx.restore(mark);
        let (selection, value_param_types, body_expected) = prepared?;
        Ok(PreparedOrdinaryLambdaBody {
            lambda_owners,
            selection,
            value_param_types,
            ambient_binders,
            body_expected,
        })
    }

    fn enter_prepared_lambda_body(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        retained_binders: &[super::RetainedTypeBinder<'m>],
        mut prepared: PreparedOrdinaryLambdaBody<'m>,
        deferred_tail: Option<DeferredTailResolution>,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryLambdaState<'m>, Error> {
        let crate::ast::Expr::FnExpr { sig, body, .. } = source else {
            unreachable!("a prepared ordinary lambda retained another expression family")
        };
        if matches!(deferred_tail, Some(DeferredTailResolution::Lifted(_)))
            && !matches!(prepared.selection, OrdinaryLambdaSelection::Check { .. })
        {
            unreachable!("a lifted deferred-tail lambda lost its reserved public header");
        }
        #[cfg(all(test, feature = "surface"))]
        record_lambda_body_entry(source.span(), tcx);
        let mark = tcx.save();
        push_ordinary_lambda_scope(sig, &prepared.value_param_types, retained_binders, tcx);
        let mut lambda_frontier =
            frontier.ordinary_child_frontier(prepared.lambda_owners.innermost_mut());
        let body_expected = match deferred_tail {
            Some(DeferredTailResolution::Lifted(_)) => {
                let crate::ast::Expr::RecOrder { plan, .. } = body.as_ref() else {
                    unreachable!("a lifted deferred-tail lambda lost its exact root carrier")
                };
                let runtime = tcx.intern_type(&plan.runtime_ty);
                let continuation = deferred_tail_continuation_type(plan, tcx);
                let public = prepared
                    .body_expected
                    .as_ref()
                    .expect("a checked lifted lambda lost its public result type")
                    .clone();
                {
                    let (store, owner, delta, _publication) = lambda_frontier.parts_mut();
                    let runtime_scoped = store.scoped_type(owner, runtime.clone(), body.span())?;
                    let continuation = store.scoped_type(owner, continuation, body.span())?;
                    let input = continuation
                        .projected_structural_child(super::ScopedTypeEdge::FunctionParam)
                        .expect("a deferred callback continuation has an ordinary function type");
                    let output = continuation
                        .projected_structural_child(super::ScopedTypeEdge::FunctionReturn)
                        .expect("a deferred callback continuation has an ordinary function type");
                    let public =
                        public.into_expected_equation_operand(owner, store, body.span())?;
                    store.constrain_equation(delta, input, public, body.span(), tcx)?;
                    store.constrain_equation(
                        delta,
                        output,
                        runtime_scoped.into(),
                        body.span(),
                        tcx,
                    )?;
                }
                Some(OwnerBoundType::Plain(runtime))
            }
            Some(DeferredTailResolution::OrdinaryBypass) | None => prepared.body_expected.take(),
        };
        let body = match deferred_tail {
            Some(resolution) => {
                assert!(
                    matches!(
                        body.as_ref(),
                        crate::ast::Expr::RecOrder {
                            plan,
                            ..
                        } if matches!(
                            plan.disposition,
                            RecOrderDisposition::DeferredTail { .. }
                        )
                    ),
                    "a selected deferred-tail lambda lost its exact root carrier"
                );
                Self::begin_seeded_child(
                    body,
                    body_expected,
                    OrdinaryValueSeed::DeferredRecOrder(resolution),
                    &mut lambda_frontier,
                    tcx,
                )
            }
            None => Self::begin_child(body, body_expected, &mut lambda_frontier, tcx),
        };
        tcx.restore(mark);
        Ok(OrdinaryLambdaState::Body {
            lambda_owners: prepared.lambda_owners,
            body: body?,
            selection: prepared.selection,
            value_param_types: prepared.value_param_types,
            ambient_binders: prepared.ambient_binders,
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn begin_reserved_lambda_body(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        lambda_owners: OpenLambdaOwnerChain<'m>,
        header: &mut super::annotation_plan::LambdaHeaderPlan<'m>,
        selection: OrdinaryLambdaSelection,
        value_param_types: Vec<OwnerBoundType>,
        retained_binders: &[super::RetainedTypeBinder<'m>],
        ambient_binders: crate::pass::typecheck_full::TypeBinderScope,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryLambdaState<'m>, Error> {
        let prepared = Self::prepare_reserved_lambda_body(
            source,
            lambda_owners,
            header,
            selection,
            value_param_types,
            retained_binders,
            ambient_binders,
            frontier,
            tcx,
        )?;
        Self::enter_prepared_lambda_body(source, retained_binders, prepared, None, frontier, tcx)
    }

    fn advance_lambda_step(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        lambda: PlannedOrdinaryLambda<'m>,
        mode: frontier::FrontierMode,
        frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryDriverStep<'m>, Error> {
        let crate::ast::Expr::FnExpr { sig, .. } = source else {
            unreachable!("a planned ordinary lambda retained another expression family")
        };
        let PlannedOrdinaryLambda {
            mut header,
            mut retained_binders,
            state,
        } = lambda;
        let state = match state {
            OrdinaryLambdaState::Unselected => {
                let ambient_binders = tcx.in_scope_type_param_presentation();
                let Some((mut selection, mut value_param_types)) = select_ordinary_lambda(
                    source,
                    &mut header,
                    expected.as_ref(),
                    mode,
                    frontier,
                    tcx,
                )?
                else {
                    return Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::pending(
                        Self {
                            source,
                            expected,
                            planned: PlannedOrdinaryValue::Lambda(PlannedOrdinaryLambda {
                                header,
                                retained_binders,
                                state: OrdinaryLambdaState::Unselected,
                            }),
                        },
                    )));
                };
                if retained_binders.is_empty() {
                    retained_binders = Self::retain_lambda_binders(sig, tcx);
                }
                if matches!(selection, OrdinaryLambdaSelection::Check { .. }) {
                    let (body_type, selected_value_types) =
                        header.bind_selected_alpha_edges(&retained_binders);
                    selection = OrdinaryLambdaSelection::Check {
                        body_type: OwnerBoundType::Plain(body_type),
                    };
                    value_param_types = selected_value_types;
                }
                let lambda_owners = Self::reserve_lambda_owner_chain(
                    source.span(),
                    sig,
                    &mut header,
                    &retained_binders,
                    frontier,
                    tcx,
                )?;
                Self::begin_reserved_lambda_body(
                    source,
                    lambda_owners,
                    &mut header,
                    selection,
                    value_param_types
                        .into_iter()
                        .map(OwnerBoundType::Plain)
                        .collect(),
                    &retained_binders,
                    ambient_binders,
                    frontier,
                    tcx,
                )?
            }
            state => state,
        };

        let OrdinaryLambdaState::Body {
            mut lambda_owners,
            mut body,
            mut selection,
            value_param_types,
            ambient_binders,
        } = state
        else {
            return Self::finish_ordinary_lambda(
                source,
                expected,
                header,
                retained_binders,
                state,
                mode,
                frontier,
                tcx,
            )
            .map(OrdinaryDriverStep::Ready);
        };
        let checking_handoff = if matches!(
            selection,
            OrdinaryLambdaSelection::Synthesizing {
                annotated_return: None
            }
        ) && body.cursor.awaits_expected()
        {
            match expected.as_ref() {
                Some(expected) => select_ordinary_lambda(
                    source,
                    &mut header,
                    Some(expected),
                    frontier::FrontierMode::ExpectedOnly,
                    frontier,
                    tcx,
                )?,
                None => None,
            }
        } else {
            None
        };
        let scope_mark = tcx.save();
        push_ordinary_lambda_scope(sig, &value_param_types, &retained_binders, tcx);
        let prepared = (|| {
            let mut lambda_frontier =
                frontier.ordinary_child_frontier(lambda_owners.innermost_mut());
            if let Some((next_selection, _selected_value_types)) = checking_handoff {
                let OrdinaryLambdaSelection::Check { .. } = next_selection else {
                    unreachable!("an expectation-only lambda handoff selected synthesis")
                };
                let (body_type, expected_value_param_types) =
                    header.bind_selected_alpha_edges(&retained_binders);
                let body_type = OwnerBoundType::Plain(body_type);
                selection = handoff_ordinary_lambda_check(
                    source,
                    sig,
                    &mut header,
                    body_type.ty().clone(),
                    expected_value_param_types,
                    &value_param_types,
                    &mut body,
                    &mut lambda_frontier,
                    tcx,
                )?;
            }
            Ok::<(), Error>(())
        })();
        if let Err(error) = prepared {
            tcx.restore(scope_mark);
            return Err(error);
        }
        assert!(!lambda_owners.owners.is_empty());
        let bridge = OrdinaryDriverBridge::Chain(std::mem::take(&mut lambda_owners.owners));
        Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
            child: body,
            inherited_mode: mode,
            demand: OrdinaryCompletionDemand::GoalFreeValue,
            handoff: OrdinaryDriverHandoff::Bridge {
                bridge,
                resume: Box::new(move |bridge, result, frontier, tcx| {
                    let OrdinaryDriverBridge::Chain(owners) = bridge else {
                        unreachable!("a lambda resumed through a direct callee bridge")
                    };
                    assert!(lambda_owners.owners.is_empty());
                    lambda_owners.owners = owners;
                    assert_eq!(
                        lambda_owners.owners.len(),
                        lambda_owners
                            .owner_for_slice
                            .last()
                            .copied()
                            .map_or(0, |owner| owner + 1),
                        "a lambda driver restored the wrong lexical owner depth"
                    );
                    let state = match result {
                        OrdinaryChildAdvance::Pending(body) => OrdinaryLambdaState::Body {
                            lambda_owners,
                            body,
                            selection,
                            value_param_types,
                            ambient_binders,
                        },
                        OrdinaryChildAdvance::Complete(body) => {
                            let selection = match selection {
                                OrdinaryLambdaSelection::Synthesizing { annotated_return } => {
                                    OrdinaryLambdaSelection::Synth { annotated_return }
                                }
                                check @ OrdinaryLambdaSelection::Check { .. } => check,
                                OrdinaryLambdaSelection::Synth { .. } => {
                                    unreachable!("an ordinary lambda committed synthesis twice")
                                }
                            };
                            OrdinaryLambdaState::BodyComplete {
                                lambda_owners,
                                body,
                                completion_wait: None,
                                selection,
                                value_param_types,
                                ambient_binders,
                            }
                        }
                    };
                    match state {
                        OrdinaryLambdaState::Body { .. } => Ok(OrdinaryDriverStep::Ready(
                            OrdinaryValueAdvance::pending(Self {
                                source,
                                expected,
                                planned: PlannedOrdinaryValue::Lambda(PlannedOrdinaryLambda {
                                    header,
                                    retained_binders,
                                    state,
                                }),
                            }),
                        )),
                        state @ OrdinaryLambdaState::BodyComplete { .. } => {
                            Self::finish_ordinary_lambda(
                                source,
                                expected,
                                header,
                                retained_binders,
                                state,
                                mode,
                                frontier,
                                tcx,
                            )
                            .map(OrdinaryDriverStep::Ready)
                        }
                        OrdinaryLambdaState::Unselected => unreachable!(
                            "a completed driver lambda returned to its unselected state"
                        ),
                    }
                }),
            },
            scope_exit: OrdinaryDriverScopeExit::RestoreBeforeResume(scope_mark),
        }))
    }

    #[allow(clippy::too_many_arguments)]
    fn finish_ordinary_lambda(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        mut header: super::annotation_plan::LambdaHeaderPlan<'m>,
        retained_binders: Vec<super::RetainedTypeBinder<'m>>,
        state: OrdinaryLambdaState<'m>,
        _mode: frontier::FrontierMode,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryValueAdvance<'m>, Error> {
        let crate::ast::Expr::FnExpr { sig, .. } = source else {
            unreachable!("a planned ordinary lambda retained another expression family")
        };
        let OrdinaryLambdaState::BodyComplete {
            mut lambda_owners,
            body,
            mut completion_wait,
            selection,
            value_param_types,
            ambient_binders,
        } = state
        else {
            unreachable!("the ordinary lambda body-completion transition was skipped")
        };
        let mark = tcx.save();
        push_ordinary_lambda_scope(sig, &value_param_types, &retained_binders, tcx);
        let finished = (|| {
            let mut lambda_frontier =
                frontier.ordinary_child_frontier(lambda_owners.innermost_mut());
            if let Some(wait) = completion_wait.as_deref() {
                let (store, _, delta, _) = lambda_frontier.parts_mut();
                if !store.completion_wait_changed(wait.0, delta, source.span())? {
                    return Ok(None);
                }
                #[cfg(test)]
                record_completion_work(|work| work.resumed += 1);
            }
            if matches!(
                &selection,
                OrdinaryLambdaSelection::Synth {
                    annotated_return: None
                }
            ) {
                let expected = body.scoped().clone();
                let (store, _owner, delta, publication) = lambda_frontier.parts_mut();
                header.constrain_reserved_return(expected, store, delta, publication, tcx)?;
            }

            let actual = match &selection {
                OrdinaryLambdaSelection::Check { body_type } => {
                    let prepared = prepare_signature_for_close(
                        sig,
                        body_type.clone(),
                        &value_param_types,
                        &retained_binders,
                        source.span(),
                        &mut lambda_frontier,
                        tcx,
                    )?;
                    if let Some(wait) = lambda_frontier
                        .store()
                        .prepared_completion_wait(&prepared)?
                    {
                        match &mut completion_wait {
                            Some(retained) => retained.0 = wait,
                            None => {
                                #[cfg(test)]
                                record_completion_work(|work| {
                                    work.created += 1;
                                    work.live += 1;
                                    work.peak_live = work.peak_live.max(work.live);
                                });
                                completion_wait = Some(Box::new(RetainedCompletionWait(wait)));
                            }
                        }
                        return Ok(None);
                    }
                    {
                        let (_store, _owner, publication) = lambda_frontier.publication_mut();
                        publication.record_prepared_goal_free_position_type(
                            source.span(),
                            prepared.clone(),
                            ambient_binders.clone(),
                        );
                    }
                    OrdinaryLambdaActual::Prepared(prepared)
                }
                OrdinaryLambdaSelection::Synth { annotated_return } => {
                    let body_type = match annotated_return {
                        Some(annotation) => annotation.clone(),
                        None => match &body {
                            CompletedInFrame::Value(body, _)
                            | CompletedInFrame::FunctionScheme(body, _) => body.ty().clone(),
                            CompletedInFrame::UserElaboratorCall { .. } => unreachable!(
                                "an elaborator transcript escaped its owning value cursor"
                            ),
                        },
                    };
                    let value_param_types =
                        value_param_types.iter().map(|ty| ty.ty().clone()).collect();
                    let actual = super::synth::build_fn_type_from_body_type(
                        sig,
                        body_type,
                        value_param_types,
                        source.span(),
                        tcx,
                    );
                    let actual = lambda_frontier.store().scoped_type(
                        lambda_frontier.owner(),
                        InternedType::fresh_canonical(actual),
                        source.span(),
                    )?;
                    {
                        let (_store, _owner, publication) = lambda_frontier.publication_mut();
                        publication.record_position_type(
                            source.span(),
                            actual.clone(),
                            ambient_binders.clone(),
                        );
                    }
                    OrdinaryLambdaActual::Scoped(actual)
                }
                OrdinaryLambdaSelection::Synthesizing { .. } => {
                    unreachable!("an ordinary lambda finished before synthesis committed")
                }
            };
            Ok(Some(actual))
        })();
        tcx.restore(mark);
        let Some(actual) = finished? else {
            return Ok(OrdinaryValueAdvance::Waiting(Box::new(Self {
                source,
                expected,
                planned: PlannedOrdinaryValue::Lambda(PlannedOrdinaryLambda {
                    header,
                    retained_binders,
                    state: OrdinaryLambdaState::BodyComplete {
                        lambda_owners,
                        body,
                        completion_wait,
                        selection,
                        value_param_types,
                        ambient_binders,
                    },
                }),
            })));
        };
        let mut actual = match actual {
            OrdinaryLambdaActual::Prepared(actual) => actual,
            OrdinaryLambdaActual::Scoped(actual) => {
                let mut lambda_frontier =
                    frontier.ordinary_child_frontier(lambda_owners.innermost_mut());
                let (store, _owner, delta, _publication) = lambda_frontier.parts_mut();
                store.zonk_for_close(delta, actual, tcx)?
            }
        };

        while lambda_owners.owners.len() > 1 {
            let child = lambda_owners.take_innermost();
            let parent = lambda_owners.innermost_mut();
            let mut parent_frontier = frontier.ordinary_child_frontier(parent);
            let destination = parent_frontier.owner();
            let mut outputs = parent_frontier.close_prepared_ordinary_child(
                child,
                vec![(actual, GoalEscape::ToOwner(destination))],
                tcx,
            )?;
            assert_eq!(
                outputs.len(),
                1,
                "a lambda slice returned the wrong output count"
            );
            let scoped = match outputs.remove(0) {
                ClosedGoalOutput::Retained(output) => output.into_scoped_type(),
                ClosedGoalOutput::RetainedFunctionScheme(_)
                | ClosedGoalOutput::GoalFree(_)
                | ClosedGoalOutput::FunctionScheme(_) => {
                    unreachable!("an open lambda slice closed outside its direct parent")
                }
            };
            let (store, _owner, delta, _publication) = parent_frontier.parts_mut();
            actual = store.zonk_for_close(delta, scoped, tcx)?;
        }

        let lambda_child = lambda_owners.take_innermost();
        assert!(lambda_owners.owners.is_empty());
        let destination = frontier.owner();
        let mut outputs = frontier.close_prepared_ordinary_child(
            lambda_child,
            vec![(actual, GoalEscape::ToOwner(destination))],
            tcx,
        )?;
        assert_eq!(outputs.len(), 1, "a lambda returned the wrong output count");
        let result = match outputs.remove(0) {
            ClosedGoalOutput::Retained(output) => output.into_scoped_type(),
            ClosedGoalOutput::GoalFree(output) => output.into_scoped_type(),
            ClosedGoalOutput::RetainedFunctionScheme(_) | ClosedGoalOutput::FunctionScheme(_) => {
                unreachable!("an anonymous lambda closed as a named function scheme")
            }
        };
        if let Some(expected) = expected {
            let (store, owner, delta, _publication) = frontier.parts_mut();
            let expected = expected.into_expected_equation_operand(owner, store, source.span())?;
            store.constrain_equation(delta, result.clone(), expected, source.span(), tcx)?;
        }
        Ok(OrdinaryValueAdvance::Complete(CompletedInFrame::Value(
            result, 0,
        )))
    }

    fn begin_seeded_child(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        seed: OrdinaryValueSeed<'m>,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryChildContinuation<'m>, Error> {
        let (reservation, planned) =
            frontier.reserve_ordinary_child_with(source.span(), tcx, |store, owner| {
                Self::plan(source, seed, store, owner, tcx)
            })?;
        let mut child = frontier.open_ordinary_child(reservation)?;
        child.retain_quote_source(source, tcx);
        let cursor = match expected {
            Some(expected) => Self::bind(source, expected, planned),
            None => Self::bind_synth(source, planned),
        };
        Ok(OrdinaryChildContinuation {
            child,
            cursor: Box::new(cursor),
            next_mode: frontier::FrontierMode::ExpectedOnly,
            suspension: OrdinarySuspension::Mode,
        })
    }

    fn begin_child(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryChildContinuation<'m>, Error> {
        Self::begin_child_with_annotation(source, expected, None, frontier, tcx)
    }

    fn begin_annotated_child(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        written: &'m crate::ast::Type<crate::ast::Lowered>,
        plan: super::annotation_plan::AnnotationPlan<'m, crate::ast::Lowered>,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryChildContinuation<'m>, Error> {
        plan.require_admitted()?;
        Self::begin_child_with_annotation(source, None, Some((written, plan)), frontier, tcx)
    }

    fn begin_child_with_annotation(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        mut annotation: Option<(
            &'m crate::ast::Type<crate::ast::Lowered>,
            super::annotation_plan::AnnotationPlan<'m, crate::ast::Lowered>,
        )>,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryChildContinuation<'m>, Error> {
        assert!(
            expected.is_none() || annotation.is_none(),
            "an ordinary child received two expected-type authorities"
        );
        let seed = Self::seed(source, tcx)?;
        let (reservation, planned, reserved_annotation) = match seed {
            OrdinaryValueSeed::ConnectedCall { direct, layers } => {
                match frontier.select_ordinary_child_with(source.span(), tcx, |store, owner| {
                    match UnpreparedConnectedCallChain::plan(&direct, &layers, store, owner, tcx)? {
                        frontier::PlanningSelection::Selected(chain) => {
                            let reserved = match annotation.take() {
                                Some((written, plan)) => {
                                    Some(plan.reserve_for_owner(written, store, owner, tcx)?)
                                }
                                None => None,
                            };
                            Ok(frontier::PlanningSelection::Selected((chain, reserved)))
                        }
                        frontier::PlanningSelection::Unselected(outcome) => {
                            Ok(frontier::PlanningSelection::Unselected(outcome))
                        }
                    }
                })? {
                    frontier::PlanningSelection::Selected((reservation, (chain, reserved))) => (
                        reservation,
                        PlannedOrdinaryValue::ConnectedCall {
                            direct,
                            layers,
                            chain,
                        },
                        reserved,
                    ),
                    frontier::PlanningSelection::Unselected(ConnectedPlanOutcome::Decline {
                        layer,
                    }) => {
                        debug_assert!(layer < layers.len());
                        let fallback =
                            OrdinaryValueSeed::Recursive(OrdinaryRecursiveFamily::ComputedCall);
                        let (reservation, (planned, reserved)) = frontier
                            .reserve_ordinary_child_with(source.span(), tcx, |store, owner| {
                                let planned = Self::plan(source, fallback, store, owner, tcx)?;
                                let reserved = match annotation.take() {
                                    Some((written, plan)) => {
                                        Some(plan.reserve_for_owner(written, store, owner, tcx)?)
                                    }
                                    None => None,
                                };
                                Ok((planned, reserved))
                            })?;
                        (reservation, planned, reserved)
                    }
                    frontier::PlanningSelection::Unselected(
                        ConnectedPlanOutcome::NeedsDynamicSuccessor,
                    ) => {
                        let fallback =
                            OrdinaryValueSeed::Recursive(OrdinaryRecursiveFamily::ComputedCall);
                        let (reservation, (planned, reserved)) = frontier
                            .reserve_ordinary_child_with(source.span(), tcx, |store, owner| {
                                let planned = Self::plan(source, fallback, store, owner, tcx)?;
                                let reserved = match annotation.take() {
                                    Some((written, plan)) => {
                                        Some(plan.reserve_for_owner(written, store, owner, tcx)?)
                                    }
                                    None => None,
                                };
                                Ok((planned, reserved))
                            })?;
                        (reservation, planned, reserved)
                    }
                    frontier::PlanningSelection::Unselected(
                        ConnectedPlanOutcome::NonCallable { layer, error },
                    ) => {
                        debug_assert!(layer < layers.len());
                        return Err(error);
                    }
                }
            }
            seed => {
                let (reservation, (planned, reserved)) =
                    frontier.reserve_ordinary_child_with(source.span(), tcx, |store, owner| {
                        let planned = Self::plan(source, seed, store, owner, tcx)?;
                        let reserved = match annotation.take() {
                            Some((written, plan)) => {
                                Some(plan.reserve_for_owner(written, store, owner, tcx)?)
                            }
                            None => None,
                        };
                        Ok((planned, reserved))
                    })?;
                (reservation, planned, reserved)
            }
        };
        assert!(
            annotation.is_none(),
            "an ordinary child lost its annotation plan"
        );
        let mut child = frontier.open_ordinary_child(reservation)?;
        child.retain_quote_source(source, tcx);
        let annotation_expected = reserved_annotation.map(|reserved| {
            let (written, solver) = reserved.stage_into(child.publication_mut(), tcx);
            OwnerBoundType::Retained {
                owner: child.owner(),
                ty: solver,
            }
            .with_diagnostic(Some(written))
        });
        let expected = expected.or(annotation_expected);
        let cursor = match expected {
            Some(expected) => Self::bind(source, expected, planned),
            None => Self::bind_synth(source, planned),
        };
        Ok(OrdinaryChildContinuation {
            child,
            cursor: Box::new(cursor),
            next_mode: frontier::FrontierMode::ExpectedOnly,
            suspension: OrdinarySuspension::Mode,
        })
    }

    fn advance_open_child_iterative(
        continuation: OrdinaryChildContinuation<'m>,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
        relation_probe: bool,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OpenOrdinaryChildAdvance<'m>, Error> {
        fn contribute_pending_header<'m>(
            child: &mut OrdinaryChildContinuation<'m>,
            frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
            tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
        ) -> Result<(), Error> {
            let Some(expected) = child.cursor.expected.clone() else {
                return Ok(());
            };
            let span = child.cursor.source.span();
            let closed = {
                let mut child_frontier = frontier.ordinary_child_frontier(&mut child.child);
                let header = match &mut child.cursor.planned {
                    PlannedOrdinaryValue::Call(call) => {
                        fills::projected_call_header_result(call, span, &mut child_frontier, tcx)?
                    }
                    PlannedOrdinaryValue::Field(_) => fills::projected_field_header_result(
                        &mut child.cursor,
                        &mut child_frontier,
                        tcx,
                    )?,
                    _ => None,
                };
                let Some(header) = header else {
                    return Ok(());
                };
                let (store, _, delta, _) = child_frontier.parts_mut();
                store.try_zonk_goal_free(delta, header, tcx)?
            };
            let Some(closed) = closed else {
                return Ok(());
            };
            let export = frontier.reserve_parent_header_export(&child.child, closed, span)?;
            let header = export.parent_header().clone();
            frontier.install_parent_header_export(&mut child.child, export, span, tcx)?;
            try_apply_expected_equation(frontier, header, &expected, span, tcx)?;
            #[cfg(test)]
            record_public_header_work(|work| work.pending_exports += 1);
            Ok(())
        }

        fn restore_before_resume(
            scope_exit: OrdinaryDriverScopeExit,
            tcx: &mut TypeCtx<'_, '_, crate::ast::Lowered>,
        ) {
            if let OrdinaryDriverScopeExit::RestoreBeforeResume(mark) = scope_exit {
                tcx.restore(mark);
            }
        }

        fn restore_after_close_error(
            scope_exit: OrdinaryDriverScopeExit,
            tcx: &mut TypeCtx<'_, '_, crate::ast::Lowered>,
        ) {
            match scope_exit {
                OrdinaryDriverScopeExit::None => {}
                OrdinaryDriverScopeExit::RestoreBeforeResume(mark)
                | OrdinaryDriverScopeExit::RestoreAfterResume(mark) => tcx.restore(mark),
            }
        }

        fn restore_after_resume(
            scope_exit: OrdinaryDriverScopeExit,
            tcx: &mut TypeCtx<'_, '_, crate::ast::Lowered>,
        ) {
            if let OrdinaryDriverScopeExit::RestoreAfterResume(mark) = scope_exit {
                tcx.restore(mark);
            }
        }

        fn rec_order_runtime_for_use_from_causal_ancestors<'m>(
            frames: &mut [OrdinaryDriverFrame<'m>],
            frontier: &mut impl OrdinaryFrontierReentry<'m>,
            source: &'m crate::ast::Expr<crate::ast::Lowered>,
        ) -> Option<(crate::ast::TypeGoalOwner, ScopedType)> {
            for frame in frames.iter_mut().rev() {
                if let OrdinaryDriverHandoff::Bridge { bridge, .. } = &mut frame.handoff {
                    for owner in bridge.owners_mut().iter_mut().rev() {
                        let found = {
                            let bridge_frontier = frontier.ordinary_child_frontier(owner);
                            bridge_frontier
                                .rec_order_runtime_for_use(source)
                                .map(|checked| (bridge_frontier.owner(), checked))
                        };
                        if found.is_some() {
                            return found;
                        }
                    }
                }
                let found = {
                    let parent_frontier = frontier.ordinary_child_frontier(&mut frame.parent);
                    parent_frontier
                        .rec_order_runtime_for_use(source)
                        .map(|checked| (parent_frontier.owner(), checked))
                };
                if found.is_some() {
                    return found;
                }
            }
            frontier
                .rec_order_runtime_for_use(source)
                .map(|checked| (frontier.owner(), checked))
        }

        #[allow(clippy::type_complexity)]
        fn resume_frame<'m>(
            frame: OrdinaryDriverFrame<'m>,
            mut child: OpenOrdinaryChildAdvance<'m>,
            public_header_only: bool,
            frontier: &mut impl OrdinaryFrontierReentry<'m>,
            tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
        ) -> Result<
            (
                frontier::OpenRetainedPremise<'m>,
                frontier::FrontierMode,
                frontier::FrontierMode,
                OrdinaryCompletionDemand,
                bool,
                OrdinaryDriverStep<'m>,
            ),
            Error,
        > {
            let OrdinaryDriverFrame {
                mut parent,
                next_mode,
                inherited_mode,
                demand,
                mut handoff,
                scope_exit,
                relation_probe,
            } = frame;
            if public_header_only
                && !matches!(handoff, OrdinaryDriverHandoff::Open(_))
                && let OpenOrdinaryChildAdvance::Pending(child) = &mut child
            {
                #[cfg(test)]
                let bridge_exports_before =
                    matches!(&handoff, OrdinaryDriverHandoff::Bridge { .. })
                        .then(|| public_header_work().pending_exports);
                let mut parent_frontier = match &mut handoff {
                    OrdinaryDriverHandoff::Bridge { bridge, .. } => {
                        frontier.ordinary_child_frontier(bridge.innermost_mut())
                    }
                    OrdinaryDriverHandoff::Current(_) => {
                        frontier.ordinary_child_frontier(&mut parent)
                    }
                    OrdinaryDriverHandoff::Open(_) => unreachable!("open handoffs are unchanged"),
                };
                contribute_pending_header(child, &mut parent_frontier, tcx)?;
                #[cfg(test)]
                if let Some(before) = bridge_exports_before {
                    record_public_header_work(|work| {
                        work.bridge_exports += work.pending_exports - before;
                    });
                }
            }
            let next = match handoff {
                OrdinaryDriverHandoff::Current(resume) => {
                    let child = match child {
                        OpenOrdinaryChildAdvance::Pending(child) => {
                            OrdinaryChildAdvance::Pending(child)
                        }
                        OpenOrdinaryChildAdvance::Complete { child, completed } => {
                            let closed = {
                                let mut parent_frontier =
                                    frontier.ordinary_child_frontier(&mut parent);
                                let destination = parent_frontier.owner();
                                close_completed_ordinary_child(
                                    &mut parent_frontier,
                                    child,
                                    completed,
                                    destination,
                                    tcx,
                                )
                            };
                            match closed {
                                Ok(closed) => OrdinaryChildAdvance::Complete(closed),
                                Err(error) => {
                                    restore_after_close_error(scope_exit, tcx);
                                    return Err(error);
                                }
                            }
                        }
                    };
                    restore_before_resume(scope_exit, tcx);
                    {
                        let mut parent_frontier = frontier.ordinary_child_frontier(&mut parent);
                        resume(child, &mut parent_frontier, tcx)
                    }
                }
                OrdinaryDriverHandoff::Open(resume) => {
                    restore_before_resume(scope_exit, tcx);
                    {
                        let mut parent_frontier = frontier.ordinary_child_frontier(&mut parent);
                        resume(child, &mut parent_frontier, tcx)
                    }
                }
                OrdinaryDriverHandoff::Bridge { mut bridge, resume } => {
                    let child = match child {
                        OpenOrdinaryChildAdvance::Pending(child) => {
                            OrdinaryChildAdvance::Pending(child)
                        }
                        OpenOrdinaryChildAdvance::Complete { child, completed } => {
                            let closed = {
                                let mut bridge_frontier =
                                    frontier.ordinary_child_frontier(bridge.innermost_mut());
                                let destination = bridge_frontier.owner();
                                close_completed_ordinary_child(
                                    &mut bridge_frontier,
                                    child,
                                    completed,
                                    destination,
                                    tcx,
                                )
                            };
                            match closed {
                                Ok(closed) => OrdinaryChildAdvance::Complete(closed),
                                Err(error) => {
                                    restore_after_close_error(scope_exit, tcx);
                                    return Err(error);
                                }
                            }
                        }
                    };
                    restore_before_resume(scope_exit, tcx);
                    {
                        let mut parent_frontier = frontier.ordinary_child_frontier(&mut parent);
                        resume(bridge, child, &mut parent_frontier, tcx)
                    }
                }
            };
            restore_after_resume(scope_exit, tcx);
            let next = next?;
            let next = match next {
                OrdinaryDriverStep::AfterScope(resume) => {
                    assert!(
                        matches!(scope_exit, OrdinaryDriverScopeExit::RestoreAfterResume(_)),
                        "a post-scope continuation was returned without deferred restoration"
                    );
                    let mut parent_frontier = frontier.ordinary_child_frontier(&mut parent);
                    resume(&mut parent_frontier, tcx)?
                }
                next => {
                    assert!(
                        !matches!(scope_exit, OrdinaryDriverScopeExit::RestoreAfterResume(_)),
                        "a deferred scope restoration omitted its post-scope continuation"
                    );
                    next
                }
            };
            Ok((
                parent,
                next_mode,
                inherited_mode,
                demand,
                relation_probe,
                next,
            ))
        }

        let entry_mark = tcx.save();
        let public_header_only = demand == OrdinaryCompletionDemand::PublicHeader;
        assert!(
            !public_header_only || mode == frontier::FrontierMode::ExpectedOnly,
            "body-free header preparation must stay in its expectation-only pass"
        );
        let OrdinaryChildContinuation {
            child,
            cursor,
            next_mode,
            suspension,
        } = continuation;
        let completion_wait = matches!(suspension, OrdinarySuspension::Completion)
            && !cursor.completion_changed(frontier.store())?;
        assert!(
            mode != frontier::FrontierMode::RelationProbe || relation_probe,
            "an ordinary child entered RelationProbe outside a symmetric relation host"
        );
        let mut active = ActiveOrdinaryDriverChild {
            child,
            cursor: Some(cursor),
            next_mode,
            inherited_mode: mode,
            demand,
            relation_probe,
            completion_wait,
        };
        let mut frames = Vec::<OrdinaryDriverFrame<'m>>::new();
        let mut resumed = None;
        // Marked-only ancestor requests are rare. Build the exact open-frame
        // owner index lazily, then reuse it for every producer in the same
        // frozen adoption sweep. Any ordinary descent/unwind invalidates it.
        let mut ancestor_locations = None::<
            Box<
                std::collections::HashMap<
                    crate::ast::TypeGoalOwner,
                    OrdinaryDriverAncestorLocation,
                >,
            >,
        >;

        loop {
            if resumed.is_none()
                && (active.completion_wait
                    || active.next_mode.rank() > active.inherited_mode.rank())
            {
                let before_unwind = (|| {
                    let cursor = active
                        .cursor
                        .as_ref()
                        .expect("a suspended child retains its cursor");
                    if active.completion_wait {
                        if cursor.completion_changed(frontier.store())? {
                            return Ok(true);
                        }
                        if active.child.is_independent_source() {
                            cursor.require_completion_outside(
                                active.child.owner(),
                                frontier.store(),
                            )?;
                        }
                    }
                    if active.child.is_independent_source() && !active.completion_wait {
                        return Ok(false);
                    }
                    let contributed = if let Some(frame) = frames.last_mut() {
                        match &mut frame.handoff {
                            OrdinaryDriverHandoff::Current(_) | OrdinaryDriverHandoff::Open(_) => {
                                frontier
                                    .ordinary_child_frontier(&mut frame.parent)
                                    .forward_rec_order_entries(&mut active.child, tcx)?
                            }
                            OrdinaryDriverHandoff::Bridge { bridge, .. } => {
                                #[cfg(test)]
                                let is_chain = matches!(bridge, OrdinaryDriverBridge::Chain(_));
                                let mut contributed = frontier
                                    .ordinary_child_frontier(bridge.innermost_mut())
                                    .forward_rec_order_entries(&mut active.child, tcx)?;
                                #[cfg(test)]
                                let mut contributing_edges = usize::from(contributed);
                                let owners = bridge.owners_mut();
                                for index in (1..owners.len()).rev() {
                                    let (parents, children) = owners.split_at_mut(index);
                                    let edge_contributed = frontier
                                        .ordinary_child_frontier(&mut parents[index - 1])
                                        .forward_rec_order_entries(&mut children[0], tcx)?;
                                    contributed |= edge_contributed;
                                    #[cfg(test)]
                                    {
                                        contributing_edges += usize::from(edge_contributed);
                                    }
                                }
                                let edge_contributed = frontier
                                    .ordinary_child_frontier(&mut frame.parent)
                                    .forward_rec_order_entries(&mut owners[0], tcx)?;
                                contributed |= edge_contributed;
                                #[cfg(test)]
                                if is_chain {
                                    contributing_edges += usize::from(edge_contributed);
                                    record_completion_work(|work| {
                                        work.max_chain_contributing_edges = work
                                            .max_chain_contributing_edges
                                            .max(contributing_edges);
                                    });
                                }
                                contributed
                            }
                        }
                    } else {
                        frontier.forward_rec_order_entries(&mut active.child, tcx)?
                    };
                    // An accepted export can bind an old blocker to a proxy.
                    // Refresh at the origin before restoring any lexical scope.
                    let changed = active.completion_wait
                        && contributed
                        && cursor.completion_changed(frontier.store())?;
                    #[cfg(test)]
                    if changed {
                        record_completion_work(|work| work.transport_refreshes += 1);
                    }
                    Ok(changed)
                })();
                match before_unwind {
                    Ok(true) => {
                        active.completion_wait = false;
                        #[cfg(test)]
                        record_completion_work(|work| work.final_retries += 1);
                        continue;
                    }
                    Ok(false) => {}
                    Err(error) => {
                        tcx.restore(entry_mark);
                        return Err(error);
                    }
                }
                let pending = OrdinaryChildContinuation {
                    child: active.child,
                    cursor: active
                        .cursor
                        .take()
                        .expect("a suspended driver child retains its cursor"),
                    next_mode: active.next_mode,
                    suspension: if active.completion_wait {
                        OrdinarySuspension::Completion
                    } else {
                        OrdinarySuspension::Mode
                    },
                };
                if frames.is_empty() {
                    return Ok(OpenOrdinaryChildAdvance::Pending(pending));
                }
                let resumed_frame = resume_frame(
                    frames.pop().expect("the driver frame was checked above"),
                    OpenOrdinaryChildAdvance::Pending(pending),
                    public_header_only,
                    frontier,
                    tcx,
                );
                ancestor_locations = None;
                let (parent, next_mode, inherited_mode, demand, relation_probe, next) =
                    match resumed_frame {
                        Ok(resumed) => resumed,
                        Err(error) => {
                            tcx.restore(entry_mark);
                            return Err(error);
                        }
                    };
                active = ActiveOrdinaryDriverChild {
                    child: parent,
                    cursor: None,
                    next_mode,
                    inherited_mode,
                    demand,
                    relation_probe,
                    completion_wait: false,
                };
                resumed = Some(next);
                continue;
            }

            let step = match resumed.take() {
                Some(step) => step,
                None => {
                    let cursor = active
                        .cursor
                        .take()
                        .expect("an active driver child retains its cursor");
                    let current = active.next_mode;
                    let advanced = (|| {
                        if public_header_only {
                            let body_free = match &cursor.planned {
                                PlannedOrdinaryValue::Leaf(_) => true,
                                PlannedOrdinaryValue::Call(call) => {
                                    call.open_goal_call().is_some_and(|call| {
                                        call.immediate_lambda.is_none()
                                            && call.user_elaborator_transcript.is_none()
                                    })
                                }
                                PlannedOrdinaryValue::ComputedCall(_)
                                | PlannedOrdinaryValue::Recursive(
                                    OrdinaryRecursiveFamily::ComputedCall,
                                ) => true,
                                PlannedOrdinaryValue::Field(_)
                                | PlannedOrdinaryValue::Recursive(OrdinaryRecursiveFamily::Field) =>
                                {
                                    matches!(
                                        cursor.source,
                                        crate::ast::Expr::Elaborator {
                                            call: crate::ast::ElaboratorCall::FieldAccess { .. },
                                            ..
                                        }
                                    )
                                }
                                _ => false,
                            };
                            if !body_free {
                                #[cfg(test)]
                                if matches!(
                                    &cursor.planned,
                                    PlannedOrdinaryValue::UserElaborator(_)
                                ) {
                                    record_public_header_work(|work| work.blocked_elaborators += 1);
                                }
                                return Ok(OrdinaryDriverStep::Ready(
                                    OrdinaryValueAdvance::Pending(cursor),
                                ));
                            }
                        }
                        if current == frontier::FrontierMode::Final
                            && matches!(&cursor.planned, PlannedOrdinaryValue::PendingRecOrderPath)
                        {
                            let effective_source = tcx.effective_rec_order_source(cursor.source);
                            let checked = rec_order_runtime_for_use_from_causal_ancestors(
                                &mut frames,
                                frontier,
                                effective_source,
                            );
                            if let Some((parent_owner, checked)) = checked {
                                let checked = OwnerBoundType::Retained {
                                    owner: parent_owner,
                                    ty: checked,
                                };
                                let expected = cursor.expected.clone().expect(
                                    "a final pending recursive-order occurrence has an expected type",
                                );
                                let mut child_frontier =
                                    frontier.ordinary_child_frontier(&mut active.child);
                                let actual = {
                                    let (store, owner, delta, _publication) =
                                        child_frontier.parts_mut();
                                    let span = cursor.source.span();
                                    let actual = checked.into_scoped(owner, store, span)?;
                                    let expected = expected
                                        .into_expected_equation_operand(owner, store, span)?;
                                    store.constrain_equation(
                                        delta,
                                        actual.clone(),
                                        expected,
                                        span,
                                        tcx,
                                    )?;
                                    actual
                                };
                                let completed = CompletedInFrame::Value(actual, 0);
                                child_frontier.stage_rec_order(
                                    effective_source,
                                    PendingRecOrderState::Runtime {
                                        exact_ty: completed.scoped().ty().clone(),
                                        source_checked: false,
                                    },
                                    tcx,
                                )?;
                                Self::stage_expression_type(
                                    cursor.source,
                                    &completed,
                                    &mut child_frontier,
                                    tcx,
                                );
                                return Ok(OrdinaryDriverStep::Ready(
                                    OrdinaryValueAdvance::Complete(completed),
                                ));
                            }
                        }
                        let mut child_frontier =
                            frontier.ordinary_child_frontier(&mut active.child);
                        (*cursor).advance_step(current, active.demand, &mut child_frontier, tcx)
                    })();
                    match advanced {
                        Ok(step) => step,
                        Err(error) => {
                            tcx.restore(entry_mark);
                            return Err(error);
                        }
                    }
                }
            };

            match step {
                OrdinaryDriverStep::Descend(descend) => {
                    let OrdinaryDriverDescend {
                        child,
                        inherited_mode,
                        demand,
                        handoff,
                        scope_exit,
                    } = descend;
                    let OrdinaryChildContinuation {
                        child,
                        cursor,
                        next_mode,
                        suspension,
                    } = child;
                    let completion_wait = matches!(suspension, OrdinarySuspension::Completion)
                        && !cursor.completion_changed(frontier.store())?;
                    let child_relation_probe = active.relation_probe;
                    let parent = std::mem::replace(&mut active.child, child);
                    frames.push(OrdinaryDriverFrame {
                        parent,
                        next_mode: active.next_mode,
                        inherited_mode: active.inherited_mode,
                        demand: active.demand,
                        handoff,
                        scope_exit,
                        relation_probe: active.relation_probe,
                    });
                    #[cfg(test)]
                    update_ordinary_planning_work(|work| {
                        work.max_driver_frames = work.max_driver_frames.max(frames.len());
                    });
                    ancestor_locations = None;
                    active.cursor = Some(cursor);
                    active.next_mode = next_mode;
                    active.inherited_mode = inherited_mode;
                    active.demand = if public_header_only
                        && demand == OrdinaryCompletionDemand::GoalFreeValue
                    {
                        OrdinaryCompletionDemand::PublicHeader
                    } else {
                        demand
                    };
                    active.relation_probe = child_relation_probe;
                    active.completion_wait = completion_wait;
                }
                OrdinaryDriverStep::Ready(OrdinaryValueAdvance::Pending(cursor)) => {
                    if active.next_mode == frontier::FrontierMode::Final
                        && cursor.has_completion_wait()
                    {
                        active.completion_wait = !cursor.completion_changed(frontier.store())?;
                        #[cfg(test)]
                        if !active.completion_wait {
                            record_completion_work(|work| work.final_retries += 1);
                        }
                        active.cursor = Some(cursor);
                        continue;
                    }
                    active.cursor = Some(cursor);
                    #[cfg(test)]
                    record_completion_work(|work| work.mode_advances += 1);
                    active.next_mode = active
                        .next_mode
                        .successor(active.relation_probe)
                        .unwrap_or_else(|| {
                            unreachable!("an ordinary child remained pending after Final")
                        });
                }
                OrdinaryDriverStep::Ready(OrdinaryValueAdvance::Waiting(cursor)) => {
                    active.cursor = Some(cursor);
                    active.completion_wait = true;
                }
                OrdinaryDriverStep::Ready(OrdinaryValueAdvance::Complete(completed)) => {
                    let completed = OpenOrdinaryChildAdvance::Complete {
                        child: active.child,
                        completed,
                    };
                    if frames.is_empty() {
                        return Ok(completed);
                    }
                    let resumed_frame = resume_frame(
                        frames.pop().expect("the driver frame was checked above"),
                        completed,
                        public_header_only,
                        frontier,
                        tcx,
                    );
                    ancestor_locations = None;
                    let (parent, next_mode, inherited_mode, demand, relation_probe, next) =
                        match resumed_frame {
                            Ok(resumed) => resumed,
                            Err(error) => {
                                tcx.restore(entry_mark);
                                return Err(error);
                            }
                        };
                    active = ActiveOrdinaryDriverChild {
                        child: parent,
                        cursor: None,
                        next_mode,
                        inherited_mode,
                        demand,
                        relation_probe,
                        completion_wait: false,
                    };
                    resumed = Some(next);
                }
                OrdinaryDriverStep::Continue(resume) => {
                    let next = {
                        let mut child_frontier =
                            frontier.ordinary_child_frontier(&mut active.child);
                        resume(&mut child_frontier, tcx)
                    };
                    match next {
                        Ok(next) => resumed = Some(next),
                        Err(error) => {
                            tcx.restore(entry_mark);
                            return Err(error);
                        }
                    }
                }
                OrdinaryDriverStep::AfterScope(_) => {
                    tcx.restore(entry_mark);
                    unreachable!("a post-scope continuation escaped its owning driver frame")
                }
                OrdinaryDriverStep::AtAncestor { owner, resume } => {
                    let locations = ancestor_locations.get_or_insert_with(|| {
                        let mut locations = std::collections::HashMap::new();
                        locations.insert(
                            active.child.owner(),
                            OrdinaryDriverAncestorLocation::Current,
                        );
                        for (index, frame) in frames.iter().enumerate() {
                            assert!(
                                locations
                                    .insert(
                                        frame.parent.owner(),
                                        OrdinaryDriverAncestorLocation::Parent(index),
                                    )
                                    .is_none(),
                                "an ordinary driver retained one owner in two parent frames"
                            );
                            if let OrdinaryDriverHandoff::Bridge { bridge, .. } = &frame.handoff {
                                for (owner_index, owner) in bridge.owners().iter().enumerate() {
                                    assert!(
                                        locations
                                            .insert(
                                                owner.owner(),
                                                OrdinaryDriverAncestorLocation::Bridge(
                                                    index,
                                                    owner_index
                                                ),
                                            )
                                            .is_none(),
                                        "an ordinary driver retained one owner in two bridge frames"
                                    );
                                }
                            }
                        }
                        Box::new(locations)
                    });
                    let location = *locations.get(&owner).unwrap_or_else(|| {
                        unreachable!(
                            "a marked causal request targeted an owner absent from its live driver path"
                        )
                    });
                    let resume_current = match location {
                        OrdinaryDriverAncestorLocation::Current => {
                            let mut current = frontier.ordinary_child_frontier(&mut active.child);
                            resume(&mut current, tcx)
                        }
                        OrdinaryDriverAncestorLocation::Parent(index) => {
                            assert!(
                                frames[index..].iter().all(|frame| matches!(
                                    frame.scope_exit,
                                    OrdinaryDriverScopeExit::None
                                )),
                                "a marked ancestor request crossed an inactive lexical scope"
                            );
                            let frame = frames
                                .get_mut(index)
                                .expect("the ancestor-owner index named a missing parent frame");
                            let mut parent = frontier.ordinary_child_frontier(&mut frame.parent);
                            resume(&mut parent, tcx)
                        }
                        OrdinaryDriverAncestorLocation::Bridge(index, owner_index) => {
                            assert!(
                                frames[index + 1..].iter().all(|frame| matches!(
                                    frame.scope_exit,
                                    OrdinaryDriverScopeExit::None
                                )),
                                "a marked bridge request crossed an inactive lexical scope"
                            );
                            let frame = frames
                                .get_mut(index)
                                .expect("the ancestor-owner index named a missing bridge frame");
                            let OrdinaryDriverHandoff::Bridge { bridge, .. } = &mut frame.handoff
                            else {
                                unreachable!("the ancestor-owner index outlived its bridge handoff")
                            };
                            let mut bridge = frontier
                                .ordinary_child_frontier(&mut bridge.owners_mut()[owner_index]);
                            resume(&mut bridge, tcx)
                        }
                    };
                    let resume_current = match resume_current {
                        Ok(resume) => resume,
                        Err(error) => {
                            tcx.restore(entry_mark);
                            return Err(error);
                        }
                    };
                    let next = {
                        let mut current = frontier.ordinary_child_frontier(&mut active.child);
                        resume_current(&mut current, tcx)
                    };
                    match next {
                        Ok(next) => resumed = Some(next),
                        Err(error) => {
                            tcx.restore(entry_mark);
                            return Err(error);
                        }
                    }
                }
            }
        }
    }

    #[cfg(test)]
    fn advance_child_for_test(
        continuation: OrdinaryChildContinuation<'m>,
        mode: frontier::FrontierMode,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryChildAdvance<'m>, Error> {
        match Self::advance_open_child_iterative(
            continuation,
            mode,
            OrdinaryCompletionDemand::GoalFreeValue,
            false,
            frontier,
            tcx,
        )? {
            OpenOrdinaryChildAdvance::Pending(continuation) => {
                Ok(OrdinaryChildAdvance::Pending(continuation))
            }
            OpenOrdinaryChildAdvance::Complete { child, completed } => {
                let destination = frontier.owner();
                close_completed_ordinary_child(frontier, child, completed, destination, tcx)
                    .map(OrdinaryChildAdvance::Complete)
            }
        }
    }

    fn stage_expression_type(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        completed: &CompletedInFrame,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
    ) {
        let (_store, _owner, publication) = frontier.publication_mut();
        match completed {
            CompletedInFrame::Value(ty, _) => publication.record_position_type(
                source.span(),
                ty.clone(),
                tcx.in_scope_type_param_presentation(),
            ),
            CompletedInFrame::FunctionScheme(ty, _) => publication
                .record_scoped_function_scheme_position_type(
                    source.span(),
                    ty.clone(),
                    tcx.in_scope_type_param_presentation(),
                ),
            CompletedInFrame::UserElaboratorCall { .. } => {
                unreachable!("an elaborator transcript escaped its owning value cursor")
            }
        }
    }

    fn advance_let_step(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        continuation: Option<LetContinuation<'m>>,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
        frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryDriverStep<'m>, Error> {
        let crate::ast::Expr::Let {
            name,
            name_span,
            ty,
            value,
            body,
            ..
        } = source
        else {
            unreachable!("the Let continuation received another expression family")
        };
        let continuation = match continuation {
            Some(continuation) => continuation,
            None => {
                let mut prefix = match ty.as_ref() {
                    Some(annotation) => {
                        let lexical = super::annotation_plan::PlanningLexicalView::borrowed(tcx);
                        let plan = super::annotation_plan::plan_source_annotation(
                            annotation, tcx, &lexical, false,
                        )?;
                        drop(lexical);
                        Self::begin_annotated_child(value, annotation, plan, frontier, tcx)?
                    }
                    None => Self::begin_child(value, None, frontier, tcx)?,
                };
                prefix.child.mark_independent_source();
                LetContinuation::Prefix(prefix)
            }
        };
        let (bound, body_continuation) = match continuation {
            LetContinuation::Prefix(prefix) => {
                return Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
                    child: prefix,
                    inherited_mode: mode,
                    demand: OrdinaryCompletionDemand::GoalFreeValue,
                    handoff: OrdinaryDriverHandoff::Current(Box::new(
                        move |result, frontier, tcx| match result {
                            OrdinaryChildAdvance::Pending(prefix) => {
                                if mode == frontier::FrontierMode::Final
                                    && prefix.is_completion_wait()
                                {
                                    prefix.cursor.require_completion_outside(
                                        prefix.child.owner(),
                                        frontier.store(),
                                    )?;
                                }
                                if mode == frontier::FrontierMode::Final
                                    && !prefix.is_completion_wait()
                                {
                                    unreachable!("a Let prefix remained pending after Final")
                                }
                                Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::pending(
                                    Self {
                                        source,
                                        expected,
                                        planned: PlannedOrdinaryValue::Let(
                                            LetContinuation::Prefix(prefix),
                                        ),
                                    },
                                )))
                            }
                            OrdinaryChildAdvance::Complete(completed) => {
                                let bound = completed.scoped().ty().clone();
                                {
                                    let (_store, _owner, publication) = frontier.publication_mut();
                                    if name != "_" {
                                        publication.record_local_decl(
                                            name.clone(),
                                            *name_span,
                                            super::ResolvedBinderKind::Local,
                                        );
                                    }
                                    if name != "_"
                                        && ty.as_ref().is_none_or(|annotation| {
                                            matches!(annotation, crate::ast::Type::Infer { .. })
                                        })
                                    {
                                        publication.record_inlay_let_type(
                                            *name_span,
                                            completed.scoped().clone(),
                                            tcx.in_scope_type_param_presentation(),
                                        );
                                    }
                                }
                                let mark = tcx.save();
                                tcx.push_value_interned(name.clone(), bound.clone());
                                tcx.attach_decl_span_to_local(name, *name_span);
                                let body_continuation =
                                    Self::begin_child(body, expected.clone(), frontier, tcx);
                                tcx.restore(mark);
                                Self::advance_let_step(
                                    source,
                                    expected,
                                    Some(LetContinuation::Body {
                                        bound,
                                        body: body_continuation?,
                                    }),
                                    mode,
                                    demand,
                                    frontier,
                                    tcx,
                                )
                            }
                        },
                    )),
                    scope_exit: OrdinaryDriverScopeExit::None,
                }));
            }
            LetContinuation::Body { bound, body } => (bound, body),
        };
        let mark = tcx.save();
        tcx.push_value_interned(name.clone(), bound.clone());
        tcx.attach_decl_span_to_local(name, *name_span);
        Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
            child: body_continuation,
            inherited_mode: mode,
            demand,
            handoff: OrdinaryDriverHandoff::Current(Box::new(move |result, frontier, tcx| {
                match result {
                    OrdinaryChildAdvance::Pending(body) => {
                        if mode == frontier::FrontierMode::Final && !body.is_completion_wait() {
                            unreachable!("a Let continuation remained pending after Final")
                        }
                        Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::pending(
                            Self {
                                source,
                                expected,
                                planned: PlannedOrdinaryValue::Let(LetContinuation::Body {
                                    bound,
                                    body,
                                }),
                            },
                        )))
                    }
                    OrdinaryChildAdvance::Complete(completed) => {
                        Self::stage_expression_type(source, &completed, frontier, tcx);
                        Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::Complete(
                            completed,
                        )))
                    }
                }
            })),
            scope_exit: OrdinaryDriverScopeExit::RestoreBeforeResume(mark),
        }))
    }

    fn advance_sequence_step(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        continuation: Option<SequenceContinuation<'m>>,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
        frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryDriverStep<'m>, Error> {
        let crate::ast::Expr::Seq { value, body, .. } = source else {
            unreachable!("the Sequence continuation received another expression family")
        };
        let continuation = match continuation {
            Some(continuation) => continuation,
            None => SequenceContinuation::Prefix(Self::begin_child(
                value,
                Some(OwnerBoundType::Plain(InternedType::fresh_canonical(
                    crate::ast::Type::Unit {
                        meta: crate::ast::Meta::new(value.span()),
                    },
                ))),
                frontier,
                tcx,
            )?),
        };
        let body_continuation = match continuation {
            SequenceContinuation::Prefix(mut prefix) => {
                prefix.child.mark_independent_source();
                return Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
                    child: prefix,
                    inherited_mode: mode,
                    demand: OrdinaryCompletionDemand::GoalFreeValue,
                    handoff: OrdinaryDriverHandoff::Current(Box::new(
                        move |result, frontier, tcx| match result {
                            OrdinaryChildAdvance::Pending(prefix) => {
                                if mode == frontier::FrontierMode::Final
                                    && prefix.is_completion_wait()
                                {
                                    prefix.cursor.require_completion_outside(
                                        prefix.child.owner(),
                                        frontier.store(),
                                    )?;
                                }
                                if mode == frontier::FrontierMode::Final
                                    && !prefix.is_completion_wait()
                                {
                                    unreachable!("a Sequence prefix remained pending after Final")
                                }
                                Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::pending(
                                    Self {
                                        source,
                                        expected,
                                        planned: PlannedOrdinaryValue::Sequence(
                                            SequenceContinuation::Prefix(prefix),
                                        ),
                                    },
                                )))
                            }
                            OrdinaryChildAdvance::Complete(_) => {
                                let body =
                                    Self::begin_child(body, expected.clone(), frontier, tcx)?;
                                Self::advance_sequence_step(
                                    source,
                                    expected,
                                    Some(SequenceContinuation::Body(body)),
                                    mode,
                                    demand,
                                    frontier,
                                    tcx,
                                )
                            }
                        },
                    )),
                    scope_exit: OrdinaryDriverScopeExit::None,
                }));
            }
            SequenceContinuation::Body(body) => body,
        };
        Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
            child: body_continuation,
            inherited_mode: mode,
            demand,
            handoff: OrdinaryDriverHandoff::Current(Box::new(move |result, frontier, tcx| {
                match result {
                    OrdinaryChildAdvance::Pending(body) => {
                        if mode == frontier::FrontierMode::Final && !body.is_completion_wait() {
                            unreachable!("a Sequence body remained pending after Final")
                        }
                        Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::pending(
                            Self {
                                source,
                                expected,
                                planned: PlannedOrdinaryValue::Sequence(
                                    SequenceContinuation::Body(body),
                                ),
                            },
                        )))
                    }
                    OrdinaryChildAdvance::Complete(completed) => {
                        Self::stage_expression_type(source, &completed, frontier, tcx);
                        Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::Complete(
                            completed,
                        )))
                    }
                }
            })),
            scope_exit: OrdinaryDriverScopeExit::None,
        }))
    }

    fn finish_field(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        prepared: crate::pass::typecheck_full::PreparedFieldElaboration,
        demand: OrdinaryCompletionDemand,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryValueAdvance<'m>, Error> {
        let crate::ast::Expr::Elaborator { ext, .. } = source else {
            unreachable!("the Field finalizer received another expression family")
        };
        let binders = tcx.in_scope_type_param_presentation();
        let mut actual = {
            let (store, owner, delta, publication) = frontier.parts_mut();
            let actual = store.scoped_type(owner, prepared.result_ty, source.span())?;
            if let Some(expected) = expected.as_ref() {
                let expected =
                    expected
                        .clone()
                        .into_expected_equation_operand(owner, store, source.span())?;
                store.constrain_equation(delta, actual.clone(), expected, source.span(), tcx)?;
            }
            publication.record_lowered_elaboration(store, *ext, prepared.replacement);
            publication.record_prime_requalification_bindings(prepared.imports, prepared.aliases);
            actual
        };
        let retained_callable =
            if expected.is_none() && demand == OrdinaryCompletionDemand::ImmediateCallee {
                Self::retain_callable_progress(&mut actual, frontier, tcx)?
            } else {
                None
            };
        {
            let (_store, _owner, publication) = frontier.publication_mut();
            match retained_callable {
                Some(RetainedCallableProgress::FunctionScheme) => publication
                    .record_scoped_function_scheme_position_type(
                        source.span(),
                        actual.clone(),
                        binders,
                    ),
                Some(
                    RetainedCallableProgress::Function | RetainedCallableProgress::PolymorphicValue,
                )
                | None => publication.record_position_type(source.span(), actual.clone(), binders),
            }
        }
        Ok(OrdinaryValueAdvance::Complete(match retained_callable {
            Some(RetainedCallableProgress::FunctionScheme) => {
                CompletedInFrame::FunctionScheme(actual, 0)
            }
            Some(
                RetainedCallableProgress::Function | RetainedCallableProgress::PolymorphicValue,
            )
            | None => CompletedInFrame::Value(actual, 0),
        }))
    }

    fn field_value_type(completed: CompletedInFrame, span: Span) -> Result<ScopedType, Error> {
        match completed {
            CompletedInFrame::Value(ty, _) => Ok(ty),
            CompletedInFrame::FunctionScheme(_, _) => {
                Err(super::types::scheme_in_mono_position(span))
            }
            CompletedInFrame::UserElaboratorCall { .. } => {
                unreachable!("an elaborator transcript escaped its owning value cursor")
            }
        }
    }

    fn begin_field_update_value(
        update: &'m crate::ast::FieldUpdateLabel<crate::ast::Lowered>,
        expected: Option<&OwnerBoundType>,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryChildContinuation<'m>, Error> {
        let expected = Self::progressed_field_expected(expected, update.meta.span, frontier, tcx)?;
        let expected = crate::pass::typecheck_full::field_update_expected_type(
            update,
            expected.as_ref(),
            tcx,
        )?
        .map(OwnerBoundType::Plain);
        Self::begin_child(&update.value, expected, frontier, tcx)
    }

    fn progressed_field_expected(
        expected: Option<&OwnerBoundType>,
        span: Span,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<Option<InternedType<crate::ast::Lowered>>, Error> {
        let Some(expected) = expected else {
            return Ok(None);
        };
        let expected = expected.clone();
        let (store, owner, delta, _publication) = frontier.parts_mut();
        let scoped = expected.into_scoped(owner, store, span)?;
        let progressed = store.zonk_for_progress(delta, scoped, tcx)?;
        Ok(Some(progressed.ty().clone()))
    }

    fn prepare_completed_field(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<&OwnerBoundType>,
        receiver_ty: InternedType<crate::ast::Lowered>,
        rhs_types: &[InternedType<crate::ast::Lowered>],
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<crate::pass::typecheck_full::PreparedFieldElaboration, Error> {
        let crate::ast::Expr::Elaborator {
            call,
            meta: crate::ast::Meta { span, .. },
            ..
        } = source
        else {
            unreachable!("field preparation received another expression family")
        };
        match call {
            crate::ast::ElaboratorCall::FieldAccess { receiver, labels } => {
                debug_assert!(rhs_types.is_empty());
                crate::pass::typecheck_full::prepare_field_access_elaboration(
                    source,
                    receiver,
                    labels,
                    receiver_ty,
                    *span,
                    tcx,
                )
            }
            crate::ast::ElaboratorCall::FieldUpdate { receiver, updates } => {
                let expected = Self::progressed_field_expected(expected, *span, frontier, tcx)?;
                crate::pass::typecheck_full::prepare_field_update_elaboration(
                    source,
                    receiver,
                    updates,
                    receiver_ty,
                    rhs_types,
                    expected.as_ref(),
                    *span,
                    tcx,
                )
            }
        }
    }

    fn advance_field_step(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        continuation: Option<FieldContinuation<'m>>,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
        frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryDriverStep<'m>, Error> {
        let crate::ast::Expr::Elaborator { call, .. } = source else {
            unreachable!("the Field continuation received another expression family")
        };
        let receiver_source = match call {
            crate::ast::ElaboratorCall::FieldAccess { receiver, .. }
            | crate::ast::ElaboratorCall::FieldUpdate { receiver, .. } => receiver.as_ref(),
        };
        let continuation = match continuation {
            Some(continuation) => continuation,
            None => FieldContinuation::Receiver(Self::begin_child(
                receiver_source,
                None,
                frontier,
                tcx,
            )?),
        };
        match continuation {
            FieldContinuation::Receiver(mut receiver) => {
                receiver.child.mark_independent_source();
                Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
                    child: receiver,
                    inherited_mode: mode,
                    demand: OrdinaryCompletionDemand::GoalFreeValue,
                    handoff: OrdinaryDriverHandoff::Current(Box::new(
                        move |advance, frontier, tcx| match advance {
                            OrdinaryChildAdvance::Pending(receiver) => {
                                if mode == frontier::FrontierMode::Final
                                    && !receiver.is_completion_wait()
                                {
                                    unreachable!("a Field receiver remained pending after Final")
                                }
                                Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::pending(
                                    Self {
                                        source,
                                        expected,
                                        planned: PlannedOrdinaryValue::Field(
                                            FieldContinuation::Receiver(receiver),
                                        ),
                                    },
                                )))
                            }
                            OrdinaryChildAdvance::Complete(completed) => {
                                let receiver =
                                    Self::field_value_type(completed, receiver_source.span())?;
                                let crate::ast::ElaboratorCall::FieldUpdate { updates, .. } = call
                                else {
                                    let prepared = Self::prepare_completed_field(
                                        source,
                                        expected.as_ref(),
                                        receiver.ty().clone(),
                                        &[],
                                        frontier,
                                        tcx,
                                    )?;
                                    return Self::finish_field(
                                        source, expected, prepared, demand, frontier, tcx,
                                    )
                                    .map(OrdinaryDriverStep::Ready);
                                };
                                let Some(first) = updates.first() else {
                                    let prepared = Self::prepare_completed_field(
                                        source,
                                        expected.as_ref(),
                                        receiver.ty().clone(),
                                        &[],
                                        frontier,
                                        tcx,
                                    )?;
                                    return Self::finish_field(
                                        source, expected, prepared, demand, frontier, tcx,
                                    )
                                    .map(OrdinaryDriverStep::Ready);
                                };
                                let current = Self::begin_field_update_value(
                                    first,
                                    expected.as_ref(),
                                    frontier,
                                    tcx,
                                )?;
                                Self::advance_field_step(
                                    source,
                                    expected,
                                    Some(FieldContinuation::UpdateValues {
                                        receiver,
                                        completed: Vec::with_capacity(updates.len()),
                                        current,
                                        next: 0,
                                    }),
                                    mode,
                                    demand,
                                    frontier,
                                    tcx,
                                )
                            }
                        },
                    )),
                    scope_exit: OrdinaryDriverScopeExit::None,
                }))
            }
            FieldContinuation::UpdateValues {
                receiver,
                mut completed,
                mut current,
                next,
            } => {
                let crate::ast::ElaboratorCall::FieldUpdate { updates, .. } = call else {
                    unreachable!("a field-access continuation retained update-value state")
                };
                let value_span = updates[next].value.span();
                current.child.mark_independent_source();
                Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
                    child: current,
                    inherited_mode: mode,
                    demand: OrdinaryCompletionDemand::GoalFreeValue,
                    handoff: OrdinaryDriverHandoff::Current(Box::new(
                        move |advance, frontier, tcx| match advance {
                            OrdinaryChildAdvance::Pending(current) => {
                                if mode == frontier::FrontierMode::Final
                                    && !current.is_completion_wait()
                                {
                                    unreachable!(
                                        "a Field update value remained pending after Final"
                                    )
                                }
                                Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::pending(
                                    Self {
                                        source,
                                        expected,
                                        planned: PlannedOrdinaryValue::Field(
                                            FieldContinuation::UpdateValues {
                                                receiver,
                                                completed,
                                                current,
                                                next,
                                            },
                                        ),
                                    },
                                )))
                            }
                            OrdinaryChildAdvance::Complete(value) => {
                                completed.push(Self::field_value_type(value, value_span)?);
                                let next = next + 1;
                                if next == updates.len() {
                                    let rhs_types = completed
                                        .iter()
                                        .map(|ty| ty.ty().clone())
                                        .collect::<Vec<_>>();
                                    let prepared = Self::prepare_completed_field(
                                        source,
                                        expected.as_ref(),
                                        receiver.ty().clone(),
                                        &rhs_types,
                                        frontier,
                                        tcx,
                                    )?;
                                    return Self::finish_field(
                                        source, expected, prepared, demand, frontier, tcx,
                                    )
                                    .map(OrdinaryDriverStep::Ready);
                                }
                                let current = Self::begin_field_update_value(
                                    &updates[next],
                                    expected.as_ref(),
                                    frontier,
                                    tcx,
                                )?;
                                Self::advance_field_step(
                                    source,
                                    expected,
                                    Some(FieldContinuation::UpdateValues {
                                        receiver,
                                        completed,
                                        current,
                                        next,
                                    }),
                                    mode,
                                    demand,
                                    frontier,
                                    tcx,
                                )
                            }
                        },
                    )),
                    scope_exit: OrdinaryDriverScopeExit::None,
                }))
            }
        }
    }

    fn begin_computed_application(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        callee: Synth<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryChildContinuation<'m>, Error> {
        let crate::ast::Expr::Call {
            callee: callee_source,
            args,
            meta: _,
            ..
        } = source
        else {
            unreachable!("a computed-call continuation received another expression family")
        };
        let args = call_arg_refs(args);
        reject_invalid_polymorphic_non_function_application(&callee.ty, &args, source.site(), tcx)?;
        let (reservation, plan) =
            frontier.reserve_ordinary_child_with(source.span(), tcx, |store, owner| {
                open_selecting_goal_call(
                    &callee,
                    args,
                    None,
                    None,
                    0,
                    callee_source.span(),
                    source.site(),
                    EmptyCallMode::ImplicitUnit,
                    None,
                    store,
                    owner,
                    tcx,
                )
                .map(|selecting| {
                    PlannedOrdinaryValue::Call(OrdinaryCallContinuation::Selecting(Box::new(
                        selecting,
                    )))
                })
            })?;
        let cursor = match expected {
            Some(expected) => Self::bind(source, expected, plan),
            None => Self::bind_synth(source, plan),
        };
        let child = frontier.open_ordinary_child(reservation)?;
        Ok(OrdinaryChildContinuation {
            child,
            cursor: Box::new(cursor),
            next_mode: frontier::FrontierMode::ExpectedOnly,
            suspension: OrdinarySuspension::Mode,
        })
    }

    fn advance_computed_call_step(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<OwnerBoundType>,
        continuation: Option<ComputedCallContinuation<'m>>,
        mode: frontier::FrontierMode,
        demand: OrdinaryCompletionDemand,
        frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryDriverStep<'m>, Error> {
        let crate::ast::Expr::Call { callee, .. } = source else {
            unreachable!("a computed-call continuation received another expression family")
        };
        let continuation = match continuation {
            Some(continuation) => continuation,
            None => {
                ComputedCallContinuation::Callee(Self::begin_child(callee, None, frontier, tcx)?)
            }
        };
        match continuation {
            ComputedCallContinuation::PlannedLambda(header) => {
                let callee_continuation = Self::begin_seeded_child(
                    callee,
                    None,
                    OrdinaryValueSeed::Lambda(OrdinaryLambdaSeed { header }),
                    frontier,
                    tcx,
                )?;
                Self::advance_computed_call_step(
                    source,
                    expected,
                    Some(ComputedCallContinuation::Callee(callee_continuation)),
                    mode,
                    demand,
                    frontier,
                    tcx,
                )
            }
            ComputedCallContinuation::Callee(mut callee_continuation) => {
                callee_continuation.child.mark_independent_source();
                Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
                    child: callee_continuation,
                    inherited_mode: mode,
                    demand: OrdinaryCompletionDemand::ImmediateCallee,
                    handoff: OrdinaryDriverHandoff::Open(Box::new(
                        move |advance, frontier, tcx| match advance {
                            OpenOrdinaryChildAdvance::Pending(callee_continuation) => {
                                if mode == frontier::FrontierMode::Final
                                    && !callee_continuation.is_completion_wait()
                                {
                                    unreachable!("a computed callee remained pending after Final")
                                }
                                Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::pending(
                                    Self {
                                        source,
                                        expected,
                                        planned: PlannedOrdinaryValue::ComputedCall(
                                            ComputedCallContinuation::Callee(callee_continuation),
                                        ),
                                    },
                                )))
                            }
                            OpenOrdinaryChildAdvance::Complete {
                                mut child,
                                completed,
                            } => {
                                child.finish_independent_source();
                                let inferred_type_arg_suffix = completed.inferred_type_arg_suffix();
                                let callee = match completed {
                                    CompletedInFrame::Value(ty, _) => {
                                        Synth::value_interned(ty.ty().clone())
                                    }
                                    CompletedInFrame::FunctionScheme(ty, _) => {
                                        Synth::complete_scheme_interned(ty.ty().clone())
                                    }
                                    CompletedInFrame::UserElaboratorCall { .. } => unreachable!(
                                        "an elaborator transcript escaped its owning value cursor"
                                    ),
                                }
                                .with_inferred_type_arg_suffix(inferred_type_arg_suffix);
                                let application = {
                                    let mut callee_frontier =
                                        frontier.ordinary_child_frontier(&mut child);
                                    Self::begin_computed_application(
                                        source,
                                        callee,
                                        expected.clone(),
                                        &mut callee_frontier,
                                        tcx,
                                    )?
                                };
                                Self::advance_computed_call_step(
                                    source,
                                    expected,
                                    Some(ComputedCallContinuation::Application {
                                        callee_child: child,
                                        application,
                                    }),
                                    mode,
                                    demand,
                                    frontier,
                                    tcx,
                                )
                            }
                        },
                    )),
                    scope_exit: OrdinaryDriverScopeExit::None,
                }))
            }
            ComputedCallContinuation::Application {
                callee_child,
                application,
            } => Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
                child: application,
                inherited_mode: mode,
                demand,
                handoff: OrdinaryDriverHandoff::Bridge {
                    bridge: OrdinaryDriverBridge::Direct(callee_child),
                    resume: Box::new(move |bridge, advance, frontier, tcx| {
                        let OrdinaryDriverBridge::Direct(callee_child) = bridge else {
                            unreachable!("a computed callee resumed through a lambda owner chain")
                        };
                        match advance {
                            OrdinaryChildAdvance::Pending(application) => {
                                if mode == frontier::FrontierMode::Final
                                    && !application.is_completion_wait()
                                {
                                    unreachable!(
                                        "a computed application remained pending after Final"
                                    )
                                }
                                Ok(OrdinaryDriverStep::Ready(OrdinaryValueAdvance::pending(
                                    Self {
                                        source,
                                        expected,
                                        planned: PlannedOrdinaryValue::ComputedCall(
                                            ComputedCallContinuation::Application {
                                                callee_child,
                                                application,
                                            },
                                        ),
                                    },
                                )))
                            }
                            OrdinaryChildAdvance::Complete(completed) => {
                                let destination = frontier.owner();
                                close_completed_ordinary_child(
                                    frontier,
                                    callee_child,
                                    completed,
                                    destination,
                                    tcx,
                                )
                                .map(OrdinaryValueAdvance::Complete)
                                .map(OrdinaryDriverStep::Ready)
                            }
                        }
                    }),
                },
                scope_exit: OrdinaryDriverScopeExit::None,
            })),
        }
    }

    fn advance_literal(
        self,
        mode: frontier::FrontierMode,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryValueAdvance<'m>, Error> {
        let (shape, annotation, span) = super::literal_check_parts(self.source)
            .expect("the literal cursor admitted another Lowered expression family");
        let (store, owner, delta, publication) = frontier.parts_mut();
        let scoped_expected = self
            .expected
            .clone()
            .map(|expected| expected.into_scoped(owner, store, span))
            .transpose()?;
        let ready = scoped_expected
            .as_ref()
            .map(|expected| store.try_zonk_goal_free(delta, expected.clone(), tcx))
            .transpose()?
            .flatten();
        let resolved = match ready {
            Some(ready) => super::synth::resolve_literal_against_unrecorded(
                shape,
                annotation,
                ready.ty(),
                span,
                tcx,
            )?,
            None if mode == frontier::FrontierMode::ExpectedOnly
                && is_expected_dependent_scalar(self.source) =>
            {
                return Ok(OrdinaryValueAdvance::pending(self));
            }
            None => super::synth::synth_literal_unrecorded(shape, annotation, span, tcx)?,
        };
        let actual = store.scoped_type(owner, resolved, span)?;
        if let Some(expected) = self.expected {
            let expected = expected.into_expected_equation_operand(owner, store, span)?;
            store.constrain_equation(delta, actual.clone(), expected, span, tcx)?;
        }
        publication.record_literal_resolution(self.source.site(), actual.clone());
        publication.record_position_type(
            span,
            actual.clone(),
            tcx.in_scope_type_param_presentation(),
        );
        #[cfg(all(test, feature = "surface"))]
        update_direct_lambda_work(|work| work.known_source_advances += 1);
        Ok(OrdinaryValueAdvance::Complete(CompletedInFrame::Value(
            actual, 0,
        )))
    }

    fn advance_selected_path_unit(
        self,
        mode: frontier::FrontierMode,
        prepared: PreparedOrdinaryValue<'m>,
        context: &mut SimpleGoalLeafContext<'_>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<OrdinaryValueAdvance<'m>, Error> {
        assert_eq!(
            mode,
            frontier::FrontierMode::Final,
            "the selected Path/Unit route advances at its final frontier"
        );
        assert!(
            std::ptr::eq(self.source, prepared.source),
            "an ordinary value cursor received another premise's preparation"
        );
        let result = match self.source {
            crate::ast::Expr::BlockCall { ext, .. } => match *ext {},
            crate::ast::Expr::Path { .. } | crate::ast::Expr::Unit { .. } => context
                .constrain_prepared(
                    prepared,
                    self.expected
                        .clone()
                        .expect("the selected Path/Unit route requires an expected type"),
                    tcx,
                ),
            crate::ast::Expr::Call { .. }
            | crate::ast::Expr::FnExpr { .. }
            | crate::ast::Expr::Let { .. }
            | crate::ast::Expr::Seq { .. }
            | crate::ast::Expr::StrLit { .. }
            | crate::ast::Expr::IntLit { .. }
            | crate::ast::Expr::FloatLit { .. }
            | crate::ast::Expr::BoolLit { .. }
            | crate::ast::Expr::Elaborator { .. }
            | crate::ast::Expr::RecOrder { .. }
            | crate::ast::Expr::RecQuote { .. }
            | crate::ast::Expr::UserElaborator { .. }
            | crate::ast::Expr::Ufcs { .. } => {
                unreachable!("the Path/Unit selector admitted another Lowered expression family")
            }
            crate::ast::Expr::RecCall { ext, .. }
            | crate::ast::Expr::RowLet { ext, .. }
            | crate::ast::Expr::Tuple { ext, .. }
            | crate::ast::Expr::FnPlaceholder { ext, .. }
            | crate::ast::Expr::LabelValue { ext, .. }
            | crate::ast::Expr::OpChain { ext, .. }
            | crate::ast::Expr::EnrichedTuple { ext, .. }
            | crate::ast::Expr::EnrichedProject { ext, .. }
            | crate::ast::Expr::EnrichedInject { ext, .. }
            | crate::ast::Expr::EnrichedMatch { ext, .. }
            | crate::ast::Expr::EnrichedConditional { ext, .. }
            | crate::ast::Expr::EnrichedRecord { ext, .. }
            | crate::ast::Expr::EnrichedFieldGet { ext, .. }
            | crate::ast::Expr::LowHostCall { ext, .. }
            | crate::ast::Expr::LowModuleCall { ext, .. }
            | crate::ast::Expr::LowQualifiedModuleCall { ext, .. }
            | crate::ast::Expr::LowQualifiedNewtypeMember { ext, .. }
            | crate::ast::Expr::LowNewtypeCtor { ext, .. }
            | crate::ast::Expr::LowNewtypeProj { ext, .. }
            | crate::ast::Expr::LowClosureCall { ext, .. }
            | crate::ast::Expr::LowIndirectCall { ext, .. }
            | crate::ast::Expr::LowTypeApplication { ext, .. }
            | crate::ast::Expr::LowAbsurdCall { ext, .. }
            | crate::ast::Expr::LowCpsProjectorApply { ext, .. }
            | crate::ast::Expr::LowBoundRef { ext, .. }
            | crate::ast::Expr::LowHostFnValueRef { ext, .. }
            | crate::ast::Expr::LowModuleFnValueRef { ext, .. } => match *ext {},
        };
        result.map(OrdinaryValueAdvance::Complete)
    }
}

#[cfg(feature = "surface")]
#[allow(clippy::too_many_arguments)] // lambda selection consumes the full retained-frontier context
fn select_ordinary_lambda<'m>(
    source: &'m crate::ast::Expr<crate::ast::Lowered>,
    header: &mut super::annotation_plan::LambdaHeaderPlan<'m>,
    expected: Option<&OwnerBoundType>,
    mode: frontier::FrontierMode,
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<OrdinaryLambdaSelectionResult, Error> {
    if let Some(expected) = expected {
        let progressed = {
            let (store, owner, delta, _publication) = frontier.parts_mut();
            let expected = expected.clone().into_scoped(owner, store, source.span())?;
            store.zonk_for_progress(delta, expected, tcx)?
        };
        if let Some((body_type, value_param_types)) =
            header.select_check(progressed.ty(), source.span(), tcx)?
        {
            return Ok(Some((
                OrdinaryLambdaSelection::Check {
                    body_type: OwnerBoundType::Plain(body_type),
                },
                value_param_types,
            )));
        }
    }

    // Keep an expectation-only probe unselected unless an expected function
    // shape chose checking, so a call selector can attach its known value slot
    // before the body commits to standalone synthesis.
    if mode == frontier::FrontierMode::ExpectedOnly {
        return Ok(None);
    }

    let Some((value_param_types, annotated_return)) =
        header.select_synth(mode == frontier::FrontierMode::Final, tcx)?
    else {
        return Ok(None);
    };
    Ok(Some((
        OrdinaryLambdaSelection::Synthesizing { annotated_return },
        value_param_types,
    )))
}

#[cfg(feature = "surface")]
fn prepare_signature_for_close<'m>(
    sig: &'m crate::ast::Signature<crate::ast::Lowered>,
    body_type: OwnerBoundType,
    value_param_types: &[OwnerBoundType],
    retained_binders: &[super::RetainedTypeBinder<'m>],
    span: Span,
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<PreparedCloseType, Error> {
    let (store, owner, delta, _publication) = frontier.parts_mut();
    let body = body_type.into_scoped(owner, store, span)?;
    let mut result = store.zonk_for_close(delta, body, tcx)?;
    let mut values = value_param_types
        .iter()
        .cloned()
        .map(|ty| {
            let scoped = ty.into_scoped(owner, store, span)?;
            store.zonk_for_close(delta, scoped, tcx)
        })
        .collect::<Result<Vec<_>, Error>>()?;

    let mut binder_end = retained_binders.len();
    if !sig.has_value_group() {
        result = store.value_group_function_for_close(Vec::new(), result, span)?;
    }
    for group in sig.canonical_group_refs().rev() {
        match group {
            crate::ast::SignatureGroupRef::Type(params) => {
                for param in params.iter().rev() {
                    let crate::ast::SignatureParam::Type(param) = param else {
                        unreachable!("a signature type group contains only type parameters")
                    };
                    binder_end = binder_end
                        .checked_sub(1)
                        .expect("a signature retained too few type binders");
                    let binder = &retained_binders[binder_end];
                    assert_eq!(
                        binder.param().name,
                        param.name,
                        "a retained signature binder lost source order"
                    );
                    result = store.abstract_lexical_forall(result, binder);
                }
            }
            crate::ast::SignatureGroupRef::Value(params) => {
                let start = values
                    .len()
                    .checked_sub(params.len())
                    .expect("a signature retained too few value parameters");
                let group_values = values.split_off(start);
                result = store.value_group_function_for_close(group_values, result, span)?;
            }
        }
    }
    assert_eq!(binder_end, 0, "a signature retained extra type binders");
    assert!(
        values.is_empty(),
        "a signature retained extra value parameters"
    );
    Ok(result)
}

#[cfg(feature = "surface")]
#[allow(clippy::too_many_arguments)] // header preparation shares the selector's retained context
fn prepare_ordinary_lambda_header<'m>(
    source: &'m crate::ast::Expr<crate::ast::Lowered>,
    sig: &'m crate::ast::Signature<crate::ast::Lowered>,
    ret_ty: Option<&'m crate::ast::Type<crate::ast::Lowered>>,
    header: &mut super::annotation_plan::LambdaHeaderPlan<'m>,
    selection: OrdinaryLambdaSelection,
    value_param_types: Vec<OwnerBoundType>,
    retained_binders: &[super::RetainedTypeBinder<'m>],
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<(OrdinaryLambdaSelection, Vec<OwnerBoundType>), Error> {
    #[cfg(test)]
    {
        record_lambda_header();
        super::annotation_plan::record_ordinary_retained_consumer();
    }
    let all_binders_mark = tcx.save();
    for binder in retained_binders {
        tcx.push_retained_type_binder(binder);
    }
    let mut prepared_value_types = Vec::with_capacity(value_param_types.len());
    for ty in value_param_types {
        prepared_value_types.push(match ty {
            OwnerBoundType::Plain(ty) => {
                prepare_owner_bound_type(frontier, ty, source.span(), tcx)?
            }
            retained @ OwnerBoundType::Retained { .. } => {
                let owner = frontier.owner();
                let ty = retained.into_scoped(owner, frontier.store(), source.span())?;
                OwnerBoundType::Retained { owner, ty }
            }
            OwnerBoundType::Diagnostic { solver, written } => {
                let solver = match *solver {
                    OwnerBoundType::Plain(ty) => {
                        prepare_owner_bound_type(frontier, ty, source.span(), tcx)?
                    }
                    retained @ OwnerBoundType::Retained { .. } => {
                        let owner = frontier.owner();
                        let ty = retained.into_scoped(owner, frontier.store(), source.span())?;
                        OwnerBoundType::Retained { owner, ty }
                    }
                    OwnerBoundType::Diagnostic { .. } => {
                        unreachable!("an owner-bound type retained nested diagnostic wrappers")
                    }
                };
                solver.with_diagnostic(Some(written))
            }
        });
    }
    let selection = match selection {
        OrdinaryLambdaSelection::Check { body_type } => OrdinaryLambdaSelection::Check {
            body_type: prepare_owner_bound_type(
                frontier,
                body_type.ty().clone(),
                source.span(),
                tcx,
            )?,
        },
        synth @ (OrdinaryLambdaSelection::Synthesizing { .. }
        | OrdinaryLambdaSelection::Synth { .. }) => synth,
    };
    tcx.restore(all_binders_mark);

    let mut retained = retained_binders.iter();
    let mut values = prepared_value_types.iter_mut();
    let mut value_index = 0usize;
    for param in &sig.params {
        match param {
            crate::ast::SignatureParam::Type(param) => {
                let binder = retained
                    .next()
                    .expect("a lambda seed retains every source type binder");
                tcx.push_retained_type_binder(binder);
                tcx.attach_decl_span_to_local(&param.name, param.span);
                let (_store, _owner, publication) = frontier.publication_mut();
                publication.record_local_decl(
                    param.name.clone(),
                    param.span,
                    super::ResolvedBinderKind::TypeParam,
                );
            }
            crate::ast::SignatureParam::Value(param) => {
                let expected = values
                    .next()
                    .expect("a lambda shape has one type per value parameter");
                {
                    let (store, owner, delta, publication) = frontier.parts_mut();
                    let scoped = expected
                        .clone()
                        .into_scoped(owner, store, param.meta.span)?;
                    header.constrain_reserved_value(
                        value_index,
                        scoped,
                        store,
                        delta,
                        publication,
                        tcx,
                    )?;
                }

                if matches!(selection, OrdinaryLambdaSelection::Check { .. }) && param.ty.is_some()
                {
                    let (store, owner, delta, _publication) = frontier.parts_mut();
                    let scoped = expected
                        .clone()
                        .into_scoped(owner, store, param.meta.span)?;
                    let effective = store.zonk_for_progress(delta, scoped, tcx)?;
                    *expected = if super::type_contains_goal(effective.ty().as_type()) {
                        OwnerBoundType::Retained {
                            owner,
                            ty: effective,
                        }
                    } else {
                        OwnerBoundType::Plain(effective.into_interned_type())
                    };
                }
                tcx.push_value_interned(param.name.clone(), expected.ty().clone());
                tcx.attach_decl_span_to_local(&param.name, param.meta.span);
                {
                    let (store, owner, publication) = frontier.publication_mut();
                    publication.record_local_decl(
                        param.name.clone(),
                        param.meta.span,
                        super::ResolvedBinderKind::Local,
                    );
                    if header.value_slot_needs_type_publication(value_index) {
                        let resolved =
                            expected
                                .clone()
                                .into_scoped(owner, store, param.meta.span)?;
                        publication.record_fn_param_type(source.site(), value_index, resolved);
                    }
                }
                value_index += 1;
            }
        }
    }
    assert!(retained.next().is_none());
    assert!(values.next().is_none());

    let return_expected = match &selection {
        OrdinaryLambdaSelection::Check { body_type } => Some(body_type.clone()),
        OrdinaryLambdaSelection::Synthesizing {
            annotated_return: Some(annotation),
        }
        | OrdinaryLambdaSelection::Synth {
            annotated_return: Some(annotation),
        } => Some(OwnerBoundType::Plain(annotation.clone())),
        OrdinaryLambdaSelection::Synthesizing {
            annotated_return: None,
        }
        | OrdinaryLambdaSelection::Synth {
            annotated_return: None,
        } => None,
    };
    if let (Some(annotation), Some(expected)) = (ret_ty, return_expected) {
        let (store, owner, delta, publication) = frontier.parts_mut();
        let expected = expected.into_scoped(owner, store, annotation.span())?;
        header.constrain_reserved_return(expected, store, delta, publication, tcx)?;
    }
    Ok((selection, prepared_value_types))
}

#[cfg(feature = "surface")]
#[allow(clippy::too_many_arguments)]
fn prepare_ordinary_lambda_check_equations<'m>(
    source: &'m crate::ast::Expr<crate::ast::Lowered>,
    sig: &'m crate::ast::Signature<crate::ast::Lowered>,
    header: &mut super::annotation_plan::LambdaHeaderPlan<'m>,
    body_type: InternedType<crate::ast::Lowered>,
    expected_value_param_types: Vec<InternedType<crate::ast::Lowered>>,
    value_param_types: &[OwnerBoundType],
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<OwnerBoundType, Error> {
    assert_eq!(
        value_param_types.len(),
        sig.value_param_count(),
        "a selected lambda retained the wrong parameter-type count"
    );
    assert_eq!(
        expected_value_param_types.len(),
        value_param_types.len(),
        "a late lambda checking handoff derived the wrong parameter-type count"
    );

    let body_type = prepare_owner_bound_type(frontier, body_type, source.span(), tcx)?;
    let mut prepared_expected_value_param_types =
        Vec::with_capacity(expected_value_param_types.len());
    for expected in expected_value_param_types {
        prepared_expected_value_param_types.push(prepare_owner_bound_type(
            frontier,
            expected,
            source.span(),
            tcx,
        )?);
    }

    for ((param, actual), expected) in sig
        .value_params()
        .zip(value_param_types)
        .zip(prepared_expected_value_param_types)
    {
        let (store, owner, delta, _publication) = frontier.parts_mut();
        let actual = actual.clone().into_scoped(owner, store, param.meta.span)?;
        let expected = expected.into_scoped(owner, store, param.meta.span)?;
        store.constrain(delta, actual, expected, param.meta.span, tcx)?;
    }

    {
        let (store, owner, delta, publication) = frontier.parts_mut();
        let expected = body_type.clone().into_scoped(owner, store, source.span())?;
        header.constrain_reserved_return(expected, store, delta, publication, tcx)?;
    }
    Ok(body_type)
}

#[cfg(feature = "surface")]
#[allow(clippy::too_many_arguments)] // atomic handoff needs both owner scopes and lambda evidence
fn handoff_ordinary_lambda_check<'m>(
    source: &'m crate::ast::Expr<crate::ast::Lowered>,
    sig: &'m crate::ast::Signature<crate::ast::Lowered>,
    header: &mut super::annotation_plan::LambdaHeaderPlan<'m>,
    body_type: InternedType<crate::ast::Lowered>,
    expected_value_param_types: Vec<InternedType<crate::ast::Lowered>>,
    value_param_types: &[OwnerBoundType],
    body: &mut OrdinaryChildContinuation<'m>,
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<OrdinaryLambdaSelection, Error> {
    assert!(
        body.cursor.awaits_expected(),
        "a late lambda checking handoff lost its expected-dependent body"
    );
    let body_type = prepare_ordinary_lambda_check_equations(
        source,
        sig,
        header,
        body_type,
        expected_value_param_types,
        value_param_types,
        frontier,
        tcx,
    )?;

    // The retained body has only consumed its standalone passes. Attach the
    // newly concrete slot to that same cursor and let it resume from its
    // existing boundary; no body premise is abandoned or replayed.
    body.cursor.supply_expected(body_type.clone());
    body.next_mode = frontier::FrontierMode::ExpectedOnly;
    Ok(OrdinaryLambdaSelection::Check { body_type })
}

#[cfg(feature = "surface")]
fn push_ordinary_lambda_scope<'m>(
    sig: &'m crate::ast::Signature<crate::ast::Lowered>,
    value_param_types: &[OwnerBoundType],
    retained_binders: &[super::RetainedTypeBinder<'m>],
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) {
    let mut retained = retained_binders.iter();
    let mut values = value_param_types.iter();
    for param in &sig.params {
        match param {
            crate::ast::SignatureParam::Type(param) => {
                tcx.push_retained_type_binder(
                    retained
                        .next()
                        .expect("a lambda seed retains every source type binder"),
                );
                tcx.attach_decl_span_to_local(&param.name, param.span);
            }
            crate::ast::SignatureParam::Value(param) => {
                let ty = values
                    .next()
                    .expect("a lambda shape has one type per value parameter");
                let ty = match ty {
                    OwnerBoundType::Diagnostic { solver, .. } => solver.as_ref(),
                    ty => ty,
                };
                match ty {
                    OwnerBoundType::Plain(ty) => {
                        tcx.push_value_interned(param.name.clone(), ty.clone())
                    }
                    OwnerBoundType::Retained { owner, ty } => {
                        tcx.push_retained_value(param.name.clone(), *owner, ty.clone())
                    }
                    OwnerBoundType::Diagnostic { .. } => {
                        unreachable!("an owner-bound type retained nested diagnostic wrappers")
                    }
                }
                tcx.attach_decl_span_to_local(&param.name, param.meta.span);
            }
        }
    }
    assert!(retained.next().is_none());
    assert!(values.next().is_none());
}

#[cfg(feature = "surface")]
fn prepare_owner_bound_type<'m>(
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    ty: InternedType<crate::ast::Lowered>,
    span: Span,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<OwnerBoundType, Error> {
    prepare_owner_bound_type_at_prefix(frontier, ty, span, None, tcx)
}

#[cfg(feature = "surface")]
fn prepare_owner_bound_type_at_prefix<'m>(
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    ty: InternedType<crate::ast::Lowered>,
    span: Span,
    lexical_scope: Option<&RigidScope>,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<OwnerBoundType, Error> {
    // The retained-owner reconstruction exists solely to carry an ancestor
    // inference goal through a lexical `Forall`.  Goal-free types and goals
    // outside every `Forall` stay on the ordinary hot path.
    if !super::type_contains_goal(ty.as_type()) {
        return Ok(OwnerBoundType::Plain(ty));
    }
    let ambient = tcx.in_scope_type_param_binders();
    let aliases = tcx.binder_alias_ctx(&ambient);
    let mut protected = ambient.clone();
    if !contains_goal_beneath_forall_with_aliases(
        ty.as_type(),
        &aliases,
        &mut protected,
        ty.identity_is_canonical(),
        false,
    ) {
        return Ok(OwnerBoundType::Plain(ty));
    }
    let (candidate, identity_canonical) = super::aliases::canonicalize_deep_for_comparison(
        ty.as_type(),
        &aliases,
        ty.identity_is_canonical(),
    );
    debug_assert!(super::contains_goal_beneath_forall(&candidate, false));
    assert!(
        identity_canonical,
        "deep owner-bound canonicalization left a non-canonical type identity"
    );
    let candidate = freshen_reconstructed_foralls(candidate, &ambient);
    let owner = frontier.owner();
    let retained =
        frontier.retain_structural_foralls(InternedType::fresh_canonical(candidate), span, tcx)?;
    let retained = match lexical_scope {
        Some(scope) => frontier
            .store()
            .rebase_reconstructed_type_to_lexical_prefix(retained, scope, span)?,
        None => retained,
    };
    Ok(OwnerBoundType::Retained {
        owner,
        ty: retained,
    })
}

#[cfg(feature = "surface")]
fn prepare_expected_value_packet<'m>(
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    expected: ExpectedValuePacket,
    span: Span,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<OwnerBoundType, Error> {
    let solver = prepare_owner_bound_type(frontier, expected.solver, span, tcx)?;
    Ok(solver.with_diagnostic(expected.written))
}

#[cfg(feature = "surface")]
fn freshen_reconstructed_foralls(
    ty: crate::ast::Type<crate::ast::Lowered>,
    ambient: &std::collections::HashSet<String>,
) -> crate::ast::Type<crate::ast::Lowered> {
    fn go(
        ty: crate::ast::Type<crate::ast::Lowered>,
        protected: &mut std::collections::HashSet<String>,
    ) -> crate::ast::Type<crate::ast::Lowered> {
        match ty {
            crate::ast::Type::Forall {
                mut param,
                body,
                meta,
            } => {
                let mut body = *body;
                if protected.contains(&param.name) {
                    let mut reserved = protected.clone();
                    collect_free_type_vars(&body, &mut reserved);
                    reserved.insert(param.name.clone());
                    let fresh = fresh_type_var(&param.name, &reserved);
                    body = subst_type(
                        &body,
                        &HashMap::from([(
                            param.name.clone(),
                            crate::ast::Type::synth_path(
                                vec![fresh.clone()],
                                Vec::new(),
                                param.span,
                            ),
                        )]),
                    );
                    param.name = fresh;
                }
                let inserted = protected.insert(param.name.clone());
                let body = go(body, protected);
                if inserted {
                    protected.remove(&param.name);
                }
                crate::ast::Type::Forall {
                    param,
                    body: Box::new(body),
                    meta,
                }
            }
            crate::ast::Type::Function {
                param,
                ret,
                meta,
                abi_arity,
                caps,
            } => crate::ast::Type::Function {
                param: Box::new(go(*param, protected)),
                ret: Box::new(go(*ret, protected)),
                meta,
                abi_arity,
                caps,
            },
            crate::ast::Type::Product { left, right, meta } => crate::ast::Type::Product {
                left: Box::new(go(*left, protected)),
                right: Box::new(go(*right, protected)),
                meta,
            },
            crate::ast::Type::Sum { left, right, meta } => crate::ast::Type::Sum {
                left: Box::new(go(*left, protected)),
                right: Box::new(go(*right, protected)),
                meta,
            },
            crate::ast::Type::Path {
                segments,
                args,
                meta,
            } => crate::ast::Type::Path {
                segments,
                args: args.into_iter().map(|arg| go(arg, protected)).collect(),
                meta,
            },
            crate::ast::Type::Goal {
                goal,
                args,
                meta,
                ext,
            } => crate::ast::Type::Goal {
                goal,
                args: args.into_iter().map(|arg| go(arg, protected)).collect(),
                meta,
                ext,
            },
            crate::ast::Type::Unit { .. }
            | crate::ast::Type::Bottom { .. }
            | crate::ast::Type::Infer { .. } => ty,
            crate::ast::Type::LabelSugar { ext, .. } => match ext {},
        }
    }

    go(ty, &mut ambient.clone())
}

#[cfg(feature = "surface")]
trait OrdinaryFrontierReentry<'m> {
    /// Owner that allocated this call layer's inferred binders.
    fn goal_owner(&self) -> crate::ast::TypeGoalOwner;

    /// Owner of this layer's expression, publication, and gather children.
    fn owner(&self) -> crate::ast::TypeGoalOwner;

    fn store(&self) -> &GoalStore;

    fn publication_mut(
        &mut self,
    ) -> (
        &GoalStore,
        crate::ast::TypeGoalOwner,
        &mut PublicationBuilder,
    );

    fn parts_mut(
        &mut self,
    ) -> (
        &GoalStore,
        crate::ast::TypeGoalOwner,
        &mut GoalDelta,
        &mut PublicationBuilder,
    );

    fn activate_reserved_goal(
        &mut self,
        reserved: ReservedGoalRef,
        diagnostic_span: Span,
        occurrence_span: Span,
    ) -> Result<(crate::ast::TypeGoalRef, ScopedType), Error>;

    fn reserve_goal_in_live_delta(
        &mut self,
        kind: crate::ast::Kind,
        solution_policy: GoalSolutionPolicy,
        origin: GoalOrigin,
    ) -> Result<crate::ast::TypeGoalRef, Error>;

    fn stage_rec_order(
        &mut self,
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        state: PendingRecOrderState<crate::ast::Lowered>,
        tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<(), Error>;

    fn rec_order_runtime_for_use(
        &self,
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
    ) -> Option<ScopedType>;

    fn forward_rec_order_entries(
        &mut self,
        child: &mut frontier::OpenRetainedPremise<'m>,
        tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<bool, Error>;

    fn take_rec_order_observation(
        &mut self,
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<Option<(Option<ScopedType>, bool)>, Error>;

    fn begin_gather(
        &mut self,
        span: Span,
        tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<frontier::GatherFrame, Error>;

    fn close_gather(
        &mut self,
        gather: frontier::GatherFrame,
        tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<(), Error>;

    fn retain_structural_foralls(
        &mut self,
        ty: InternedType<crate::ast::Lowered>,
        span: Span,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<ScopedType, Error>;

    fn reserve_ordinary_child_with<T>(
        &mut self,
        span: Span,
        tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
        plan: impl FnOnce(&mut GoalStore, crate::ast::TypeGoalOwner) -> Result<T, Error>,
    ) -> Result<(frontier::FrontierChildReservation, T), Error>;

    fn reserve_ordinary_lexical_child_with<T>(
        &mut self,
        binders: &[super::RetainedTypeBinder<'m>],
        span: Span,
        plan: impl FnOnce(&mut GoalStore, crate::ast::TypeGoalOwner) -> Result<T, Error>,
    ) -> Result<(frontier::FrontierChildReservation, T), Error>;

    fn select_ordinary_child_with<T, U>(
        &mut self,
        span: Span,
        tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
        select: impl FnOnce(
            &mut GoalStore,
            crate::ast::TypeGoalOwner,
        ) -> Result<frontier::PlanningSelection<T, U>, Error>,
    ) -> Result<frontier::PlanningSelection<(frontier::FrontierChildReservation, T), U>, Error>;

    fn reserve_connected_call_child_with<T>(
        &mut self,
        span: Span,
        tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
        plan: impl FnOnce(&mut GoalStore, crate::ast::TypeGoalOwner) -> Result<T, Error>,
    ) -> Result<(frontier::FrontierChildReservation, T), Error>;

    fn reserve_lambda_lexical_child_with<T>(
        &mut self,
        binders: &[super::RetainedTypeBinder<'m>],
        span: Span,
        plan: impl FnOnce(&mut GoalStore, crate::ast::TypeGoalOwner) -> Result<T, Error>,
    ) -> Result<(frontier::FrontierChildReservation, T), Error>;

    fn open_ordinary_child(
        &self,
        reservation: frontier::FrontierChildReservation,
    ) -> Result<frontier::OpenRetainedPremise<'m>, Error>;

    fn ordinary_child_frontier<'a>(
        &'a mut self,
        child: &'a mut frontier::OpenRetainedPremise<'m>,
    ) -> frontier::ConnectedCallFrontier<'a, 'm>;

    fn connected_call_child_frontier<'a>(
        &'a mut self,
        child: &'a mut frontier::OpenRetainedPremise<'m>,
    ) -> frontier::ConnectedCallFrontier<'a, 'm>;

    fn close_ordinary_child(
        &mut self,
        child: frontier::OpenRetainedPremise<'m>,
        outputs: Vec<(ScopedType, GoalEscape)>,
        tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<Vec<ClosedGoalOutput>, Error>;

    fn close_prepared_ordinary_child(
        &mut self,
        child: frontier::OpenRetainedPremise<'m>,
        outputs: Vec<(PreparedCloseType, GoalEscape)>,
        tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<Vec<ClosedGoalOutput>, Error>;
}

