#[cfg(feature = "surface")]
fn prepare_implicit_unit_goal_argument<'m>(
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    call: &OpenGoalCall<'m>,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<Option<OwnerBoundType>, Error> {
    if !call.shape.has_implicit_unit_value() {
        return Ok(None);
    }
    prepare_expected_value_packet(
        frontier,
        call.remaining_param.clone(),
        call.call_site.span,
        tcx,
    )
    .map(Some)
}

#[cfg(feature = "surface")]
fn constrain_implicit_unit_goal_argument<'m>(
    frontier: &impl OrdinaryFrontierReentry<'m>,
    gather: &mut frontier::GatherFrame,
    expected: OwnerBoundType,
    call_site: crate::ast::ExpressionSite,
    tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<(), Error> {
    let store = frontier.store();
    let actual = store.scoped_type(
        gather.owner(),
        InternedType::fresh_canonical(crate::ast::Type::Unit {
            meta: crate::ast::Meta::new(call_site.span),
        }),
        call_site.span,
    )?;
    let expected =
        expected.into_expected_equation_operand(gather.owner(), store, call_site.span)?;
    store.constrain_equation(gather.delta_mut(), actual, expected, call_site.span, tcx)
}

#[cfg(feature = "surface")]
fn advance_path_unit_goal_call<'m>(
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    mut call: OpenGoalCall<'m>,
    values: Vec<PreparedOrdinaryValue<'m>>,
    result_inferred_type_arg_suffix: usize,
    expected_ret: Option<&InternedType<crate::ast::Lowered>>,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<CompletedPathUnitGoalCall<'m>, Error> {
    assert_eq!(
        call.owner,
        frontier.goal_owner(),
        "goal-call plan was advanced through a different inference owner"
    );
    for (source, state) in pending_type_arg_updates(&call.shape.type_args, tcx) {
        frontier.stage_rec_order(source, state, tcx)?;
    }

    let goal_owner = frontier.goal_owner();
    let owner = frontier.owner();
    let mut prepared_values = Vec::with_capacity(values.len());
    for (index, value) in values.into_iter().enumerate() {
        let expected = call.next_expected(index, tcx);
        let expected = prepare_expected_value_packet(frontier, expected, value.source.span(), tcx)?;
        prepared_values.push((value, expected));
    }
    let implicit_unit_expected = prepare_implicit_unit_goal_argument(frontier, &call, tcx)?;
    let written_type_only_residual =
        call.shape.has_written_type_only() && !call.shape.result_is_pre_residual;
    let result_type = if written_type_only_residual {
        call.residual_function_type(goal_owner)
    } else {
        call.result_type(goal_owner)
    };
    let result_type = prepare_owner_bound_type(frontier, result_type, call.call_site.span, tcx)?;

    if call.user_elaborator_transcript.is_some() {
        let mut type_slots = Vec::with_capacity(call.shape.binders.len());
        for binder in &call.shape.binders {
            let Some(ty) = call.replacements.get(goal_owner, &binder.name) else {
                type_slots.push(None);
                continue;
            };
            let prepared = prepare_owner_bound_type(frontier, ty, binder.span, tcx)?;
            type_slots.push(Some(prepared.into_scoped(
                owner,
                frontier.store(),
                binder.span,
            )?));
        }
        let value_layer_consumed = call.shape.has_implicit_unit_value();
        if let Some(transcript) = call.user_elaborator_transcript.as_mut() {
            transcript.layers.push(UserElaboratorCallTranscriptLayer {
                type_slots,
                sources: Vec::new(),
                value_layer_consumed,
            });
        }
    }

    let mut gather = frontier.begin_gather(call.call_site.span, tcx)?;
    if let Some(expected) = implicit_unit_expected {
        constrain_implicit_unit_goal_argument(
            frontier,
            &mut gather,
            expected,
            call.call_site,
            tcx,
        )?;
    }
    for (value, expected) in prepared_values {
        let source = value.source;
        let cursor = OrdinaryValueCursor::new(source, expected);
        if tcx.has_pending_rec_order() {
            frontier.stage_rec_order(
                source,
                PendingRecOrderState::Runtime {
                    exact_ty: cursor
                        .expected
                        .as_ref()
                        .expect("a selected Path/Unit premise has an expected type")
                        .ty()
                        .clone(),
                    source_checked: true,
                },
                tcx,
            )?;
        }
        let store = frontier.store();
        let publication_owner = gather.owner();
        let (delta, publication) = gather.parts_mut();
        let mut leaf_context = SimpleGoalLeafContext {
            equation_owner: publication_owner,
            publication_owner,
            store,
            delta,
            publication,
        };
        let advanced = cursor.advance_selected_path_unit(
            frontier::FrontierMode::Final,
            value,
            &mut leaf_context,
            tcx,
        )?;
        let OrdinaryValueAdvance::Complete(_completed) = advanced else {
            unreachable!("a selected Path/Unit premise did not complete in final mode")
        };
    }

    if let Some(expected) = expected_ret {
        let store = frontier.store();
        let result = result_type
            .clone()
            .into_scoped(gather.owner(), store, call.call_site.span)?;
        let expected = store.scoped_type(gather.owner(), expected.clone(), call.call_site.span)?;
        store.constrain(
            gather.delta_mut(),
            result,
            expected,
            call.call_site.span,
            tcx,
        )?;
    }
    let result = result_type.into_scoped(owner, frontier.store(), call.call_site.span)?;
    {
        let store = frontier.store();
        let publication_owner = gather.owner();
        let (_, publication) = gather.parts_mut();
        if call.shape.has_implicit_unit_value() {
            publication.record_call_implicit_unit(
                call.call_site,
                call.slot_offset + call.shape.binders.len(),
            );
        }
        call.stage_type_argument_metadata(goal_owner, publication_owner, store, publication, tcx)?;
    }
    frontier.close_gather(gather, tcx)?;
    Ok(CompletedPathUnitGoalCall {
        call,
        result,
        result_inferred_type_arg_suffix,
    })
}

#[cfg(feature = "surface")]
fn begin_general_goal_call<'m>(
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    mut call: OpenGoalCall<'m>,
    values: Vec<SelectedOrdinaryCallValue<'m>>,
    result_inferred_type_arg_suffix: usize,
    expected_ret: Option<OwnerBoundType>,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<AdvancingOrdinaryCall<'m>, Error> {
    assert_eq!(
        call.owner,
        frontier.goal_owner(),
        "ordinary goal-call plan was advanced through another inference owner"
    );
    for (source, state) in pending_type_arg_updates(&call.shape.type_args, tcx) {
        frontier.stage_rec_order(source, state, tcx)?;
    }

    let goal_owner = frontier.goal_owner();
    let owner = frontier.owner();
    let mut prepared_values = Vec::with_capacity(values.len());
    for SelectedOrdinaryCallValue {
        value,
        expected,
        immediate_evidence,
        expanded_start,
        expanded_width,
    } in values
    {
        let source = match &value {
            OrdinaryCallValue::Completed { source, .. } => *source,
            OrdinaryCallValue::Retained(retained) => retained.cursor.source,
        };
        let expected = match expected {
            OwnerBoundType::Plain(expected) => {
                prepare_owner_bound_type(frontier, expected, source.span(), tcx)?
            }
            retained @ OwnerBoundType::Retained { .. } => retained,
            OwnerBoundType::Diagnostic { solver, written } => {
                let solver = match *solver {
                    OwnerBoundType::Plain(expected) => {
                        prepare_owner_bound_type(frontier, expected, source.span(), tcx)?
                    }
                    retained @ OwnerBoundType::Retained { .. } => retained,
                    OwnerBoundType::Diagnostic { .. } => {
                        unreachable!("an owner-bound type retained nested diagnostic wrappers")
                    }
                };
                solver.with_diagnostic(Some(written))
            }
        };
        if tcx.has_pending_rec_order() {
            frontier.stage_rec_order(
                source,
                PendingRecOrderState::Runtime {
                    exact_ty: expected.ty().clone(),
                    source_checked: true,
                },
                tcx,
            )?;
        }
        prepared_values.push((
            value,
            expected,
            immediate_evidence,
            expanded_start,
            expanded_width,
        ));
    }

    if let Some(next_source_index) = call
        .user_elaborator_transcript
        .as_ref()
        .map(|transcript| transcript.next_source_index)
    {
        let mut type_slots = Vec::with_capacity(call.shape.binders.len());
        for binder in &call.shape.binders {
            let Some(ty) = call.replacements.get(goal_owner, &binder.name) else {
                type_slots.push(None);
                continue;
            };
            let prepared = prepare_owner_bound_type(frontier, ty, binder.span, tcx)?;
            type_slots.push(Some(prepared.into_scoped(
                owner,
                frontier.store(),
                binder.span,
            )?));
        }
        let mut sources = Vec::with_capacity(prepared_values.len());
        for (
            source_offset,
            (value, expected, _immediate_evidence, expanded_start, expanded_width),
        ) in prepared_values.iter().enumerate()
        {
            let source = match value {
                OrdinaryCallValue::Completed { source, .. } => *source,
                OrdinaryCallValue::Retained(retained) => retained.cursor.source,
            };
            sources.push(UserElaboratorCallTranscriptSource {
                source_index: next_source_index + source_offset,
                source: source.clone(),
                expanded_start: *expanded_start,
                expanded_width: *expanded_width,
                expected: expected
                    .clone()
                    .into_scoped(owner, frontier.store(), source.span())?,
            });
        }
        let value_layer_consumed = call.shape.has_value_layer
            && (!prepared_values.is_empty()
                || accepts_zero_value_args(&call.remaining_param.solver, &tcx.env.alias_ctx()));
        if let Some(transcript) = call.user_elaborator_transcript.as_mut() {
            transcript.next_source_index += sources.len();
            transcript.layers.push(UserElaboratorCallTranscriptLayer {
                type_slots,
                value_layer_consumed,
                sources,
            });
        }
    }
    let result_type = prepare_owner_bound_type(
        frontier,
        call.result_type(goal_owner),
        call.call_site.span,
        tcx,
    )?;

    let mut gather = None;
    let mut retained = Vec::new();
    for (value, expected, immediate_evidence, _expanded_start, _expanded_width) in prepared_values {
        let source = match &value {
            OrdinaryCallValue::Completed { source, .. } => *source,
            OrdinaryCallValue::Retained(retained) => retained.cursor.source,
        };
        match value {
            OrdinaryCallValue::Completed { output, .. } => {
                if matches!(output, CompletedInFrame::FunctionScheme(_, _)) {
                    let ambient_binders = tcx.in_scope_type_param_binders();
                    let (expected_head, _) = super::aliases::unfold_and_qualify_state(
                        expected.ty().as_type(),
                        &tcx.binder_alias_ctx(&ambient_binders),
                        expected.ty().identity_is_canonical(),
                    );
                    if !matches!(
                        expected_head,
                        crate::ast::Type::Forall { .. } | crate::ast::Type::Goal { .. }
                    ) {
                        return Err(super::types::scheme_in_mono_position(source.span()));
                    }
                }
                if let Some(immediate_evidence) = immediate_evidence {
                    if let Some(completed) = gather.take() {
                        frontier.close_gather(completed, tcx)?;
                    }
                    let actual = {
                        let (store, _owner, delta, _publication) = frontier.parts_mut();
                        store.require_goal_free_after_delta(delta, output.scoped().clone(), tcx)?
                    };
                    let mut evidence_gather = frontier.begin_gather(call.call_site.span, tcx)?;
                    let store = frontier.store();
                    let actual = OwnerBoundType::Retained { owner, ty: actual }.into_scoped(
                        evidence_gather.owner(),
                        store,
                        source.span(),
                    )?;
                    let expected = expected.into_expected_equation_operand(
                        evidence_gather.owner(),
                        store,
                        source.span(),
                    )?;
                    let outcome = store.try_constrain_gather_equation(
                        evidence_gather.delta_mut(),
                        actual,
                        expected,
                        source.span(),
                        tcx,
                    )?;
                    assert_eq!(
                        outcome,
                        CloseReadyEquationConstraint::Applied,
                        "a goal-free immediate argument left a descendant-dependent evidence equation"
                    );
                    frontier.close_gather(evidence_gather, tcx)?;
                    call.immediate_lambda
                        .as_mut()
                        .expect("immediate evidence outlived its direct lambda")
                        .mark_observed(&immediate_evidence);
                    continue;
                }
                if gather.is_none() {
                    gather = Some(frontier.begin_gather(call.call_site.span, tcx)?);
                }
                let current = gather
                    .as_mut()
                    .expect("a completed ordinary value has an open gather segment");
                let store = frontier.store();
                let actual = OwnerBoundType::Retained {
                    owner,
                    ty: output.scoped().clone(),
                }
                .into_scoped(current.owner(), store, source.span())?;
                let expected = expected.into_expected_equation_operand(
                    current.owner(),
                    store,
                    source.span(),
                )?;
                let outcome = store.try_constrain_gather_equation(
                    current.delta_mut(),
                    actual,
                    expected,
                    source.span(),
                    tcx,
                )?;
                assert_eq!(
                    outcome,
                    CloseReadyEquationConstraint::Applied,
                    "a closed ordinary premise left a descendant-dependent gather equation"
                );
            }
            OrdinaryCallValue::Retained(retained_child) => {
                if let Some(completed) = gather.take() {
                    frontier.close_gather(completed, tcx)?;
                }
                retained.push(PendingOrdinaryCallChild {
                    child: retained_child,
                    role: immediate_evidence.map_or(PendingOrdinaryChildRole::Value, |evidence| {
                        PendingOrdinaryChildRole::ImmediateEvidence(Box::new(
                            PendingImmediateEvidence {
                                expected,
                                evidence: *evidence,
                            },
                        ))
                    }),
                });
            }
        }
    }

    if gather.is_none() {
        gather = Some(frontier.begin_gather(call.call_site.span, tcx)?);
    }
    let mut gather = gather.expect("ordinary call always has a final gather segment");
    // Every caller immediately advances this continuation through one
    // frontier mode. Let that scheduler own the first result equation so an
    // initially deferred equation is not retried before any child progresses.
    let pending_expected_result = expected_ret.map(PendingExpectedResult::new);
    let result = result_type.into_scoped(owner, frontier.store(), call.call_site.span)?;
    {
        let store = frontier.store();
        let publication_owner = gather.owner();
        let (_, publication) = gather.parts_mut();
        call.stage_type_argument_metadata(goal_owner, publication_owner, store, publication, tcx)?;
    }
    frontier.close_gather(gather, tcx)?;

    Ok(AdvancingOrdinaryCall {
        call,
        result,
        result_inferred_type_arg_suffix,
        destination: owner,
        pending: retained,
        pending_expected_result,
    })
}

#[cfg(feature = "surface")]
// Pending call children enter the shared heap driver. Keep the resumable
// outcomes pointer-sized so each continuation remains bounded.
enum GeneralGoalCallAdvance<'m> {
    Pending(Box<AdvancingOrdinaryCall<'m>>),
    Complete(Box<CompletedPathUnitGoalCall<'m>>),
    ContextualReturnedForall(Box<AdvancingOrdinaryCall<'m>>),
}

#[cfg(feature = "surface")]
type GeneralGoalCallDriverContinue<'m> = Box<
    dyn for<'a, 'e> FnOnce(
            GeneralGoalCallAdvance<'m>,
            &mut frontier::ConnectedCallFrontier<'a, 'm>,
            &mut TypeCtx<'m, 'e, crate::ast::Lowered>,
        ) -> Result<OrdinaryDriverStep<'m>, Error>
        + 'm,
>;

#[cfg(feature = "surface")]
type ImmediateLambdaDriverContinue<'m> = Box<
    dyn for<'a, 'e> FnOnce(
            Box<AdvancingOrdinaryCall<'m>>,
            bool,
            &mut frontier::ConnectedCallFrontier<'a, 'm>,
            &mut TypeCtx<'m, 'e, crate::ast::Lowered>,
        ) -> Result<OrdinaryDriverStep<'m>, Error>
        + 'm,
>;

#[cfg(feature = "surface")]
struct GeneralGoalCallDriverState<'m> {
    advancing: Box<AdvancingOrdinaryCall<'m>>,
    mode: frontier::FrontierMode,
    declared_transition: Option<DeclaredValueTransition>,
    contextual_returned_forall_boundary: Option<ContextualReturnedForallBoundary>,
    had_pending_children: bool,
    immediate_body_was_incomplete: bool,
    pending: Vec<PendingOrdinaryCallChild<'m>>,
    remaining: std::collections::VecDeque<PendingOrdinaryCallChild<'m>>,
    deferred_non_evidence: Vec<PendingOrdinaryCallChild<'m>>,
    prioritize_contextual_returned_forall: bool,
}

#[cfg(feature = "surface")]
fn try_apply_expected_equation<'m>(
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    output: ScopedType,
    expected: &OwnerBoundType,
    span: Span,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<bool, Error> {
    let output_owner = frontier.owner();
    let mut gather = frontier.begin_gather(span, tcx)?;
    let store = frontier.store();
    let actual = OwnerBoundType::Retained {
        owner: output_owner,
        ty: output,
    }
    .into_scoped(gather.owner(), store, span)?;
    let expected = expected
        .clone()
        .into_expected_equation_operand(gather.owner(), store, span)?;
    let outcome =
        store.try_constrain_gather_equation(gather.delta_mut(), actual, expected, span, tcx)?;
    frontier.close_gather(gather, tcx)?;
    Ok(outcome == CloseReadyEquationConstraint::Applied)
}

#[cfg(feature = "surface")]
fn expected_equation_snapshot<'m>(
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    advancing: &AdvancingOrdinaryCall<'m>,
    tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<EquationSnapshot, Error> {
    let span = advancing.call.call_site;
    let pending = advancing
        .pending_expected_result
        .as_ref()
        .expect("an expected-result progress snapshot lost its equation");
    let (store, owner, delta, _publication) = frontier.parts_mut();
    let result = advancing.result.clone();
    let expected = pending
        .expected
        .clone()
        .into_scoped(owner, store, span.span)?;
    EquationSnapshot::zonked(store, delta, result, expected, tcx)
}

#[cfg(feature = "surface")]
fn try_apply_pending_expected_result<'m>(
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    advancing: &mut AdvancingOrdinaryCall<'m>,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<bool, Error> {
    if advancing.pending_expected_result.is_none() {
        return Ok(true);
    }
    let snapshot = expected_equation_snapshot(frontier, advancing, tcx)?;
    let Some(mut pending) = advancing.pending_expected_result.take() else {
        unreachable!("an expected-result attempt lost its pending equation")
    };
    #[cfg(test)]
    record_expected_result_equation();
    let mut gather = frontier.begin_gather(advancing.call.call_site.span, tcx)?;
    let store = frontier.store();
    let result = OwnerBoundType::Retained {
        owner: advancing.destination,
        ty: advancing.result.clone(),
    }
    .into_scoped(gather.owner(), store, advancing.call.call_site.span)?;
    let expected_equation = pending.expected.clone().into_expected_equation_operand(
        gather.owner(),
        store,
        advancing.call.call_site.span,
    )?;
    let outcome = store.try_constrain_gather_equation(
        gather.delta_mut(),
        result.clone(),
        expected_equation,
        advancing.call.call_site.span,
        tcx,
    )?;
    frontier.close_gather(gather, tcx)?;
    if outcome == CloseReadyEquationConstraint::Deferred {
        pending.progress = EquationProgress::AwaitingProgress(snapshot);
        advancing.pending_expected_result = Some(pending);
    } else if let Some(immediate) = advancing.call.immediate_lambda.as_ref() {
        assert!(
            matches!(immediate.body, ImmediateLambdaBodyState::Complete { .. })
                && immediate.outer_expected.is_none(),
            "an expected-result equation consumed an incomplete immediate lambda"
        );
    }
    Ok(outcome == CloseReadyEquationConstraint::Applied)
}

#[cfg(feature = "surface")]
fn instantiated_immediate_lambda_residuals<'m>(
    call: &OpenGoalCall<'m>,
    immediate: &ImmediateLambdaCall<'m>,
    actual: &ScopedType,
    current_output: &ScopedType,
    destination: crate::ast::TypeGoalOwner,
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<Vec<(ScopedType, OwnerBoundType)>, Error> {
    assert_eq!(
        call.owner,
        frontier.goal_owner(),
        "an immediate lambda result was installed through another inference owner"
    );
    assert_eq!(
        destination,
        frontier.owner(),
        "an immediate lambda result changed its application destination"
    );
    assert_eq!(
        immediate.completed_layers.len(),
        immediate.current_layer,
        "an immediate lambda lost one declared-layer instantiation"
    );
    let mut actual_body = actual.ty().clone_type();
    let mut identity_canonical = actual.ty().identity_is_canonical();
    let mut residuals = Vec::with_capacity(immediate.completed_layers.len() + 1);

    for (ordinal, (binders, replacements, output, result_canonical)) in immediate
        .completed_layers
        .iter()
        .map(|layer| {
            (
                layer.binders.as_slice(),
                &layer.replacements,
                &layer.output,
                layer.result_canonical,
            )
        })
        .chain(std::iter::once((
            call.shape.binders.as_slice(),
            &call.replacements,
            current_output,
            call.result_canonical,
        )))
        .enumerate()
    {
        if let Some(completed) = immediate.completed_layers.get(ordinal) {
            assert_eq!(
                completed.ordinal, ordinal,
                "an immediate lambda reordered its declared layers"
            );
        } else {
            assert_eq!(
                ordinal, immediate.current_layer,
                "an immediate lambda opened its current layer out of order"
            );
        }
        identity_canonical &= result_canonical;
        for source_binder in binders {
            let crate::ast::Type::Forall { param, body, .. } = actual_body else {
                unreachable!("an immediate lambda result lost a declared type-binder layer")
            };
            assert_eq!(
                param.effective_kind(),
                source_binder.effective_kind(),
                "an immediate lambda result changed a declared binder kind"
            );
            let replacement = replacements
                .get(call.owner, &source_binder.name)
                .expect("an opened immediate call has one replacement per current binder");
            identity_canonical &= replacement.identity_is_canonical();
            let mut substitution = HashMap::new();
            substitution.insert(param.name, replacement.clone_type());
            actual_body = subst_type(&body, &substitution);
        }
        let ambient_binders = tcx.in_scope_type_param_binders();
        let (head, head_canonical) = super::aliases::unfold_and_qualify_state(
            &actual_body,
            &tcx.binder_alias_ctx(&ambient_binders),
            identity_canonical,
        );
        let crate::ast::Type::Function { ret, .. } = head else {
            unreachable!("an immediate lambda result lost its current function layer")
        };
        actual_body = *ret;
        identity_canonical = head_canonical;
        let residual = prepare_owner_bound_type(
            frontier,
            InternedType::fresh_with_identity(actual_body.clone(), identity_canonical),
            call.call_site.span,
            tcx,
        )?;
        residuals.push((output.clone(), residual));
    }
    Ok(residuals)
}

#[cfg(feature = "surface")]
fn constrain_immediate_lambda_residuals<'m>(
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    residuals: Vec<(ScopedType, OwnerBoundType)>,
    first_unsolved: usize,
    span: Span,
    tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<(), Error> {
    let destination = frontier.owner();
    let mut gather = frontier.begin_gather(span, tcx)?;
    let gather_owner = gather.owner();
    let store = frontier.store();
    let mut equations = Vec::new();
    for (output, actual) in residuals.into_iter().skip(first_unsolved) {
        let output = OwnerBoundType::Retained {
            owner: destination,
            ty: output,
        }
        .into_scoped(gather_owner, store, span)?;
        let actual = actual.into_scoped(gather_owner, store, span)?;
        equations.push((actual, output, span));
    }
    assert!(
        !equations.is_empty(),
        "an immediate lambda residual gather had no active layer"
    );
    let outcome = store.try_constrain_gather_equations(gather.delta_mut(), equations, tcx)?;
    assert_eq!(
        outcome,
        CloseReadyEquationConstraint::Applied,
        "a closed immediate lambda retained a descendant-dependent residual equation"
    );
    frontier.close_gather(gather, tcx)?;
    Ok(())
}

#[cfg(feature = "surface")]
fn completed_immediate_expected_is_whole_forall<'m>(
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    expected: &OwnerBoundType,
    span: Span,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<bool, Error> {
    let expected = {
        let (store, owner, delta, _publication) = frontier.parts_mut();
        let expected = expected.clone().into_scoped(owner, store, span)?;
        store.zonk_for_progress(delta, expected, tcx)?
    };
    completed_scoped_expected_is_whole_forall(frontier, &expected, span, tcx)
}

#[cfg(feature = "surface")]
fn completed_scoped_expected_is_whole_forall<'m>(
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    expected: &ScopedType,
    _span: Span,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<bool, Error> {
    let progressed = {
        let (store, _owner, delta, _publication) = frontier.parts_mut();
        store.zonk_for_progress(delta, expected.clone(), tcx)?
    };
    let ambient_binders = tcx.in_scope_type_param_binders();
    let (head, _) = super::aliases::unfold_and_qualify_state(
        progressed.ty().as_type(),
        &tcx.binder_alias_ctx(&ambient_binders),
        progressed.ty().identity_is_canonical(),
    );
    Ok(matches!(head, crate::ast::Type::Forall { .. }))
}

#[cfg(feature = "surface")]
fn completed_immediate_contextual_returned_forall<'m>(
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    advancing: &AdvancingOrdinaryCall<'m>,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<Option<ScopedType>, Error> {
    let Some(expected) = advancing
        .call
        .immediate_lambda
        .as_ref()
        .filter(|immediate| matches!(immediate.body, ImmediateLambdaBodyState::Complete { .. }))
        .and_then(|immediate| immediate.outer_expected.clone())
    else {
        return Ok(None);
    };
    assert!(
        advancing.pending_expected_result.is_none(),
        "a contextual returned-Forall retained a whole-result equation"
    );
    let span = advancing.call.call_site;
    let (returned, expected) = {
        let (store, owner, delta, _publication) = frontier.parts_mut();
        let returned = store.zonk_for_progress(delta, advancing.result.clone(), tcx)?;
        let expected = expected.into_scoped(owner, store, span.span)?;
        let expected = store.zonk_for_progress(delta, expected, tcx)?;
        (returned, expected)
    };
    let ambient_binders = tcx.in_scope_type_param_binders();
    let aliases = tcx.binder_alias_ctx(&ambient_binders);
    let (returned_head, _) = super::aliases::unfold_and_qualify_state(
        returned.ty().as_type(),
        &aliases,
        returned.ty().identity_is_canonical(),
    );
    if !matches!(returned_head, crate::ast::Type::Forall { .. }) {
        return Ok(None);
    }
    let (expected_head, _) = super::aliases::unfold_and_qualify_state(
        expected.ty().as_type(),
        &aliases,
        expected.ty().identity_is_canonical(),
    );
    Ok((!matches!(expected_head, crate::ast::Type::Forall { .. })
        && !matches!(expected_head, crate::ast::Type::Goal { args, .. } if args.is_empty()))
    .then_some(returned))
}

#[cfg(feature = "surface")]
fn retain_or_install_completed_immediate_expected<'m>(
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    advancing: &mut AdvancingOrdinaryCall<'m>,
    mut immediate: Box<ImmediateLambdaCall<'m>>,
    returned_head: &crate::ast::Type<crate::ast::Lowered>,
    declared_transition: Option<DeclaredValueTransition>,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<(), Error> {
    if declared_transition.is_some() || advancing.pending_expected_result.is_some() {
        advancing.call.immediate_lambda = Some(immediate);
        return Ok(());
    }
    let install_equation = match immediate.outer_expected.as_ref() {
        None => false,
        Some(_) if !matches!(returned_head, crate::ast::Type::Forall { .. }) => true,
        Some(expected) => completed_immediate_expected_is_whole_forall(
            frontier,
            expected,
            advancing.call.call_site.span,
            tcx,
        )?,
    };
    if install_equation {
        assert!(
            advancing.pending_expected_result.is_none(),
            "a completed immediate lambda installed its expected result twice"
        );
        advancing.pending_expected_result = immediate
            .outer_expected
            .take()
            .map(PendingExpectedResult::new);
    }
    if immediate.outer_expected.is_some() || advancing.pending_expected_result.is_some() {
        advancing.call.immediate_lambda = Some(immediate);
    }
    Ok(())
}

#[cfg(feature = "surface")]
fn finish_immediate_lambda_body_advance<'m>(
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    advancing: &mut AdvancingOrdinaryCall<'m>,
    mut immediate: Box<ImmediateLambdaCall<'m>>,
    advanced: OrdinaryValueAdvance<'m>,
    declared_transition: Option<DeclaredValueTransition>,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<bool, Error> {
    match advanced {
        OrdinaryValueAdvance::Pending(cursor) | OrdinaryValueAdvance::Waiting(cursor) => {
            let OrdinaryValueCursor {
                source,
                expected,
                planned,
            } = *cursor;
            assert!(
                std::ptr::eq(source, immediate.source) && expected.is_none(),
                "an immediate lambda body changed its retained source or gained an outer expectation"
            );
            let PlannedOrdinaryValue::Lambda(planned) = planned else {
                unreachable!("an immediate lambda body resumed as another value family")
            };
            immediate.body = ImmediateLambdaBodyState::Advancing(planned);
            advancing.call.immediate_lambda = Some(immediate);
            Ok(false)
        }
        OrdinaryValueAdvance::Complete(actual) => {
            let result = &immediate.current_value_layer().result;
            if let ImmediateLambdaResult::Pending { goal: pending, .. } = result {
                assert!(
                    matches!(
                        advancing.result.ty().as_type(),
                        crate::ast::Type::Goal { goal, args, .. }
                            if goal == pending && args.is_empty()
                    ),
                    "an immediate lambda body completed against another pending result token"
                );
            }
            let actual = match actual {
                CompletedInFrame::Value(actual, _) => actual,
                CompletedInFrame::FunctionScheme(_, _)
                | CompletedInFrame::UserElaboratorCall { .. } => {
                    unreachable!("an anonymous lambda completed as another semantic family")
                }
            };
            let residuals = instantiated_immediate_lambda_residuals(
                &advancing.call,
                &immediate,
                &actual,
                &advancing.result,
                advancing.destination,
                frontier,
                tcx,
            )?;
            let actual_return = residuals
                .last()
                .expect("an immediate lambda has one active value layer")
                .1
                .clone();
            let ambient_binders = tcx.in_scope_type_param_binders();
            let (actual_return_head, _) = super::aliases::unfold_and_qualify_state(
                actual_return.ty().as_type(),
                &tcx.binder_alias_ctx(&ambient_binders),
                actual_return.ty().identity_is_canonical(),
            );
            constrain_immediate_lambda_residuals(
                frontier,
                residuals,
                0,
                advancing.call.call_site.span,
                tcx,
            )?;
            immediate.body = ImmediateLambdaBodyState::Complete { actual };
            assert!(
                advancing.pending_expected_result.is_none(),
                "an immediate lambda retained an outer expectation before its body"
            );
            retain_or_install_completed_immediate_expected(
                frontier,
                advancing,
                immediate,
                &actual_return_head,
                declared_transition,
                tcx,
            )?;
            #[cfg(all(test, feature = "surface"))]
            update_direct_lambda_work(|work| work.resume_entries += 1);
            Ok(true)
        }
    }
}

#[cfg(feature = "surface")]
fn advance_immediate_lambda_body_driver<'m>(
    frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
    mut advancing: Box<AdvancingOrdinaryCall<'m>>,
    mode: frontier::FrontierMode,
    declared_transition: Option<DeclaredValueTransition>,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    next: ImmediateLambdaDriverContinue<'m>,
) -> Result<OrdinaryDriverStep<'m>, Error> {
    let Some(mut immediate) = advancing.call.immediate_lambda.take() else {
        return next(advancing, true, frontier, tcx);
    };
    if matches!(immediate.body, ImmediateLambdaBodyState::Complete { .. }) {
        if declared_transition.is_some() || advancing.pending_expected_result.is_some() {
            advancing.call.immediate_lambda = Some(immediate);
        } else if immediate.outer_expected.is_some() {
            let returned = {
                let (store, _owner, delta, _publication) = frontier.parts_mut();
                store.zonk_for_progress(delta, advancing.result.clone(), tcx)?
            };
            let ambient_binders = tcx.in_scope_type_param_binders();
            let (head, _) = super::aliases::unfold_and_qualify_state(
                returned.ty().as_type(),
                &tcx.binder_alias_ctx(&ambient_binders),
                returned.ty().identity_is_canonical(),
            );
            retain_or_install_completed_immediate_expected(
                frontier,
                &mut advancing,
                immediate,
                &head,
                declared_transition,
                tcx,
            )?;
        }
        return next(advancing, true, frontier, tcx);
    }

    if matches!(
        immediate.body,
        ImmediateLambdaBodyState::AwaitingEvidence(_)
    ) {
        if let Some(transition) = declared_transition
            && !immediate.evidence_observed()
            && immediate.has_only_dormant_unresolved_parameters()
        {
            assert_eq!(
                transition.next_ordinal,
                immediate.current_layer + 1,
                "a declared-layer body bypass skipped a layer"
            );
            advancing.call.immediate_lambda = Some(immediate);
            return next(advancing, true, frontier, tcx);
        }
        let Some(value_param_types) = immediate.resolved_parameter_types(mode, frontier, tcx)?
        else {
            advancing.call.immediate_lambda = Some(immediate);
            return next(advancing, false, frontier, tcx);
        };
        let Some(annotated_return) = immediate.resolved_body_return(mode, frontier, tcx)? else {
            advancing.call.immediate_lambda = Some(immediate);
            return next(advancing, false, frontier, tcx);
        };
        let lambda_owners = match std::mem::replace(
            &mut immediate.body,
            ImmediateLambdaBodyState::NeedsReservation,
        ) {
            ImmediateLambdaBodyState::AwaitingEvidence(lambda_owners) => lambda_owners,
            _ => unreachable!("an immediate lambda evidence transition changed body state"),
        };
        let retained_binders = immediate
            .retained_binders
            .take()
            .expect("an immediate lambda entered its body twice");
        let mut header = immediate
            .header
            .take()
            .expect("an immediate lambda lost its source header plan");
        let ambient_binders = tcx.in_scope_type_param_presentation();
        let state = OrdinaryValueCursor::begin_reserved_lambda_body(
            immediate.source,
            lambda_owners,
            &mut header,
            OrdinaryLambdaSelection::Synthesizing { annotated_return },
            value_param_types,
            &retained_binders,
            ambient_binders,
            frontier,
            tcx,
        )?;
        #[cfg(all(test, feature = "surface"))]
        update_direct_lambda_work(|work| work.body_entries += 1);
        immediate.body = ImmediateLambdaBodyState::Advancing(PlannedOrdinaryLambda {
            header,
            retained_binders,
            state,
        });
    }

    let planned = match std::mem::replace(
        &mut immediate.body,
        ImmediateLambdaBodyState::NeedsReservation,
    ) {
        ImmediateLambdaBodyState::Advancing(planned) => planned,
        ImmediateLambdaBodyState::NeedsReservation => {
            unreachable!("an advancing immediate lambda lost its reserved child")
        }
        ImmediateLambdaBodyState::AwaitingEvidence(_) => {
            unreachable!("an immediate lambda advanced before its evidence became ready")
        }
        ImmediateLambdaBodyState::Complete { .. } => {
            unreachable!("a completed immediate lambda resumed its body")
        }
    };
    let immediate_source = immediate.source;
    let step = OrdinaryValueCursor::advance_lambda_step(
        immediate_source,
        None,
        planned,
        mode,
        frontier,
        tcx,
    )?;
    step.and_then(
        frontier,
        tcx,
        Box::new(move |advanced, frontier, tcx| {
            let completed = finish_immediate_lambda_body_advance(
                frontier,
                &mut advancing,
                immediate,
                advanced,
                declared_transition,
                tcx,
            )?;
            next(advancing, completed, frontier, tcx)
        }),
    )
}

#[cfg(feature = "surface")]
fn advance_general_goal_call_mode_driver<'m>(
    frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
    mut advancing: Box<AdvancingOrdinaryCall<'m>>,
    mode: frontier::FrontierMode,
    declared_transition: Option<DeclaredValueTransition>,
    contextual_returned_forall_boundary: Option<ContextualReturnedForallBoundary>,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    next: GeneralGoalCallDriverContinue<'m>,
) -> Result<OrdinaryDriverStep<'m>, Error> {
    assert_eq!(
        advancing.destination,
        frontier.owner(),
        "an ordinary call continuation re-entered through another inference owner"
    );
    let had_pending_children = !advancing.pending.is_empty();
    let immediate_body_was_incomplete =
        advancing
            .call
            .immediate_lambda
            .as_ref()
            .is_some_and(|immediate| {
                !matches!(immediate.body, ImmediateLambdaBodyState::Complete { .. })
            });
    let initial_attempted = matches!(
        advancing
            .pending_expected_result
            .as_ref()
            .map(|pending| &pending.progress),
        Some(EquationProgress::Initial)
    );
    if initial_attempted {
        let _ = try_apply_pending_expected_result(frontier, &mut advancing, tcx)?;
    } else if advancing.pending_expected_result.is_some() {
        let snapshot = expected_equation_snapshot(frontier, &advancing, tcx)?;
        let progressed = match advancing
            .pending_expected_result
            .as_ref()
            .map(|pending| &pending.progress)
        {
            Some(EquationProgress::AwaitingProgress(previous)) => previous.differs_from(&snapshot),
            Some(EquationProgress::Initial) | None => {
                unreachable!("a deferred expected-result equation lost its progress snapshot")
            }
        };
        if progressed {
            let _ = try_apply_pending_expected_result(frontier, &mut advancing, tcx)?;
        }
    }
    let prioritize_contextual_returned_forall = advancing.pending.iter().any(|pending| {
        matches!(
            pending.role,
            PendingOrdinaryChildRole::ContextualReturnedForall
        )
    });
    let remaining = std::mem::take(&mut advancing.pending).into();
    advance_general_goal_call_driver_pending(
        GeneralGoalCallDriverState {
            advancing,
            mode,
            declared_transition,
            contextual_returned_forall_boundary,
            had_pending_children,
            immediate_body_was_incomplete,
            pending: Vec::new(),
            remaining,
            deferred_non_evidence: Vec::new(),
            prioritize_contextual_returned_forall,
        },
        frontier,
        tcx,
        next,
    )
}

#[cfg(feature = "surface")]
fn advance_general_goal_call_driver_pending<'m>(
    mut state: GeneralGoalCallDriverState<'m>,
    frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    next: GeneralGoalCallDriverContinue<'m>,
) -> Result<OrdinaryDriverStep<'m>, Error> {
    while let Some(pending_child) = state.remaining.pop_front() {
        if (state.immediate_body_was_incomplete
            && matches!(pending_child.role, PendingOrdinaryChildRole::Value))
            || (state.prioritize_contextual_returned_forall
                && !matches!(
                    pending_child.role,
                    PendingOrdinaryChildRole::ContextualReturnedForall
                ))
        {
            state.deferred_non_evidence.push(pending_child);
            continue;
        }
        let PendingOrdinaryCallChild { child, role } = pending_child;
        let evidence_span = child.cursor.source.span();
        return Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
            child,
            inherited_mode: state.mode,
            demand: OrdinaryCompletionDemand::GoalFreeValue,
            handoff: OrdinaryDriverHandoff::Current(Box::new(move |result, frontier, tcx| {
                match result {
                    OrdinaryChildAdvance::Complete(output) => {
                        if let PendingOrdinaryChildRole::ImmediateEvidence(immediate) = role {
                            let PendingImmediateEvidence { expected, evidence } = *immediate;
                            if matches!(output, CompletedInFrame::FunctionScheme(_, _))
                                && !ImmediateLambdaCall::accepts_function_scheme_evidence(
                                    &expected, &evidence,
                                )
                            {
                                return Err(super::types::scheme_in_mono_position(evidence_span));
                            }
                            let destination = frontier.owner();
                            let actual = {
                                let (store, _owner, delta, _publication) = frontier.parts_mut();
                                store.require_goal_free_after_delta(
                                    delta,
                                    output.scoped().clone(),
                                    tcx,
                                )?
                            };
                            let mut gather =
                                frontier.begin_gather(state.advancing.call.call_site.span, tcx)?;
                            let store = frontier.store();
                            let actual = OwnerBoundType::Retained {
                                owner: destination,
                                ty: actual,
                            }
                            .into_scoped(
                                gather.owner(),
                                store,
                                evidence_span,
                            )?;
                            let expected = expected.into_expected_equation_operand(
                                gather.owner(),
                                store,
                                evidence_span,
                            )?;
                            let outcome = store.try_constrain_gather_equation(
                                gather.delta_mut(),
                                actual,
                                expected,
                                evidence_span,
                                tcx,
                            )?;
                            assert_eq!(
                                outcome,
                                CloseReadyEquationConstraint::Applied,
                                "a closed immediate argument left a descendant-dependent evidence equation"
                            );
                            frontier.close_gather(gather, tcx)?;
                            state
                                .advancing
                                .call
                                .immediate_lambda
                                .as_mut()
                                .expect("immediate evidence outlived its direct lambda")
                                .mark_observed(&evidence);
                        } else if matches!(role, PendingOrdinaryChildRole::ContextualReturnedForall)
                        {
                            let CompletedInFrame::Value(result, inferred_type_arg_suffix) = output
                            else {
                                unreachable!(
                                    "a contextual returned-Forall completed as another semantic family"
                                )
                            };
                            state.advancing.result = result;
                            state.advancing.result_inferred_type_arg_suffix =
                                inferred_type_arg_suffix;
                        }
                    }
                    OrdinaryChildAdvance::Pending(child) => {
                        state.pending.push(PendingOrdinaryCallChild { child, role });
                    }
                }
                advance_general_goal_call_driver_pending(state, frontier, tcx, next)
            })),
            scope_exit: OrdinaryDriverScopeExit::None,
        }));
    }
    state.advancing.pending = std::mem::take(&mut state.pending);
    if state.advancing.pending.iter().any(|pending| {
        matches!(
            pending.role,
            PendingOrdinaryChildRole::ContextualReturnedForall
        )
    }) {
        state
            .advancing
            .pending
            .append(&mut state.deferred_non_evidence);
        return next(
            GeneralGoalCallAdvance::Pending(state.advancing),
            frontier,
            tcx,
        );
    }
    let GeneralGoalCallDriverState {
        advancing,
        mode,
        declared_transition,
        contextual_returned_forall_boundary,
        had_pending_children,
        immediate_body_was_incomplete,
        pending,
        remaining,
        deferred_non_evidence,
        prioritize_contextual_returned_forall,
    } = state;
    debug_assert!(pending.is_empty() && remaining.is_empty());
    advance_immediate_lambda_body_driver(
        frontier,
        advancing,
        mode,
        declared_transition,
        tcx,
        Box::new(move |mut advancing, body_complete, frontier, tcx| {
            if !body_complete {
                advancing.pending.extend(deferred_non_evidence);
                return next(GeneralGoalCallAdvance::Pending(advancing), frontier, tcx);
            }
            advance_general_goal_call_driver_after_immediate(
                GeneralGoalCallDriverState {
                    advancing,
                    mode,
                    declared_transition,
                    contextual_returned_forall_boundary,
                    had_pending_children,
                    immediate_body_was_incomplete,
                    pending: Vec::new(),
                    remaining: deferred_non_evidence.into(),
                    deferred_non_evidence: Vec::new(),
                    prioritize_contextual_returned_forall,
                },
                frontier,
                tcx,
                next,
            )
        }),
    )
}

#[cfg(feature = "surface")]
fn advance_general_goal_call_driver_after_immediate<'m>(
    mut state: GeneralGoalCallDriverState<'m>,
    frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    next: GeneralGoalCallDriverContinue<'m>,
) -> Result<OrdinaryDriverStep<'m>, Error> {
    let newly_initial = matches!(
        state
            .advancing
            .pending_expected_result
            .as_ref()
            .map(|pending| &pending.progress),
        Some(EquationProgress::Initial)
    );
    if newly_initial {
        #[cfg(all(test, feature = "surface"))]
        if state.immediate_body_was_incomplete {
            IMMEDIATE_POST_BODY_EXPECTED_EQUATIONS
                .with(|attempts| attempts.set(attempts.get() + 1));
        }
        let _ = try_apply_pending_expected_result(frontier, &mut state.advancing, tcx)?;
    }
    if state.contextual_returned_forall_boundary.is_some()
        && let Some(returned) =
            completed_immediate_contextual_returned_forall(frontier, &state.advancing, tcx)?
    {
        assert!(
            state.declared_transition.is_none(),
            "a contextual returned-Forall preceded a declared value transition"
        );
        state.advancing.result = returned;
        state.advancing.pending.extend(state.remaining);
        return next(
            GeneralGoalCallAdvance::ContextualReturnedForall(state.advancing),
            frontier,
            tcx,
        );
    }
    advance_general_goal_call_driver_deferred(state, newly_initial, frontier, tcx, next)
}

#[cfg(feature = "surface")]
fn advance_general_goal_call_driver_deferred<'m>(
    mut state: GeneralGoalCallDriverState<'m>,
    newly_initial: bool,
    frontier: &mut frontier::ConnectedCallFrontier<'_, 'm>,
    tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    next: GeneralGoalCallDriverContinue<'m>,
) -> Result<OrdinaryDriverStep<'m>, Error> {
    if let Some(PendingOrdinaryCallChild { mut child, role }) = state.remaining.pop_front() {
        assert!(
            matches!(role, PendingOrdinaryChildRole::Value),
            "the post-body child phase retained immediate evidence"
        );
        let span = child.cursor.source.span();
        if let Some(expected) = child.cursor.expected.clone() {
            let destination = frontier.owner();
            let progressed = {
                let (store, owner, delta, _publication) = frontier.parts_mut();
                let expected = expected.into_scoped(owner, store, span)?;
                store.try_zonk_goal_free(delta, expected, tcx)?
            };
            if let Some(ty) = progressed {
                child.cursor.expected = Some(OwnerBoundType::Retained {
                    owner: destination,
                    ty,
                });
            }
        }
        return Ok(OrdinaryDriverStep::Descend(OrdinaryDriverDescend {
            child,
            inherited_mode: state.mode,
            demand: OrdinaryCompletionDemand::GoalFreeValue,
            handoff: OrdinaryDriverHandoff::Current(Box::new(move |result, frontier, tcx| {
                if let OrdinaryChildAdvance::Pending(child) = result {
                    state.advancing.pending.push(PendingOrdinaryCallChild {
                        child,
                        role: PendingOrdinaryChildRole::Value,
                    });
                }
                advance_general_goal_call_driver_deferred(state, newly_initial, frontier, tcx, next)
            })),
            scope_exit: OrdinaryDriverScopeExit::None,
        }));
    }
    if state.advancing.pending_expected_result.is_some() {
        let descendants_closed = state.had_pending_children && state.advancing.pending.is_empty();
        if descendants_closed && !newly_initial {
            let _ = try_apply_pending_expected_result(frontier, &mut state.advancing, tcx)?;
        }
        if state.advancing.pending.is_empty()
            && let Some(pending_expected_result) = state.advancing.pending_expected_result.as_ref()
        {
            if state.mode.executes_actions() {
                let span = state.advancing.call.call_site;
                let expected = pending_expected_result.expected.clone();
                let (store, owner, delta, _publication) = frontier.parts_mut();
                let _ = store.require_goal_free_after_delta(
                    delta,
                    state.advancing.result.clone(),
                    tcx,
                )?;
                let expected = expected.into_scoped(owner, store, span.span)?;
                let _ = store.require_goal_free_after_delta(delta, expected, tcx)?;
                unreachable!("a blocked final expected-result equation had two goal-free sides")
            }
            return next(
                GeneralGoalCallAdvance::Pending(state.advancing),
                frontier,
                tcx,
            );
        }
    }
    if state.advancing.pending.is_empty() {
        let advancing = *state.advancing;
        return next(
            GeneralGoalCallAdvance::Complete(Box::new(CompletedPathUnitGoalCall {
                call: advancing.call,
                result: advancing.result,
                result_inferred_type_arg_suffix: advancing.result_inferred_type_arg_suffix,
            })),
            frontier,
            tcx,
        );
    }
    if state.mode == frontier::FrontierMode::Final
        && state
            .advancing
            .pending
            .iter()
            .any(|pending| !pending.child.is_completion_wait())
    {
        unreachable!("an ordinary call child remained pending after Final")
    }
    next(
        GeneralGoalCallAdvance::Pending(state.advancing),
        frontier,
        tcx,
    )
}

#[cfg(feature = "surface")]
fn close_completed_ordinary_child<'m>(
    frontier: &mut impl OrdinaryFrontierReentry<'m>,
    mut child: frontier::OpenRetainedPremise<'m>,
    completed: CompletedInFrame,
    destination: crate::ast::TypeGoalOwner,
    tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
) -> Result<CompletedInFrame, Error> {
    if let Some(source) = child.take_quote_source() {
        assert!(
            !matches!(completed, CompletedInFrame::UserElaboratorCall { .. }),
            "a public quotation source closed as an internal call transcript"
        );
        child.publication_mut().record_rec_quote_source_type(
            source,
            completed.scoped().clone(),
            matches!(completed, CompletedInFrame::FunctionScheme(..)),
        );
    }
    let completed = match completed {
        CompletedInFrame::UserElaboratorCall {
            output,
            inferred_type_arg_suffix,
            mut transcript,
        } => {
            let mut semantic_outputs = vec![(output, GoalEscape::ToOwner(destination))];
            for layer in &transcript.layers {
                semantic_outputs.extend(
                    layer
                        .type_slots
                        .iter()
                        .filter_map(|ty| ty.clone())
                        .map(|ty| (ty, GoalEscape::ToOwner(destination))),
                );
                semantic_outputs.extend(
                    layer
                        .sources
                        .iter()
                        .map(|source| (source.expected.clone(), GoalEscape::ToOwner(destination))),
                );
            }
            let outputs = frontier.close_ordinary_child(child, semantic_outputs, tcx)?;
            let mut outputs = outputs.into_iter();
            let output = match outputs
                .next()
                .expect("a retained user-elaborator call returned no value output")
            {
                ClosedGoalOutput::Retained(output) => output.into_scoped_type(),
                ClosedGoalOutput::RetainedFunctionScheme(_)
                | ClosedGoalOutput::GoalFree(_)
                | ClosedGoalOutput::FunctionScheme(_) => {
                    unreachable!("a retained user-elaborator call changed semantic class")
                }
            };
            for layer in &mut transcript.layers {
                for ty in &mut layer.type_slots {
                    if ty.is_some() {
                        *ty = Some(
                            match outputs
                                .next()
                                .expect("a retained elaborator transcript lost a type slot")
                            {
                                ClosedGoalOutput::Retained(output) => output.into_scoped_type(),
                                _ => unreachable!("an elaborator type slot changed semantic class"),
                            },
                        );
                    }
                }
                for source in &mut layer.sources {
                    source.expected = match outputs
                        .next()
                        .expect("a retained elaborator transcript lost a source expectation")
                    {
                        ClosedGoalOutput::Retained(output) => output.into_scoped_type(),
                        _ => unreachable!("an elaborator source type changed semantic class"),
                    };
                }
            }
            assert!(
                outputs.next().is_none(),
                "a retained elaborator transcript returned extra semantic outputs"
            );
            return Ok(CompletedInFrame::UserElaboratorCall {
                output,
                inferred_type_arg_suffix,
                transcript,
            });
        }
        completed => completed,
    };
    let escape = match completed {
        CompletedInFrame::Value(output, suffix) => {
            (output, GoalEscape::ToOwner(destination), suffix, false)
        }
        CompletedInFrame::FunctionScheme(output, suffix) => (
            output,
            GoalEscape::ToOwnerFunctionScheme(destination),
            suffix,
            true,
        ),
        CompletedInFrame::UserElaboratorCall { .. } => {
            unreachable!("the user-elaborator completion was handled above")
        }
    };
    let (output, escape, suffix, function_scheme) = escape;
    let mut outputs = frontier.close_ordinary_child(child, vec![(output, escape)], tcx)?;
    assert_eq!(
        outputs.len(),
        1,
        "an ordinary retained value returned the wrong semantic output count"
    );
    let output = outputs
        .pop()
        .expect("an ordinary retained value returned no semantic output");
    Ok(match output {
        ClosedGoalOutput::Retained(output) => {
            assert!(
                !function_scheme,
                "a value output changed semantic class while closing"
            );
            CompletedInFrame::Value(output.into_scoped_type(), suffix)
        }
        ClosedGoalOutput::RetainedFunctionScheme(output) => {
            assert!(
                function_scheme,
                "a function scheme changed semantic class while closing"
            );
            CompletedInFrame::FunctionScheme(output.into_scoped_type(), suffix)
        }
        ClosedGoalOutput::GoalFree(_) | ClosedGoalOutput::FunctionScheme(_) => {
            unreachable!("a retained ordinary child closed as a goal-free root output")
        }
    })
}

