#[cfg(feature = "surface")]
impl<'m> OrdinaryValueCursor<'m> {
    fn run_root(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<&InternedType<crate::ast::Lowered>>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<Synth<crate::ast::Lowered>, Error> {
        Self::run_root_from_mode(source, expected, frontier::FrontierMode::ExpectedOnly, tcx)
    }

    fn run_root_from_mode(
        source: &'m crate::ast::Expr<crate::ast::Lowered>,
        expected: Option<&InternedType<crate::ast::Lowered>>,
        initial_mode: frontier::FrontierMode,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<Synth<crate::ast::Lowered>, Error> {
        let (mut frontier, ()) =
            frontier::OrdinaryFrontier::begin_root_with(source.span(), tcx, |_store, _owner| {
                Ok(())
            })?;
        let mut child = Self::begin_child(
            source,
            expected.cloned().map(OwnerBoundType::Plain),
            &mut frontier,
            tcx,
        )?;
        child.next_mode = initial_mode;
        let completed = loop {
            let mode = child.next_mode;
            match Self::advance_open_child_iterative(
                child,
                mode,
                OrdinaryCompletionDemand::GoalFreeValue,
                false,
                &mut frontier,
                tcx,
            )? {
                OpenOrdinaryChildAdvance::Pending(next) => {
                    if next.is_completion_wait() {
                        next.cursor
                            .require_completion_outside(frontier.owner(), frontier.store())?;
                        unreachable!("a root completion wait escaped its inference domain")
                    }
                    child = next;
                }
                OpenOrdinaryChildAdvance::Complete { child, completed } => {
                    let destination = frontier.owner();
                    break close_completed_ordinary_child(
                        &mut frontier,
                        child,
                        completed,
                        destination,
                        tcx,
                    )?;
                }
            }
        };
        let owner = frontier.owner();
        let inferred_type_arg_suffix = completed.inferred_type_arg_suffix();
        match completed {
            CompletedInFrame::Value(result, _) => frontier.close_root_with(
                vec![(result, GoalEscape::ClosedAt(owner))],
                tcx,
                |mut outputs, _tcx| {
                    assert_eq!(
                        outputs.len(),
                        1,
                        "ordinary root returned extra value outputs"
                    );
                    let ClosedGoalOutput::GoalFree(output) = outputs.remove(0) else {
                        unreachable!("an ordinary value root must close goal-free")
                    };
                    Ok(
                        Synth::value_interned(output.into_scoped_type().ty().clone())
                            .with_inferred_type_arg_suffix(inferred_type_arg_suffix),
                    )
                },
            ),
            CompletedInFrame::FunctionScheme(result, _) => frontier.close_root_with(
                vec![(result, GoalEscape::ClosedFunctionSchemeAt(owner))],
                tcx,
                |mut outputs, _tcx| {
                    assert_eq!(
                        outputs.len(),
                        1,
                        "ordinary root returned extra function-scheme outputs"
                    );
                    let ClosedGoalOutput::FunctionScheme(output) = outputs.remove(0) else {
                        unreachable!("an ordinary function-scheme root lost its scheme class")
                    };
                    Ok(
                        Synth::complete_scheme_interned(output.into_scoped_type().ty().clone())
                            .with_inferred_type_arg_suffix(inferred_type_arg_suffix),
                    )
                },
            ),
            CompletedInFrame::UserElaboratorCall { .. } => {
                unreachable!("an elaborator transcript escaped its owning value cursor")
            }
        }
    }
}

#[cfg(feature = "surface")]
impl<'m> OpenOrdinaryCallPlan<'m> {
    fn advance(
        self,
        frontier: &mut impl OrdinaryFrontierReentry<'m>,
        expected_ret: Option<&InternedType<crate::ast::Lowered>>,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<CompletedPathUnitGoalCall<'m>, Error> {
        match self {
            Self::PathUnit {
                call,
                values,
                result_inferred_type_arg_suffix,
            } => advance_path_unit_goal_call(
                frontier,
                call,
                values,
                result_inferred_type_arg_suffix,
                expected_ret,
                tcx,
            ),
        }
    }
}

#[cfg(feature = "surface")]
impl ConnectedCallLink {
    fn seal(
        self,
        completed_inferred_type_arg_suffix: usize,
        destination: crate::ast::TypeGoalOwner,
        output: ScopedType,
    ) -> RetainedConnectedCallee {
        assert_eq!(
            self.destination, destination,
            "a connected callee closed toward a different chain root"
        );
        assert_eq!(
            self.class,
            ConnectedCalleeClass::Value,
            "an application result must remain a value-position callee"
        );
        assert_eq!(
            self.inferred_type_arg_suffix, completed_inferred_type_arg_suffix,
            "a connected callee changed its inferred type-argument suffix while advancing"
        );
        RetainedConnectedCallee { link: self, output }
    }
}

#[cfg(feature = "surface")]
impl<'m> LinkedOrdinaryCallPlan<'m> {
    fn consume(
        self,
        incoming: Option<RetainedConnectedCallee>,
        destination: crate::ast::TypeGoalOwner,
    ) -> (OpenOrdinaryCallPlan<'m>, Option<ConnectedCallLink>) {
        match (self.incoming, incoming) {
            (None, None) => {}
            (Some(expected), Some(actual)) => {
                assert_eq!(
                    expected, actual.link,
                    "a connected call consumed another layer's retained callee"
                );
                assert_eq!(
                    expected.destination, destination,
                    "a connected call link targeted another root"
                );
                // Consuming the owner-bound value is the lifecycle proof that
                // the predecessor actually closed before this preplanned
                // successor advances. Its type already constructed this plan
                // inside `ConnectedCallChain::plan`; it is not a new equation.
                drop(actual.output);
            }
            (None, Some(_)) => {
                unreachable!("the direct connected call received a predecessor link")
            }
            (Some(_), None) => {
                unreachable!("a connected successor advanced without its predecessor link")
            }
        }
        (self.plan, self.outgoing)
    }
}

#[cfg(feature = "surface")]
enum ConnectedCallableHead {
    Callable,
    NeedsDynamic,
    NonCallable,
    UnsupportedPolymorphicValue(PolymorphicNonFunctionHead),
}

#[cfg(feature = "surface")]
struct PolymorphicNonFunctionHead {
    binders: Vec<crate::ast::TypeParam>,
    body: crate::ast::Type<crate::ast::Lowered>,
    identity_canonical: bool,
}

#[cfg(feature = "surface")]
fn connected_callable_head(
    ty: &InternedType<crate::ast::Lowered>,
    tcx: &TypeCtx<'_, '_, crate::ast::Lowered>,
) -> ConnectedCallableHead {
    fn go(
        ty: &crate::ast::Type<crate::ast::Lowered>,
        identity_canonical: bool,
        protected: &mut std::collections::HashSet<String>,
        beneath_forall: bool,
        tcx: &TypeCtx<'_, '_, crate::ast::Lowered>,
    ) -> ConnectedCallableHead {
        let (unfolded, identity_canonical) = super::aliases::unfold_and_qualify_state(
            ty,
            &tcx.binder_alias_ctx(protected),
            identity_canonical,
        );
        match unfolded {
            crate::ast::Type::Forall { param, body, .. } => {
                let inserted = protected.insert(param.name.clone());
                let mut class = go(&body, identity_canonical, protected, true, tcx);
                if inserted {
                    protected.remove(&param.name);
                }
                if let ConnectedCallableHead::UnsupportedPolymorphicValue(head) = &mut class {
                    head.binders.push(param);
                }
                class
            }
            crate::ast::Type::Function { .. } => ConnectedCallableHead::Callable,
            crate::ast::Type::Goal { .. } | crate::ast::Type::Infer { .. } => {
                if beneath_forall {
                    ConnectedCallableHead::UnsupportedPolymorphicValue(PolymorphicNonFunctionHead {
                        binders: Vec::new(),
                        body: unfolded,
                        identity_canonical,
                    })
                } else {
                    ConnectedCallableHead::NeedsDynamic
                }
            }
            crate::ast::Type::Unit { .. }
            | crate::ast::Type::Bottom { .. }
            | crate::ast::Type::Product { .. }
            | crate::ast::Type::Sum { .. }
            | crate::ast::Type::Path { .. } => {
                if beneath_forall {
                    ConnectedCallableHead::UnsupportedPolymorphicValue(PolymorphicNonFunctionHead {
                        binders: Vec::new(),
                        body: unfolded,
                        identity_canonical,
                    })
                } else {
                    ConnectedCallableHead::NonCallable
                }
            }
            crate::ast::Type::LabelSugar { ext, .. } => match ext {},
        }
    }

    let mut head = go(
        ty.as_type(),
        ty.identity_is_canonical(),
        &mut tcx.in_scope_type_param_binders(),
        false,
        tcx,
    );
    if let ConnectedCallableHead::UnsupportedPolymorphicValue(payload) = &mut head {
        payload.binders.reverse();
    }
    head
}

#[cfg(feature = "surface")]
fn dynamic_successor_layers_use_unambiguous_values(
    layers: &[SelectedPathUnitCallLayer<'_>],
) -> bool {
    layers.iter().all(|layer| {
        !layer.args.is_empty()
            && layer
                .args
                .iter()
                .map(CallArgRef::from_arg)
                .all(|arg| matches!(arg, CallArgRef::Value(_)) && !arg.type_slot_candidate())
    })
}

#[cfg(feature = "surface")]
impl<'m> UnpreparedConnectedCallChain<'m> {
    /// Construct every owner-bound call and exact symbolic link once before
    /// the root delta opens. Value premises are prepared only after the whole
    /// structural chain selects this route.
    fn plan(
        direct: &PreparedDirectCallee,
        layers: &[SelectedPathUnitCallLayer<'m>],
        store: &mut GoalStore,
        destination: crate::ast::TypeGoalOwner,
        tcx: &TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<frontier::PlanningSelection<Self, ConnectedPlanOutcome>, Error> {
        let mut callee = Synth {
            ty: direct.synth.ty.clone(),
            is_scheme: direct.synth.is_scheme,
            complete_scheme: direct.synth.complete_scheme,
            inferred_type_arg_suffix: direct.synth.inferred_type_arg_suffix,
        };
        let mut incoming = None;
        let mut plans = Vec::with_capacity(layers.len());

        for (index, layer) in layers.iter().enumerate() {
            let args = call_arg_refs(layer.args);
            let preflight =
                match preflight_open_path_unit_call(&callee, &args, layer.callee_span, tcx)? {
                    OpenPathUnitPreflightDecision::Planned(preflight) => preflight,
                    OpenPathUnitPreflightDecision::NeedsDynamic => {
                        let outcome = if index != 0
                            && dynamic_successor_layers_use_unambiguous_values(&layers[index..])
                        {
                            ConnectedPlanOutcome::NeedsDynamicSuccessor
                        } else {
                            ConnectedPlanOutcome::Decline { layer: index }
                        };
                        return Ok(frontier::PlanningSelection::Unselected(outcome));
                    }
                    OpenPathUnitPreflightDecision::StructuralDecline
                    | OpenPathUnitPreflightDecision::PolymorphicNonFunction
                    | OpenPathUnitPreflightDecision::Arity => {
                        return Ok(frontier::PlanningSelection::Unselected(
                            ConnectedPlanOutcome::Decline { layer: index },
                        ));
                    }
                    OpenPathUnitPreflightDecision::NonCallable(error) => {
                        return Ok(frontier::PlanningSelection::Unselected(
                            ConnectedPlanOutcome::NonCallable {
                                layer: index,
                                error,
                            },
                        ));
                    }
                };
            let OpenPathUnitPreflight {
                shape,
                result_inferred_type_arg_suffix,
            } = preflight;
            let call = OpenGoalCall::begin(
                shape,
                destination,
                layer.callee_span,
                layer.call_site,
                store,
                tcx,
            )?;
            let result_ty =
                if call.shape.has_written_type_only() && !call.shape.result_is_pre_residual {
                    call.residual_function_type(destination)
                } else {
                    call.result_type(destination)
                };
            let outgoing = (index + 1 < layers.len()).then_some(ConnectedCallLink {
                ordinal: index,
                destination,
                class: ConnectedCalleeClass::Value,
                inferred_type_arg_suffix: result_inferred_type_arg_suffix,
            });
            plans.push(LinkedUnpreparedOrdinaryCall {
                incoming,
                outgoing,
                call,
                result_inferred_type_arg_suffix,
            });
            incoming = outgoing;

            // This is the only construction of a symbolic intermediate
            // callee. Its class and suffix are exactly those frozen into the
            // link consumed by the successor plan.
            callee = Synth {
                ty: result_ty,
                is_scheme: false,
                complete_scheme: super::kind_scheme::CompleteScheme::Incomplete,
                inferred_type_arg_suffix: result_inferred_type_arg_suffix,
            };
        }

        Ok(frontier::PlanningSelection::Selected(
            UnpreparedConnectedCallChain { plans },
        ))
    }
}

#[cfg(feature = "surface")]
impl<'m> UnpreparedConnectedCallChain<'m> {
    fn prepare(
        self,
        tcx: &mut TypeCtx<'m, '_, crate::ast::Lowered>,
    ) -> Result<ConnectedCallChain<'m>, Error> {
        let plans = self
            .plans
            .into_iter()
            .map(|preplanned| {
                let LinkedUnpreparedOrdinaryCall {
                    incoming,
                    outgoing,
                    call,
                    result_inferred_type_arg_suffix,
                } = preplanned;
                let values = prepare_path_unit_values(&call.shape, tcx)?;
                Ok(LinkedOrdinaryCallPlan {
                    incoming,
                    outgoing,
                    plan: OpenOrdinaryCallPlan::PathUnit {
                        call,
                        values,
                        result_inferred_type_arg_suffix,
                    },
                })
            })
            .collect::<Result<Vec<_>, Error>>()?;
        Ok(ConnectedCallChain { plans })
    }
}

/// Apply a polymorphic function `Forall(binders, Function(param,
/// ret))` to a call's positional args. Walks the type left-to-right:
/// the first `binders.len()` slots are type arguments; remaining
/// arguments are values that right-fold into a `Product` matching
/// `param`. Surface Kio may infer omitted type slots. Kio' requires
/// universal slots explicitly and permits inference only for the
/// tracked existential suffix of a newtype constructor.
///
/// The function domain's product width lets the inference path detect
/// when the user elided type-args
/// (call has fewer args than `n_binders + value_slots`).
///
/// `expected_ret` is the call's expected return type when one is
/// available from the surrounding checked context (the
/// `check_call_against` entry path). In an inference-admitting slot,
/// any binder still unbound after value-argument unification is
/// solved by unifying the callee's return type against this expected
/// type — the bidirectional flow `specs/language.md` § Type system
/// specifies. Binders reachable from neither path remain unbound and
/// surface the "cannot infer" diagnostic.
///
/// `slot_offset` is the count of canonical argument slots already
/// consumed by preceding layers of a multi-layer flat call
/// (`specs/language.md` § 4c). The substitute pass walks one global
/// slot index across the *whole* flat argument list, so every
/// recorded resolution / value-at-type-slot marker must key off the
/// call-global slot (`slot_offset + layer_local_index`), not the
/// layer-local index. For a single-layer call the offset is 0 and
/// the two coincide.
#[allow(clippy::too_many_arguments)] // every argument is load-bearing: callee scheme parts (binders / fn_param / fn_ret / abi_arity), the call's args, the call's span, the per-layer slot offset, the call's expected return type for inference, and the typer context
fn apply_polymorphic_function<'m, P>(
    binders: &[crate::ast::TypeParam],
    fn_param: &crate::ast::Type<P>,
    fn_ret: &crate::ast::Type<P>,
    abi_arity: usize,
    args: &[CallArgRef<'m, P>],
    callee_span: Span,
    call_site: crate::ast::ExpressionSite,
    slot_offset: usize,
    expected_ret: Option<&InternedType<P>>,
    identity_canonical: bool,
    inferred_type_arg_suffix: usize,
    preplanned: Option<PlannedApplication<'m, P>>,
    tcx: &mut TypeCtx<'m, '_, P>,
) -> Result<Applied<P>, Error>
where
    P: TyperPhase + crate::ast::Phase<TypeLabelSugar = crate::ast::Never> + Clone,
{
    match plan_polymorphic_function(
        binders,
        fn_param,
        fn_ret,
        abi_arity,
        None,
        args,
        callee_span,
        call_site,
        slot_offset,
        expected_ret,
        identity_canonical,
        inferred_type_arg_suffix,
        preplanned,
        false,
        ValuePreparationMode::LexicalFallback,
        tcx,
    )? {
        ConsumingApplication::Complete(applied) => Ok(applied),
        ConsumingApplication::NeedsExpected(_) => {
            unreachable!("ordinary application did not permit expected-type deferral")
        }
    }
}

#[allow(clippy::too_many_arguments)] // shared consuming-application entry plus the bounded expected-type deferral switch
fn plan_polymorphic_function<'m, P>(
    binders: &[crate::ast::TypeParam],
    fn_param: &crate::ast::Type<P>,
    fn_ret: &crate::ast::Type<P>,
    abi_arity: usize,
    semantic: Option<(&SemanticCallCursor<P>, &SelectedSemanticCall<P>)>,
    args: &[CallArgRef<'m, P>],
    callee_span: Span,
    call_site: crate::ast::ExpressionSite,
    slot_offset: usize,
    expected_ret: Option<&InternedType<P>>,
    identity_canonical: bool,
    inferred_type_arg_suffix: usize,
    preplanned: Option<PlannedApplication<'m, P>>,
    allow_expected_deferral: bool,
    preparation_mode: ValuePreparationMode,
    tcx: &mut TypeCtx<'m, '_, P>,
) -> Result<ConsumingApplication<'m, P>, Error>
where
    P: TyperPhase + crate::ast::Phase<TypeLabelSugar = crate::ast::Never> + Clone,
{
    let n_binders = binders.len();
    let mut preplanned = preplanned;
    let had_preplanned = preplanned.is_some();
    let ambient_type_params = tcx.in_scope_type_param_binders();
    let mut protected_type_params = ambient_type_params.clone();
    protected_type_params.extend(binders.iter().map(|binder| binder.name.clone()));
    let value_slots = semantic.map_or_else(
        || {
            function_layer_value_slot_count_with_identity(
                fn_param,
                &tcx.binder_alias_ctx(&protected_type_params),
                identity_canonical,
            )
        },
        |(_, selected)| selected.width.structural,
    );
    let explicit_prefix = preplanned.as_ref().map_or_else(
        || {
            semantic.map_or_else(
                || explicit_type_arg_prefix_len(args, n_binders),
                |(_, selected)| selected.explicit_prefix,
            )
        },
        |plan| plan.written_type_args.len(),
    );
    let inferred_type_arg_suffix = inferred_type_arg_suffix.min(n_binders);
    let required_explicit_prefix = n_binders - inferred_type_arg_suffix;
    let type_only_residual =
        explicit_prefix > 0 && explicit_prefix < n_binders && explicit_prefix == args.len();
    if semantic.is_none()
        && !<P::Typer as Typer<P>>::ALLOW_ELIDED_UNIVERSAL_CALL_TYPE_ARGS
        && explicit_prefix < required_explicit_prefix
        && !type_only_residual
    {
        let missing = &binders[explicit_prefix].name;
        return Err(Error::type_(
            call_site.span,
            format!("Kio' requires an explicit type argument for `[{missing}]`"),
        )
        .with_help(
            "supply every universal type argument before the value arguments; Kio' does not infer them",
        ));
    }
    if explicit_prefix == 0 && args.iter().any(|arg| matches!(arg, CallArgRef::Type(_))) {
        return Err(Error::type_(
            call_site.span,
            "type arguments must precede value arguments in a call",
        ));
    }
    let (type_args, value_args) = args.split_at(explicit_prefix);
    if let Some(arg) = value_args
        .iter()
        .find(|arg| !matches!(arg, CallArgRef::Value(_)))
    {
        return Err(Error::type_(
            arg.span(),
            "type arguments must precede value arguments in a call",
        ));
    }
    let inferred_type_args = explicit_prefix < n_binders;
    let completion = if inferred_type_args {
        PlannedApplicationCompletion::Inferred
    } else {
        PlannedApplicationCompletion::Explicit
    };
    let param_requirement_source = semantic
        .and_then(|(cursor, _)| cursor.param.as_ref())
        .and_then(SemanticValueDomain::as_known)
        .and_then(InternedType::requirement_source);
    let mut plan = preplanned.take().unwrap_or_else(|| {
        PlannedApplication::empty_layer(
            binders.to_vec(),
            type_args.to_vec(),
            InternedType::fresh_with_identity(fn_param.clone(), identity_canonical)
                .with_requirement_source(param_requirement_source.cloned()),
            identity_canonical,
            completion,
        )
    });
    plan.completion = completion;
    let mut subst: HashMap<String, crate::ast::Type<P>> = HashMap::new();
    let mut result_canonical = identity_canonical;
    if had_preplanned || semantic.is_some() {
        plan.seed_prevalidated_type_arguments(
            &mut subst,
            &mut result_canonical,
            type_only_residual,
            &ambient_type_params,
            tcx,
        )?;
    } else {
        plan.seed_type_arguments(
            &mut subst,
            &mut result_canonical,
            type_only_residual,
            &ambient_type_params,
            tcx,
        )?;
    }
    plan.slot_identity_canonical = result_canonical;

    if type_only_residual {
        plan.completion = PlannedApplicationCompletion::PartialTypeApplication;
        plan.finalize(
            &mut subst,
            &std::collections::HashSet::new(),
            callee_span,
            call_site,
            slot_offset,
            &mut ApplicationHoleState::default(),
            None,
            tcx,
        )?;
        let residual = function_from_parts(
            subst_type(fn_param, &subst),
            subst_type(fn_ret, &subst),
            abi_arity,
            fn_ret.span(),
        );
        return Ok(ConsumingApplication::Complete(Applied {
            ty: InternedType::fresh_with_identity(
                wrap_foralls(&binders[explicit_prefix..], residual, fn_ret.span()),
                result_canonical,
            ),
            inferred_type_arg_suffix: inferred_type_arg_suffix.min(n_binders - explicit_prefix),
            consumed_value: false,
        }));
    }

    let type_param_names: std::collections::HashSet<String> =
        binders.iter().map(|tp| tp.name.clone()).collect();
    let implicit_unit_application = value_args.is_empty() && explicit_prefix == 0;
    let written_type_only = value_args.is_empty() && explicit_prefix > 0;
    let partial_type_application = written_type_only;
    if implicit_unit_application {
        super::synth::unify_pattern_with_holes_state(
            fn_param,
            &crate::ast::Type::Unit {
                meta: crate::ast::Meta::new(call_site.span),
            },
            &type_param_names,
            &std::collections::HashSet::new(),
            &mut subst,
            call_site.span,
            &tcx.binder_alias_ctx(&protected_type_params),
            identity_canonical,
            true,
        )?;
    }
    let any_unbound = type_param_names.iter().any(|n| !subst.contains_key(n));
    plan.completion = if partial_type_application {
        PlannedApplicationCompletion::PartialTypeApplication
    } else {
        completion
    };
    plan = if had_preplanned || partial_type_application {
        plan
    } else if any_unbound {
        let seeds = PlannedApplication::plan_value_args(value_args, call_site, tcx)?;
        plan.with_expected_slots(
            PlannedExpectedValue::type_needing_substitution(
                InternedType::fresh_with_identity(fn_param.clone(), result_canonical)
                    .with_requirement_source(param_requirement_source.cloned()),
            ),
            seeds,
            call_site,
            &tcx.binder_alias_ctx(&protected_type_params),
        )?
    } else {
        let requirement_source = if matches!(fn_param, crate::ast::Type::Path { segments, .. }
            if segments.len() == 1 && subst.contains_key(segments[0].as_str()))
        {
            None
        } else {
            param_requirement_source.cloned()
        };
        let substituted_param =
            InternedType::fresh_with_identity(subst_type(fn_param, &subst), result_canonical)
                .with_requirement_source(requirement_source);
        if !<P::Typer as Typer<P>>::ALLOW_MULTI_LAYER_FLAT_CALL {
            // Kio' does not traverse a later curry layer through one flat
            // call. A binder instantiated with a product may widen one source
            // slot into several positional slots; a binder instantiated with
            // Unit retains its one explicitly supplied value slot. Reject
            // only when the suffix exceeds both views and the result actually
            // has another callable layer.
            // The zero-component product has no ABI slots, but a source or
            // Prime call may still spell its sole value explicitly as `()`.
            // That one value belongs to this layer; only a later value would
            // cross into the returned function layer.
            let (first_layer_capacity, has_successor) = semantic.map_or_else(
                || {
                    let substituted_value_slots = function_layer_value_slot_count_with_identity(
                        substituted_param.as_type(),
                        &tcx.binder_alias_ctx(&protected_type_params),
                        substituted_param.identity_is_canonical(),
                    );
                    (
                        value_slots.max(substituted_value_slots).max(1),
                        has_applicable_head(
                            fn_ret,
                            &tcx.binder_alias_ctx(&protected_type_params),
                            identity_canonical,
                        ),
                    )
                },
                |(cursor, selected)| {
                    (
                        selected.width.capacity,
                        cursor.successor(selected, tcx).is_some(),
                    )
                },
            );
            let source_count = semantic.map_or(value_args.len(), |(_, selected)| {
                selected.consecutive_sources
            });
            if source_count > first_layer_capacity && has_successor {
                return Err(Error::type_(
                    call_site.span,
                    "Kio' requires one application per function layer",
                ));
            }
        }
        let seeds = PlannedApplication::plan_value_args(value_args, call_site, tcx)?;
        plan.with_expected_slots(
            PlannedExpectedValue::final_type(substituted_param),
            seeds,
            call_site,
            &tcx.binder_alias_ctx(&protected_type_params),
        )?
    };
    let gather_inference_constraints = (any_unbound || had_preplanned) && !partial_type_application;
    if gather_inference_constraints {
        plan.gather_synthesized_constraints(
            &type_param_names,
            &mut subst,
            call_site.span,
            &tcx.binder_alias_ctx(&protected_type_params),
        )?;
    }

    ExpectedApplication {
        binders: binders.to_vec(),
        fn_param: fn_param.clone(),
        fn_ret: fn_ret.clone(),
        abi_arity,
        plan,
        subst,
        type_param_names,
        callee_span,
        call_site,
        slot_offset,
        result_canonical,
        identity_canonical,
        partial_type_application,
        implicit_unit_application,
        gather_inference_constraints,
        expected_pass_done: false,
        fallback_pass_done: false,
        local_scope: None,
        local_hole_params: Vec::new(),
        retained_holes: ApplicationHoleState::default(),
    }
    .finish_or_defer(expected_ret, allow_expected_deferral, preparation_mode, tcx)
}

fn memoized_polymorphic_instantiation<'m, P>(
    binders: &[crate::ast::TypeParam],
    fn_param: &crate::ast::Type<P>,
    fn_ret: &crate::ast::Type<P>,
    abi_arity: usize,
    subst: &HashMap<String, crate::ast::Type<P>>,
    identity_canonical: bool,
    tcx: &TypeCtx<'m, '_, P>,
) -> InternedType<P>
where
    P: TyperPhase + crate::ast::Phase<TypeLabelSugar = crate::ast::Never> + Clone,
{
    let intern = |ty: &crate::ast::Type<P>| {
        let handle = tcx.intern_type(ty);
        if identity_canonical {
            handle.with_canonical_identity()
        } else {
            handle
        }
    };
    let type_args = binders
        .iter()
        .map(|binder| {
            let arg = subst
                .get(&binder.name)
                .expect("polymorphic instantiation memo reached after every binder was resolved");
            intern(arg)
        })
        .collect();
    let scheme_body =
        function_from_parts(fn_param.clone(), fn_ret.clone(), abi_arity, fn_ret.span());
    let scheme = wrap_foralls(binders, scheme_body, fn_ret.span());
    let key = PolymorphicInstantiationKey::new(intern(&scheme), type_args);
    tcx.env.memo.polymorphic_instantiation(key, || {
        let instantiated = subst_type(fn_ret, subst);
        intern(&instantiated)
    })
}

fn is_inline_fn_expr<P: crate::ast::Phase>(e: &crate::ast::Expr<P>) -> bool {
    matches!(e, crate::ast::Expr::FnExpr { .. })
}

/// A scalar whose admitted type can depend on its enclosing value slot.
/// Bare literals use the ordinary expected-role tier; diagnostic text is a
/// compile-time intrinsic type admitted only by its exact expected slot.
fn is_expected_dependent_scalar<P>(e: &crate::ast::Expr<P>) -> bool
where
    P: crate::ast::Phase,
{
    super::literal_check_parts(e).is_some_and(|(_, annotation, _)| {
        annotation.is_none_or(|annotation| {
            matches!(annotation, crate::ast::Type::Infer { .. })
                || matches!(annotation,
                    crate::ast::Type::Path { segments, args, .. }
                        if segments.len() == 1
                            && segments[0].as_str() == "__Diagnostic_text__"
                            && args.is_empty())
        })
    })
}

#[derive(Clone, Copy)]
