    #[cfg(feature = "surface")]
    #[test]
    fn retained_local_direct_and_leaf_uses_preserve_open_rank_n_scope() {
        use super::super::env::{reset_retained_local_work, retained_local_work};
        for body in ["step(())", "accept(step)"] {
            let source = format!("module main;
                newtype Box[A] : A {{ constructor box; projector unbox }}
                host fn accept[*F](step: [A] A -> F(A)) -> F(.);
                host fn collect[*F](body: ([A] A -> F(A)) -> F(.), later: F(.)) -> F(.);
                fn result() -> Box(.) {{ let result = collect(.(step) {{ {body} }}, Box.box(())); result }}");
            reset_retained_local_work();
            let package = resolved_lowered_test_package(&source);
            let module = &package.module("main").expect("main").module;
            let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
                .expect("environment");
            let (index, def) = module
                .items
                .iter()
                .enumerate()
                .find_map(|(index, item)| match item {
                    Item::FnDef(def) if def.name == "result" => Some((index, def)),
                    _ => None,
                })
                .expect("result");
            let mut elaborations = Elaborations::new();
            let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(index);
            run_general_ordinary_value(&def.body, None, &mut tcx)
                .expect("local proof stays scoped");
            let work = retained_local_work();
            assert!(
                work.open_forall_consumes > 0,
                "the local read must consume the open rank-N proof: {body}: {work:?}"
            );
            eprintln!("rank-N {body}: {work:?}");
        }
    }

    #[cfg(feature = "surface")]
    #[test]
    fn retained_local_position_facts_commit_only_with_the_connected_root() {
        use super::super::env::{reset_retained_local_work, retained_local_work};
        for invalid in [true, false] {
            let later = if invalid { ". -> ." } else { "." };
            let source = format!("module main;
                newtype Box[A] : A {{ constructor box; projector unbox }}
                host fn collect[*F](body: ([A] A -> F(A)) -> F(.), later: F(.)) -> F(.);
                host fn outer[T](value: T, later: .) -> T;
                fn witness(later: {later}) {{ outer(collect(.(step) {{ step(()) }}, Box.box(())), later) }}");
            let package = resolved_lowered_test_package(&source);
            let module = &package.module("main").expect("main").module;
            let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
                .expect("environment");
            let (item_index, def) = module
                .items
                .iter()
                .enumerate()
                .find_map(|(index, item)| match item {
                    Item::FnDef(def) if def.name == "witness" => Some((index, def)),
                    _ => None,
                })
                .expect("witness");
            let mut elaborations = Elaborations::new();
            let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
            for param in def.sig.value_params() {
                tcx.push_value(param.name.clone(), param.ty.clone().unwrap());
            }
            let mark = tcx.planning_state_fingerprint();
            reset_retained_local_work();
            let result = run_general_ordinary_value(&def.body, None, &mut tcx);
            let work = retained_local_work();
            assert!(
                work.open_forall_consumes > 0,
                "must stage the open local before the sibling verdict: {work:?}"
            );
            let start = source.find("step(())").unwrap() as u32;
            let span = Span::new(start, start + 4);
            let positions = tcx.elaborations.position_index();
            if invalid {
                let error = result.err().expect("later sibling conflict");
                assert!(
                    error.diagnostic().message.contains("type mismatch"),
                    "{error:?}"
                );
                assert!(positions.type_at("main", span).is_none());
                assert!(positions.binder_at("main", span).is_none());
            } else {
                result.expect("matching later sibling");
                assert!(positions.type_at("main", span).is_some());
                assert!(matches!(
                    positions.binder_at("main", span),
                    Some(crate::pass::typecheck_full::ResolvedBinder::Local { .. })
                ));
            }
            let after = tcx.planning_state_fingerprint();
            assert_eq!(
                (after.2, after.3),
                (mark.2, mark.3),
                "local and hole scopes restore"
            );
        }
    }

    fn unit_ty() -> Type {
        Type::Unit {
            meta: Meta::new(sp()),
        }
    }

    #[cfg(feature = "surface")]
    fn with_bounded_stack(run: impl FnOnce() + Send + 'static) {
        std::thread::Builder::new()
            .stack_size(256 * 1024)
            .spawn(run)
            .expect("spawn bounded-stack test thread")
            .join()
            .expect("bounded-stack test thread must not panic");
    }

    fn path_ty(name: &str) -> Type {
        Type::synth_path(vec![name.to_owned()], Vec::new(), sp())
    }

    #[cfg(feature = "surface")]
    fn lowered_path(name: &str, span: Span) -> Expr {
        Expr::Path {
            occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
            segments: vec![crate::ast::PathSegment::new(name, span)],
            meta: Meta::new(span),
            ext: (),
        }
    }

    #[cfg(feature = "surface")]
    fn lowered_call(name: &str, args: Vec<Expr>, span: Span) -> Expr {
        Expr::synth_call(
            lowered_path(name, span),
            args.into_iter().map(CallArg::Value).collect(),
            span,
        )
        .with_fresh_occurrence()
    }

    #[cfg(feature = "surface")]
    fn rec_order_function_shell_expr(
        name: &str,
        value: Expr,
        body: Expr,
        runtime_ty: Type,
        span: Span,
        node: u64,
    ) -> Expr {
        let input_span = Span::new(span.start + 1, span.start + 2);
        Expr::RecOrder {
            occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
            plan: Box::new(crate::ast::RecOrderPlan {
                tail_continuation: None,
                name: name.to_owned(),
                disposition: crate::ast::RecOrderDisposition::Ordered(
                    crate::ast::RecOrderTypeFlow::ExpectedFromBody,
                ),
                annotation: Some(Type::synth_function(
                    vec![Type::Infer {
                        meta: Meta::new(input_span),
                        ext: (),
                    }],
                    runtime_ty.clone(),
                    span,
                )),
                value: Box::new(value),
                body: Box::new(body),
                runtime_ty,
            }),
            meta: Meta::new(span),
            ext: crate::ast::NodeId(node),
        }
    }

    #[cfg(feature = "surface")]
    fn identity_lambda(name: &str, ty: Option<Type>, span: Span) -> Expr {
        Expr::FnExpr {
            occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
            sig: crate::ast::Signature::new(vec![crate::ast::SignatureParam::Value(
                crate::ast::Param {
                    name: name.to_owned(),
                    ty,
                    pattern: (),
                    meta: Meta::new(span),
                },
            )]),
            ret_ty: Some(path_ty("I32")),
            body: Box::new(lowered_path(name, span)),
            meta: Meta::new(span),
            caps: (),
        }
    }

    #[cfg(feature = "surface")]
    fn constant_lambda(name: &str, body_name: &str, span: Span) -> Expr {
        Expr::FnExpr {
            occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
            sig: crate::ast::Signature::new(vec![crate::ast::SignatureParam::Value(
                crate::ast::Param {
                    name: name.to_owned(),
                    ty: None,
                    pattern: (),
                    meta: Meta::new(span),
                },
            )]),
            ret_ty: Some(path_ty("I32")),
            body: Box::new(lowered_path(body_name, span)),
            meta: Meta::new(span),
            caps: (),
        }
    }

    #[cfg(feature = "surface")]
    fn shared_use_function_shell() -> Expr {
        let direct = lowered_call(
            "continuation",
            vec![lowered_path("input", Span::new(121, 126))],
            Span::new(112, 127),
        );
        let bare = lowered_call(
            "consume_fn",
            vec![
                lowered_path("continuation", Span::new(135, 147)),
                lowered_path("input", Span::new(149, 154)),
            ],
            Span::new(130, 155),
        );
        let body = lowered_call("combine", vec![direct, bare], Span::new(110, 160));
        rec_order_function_shell_expr(
            "continuation",
            identity_lambda("continued", Some(path_ty("I32")), Span::new(170, 180)),
            body,
            path_ty("I32"),
            Span::new(100, 190),
            9401,
        )
    }

    #[cfg(feature = "surface")]
    fn resolved_lowered_test_package(source: &str) -> Package<Lowered> {
        let module = parse(source).expect("parse function-shell test module");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower function-shell test module");
        let package =
            Package::build(Path::new(""), modules, None).expect("build function-shell package");
        package
            .resolve_imports()
            .expect("resolve function-shell test package");
        crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0
    }

    #[cfg(feature = "surface")]
    #[test]
    fn rec_order_function_shell_shares_one_goal_across_direct_and_bare_uses() {
        let package = resolved_lowered_test_package(
            "module main;
             host type I32;
             host fn combine(left: I32, right: I32) -> I32;
             host fn consume_fn(function: I32 -> I32, value: I32) -> I32;",
        );
        let module = &package.module("main").expect("main module").module;
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("function-shell module environment");

        for checked in [false, true] {
            let carrier = shared_use_function_shell();
            let mut elaborations = Elaborations::new();
            let mut tcx = TypeCtx::new(&env, &mut elaborations);
            tcx.push_value("input".to_owned(), path_ty("I32"));
            reset_rec_order_function_shell_work();
            if checked {
                <crate::pass::typecheck_full::LoweredTyper as Typer<Lowered>>::check_value_against(
                    &carrier,
                    &path_ty("I32"),
                    &mut tcx,
                )
                .expect("check-mode function shell");
            } else {
                let synthesized =
                    <crate::pass::typecheck_full::LoweredTyper as Typer<Lowered>>::synth_expr(
                        &carrier, &mut tcx,
                    )
                    .expect("synth-mode function shell");
                assert!(matches!(
                    synthesized.ty.as_type(),
                    Type::Path { segments, .. }
                        if segments.last().is_some_and(|segment| segment.as_str() == "I32")
                ));
            }
            let work = rec_order_function_shell_work();
            assert_eq!(work.reserved_input_goals, 1);
            assert_eq!(work.interned_shells, 1);
            assert_eq!(work.box_allocations, 1);
            assert_eq!(work.body_advances, 1);
            assert_eq!(work.value_advances, 1);
            assert!(
                tcx.elaborations
                    .rec_order_runtime_for("main", &carrier)
                    .is_some(),
                "successful root close must publish the shared continuation binding"
            );
        }
    }

    #[cfg(feature = "surface")]
    #[test]
    fn recursive_quotation_closes_public_source_types_separately_from_runtime() {
        use crate::ast::{ExpressionOccurrence, NodeId, RecQuotePlan};
        for valid in [true, false] {
            let package = resolved_lowered_test_package(
                "module main;
                 host type Public;
                 host type Runtime;
                 host type Other;
                 host fn compute(k: Public -> Runtime) -> Runtime;
                 host fn done(value: Public) -> Runtime;
                 host fn id[A](value: A) -> A;
                 host fn wrong(value: Other) -> Public;
                 fn computation() { .(k: Public -> Runtime) -> Runtime { compute(k) } }
                 fn operand() { id(input) }",
            );
            let module = &package.module("main").unwrap().module;
            let env = super::super::ModuleEnv::build(module, None, None, Some(&package)).unwrap();
            let Item::FnDef(computation) = &module.items[module.items.len() - 2] else {
                unreachable!()
            };
            let Item::FnDef(operand) = module.items.last().unwrap() else {
                unreachable!()
            };
            let mut value = operand.body.clone();
            let Expr::Call { callee, args, .. } = &mut value else {
                unreachable!()
            };
            if !valid {
                let Expr::Path { segments, .. } = callee.as_mut() else {
                    unreachable!()
                };
                segments[0].name = "wrong".into();
            }
            let CallArg::Value(input) = &mut args[0] else {
                unreachable!()
            };
            *input = Expr::RecQuote {
                occurrence: ExpressionOccurrence::fresh(),
                plan: Box::new(RecQuotePlan::Operand {
                    public_ty: Some(path_ty("Public")),
                    runtime_ty: path_ty("Runtime"),
                    computation: Box::new(computation.body.clone()),
                }),
                meta: Meta::new(input.span()),
                ext: NodeId(9470),
            };
            let input_id = input.site().id;
            let value_id = value.site().id;
            let expansion = Expr::RecQuote {
                occurrence: ExpressionOccurrence::fresh(),
                plan: Box::new(RecQuotePlan::Expansion {
                    runtime_ty: path_ty("Runtime"),
                    continuation: Box::new(lowered_path("done", sp())),
                    value: Box::new(value),
                }),
                meta: Meta::new(sp()),
                ext: NodeId(9471),
            };
            let mut elaborations = Elaborations::new();
            let mut tcx = TypeCtx::new(&env, &mut elaborations);
            let result = run_general_ordinary_value(&expansion, None, &mut tcx);
            if !valid {
                assert!(
                    result.is_err(),
                    "the public source still rejects an incompatible consumer"
                );
                assert!(tcx.elaborations.rec_quote_source_type(input_id).is_none());
                assert!(tcx.elaborations.rec_quote_source_type(value_id).is_none());
                assert!(tcx.elaborations.rec_quote_expansion(value_id).is_none());
                continue;
            }
            let result = result.expect("retained quotation checking");
            super::super::require_type_equiv(
                result.ty.as_type(),
                &path_ty("Runtime"),
                sp(),
                &env.alias_ctx(),
            )
            .unwrap();
            let frozen = tcx
                .elaborations
                .rec_quote_expansion(value_id)
                .expect("closed expansion");
            assert_eq!(frozen.node_id, NodeId(9471));
            assert!(
                matches!(&frozen.continuation, Expr::Path { segments, .. } if segments[0].as_str() == "done")
            );
            for (closed, name) in [
                (&frozen.public_type, "Public"),
                (&frozen.runtime_type, "Runtime"),
            ] {
                super::super::require_type_equiv_state(
                    closed.as_type(),
                    &path_ty(name),
                    sp(),
                    &env.alias_ctx(),
                    closed.identity_is_canonical(),
                    false,
                )
                .unwrap();
            }
            for id in [input_id, value_id] {
                let captured = tcx
                    .elaborations
                    .rec_quote_source_type(id)
                    .expect("closed public source type");
                assert!(!type_contains_goal(captured.as_type()));
                super::super::require_type_equiv_state(
                    captured.as_type(),
                    &path_ty("Public"),
                    sp(),
                    &env.alias_ctx(),
                    captured.identity_is_canonical(),
                    false,
                )
                .unwrap();
            }
        }
    }

    #[cfg(feature = "surface")]
    #[test]
    fn recursive_quotation_keeps_known_public_context_without_inventing_unknown_input() {
        use crate::ast::{ExpressionOccurrence, NodeId, RecQuotePlan};
        let package = resolved_lowered_test_package(
            "module main; host type Public; host type Runtime;
             host fn done(value: Public) -> Runtime;
             host fn make[A]() -> A;
             fn operand() { make() }",
        );
        let module = &package.module("main").unwrap().module;
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package)).unwrap();
        let Item::FnDef(operand) = module.items.last().unwrap() else {
            unreachable!()
        };
        for (known, local_completion) in
            [(true, false), (false, false), (true, true), (false, true)]
        {
            let value = if local_completion {
                let computation = Expr::FnExpr {
                    occurrence: ExpressionOccurrence::fresh(),
                    sig: crate::ast::Signature::new(vec![crate::ast::SignatureParam::Value(
                        crate::ast::Param {
                            name: "local".into(),
                            ty: Some(Type::synth_function(
                                vec![Type::Infer {
                                    meta: Meta::new(sp()),
                                    ext: (),
                                }],
                                path_ty("Runtime"),
                                sp(),
                            )),
                            pattern: (),
                            meta: Meta::new(sp()),
                        },
                    )]),
                    ret_ty: Some(path_ty("Runtime")),
                    body: Box::new(lowered_call("local", vec![operand.body.clone()], sp())),
                    meta: Meta::new(sp()),
                    caps: (),
                };
                Expr::RecQuote {
                    occurrence: ExpressionOccurrence::fresh(),
                    plan: Box::new(RecQuotePlan::Operand {
                        public_ty: None,
                        runtime_ty: path_ty("Runtime"),
                        computation: Box::new(computation),
                    }),
                    meta: Meta::new(sp()),
                    ext: NodeId(9482),
                }
            } else {
                operand.body.clone()
            };
            let value_id = value.site().id;
            let expansion = Expr::RecQuote {
                occurrence: ExpressionOccurrence::fresh(),
                plan: Box::new(RecQuotePlan::Expansion {
                    runtime_ty: path_ty("Runtime"),
                    continuation: Box::new(lowered_path(if known { "done" } else { "k" }, sp())),
                    value: Box::new(value),
                }),
                meta: Meta::new(sp()),
                ext: NodeId(9480),
            };
            let source = if known {
                expansion
            } else {
                let mut callback = constant_lambda("ignored", "runtime", sp());
                let Expr::FnExpr { ret_ty, .. } = &mut callback else {
                    unreachable!()
                };
                *ret_ty = Some(path_ty("Runtime"));
                rec_order_function_shell_expr(
                    "k",
                    callback,
                    expansion,
                    path_ty("Runtime"),
                    Span::new(700, 710),
                    9481,
                )
            };
            let mut elaborations = Elaborations::new();
            let mut tcx = TypeCtx::new(&env, &mut elaborations);
            tcx.push_value("runtime".into(), path_ty("Runtime"));
            let result = run_general_ordinary_value(&source, None, &mut tcx);
            assert_eq!(
                result.is_ok(),
                known,
                "{}",
                result
                    .err()
                    .map(|error| error.diagnostic().message.clone())
                    .unwrap_or_default()
            );
            assert_eq!(
                tcx.elaborations.rec_quote_expansion(value_id).is_some(),
                known
            );
        }
    }

    #[cfg(feature = "surface")]
    #[test]
    fn recursive_quotation_source_capture_preserves_polymorphic_binders() {
        let package = resolved_lowered_test_package(
            "module main; fn operand() { .[A](value: A) -> A { value } }",
        );
        let module = &package.module("main").unwrap().module;
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package)).unwrap();
        let Item::FnDef(operand) = module.items.last().unwrap() else {
            unreachable!()
        };
        let mut ordinary_elaborations = Elaborations::new();
        let ordinary = run_general_ordinary_value(
            &operand.body,
            None,
            &mut TypeCtx::new(&env, &mut ordinary_elaborations),
        )
        .unwrap();
        let mut elaborations = Elaborations::new();
        elaborations.register_rec_quote_sources(&operand.body);
        let captured = run_general_ordinary_value(
            &operand.body,
            None,
            &mut TypeCtx::new(&env, &mut elaborations),
        )
        .unwrap();
        assert_eq!(ordinary.is_scheme, captured.is_scheme);
        assert_eq!(
            ordinary.inferred_type_arg_suffix,
            captured.inferred_type_arg_suffix
        );
        assert_eq!(ordinary.ty.as_type(), captured.ty.as_type());
        assert_eq!(
            ordinary.ty.identity_is_canonical(),
            captured.ty.identity_is_canonical()
        );
        assert!(
            elaborations
                .rec_quote_source_type(operand.body.site().id)
                .is_some()
        );
        let Expr::FnExpr { body, .. } = &operand.body else {
            unreachable!()
        };
        assert!(elaborations.rec_quote_source_type(body.site().id).is_some());
    }

    #[cfg(feature = "surface")]
    #[test]
    fn nested_rec_order_function_shells_keep_distinct_owner_local_goals() {
        let package = resolved_lowered_test_package(
            "module main;
             host type I32;
             host fn combine(left: I32, right: I32) -> I32;",
        );
        let module = &package.module("main").expect("main module").module;
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("nested function-shell module environment");
        let inner_body = lowered_call(
            "combine",
            vec![
                lowered_call(
                    "outer_continuation",
                    vec![lowered_path("input", Span::new(321, 326))],
                    Span::new(310, 327),
                ),
                lowered_call(
                    "inner_continuation",
                    vec![lowered_path("input", Span::new(341, 346))],
                    Span::new(330, 347),
                ),
            ],
            Span::new(305, 350),
        );
        let inner = rec_order_function_shell_expr(
            "inner_continuation",
            identity_lambda("inner_value", Some(path_ty("I32")), Span::new(360, 370)),
            inner_body,
            path_ty("I32"),
            Span::new(300, 380),
            9411,
        );
        let outer = rec_order_function_shell_expr(
            "outer_continuation",
            identity_lambda("outer_value", Some(path_ty("I32")), Span::new(390, 400)),
            inner,
            path_ty("I32"),
            Span::new(280, 410),
            9410,
        );
        let Expr::RecOrder {
            plan: outer_plan, ..
        } = &outer
        else {
            unreachable!()
        };
        let inner_ref = outer_plan.body.as_ref();
        assert!(matches!(inner_ref, Expr::RecOrder { .. }));
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations);
        tcx.push_value("input".to_owned(), path_ty("I32"));
        reset_rec_order_function_shell_work();
        <crate::pass::typecheck_full::LoweredTyper as Typer<Lowered>>::check_value_against(
            &outer,
            &path_ty("I32"),
            &mut tcx,
        )
        .expect("nested function shells must close in their lexical owners");
        let work = rec_order_function_shell_work();
        assert_eq!(work.reserved_input_goals, 2);
        assert_eq!(work.interned_shells, 2);
        assert_eq!(work.box_allocations, 2);
        assert_ne!(
            work.first_owner, work.second_owner,
            "each nested shell must reserve its input goal in its own expression owner"
        );
        assert!(work.first_owner.is_some() && work.second_owner.is_some());
        for carrier in [&outer, inner_ref] {
            assert!(
                tcx.elaborations
                    .rec_order_runtime_for("main", carrier)
                    .is_some(),
                "each nested carrier must publish only after its owner closes"
            );
        }
    }

    #[cfg(feature = "surface")]
    #[test]
    fn rec_order_function_shell_rejects_conflicting_sibling_inputs() {
        let package = resolved_lowered_test_package(
            "module main;
             host type I32;
             host type String;
             host fn combine(left: I32, right: I32) -> I32;",
        );
        let module = &package.module("main").expect("main module").module;
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("function-shell module environment");
        let first = lowered_call(
            "continuation",
            vec![lowered_path("integer", Span::new(121, 128))],
            Span::new(112, 129),
        );
        let second = lowered_call(
            "continuation",
            vec![lowered_path("string", Span::new(141, 147))],
            Span::new(132, 148),
        );
        let carrier = rec_order_function_shell_expr(
            "continuation",
            identity_lambda("continued", Some(path_ty("I32")), Span::new(170, 180)),
            lowered_call("combine", vec![first, second], Span::new(110, 160)),
            path_ty("I32"),
            Span::new(100, 190),
            9402,
        );
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations);
        tcx.push_value("integer".to_owned(), path_ty("I32"));
        tcx.push_value("string".to_owned(), path_ty("String"));
        reset_rec_order_function_shell_work();
        <crate::pass::typecheck_full::LoweredTyper as Typer<Lowered>>::check_value_against(
            &carrier,
            &path_ty("I32"),
            &mut tcx,
        )
        .expect_err("one shared input goal must reject conflicting sibling uses");
        let work = rec_order_function_shell_work();
        assert_eq!(work.reserved_input_goals, 1);
        assert_eq!(work.interned_shells, 1);
        assert_eq!(work.box_allocations, 1);
        assert!(
            tcx.elaborations
                .rec_order_runtime_for("main", &carrier)
                .is_none(),
            "a conflicting sibling must not publish the carrier"
        );
    }

