    #[cfg(feature = "surface")]
    #[test]
    fn goal_call_substitution_retains_canonical_argument_identity() {
        let source = parse(
            "module source;
             pub newtype Actual : . { constructor actual; projector un_actual; };",
        )
        .expect("parse source module");
        let other = parse(
            "module other;
             pub newtype Actual : . { constructor actual; projector un_actual; };",
        )
        .expect("parse colliding module");
        let main = parse(
            "module main;
             import source as real;
             import other as source;
             newtype Local : . { constructor local; projector un_local; };",
        )
        .expect("parse consumer module");
        let (modules, _) = FullPipeline::lower_package(
            vec![
                (PathBuf::from("source.kio"), source),
                (PathBuf::from("other.kio"), other),
                (PathBuf::from("main.kio"), main),
            ],
            None,
        )
        .expect("lower canonical substitution package");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let module = &package.module("main").expect("main module").module;
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("module environment");
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations);
        tcx.push_type_param("Outer", sp());

        let canonical_argument = Type::synth_path(
            vec!["real".to_owned(), "Actual".to_owned()],
            Vec::new(),
            sp(),
        );
        let ambient_compound_argument = Type::Product {
            left: Box::new(path_ty("Outer")),
            right: Box::new(unit_ty()),
            meta: Meta::new(sp()),
        };
        let binder_a = crate::ast::TypeParam {
            name: "A".to_owned(),
            span: sp(),
            kind: None,
        };
        let binder_b = crate::ast::TypeParam {
            name: "B".to_owned(),
            span: sp(),
            kind: None,
        };
        let mut store = GoalStore::new();
        let owner = store
            .begin_owner(
                None,
                store.scope_from_type_ctx(&tcx),
                GoalOwnerKind::Application,
                sp(),
            )
            .expect("open canonical substitution owner");
        let call = OpenGoalCall::begin(
            GoalCallShape {
                binders: vec![binder_a, binder_b],
                param: SemanticValueDomain::known(InternedType::fresh(Type::Product {
                    left: Box::new(path_ty("Local")),
                    right: Box::new(Type::Product {
                        left: Box::new(path_ty("A")),
                        right: Box::new(path_ty("B")),
                        meta: Meta::new(sp()),
                    }),
                    meta: Meta::new(sp()),
                })),
                ret: Type::Product {
                    left: Box::new(path_ty("A")),
                    right: Box::new(path_ty("B")),
                    meta: Meta::new(sp()),
                },
                result_requirement_source: None,
                abi_arity: 1,
                has_value_layer: true,
                type_args: vec![
                    CallArgRef::Type(&canonical_argument),
                    CallArgRef::Type(&ambient_compound_argument),
                ],
                value_args: Vec::new(),
                explicit_prefix: 2,
                identity_canonical: false,
                result_is_pre_residual: false,
            },
            owner,
            sp(),
            fresh_site(sp()),
            &mut store,
            &tcx,
        )
        .expect("open explicitly instantiated call");

        assert!(
            call.replacements
                .get(owner, "A")
                .expect("A replacement")
                .identity_is_canonical(),
            "the imported caller nominal must be canonical before substitution"
        );
        assert!(
            call.replacements
                .get(owner, "B")
                .expect("B replacement")
                .identity_is_canonical(),
            "a compound caller type with a protected ambient binder is wholly canonical"
        );
        assert!(
            call.remaining_param.solver.identity_is_canonical(),
            "the canonical caller argument must not be downgraded by its raw callee template"
        );
        assert_eq!(
            display_type(call.remaining_param.solver.as_type()),
            "(main.Local & (source.Actual & (Outer & .)))"
        );
        let result = call.result_type(owner);
        assert!(
            result.identity_is_canonical(),
            "the canonical caller argument must retain exact identity in the result"
        );
        assert_eq!(
            display_type(result.as_type()),
            "(source.Actual & (Outer & .))"
        );
    }

    #[cfg(feature = "surface")]
    #[test]
    fn ordinary_value_cursor_completion_consumes_the_cursor() {
        let module = parse("module main;").expect("parse");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower Kio");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        let module = &package.module("main").expect("main module").module;
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("module environment");
        let source = Expr::Unit {
            occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
            meta: Meta::new(sp()),
        };
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations);
        let first = PreparedOrdinaryValue::path_or_unit(&source, &mut tcx)
            .expect("prepare Unit premise")
            .expect("Unit is a selected ordinary premise");
        let mut store = GoalStore::new();
        let owner = store
            .begin_owner(
                None,
                store.scope_from_type_ctx(&tcx),
                GoalOwnerKind::Application,
                sp(),
            )
            .expect("open cursor owner");
        let mut delta = store.begin_delta(owner, sp()).expect("open cursor delta");
        let mut publication = PublicationBuilder::new(&store, &delta);
        let expected = OwnerBoundType::Plain(tcx.intern_type(&unit_ty()));
        let cursor = OrdinaryValueCursor::new(&source, expected);
        let mut context = SimpleGoalLeafContext {
            equation_owner: owner,
            publication_owner: owner,
            store: &store,
            delta: &mut delta,
            publication: &mut publication,
        };

        let advanced = cursor
            .advance_selected_path_unit(
                frontier::FrontierMode::Final,
                first,
                &mut context,
                &mut tcx,
            )
            .expect("advance Unit premise once");
        assert!(matches!(
            advanced,
            OrdinaryValueAdvance::Complete(CompletedInFrame::Value(_, _))
        ));
    }

    #[cfg(feature = "surface")]
    #[test]
    fn general_ordinary_root_composes_recursive_value_families() {
        let module = parse(
            "module main;
             import control(if);
             host type Bool role(bool);
             host type I32;
             fn id[T](value: T) -> T { value }
             fn choose(flag: Bool, value: I32) -> I32 {
               let kept = value;
               ();
               if! flag { id(kept) } else { kept }
             }",
        )
        .expect("parse general ordinary-root witness");
        let control = parse(include_str!(
            "../../../../test-data/poc/elab/workdir/control.kio"
        ))
        .expect("parse ordinary conditional provider");
        let (modules, _) = FullPipeline::lower_package(
            vec![
                (PathBuf::from("main.kio"), module),
                (PathBuf::from("control.kio"), control),
            ],
            None,
        )
        .expect("lower general ordinary-root witness");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        package.resolve_imports().expect("resolve imports");
        let normalized = crate::pass::alpha_normalize::normalize_package(&package);
        let package = normalized.package();
        let scope = super::super::PackageTypecheckScope::fresh_for_normalized_package(
            &normalized,
            std::sync::Arc::new(super::super::TypeInterner::default()),
        );
        let module = &package.module("main").expect("main module").module;
        let (item_index, def) = module
            .items
            .iter()
            .enumerate()
            .find_map(|(index, item)| match item {
                Item::FnDef(def) if def.name == "choose" => Some((index, def)),
                _ => None,
            })
            .expect("choose witness function");
        let env = super::super::ModuleEnv::build_with_typecheck_scope(
            module,
            None,
            None,
            Some(package),
            scope,
        )
        .expect("module environment");
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
        for param in def.sig.value_params() {
            tcx.push_value(
                param.name.clone(),
                param.ty.clone().expect("witness parameter annotation"),
            );
        }
        let expected = InternedType::fresh(def.ret.clone());
        let actual = run_general_ordinary_value(&def.body, Some(&expected), &mut tcx)
            .expect("general ordinary root should compose Let, Seq, UserElaborator, and Call");
        crate::pass::typecheck_core::require_type_equiv_state(
            actual.ty.as_type(),
            expected.as_type(),
            def.body.span(),
            &tcx.env.alias_ctx(),
            actual.ty.identity_is_canonical(),
            expected.identity_is_canonical(),
        )
        .expect("general ordinary-root result type");
    }

    #[cfg(feature = "surface")]
    #[test]
    fn general_ordinary_root_uses_a_later_path_solution_before_literal_fallback() {
        let module = parse(
            "module main;
             host type First role(i32);
             host type Second role(i32);
             fn same[T](_first: T, second: T) -> T { second }
             fn witness(selected: Second) -> Second { same(42, selected) }",
        )
        .expect("parse expected-type literal witness");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower expected-type literal witness");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let module = &package.module("main").expect("main module").module;
        let (item_index, def) = module
            .items
            .iter()
            .enumerate()
            .find_map(|(index, item)| match item {
                Item::FnDef(def) if def.name == "witness" => Some((index, def)),
                _ => None,
            })
            .expect("witness function");
        let Expr::Call { args, .. } = &def.body else {
            panic!("witness body should be one ordinary call")
        };
        let [CallArg::Value(literal), CallArg::Value(_selected)] = args.as_slice() else {
            panic!("witness call should contain one literal and one path")
        };
        let literal_span = literal.site();

        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("module environment");
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
        for param in def.sig.value_params() {
            tcx.push_value(
                param.name.clone(),
                param.ty.clone().expect("witness parameter annotation"),
            );
        }
        let applied = run_general_ordinary_value(&def.body, None, &mut tcx)
            .expect("advance expected-type literal through the unified ordinary root");

        assert!(matches!(
            applied.ty.as_type(),
            Type::Path { segments, args, .. }
                if segments.last().is_some_and(|segment| segment.as_str() == "Second")
                    && args.is_empty()
        ));
        let resolved = tcx
            .elaborations
            .literal_resolution_for("main", literal_span.id)
            .expect("the accepted literal must publish its exact expected type");
        assert!(matches!(
            &resolved.resolved,
            Type::Path { segments, args, .. }
                if segments.last().is_some_and(|segment| segment.as_str() == "Second")
                    && args.is_empty()
        ));
    }

