    #[cfg(feature = "surface")]
    fn completion_control_provider() -> String {
        let provider = r#"module mechanisms;
            import __comptime__;
            pure fn invoke(ct: __Comptime__, thunk: __Checked_term__) -> __Checked_term__ {
                __term_call__(ct, __term_type__(ct, thunk), thunk, __term_unit__(ct))
            }
            pure fn choose_checked(
                ct: __Comptime__, fills: __Fill_ctx__, _condition_type: __Type__,
                result_type: __Type__, condition: __Checked_term__,
                on_true: __Checked_term__, on_false: __Checked_term__
            ) -> __Checked_term__ & __Fill_ctx__ {
                let true_result = invoke(ct, on_true);
                let false_result = invoke(ct, on_false);
                let with_true = __fill__(ct, fills, result_type, __term_type__(ct, true_result));
                let with_false = __fill__(ct, with_true, result_type, __term_type__(ct, false_result));
                (__intrinsic_if_then_else__(ct, result_type, condition,
                    .() -> __Checked_term__ { true_result },
                    .() -> __Checked_term__ { false_result }), with_false)
            }
            pub elab choose_lazy : [Condition][Result]
                Condition -> (. -> Result) -> (. -> Result) -> Result {
                impl(fills) choose_checked
            }
            pure fn enter_checked(ct: __Comptime__, fills: __Fill_ctx__,
                _result: __Type__, body: __Checked_term__)
                -> __Checked_term__ & __Fill_ctx__ { (invoke(ct, body), fills) }
            pub elab enter_now : [Result](. -> Result) -> Result { impl(fills) enter_checked }
            pure fn unit_checked(ct: __Comptime__, _result: __Type__ | .) -> __Checked_term__ {
                __term_unit__(ct)
            }"#;
        format!("{provider} pub elab infer_unit : [A]. -> A {{ impl unit_checked }}")
    }

    #[cfg(feature = "surface")]
    #[test]
    fn completion_wait_depth_and_width_cost() {
        eprintln!(
            "completion storage bytes: wait={}, retained_wait={}, cursor={}, child={}, driver_frame={}",
            std::mem::size_of::<super::super::goals::CompletionWait>(),
            std::mem::size_of::<RetainedCompletionWait>(),
            std::mem::size_of::<OrdinaryValueCursor<'static>>(),
            std::mem::size_of::<OrdinaryChildContinuation<'static>>(),
            std::mem::size_of::<OrdinaryDriverFrame<'static>>()
        );
        let provider = completion_control_provider();
        let mut cases = Vec::new();
        for depth in [1, 4, 16] {
            let mut nested = "supply()".to_owned();
            for _ in 0..depth {
                nested = format!("enter_now!(.() {{ {nested} }})");
            }
            cases.push((format!("marked-depth-{depth}"), format!(
                "fn result() -> . {{ let chosen = choose_lazy!(.t, .() {{ {nested} }}, .() {{ infer_unit!() }}); chosen }}"
            ), depth + 2, depth + 2, true));
        }
        for width in [4, 16, 64] {
            let parameters = (0..width)
                .map(|i| format!("_f{i}: . -> A"))
                .collect::<Vec<_>>()
                .join(", ");
            for waiting in [false, true] {
                let callback = if waiting {
                    ".() { supply() }"
                } else {
                    ".() { () }"
                };
                let callbacks = vec![callback; width].join(", ");
                let last = if waiting { "infer_unit!()" } else { "()" };
                cases.push((format!("width-{width}-wait-{waiting}"), format!(
                    "fn consume[A]({parameters}, _last: A) -> . {{ () }} fn result() -> . {{ consume({callbacks}, {last}) }}"
                ), width, usize::from(waiting), waiting));
            }
        }
        for (label, declarations, bodies, actions, waiting) in cases {
            let main = format!(
                "module main; import mechanisms(choose_lazy, enter_now, infer_unit); host type Flag role(bool); host fn supply[A]() -> A; {declarations}"
            );
            let (modules, _) = FullPipeline::lower_package(
                vec![
                    (
                        PathBuf::from("mechanisms.kio"),
                        parse(&provider).expect("provider"),
                    ),
                    (PathBuf::from("main.kio"), parse(&main).expect("consumer")),
                ],
                None,
            )
            .expect("lower cost control");
            let package = Package::build(Path::new(""), modules, None).expect("package");
            package.resolve_imports().expect("imports");
            let normalized = crate::pass::alpha_normalize::normalize_package(&package);
            let scope = super::super::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                std::sync::Arc::new(super::super::TypeInterner::default()),
            );
            let mut elaborations = Elaborations::new();
            reset_lambda_body_entries("main");
            reset_lambda_owner_work();
            record_completion_work(|work| *work = CompletionWork::default());
            let start = std::time::Instant::now();
            super::super::check_package_modules_with_typecheck_scope_collect_errors_with_execution(
                normalized.package(),
                &mut elaborations,
                scope.clone(),
                super::super::TypecheckExecution::Sequential,
            )
            .expect("bounded completion control");
            let elapsed = start.elapsed();
            let entries = take_lambda_body_entries();
            assert_eq!(entries.len(), bodies, "{label} source bodies");
            for (i, entry) in entries.iter().enumerate() {
                assert!(
                    entries[..i].iter().all(|other| other.span != entry.span),
                    "{label} replay"
                );
            }
            assert_eq!(
                scope.memo().user_elaborator_template_executions(),
                actions,
                "{label} actions"
            );
            let work = COMPLETION_WORK.with(|work| *work.borrow());
            assert_eq!(work.live, 0);
            assert_eq!(work.source_records_live, 0);
            assert_eq!(work.created > 0, waiting, "{label} wait path");
            if !waiting {
                assert_eq!(work.visitor_calls, 0, "{label} no-wait visitor");
            }
            eprintln!(
                "{label}: elapsed={elapsed:?}; bodies={bodies}; actions={actions}; owners={:?}; {work:?}",
                lambda_owner_work()
            );
            crate::pass::typecheck_full::validate_substituted_package(
                crate::pass::substitute::substitute_normalized_package(normalized, &elaborations),
            )
            .expect("cost control independently validates as Prime");
        }
    }

    #[cfg(feature = "surface")]
    #[test]
    fn marked_lambda_completion_waits_for_a_later_shared_result() {
        let provider = completion_control_provider();
        let mut owner_work = Vec::new();
        for (left, right, bodies, actions) in [
            ("supply()", "()", 2, 1),
            ("()", "supply()", 2, 1),
            ("supply()", "infer_unit!()", 2, 2),
            ("infer_unit!()", "supply()", 2, 2),
            ("enter_now!(.() { supply() })", "infer_unit!()", 3, 3),
            ("infer_unit!()", "enter_now!(.() { supply() })", 3, 3),
        ] {
            let main = format!(
                "module main; import mechanisms(choose_lazy, enter_now, infer_unit); \
                 host type Caller_flag role(bool); host fn supply[A]() -> A; \
                 fn result() -> . {{ \
                   let chosen = choose_lazy!(.t, .() {{ {left} }}, .() {{ {right} }}); \
                   chosen \
                 }}"
            );
            let (modules, _) = FullPipeline::lower_package(
                vec![
                    (
                        PathBuf::from("mechanisms.kio"),
                        parse(&provider).expect("provider"),
                    ),
                    (PathBuf::from("main.kio"), parse(&main).expect("consumer")),
                ],
                None,
            )
            .expect("lower shared-result package");
            let package = Package::build(Path::new(""), modules, None).expect("package");
            package.resolve_imports().expect("resolve imports");
            let normalized = crate::pass::alpha_normalize::normalize_package(&package);
            let scope = super::super::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                std::sync::Arc::new(super::super::TypeInterner::default()),
            );
            let mut elaborations = Elaborations::new();
            reset_lambda_body_entries("main");
            reset_lambda_owner_work();
            record_completion_work(|work| *work = CompletionWork::default());
            super::super::check_package_modules_with_typecheck_scope_collect_errors_with_execution(
                normalized.package(),
                &mut elaborations,
                scope.clone(),
                super::super::TypecheckExecution::Sequential,
            )
            .expect("either branch may establish the shared result");
            let entries = take_lambda_body_entries();
            assert_eq!(entries.len(), bodies, "each authored body is checked once");
            for (index, entry) in entries.iter().enumerate() {
                assert!(
                    entries[..index]
                        .iter()
                        .all(|prior| prior.span != entry.span)
                );
            }
            assert_eq!(scope.memo().user_elaborator_template_executions(), actions);
            owner_work.push(lambda_owner_work());
            eprintln!(
                "shared-result {left}/{right}: entries={entries:?}, owners={:?}",
                owner_work.last()
            );
            COMPLETION_WORK.with(|work| {
                let work = work.borrow();
                assert_eq!(work.live, 0, "completed derivations release every wait");
                assert!(
                    work.resumed <= work.created,
                    "these witnesses resolve each wait once"
                );
                eprintln!("completion work: {work:?}");
            });
            crate::pass::typecheck_full::validate_substituted_package(
                crate::pass::substitute::substitute_normalized_package(normalized, &elaborations),
            )
            .expect("shared result survives independent Prime typing");
        }
        for pair in owner_work.chunks_exact(2) {
            assert_eq!(pair[0], pair[1], "pending completion reserves no new owner");
        }
    }

    #[cfg(feature = "surface")]
    #[test]
    fn selecting_call_waits_for_a_later_lambda_to_pin_the_shared_slot() {
        let module = parse(
            "module main;
             host type Witness;
             host fn make[A]() -> A;
             fn consume[T](_left: T, _right: T) -> . { () }
             fn witness() -> . {
               consume(
                 .(item: Witness) { make() },
                 .(item: Witness) { item },
               )
             }",
        )
        .expect("parse shared lambda-slot witness");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower shared lambda-slot witness");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        FullPipeline::typecheck(&package)
            .expect("the established pipeline accepts the shared lambda-slot witness");
        let module = &package.module("main").expect("main module").module;
        let (item_index, def) = module
            .items
            .iter()
            .enumerate()
            .find_map(|(index, item)| match item {
                Item::FnDef(def) if def.name == "witness" => Some((index, def)),
                _ => None,
            })
            .expect("shared lambda-slot witness function");
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("module environment");
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);

        assert!(matches!(
            OrdinaryValueCursor::seed(&def.body, &mut tcx)
                .expect("seed shared lambda-slot witness"),
            OrdinaryValueSeed::DirectSelecting { .. }
        ));
        let expected = InternedType::fresh(def.ret.clone());
        let actual = run_general_ordinary_value(&def.body, Some(&expected), &mut tcx)
            .expect("the later lambda should pin the shared slot before the first body checks");
        crate::pass::typecheck_core::require_type_equiv_state(
            actual.ty.as_type(),
            expected.as_type(),
            def.body.span(),
            &tcx.env.alias_ctx(),
            actual.ty.identity_is_canonical(),
            expected.identity_is_canonical(),
        )
        .expect("shared lambda-slot result type");
    }

