    #[cfg(feature = "surface")]
    #[test]
    fn declined_immediate_lambda_transfers_the_exact_plan_without_goal_precommit() {
        let module = parse(
            "module main;
             host type I32;
             fn witness() -> [B] I32 -> I32 {
               .[A][B](value: _) { value }(I32)
             }",
        )
        .expect("parse exact-plan decline witness");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower exact-plan decline witness");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let module = &package.module("main").expect("main module").module;
        let (item_index, def) = module
            .items
            .iter()
            .enumerate()
            .find_map(|(index, item)| match item {
                Item::FnDef(def) if def.name == "witness" => Some((index, def)),
                _ => None,
            })
            .expect("exact-plan decline witness function");
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("module environment");
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);

        super::super::annotation_plan::reset_annotation_plan_work();
        let seed = OrdinaryValueCursor::seed(&def.body, &mut tcx)
            .expect("the inline lambda call has a pure source plan");
        assert!(matches!(
            &seed,
            OrdinaryValueSeed::ImmediateLambdaCall { .. }
        ));
        let source_plan_work = super::super::annotation_plan::annotation_plan_work();
        assert_eq!(source_plan_work.classifications, 1);
        assert_eq!(source_plan_work.transport_materializations, 1);
        assert_eq!(source_plan_work.rejections, 0);
        assert_eq!(source_plan_work.committed_materializations, 0);
        assert_eq!(source_plan_work.goals_allocated, 0);
        assert_eq!(source_plan_work.binder_events_published, 0);

        let mut store = GoalStore::new();
        let owner = store
            .begin_owner(
                None,
                store.scope_from_type_ctx(&tcx),
                GoalOwnerKind::Application,
                def.body.span(),
            )
            .expect("open outer call owner");
        let before = store.planning_state_fingerprint();
        let planned = OrdinaryValueCursor::plan(&def.body, seed, &mut store, owner, &tcx)
            .expect("the partial type-only packet must decline to computed application");
        assert!(matches!(
            planned,
            PlannedOrdinaryValue::ComputedCall(ComputedCallContinuation::PlannedLambda(_))
        ));
        assert_eq!(
            store.planning_state_fingerprint(),
            before,
            "decline must not reserve or activate an inference goal",
        );
        assert_eq!(
            super::super::annotation_plan::annotation_plan_work(),
            source_plan_work,
            "the computed route must consume the exact source plan rather than classify again",
        );
    }

    #[cfg(all(feature = "surface", feature = "prime", feature = "parallel"))]
    #[test]
    fn ordinary_retained_and_expected_lambda_policies_consume_the_shared_plan() {
        fn package(source: &str) -> Package<crate::ast::Lowered> {
            let module = parse(source).expect("parse annotation-plan policy witness");
            let (modules, _) =
                FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                    .expect("lower annotation-plan policy witness");
            let package = Package::build(Path::new(""), modules, None)
                .expect("build annotation-plan policy witness");
            package.resolve_imports().expect("resolve imports");
            crate::pass::alpha_normalize::normalize_package(&package)
                .into_parts()
                .0
        }

        let retained = package(
            "module main; \
             fn witness() -> . -> . { .(value: .) -> . { value } }",
        );
        let module = &retained.module("main").expect("main module").module;
        let (item_index, def) = module
            .items
            .iter()
            .enumerate()
            .find_map(|(index, item)| match item {
                Item::FnDef(def) if def.name == "witness" => Some((index, def)),
                _ => None,
            })
            .expect("ordinary retained witness");
        let env = super::super::ModuleEnv::build(module, None, None, Some(&retained))
            .expect("module environment");
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
        super::super::annotation_plan::reset_annotation_plan_consumer_work();
        let expected = InternedType::fresh(def.ret.clone());
        OrdinaryValueCursor::run_root(&def.body, Some(&expected), &mut tcx)
            .expect("ordinary retained lambda policy");
        let retained_work = super::super::annotation_plan::annotation_plan_consumer_work();
        assert_eq!(retained_work.ordinary_retained, 1);
        assert_eq!(retained_work.expected_lambda, 0);

        let expected_lambda = parse(
            "module main; \
             fn consume[T](_function: T -> T) -> . { () } \
             fn witness() -> . { consume(., .(value) { value }) }",
        )
        .expect("parse standalone Prime expected-lambda witness");
        let (expected_lambda, _) = crate::prime::pipeline::PrimePipeline::lower_package(
            vec![(PathBuf::from("main.kio"), expected_lambda)],
            None,
        )
        .expect("lower standalone Prime expected-lambda witness");
        let expected_lambda =
            Package::<crate::ast::Prime>::build(Path::new(""), expected_lambda, None)
                .expect("build standalone Prime expected-lambda witness");
        expected_lambda
            .resolve_imports()
            .expect("resolve standalone Prime expected-lambda witness");
        let pool = rayon::ThreadPoolBuilder::new()
            .num_threads(1)
            .build()
            .expect("single-thread expected-lambda observation pool");
        let expected_work = pool.install(|| {
            super::super::annotation_plan::reset_annotation_plan_consumer_work();
            crate::prime::pipeline::PrimePipeline::typecheck(&expected_lambda)
                .expect("expected-lambda policy");
            super::super::annotation_plan::annotation_plan_consumer_work()
        });
        assert_eq!(expected_work.ordinary_retained, 0);
        assert_eq!(expected_work.expected_lambda, 1);
    }

