    #[cfg(feature = "surface")]
    #[test]
    fn general_ordinary_root_selects_flat_call_layers_from_retained_values() {
        let module = parse(
            "module main;
             host type Second role(i32);
             host type String;
             fn make_pair(left: Second, right: Second) -> Second & Second { (left, right) }
             fn layered[T](first: T, second: T)(tail: String) -> T { first }
             fn scalar(left: Second, right: Second, tail: String) -> Second {
               layered(left, right, tail)
             }
             fn packed(left: Second, right: Second, tail: String) -> Second {
               layered(make_pair(left, right))(tail)
             }
             fn staged()(tail: Second) -> Second { tail }
             fn explicit_zero(tail: Second) -> Second { staged()(tail) }
             fn implicit_zero(tail: Second) -> Second { staged(tail) }",
        )
        .expect("parse retained flat-layer witnesses");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower retained flat-layer witnesses");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let module = &package.module("main").expect("main module").module;
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("module environment");
        let find = |name: &str| {
            module
                .items
                .iter()
                .enumerate()
                .find_map(|(index, item)| match item {
                    Item::FnDef(def) if def.name == name => Some((index, def)),
                    _ => None,
                })
                .unwrap_or_else(|| panic!("missing `{name}` witness"))
        };

        for (name, expected_split) in [
            ("scalar", Some(3usize)),
            ("packed", None),
            ("explicit_zero", None),
        ] {
            let (item_index, def) = find(name);
            let mut elaborations = Elaborations::new();
            let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
            for param in def.sig.value_params() {
                tcx.push_value(
                    param.name.clone(),
                    param.ty.clone().expect("witness parameter annotation"),
                );
            }
            let expected = InternedType::fresh(def.ret.clone());
            let actual = run_general_ordinary_value(&def.body, Some(&expected), &mut tcx)
                .unwrap_or_else(|error| panic!("type `{name}` through general root: {error:?}"));
            crate::pass::typecheck_core::require_type_equiv_state(
                actual.ty.as_type(),
                expected.as_type(),
                def.body.span(),
                &tcx.env.alias_ctx(),
                actual.ty.identity_is_canonical(),
                expected.identity_is_canonical(),
            )
            .unwrap_or_else(|error| panic!("result type for `{name}`: {error:?}"));
            assert_eq!(
                tcx.elaborations
                    .call_splits_for("main", def.body.site().id)
                    .and_then(|splits| splits.first())
                    .copied(),
                expected_split,
                "`{name}` selected the wrong first-layer boundary"
            );
        }

        let (item_index, def) = find("implicit_zero");
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
        for param in def.sig.value_params() {
            tcx.push_value(
                param.name.clone(),
                param.ty.clone().expect("witness parameter annotation"),
            );
        }
        let expected = InternedType::fresh(def.ret.clone());
        let error = match run_general_ordinary_value(&def.body, Some(&expected), &mut tcx) {
            Ok(_) => panic!("a flat call must not skip a zero-value function layer"),
            Err(error) => error,
        };
        assert!(
            error.diagnostic().message.contains("type mismatch")
                && error.diagnostic().message.contains("expected `.`")
                && error.diagnostic().message.contains("found `Second`"),
            "unexpected zero-layer diagnostic: {}",
            error.diagnostic().message
        );
    }

    #[cfg(feature = "surface")]
    #[test]
    fn later_sibling_closes_an_expected_dependent_result() {
        let module = parse(
            "module main;
             host type I32;
             host type Marker;
             host fn make_wrapped[A]() -> A & Marker;
             fn same[T](_left: T, _right: T) -> . { () }
             fn witness(later: I32 & Marker) -> . { same(make_wrapped(), later) }",
        )
        .expect("parse deferred-result retry witness");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower deferred-result retry witness");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let module = &package.module("main").expect("main module").module;
        let (item_index, def) = module
            .items
            .iter()
            .enumerate()
            .find_map(|(index, item)| match item {
                Item::FnDef(def) if def.name == "witness" => Some((index, def)),
                _ => None,
            })
            .expect("deferred-result retry witness function");
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("module environment");
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
        for param in def.sig.value_params() {
            tcx.push_value(
                param.name.clone(),
                param.ty.clone().expect("witness parameter annotation"),
            );
        }

        let actual = run_general_ordinary_value(&def.body, None, &mut tcx)
            .expect("the later sibling should close the deferred result equation");
        assert!(matches!(actual.ty.as_type(), crate::ast::Type::Unit { .. }));
    }

