    #[cfg(feature = "surface")]
    #[test]
    fn deferred_result_equation_is_not_replayed_across_pending_child_modes() {
        let module = parse(
            "module main;
             host type I32 role(i32);
             fn literal() -> I32 { 0 }",
        )
        .expect("parse scheduler-state witness");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower scheduler-state witness");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let module = &package.module("main").expect("main module").module;
        let source = module
            .items
            .iter()
            .find_map(|item| match item {
                Item::FnDef(def) if def.name == "literal" => Some(&def.body),
                _ => None,
            })
            .expect("literal witness function");
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("module environment");
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations);
        let goal_type = |goal| Type::Goal {
            goal,
            args: Vec::new(),
            meta: Meta::new(sp()),
            ext: (),
        };

        let (mut frontier, expected_goal) =
            frontier::OrdinaryFrontier::begin_root_with(sp(), &tcx, |store, owner| {
                store.alloc_goal(
                    owner,
                    crate::ast::Kind::Star,
                    GoalSolutionPolicy::Monotype,
                    GoalOrigin::named(sp(), GoalRole::TypeArgument, "T"),
                )
            })
            .expect("open scheduler root");
        let root = frontier.owner();
        let expected_at_root = frontier
            .store()
            .scoped_goal_at(expected_goal, Vec::new(), root, sp())
            .expect("scope ancestor expectation");
        let (reservation, (result_goal, call)) = frontier
            .reserve_root_child_with(GoalOwnerKind::RetainedValue, sp(), &tcx, |store, owner| {
                let result_goal = store.alloc_goal(
                    owner,
                    crate::ast::Kind::Star,
                    GoalSolutionPolicy::Monotype,
                    GoalOrigin::named(sp(), GoalRole::TypeArgument, "T"),
                )?;
                let call = OpenGoalCall::begin(
                    GoalCallShape {
                        binders: Vec::new(),
                        param: SemanticValueDomain::known(InternedType::fresh(unit_ty())),
                        ret: unit_ty(),
                        result_requirement_source: None,
                        abi_arity: 0,
                        has_value_layer: true,
                        type_args: Vec::new(),
                        value_args: Vec::new(),
                        explicit_prefix: 0,
                        identity_canonical: true,
                        result_is_pre_residual: false,
                    },
                    owner,
                    sp(),
                    fresh_site(sp()),
                    store,
                    &tcx,
                )?;
                Ok((result_goal, call))
            })
            .expect("reserve expected-dependent call owner");
        let mut call_child = frontier
            .open_reserved_child(reservation)
            .expect("open expected-dependent call owner");
        let call_owner = call_child.owner();
        let publication_span = fresh_site(Span::new(10, 11));
        call_child
            .publication_mut()
            .mark_value_at_type_slot(publication_span, 0);
        assert!(
            !tcx.elaborations
                .is_value_at_type_slot("main", publication_span.id, 0)
        );
        let result = frontier
            .store()
            .scoped_type(
                call_owner,
                InternedType::fresh_canonical(Type::Product {
                    left: Box::new(goal_type(result_goal)),
                    right: Box::new(unit_ty()),
                    meta: Meta::new(sp()),
                }),
                sp(),
            )
            .expect("scope expected-dependent result");
        let result_occurrence = frontier
            .store()
            .scoped_goal_at(result_goal, Vec::new(), call_owner, sp())
            .expect("scope result goal in its owner");
        let seed = OrdinaryValueCursor::seed(source, &mut tcx).expect("seed literal child");

        let expected_for_call = OwnerBoundType::Retained {
            owner: root,
            ty: expected_at_root.clone(),
        };
        let advancing = {
            let mut call_frontier = frontier.retained_value_frontier(&mut call_child);
            let (child_reservation, planned) = call_frontier
                .reserve_ordinary_child_with(sp(), &tcx, |store, owner| {
                    OrdinaryValueCursor::plan(source, seed, store, owner, &tcx)
                })
                .expect("reserve result-solving child");
            let cursor = OrdinaryValueCursor::bind(
                source,
                OwnerBoundType::Retained {
                    owner: call_owner,
                    ty: result_occurrence,
                },
                planned,
            );
            let child = call_frontier
                .open_ordinary_child(child_reservation)
                .expect("open result-solving child");
            let advancing = AdvancingOrdinaryCall {
                call,
                result,
                result_inferred_type_arg_suffix: 0,
                destination: call_owner,
                pending: vec![PendingOrdinaryCallChild {
                    child: OrdinaryChildContinuation {
                        child,
                        cursor: Box::new(cursor),
                        next_mode: frontier::FrontierMode::ExpectedOnly,
                        suspension: OrdinarySuspension::Mode,
                    },
                    role: PendingOrdinaryChildRole::Value,
                }],
                pending_expected_result: Some(PendingExpectedResult::new(
                    expected_for_call.clone(),
                )),
            };
            Box::new(advancing)
        };
        let mut continuation = OrdinaryChildContinuation {
            child: call_child,
            cursor: Box::new(OrdinaryValueCursor {
                source,
                expected: Some(expected_for_call),
                planned: PlannedOrdinaryValue::Call(OrdinaryCallContinuation::Advancing(advancing)),
            }),
            next_mode: frontier::FrontierMode::ExpectedOnly,
            suspension: OrdinarySuspension::Mode,
        };

        reset_ordinary_planning_work();
        continuation = match OrdinaryValueCursor::advance_child_for_test(
            continuation,
            frontier::FrontierMode::ExpectedOnly,
            &mut frontier,
            &mut tcx,
        )
        .expect("advance the expected-only schedule")
        {
            OrdinaryChildAdvance::Pending(continuation) => continuation,
            OrdinaryChildAdvance::Complete(_) => {
                panic!("the literal must remain pending before lexical fallback")
            }
        };
        assert_eq!(
            ordinary_planning_work().expected_result_equations,
            1,
            "the result equation gets one initial blocked attempt"
        );
        let completed = match OrdinaryValueCursor::advance_child_for_test(
            continuation,
            frontier::FrontierMode::LexicalFallback,
            &mut frontier,
            &mut tcx,
        )
        .expect("advance the lexical-fallback schedule")
        {
            OrdinaryChildAdvance::Complete(completed) => completed,
            OrdinaryChildAdvance::Pending(_) => {
                panic!("lexical fallback should close the literal and result equation")
            }
        };
        assert_eq!(
            ordinary_planning_work().expected_result_equations,
            2,
            "one blocked attempt plus one post-descendant discharge; no mode retry"
        );
        assert!(
            !tcx.elaborations
                .is_value_at_type_slot("main", publication_span.id, 0),
            "a deferred or retried equation published before its owner closed"
        );
        let CompletedInFrame::Value(result_at_root, _) = completed else {
            panic!("the completed call result must retain into the scheduler root")
        };
        frontier
            .close_root_with(
                vec![
                    (expected_at_root, GoalEscape::ClosedAt(root)),
                    (result_at_root, GoalEscape::ClosedAt(root)),
                ],
                &mut tcx,
                |outputs, _tcx| {
                    assert_eq!(outputs.len(), 2);
                    Ok(())
                },
            )
            .expect("close the causal retry witness");
        assert!(
            tcx.elaborations
                .is_value_at_type_slot("main", publication_span.id, 0)
        );
    }

    #[cfg(feature = "surface")]
    #[test]
    fn retained_leaf_equation_retries_only_after_structural_progress() {
        let module = parse("module main;").expect("parse retained-leaf scheduler witness");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower retained-leaf scheduler witness");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        let module = &package.module("main").expect("main module").module;
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("module environment");
        let source_span = Span::new(40, 41);
        let source = Expr::Unit {
            occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
            meta: Meta::new(source_span),
        };
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations);
        let goal_type = |goal| Type::Goal {
            goal,
            args: Vec::new(),
            meta: Meta::new(sp()),
            ext: (),
        };

        let (mut frontier, ancestor) =
            frontier::OrdinaryFrontier::begin_root_with(sp(), &tcx, |store, owner| {
                store.alloc_goal(
                    owner,
                    crate::ast::Kind::Star,
                    GoalSolutionPolicy::Monotype,
                    GoalOrigin::named(sp(), GoalRole::TypeArgument, "S"),
                )
            })
            .expect("open retained-leaf scheduler root");
        let (parent_reservation, descendant) = frontier
            .reserve_root_child_with(GoalOwnerKind::RetainedValue, sp(), &tcx, |store, owner| {
                store.alloc_goal(
                    owner,
                    crate::ast::Kind::Star,
                    GoalSolutionPolicy::Monotype,
                    GoalOrigin::named(sp(), GoalRole::TypeArgument, "A"),
                )
            })
            .expect("reserve descendant-owning scheduler parent");
        let mut parent_child = frontier
            .open_reserved_child(parent_reservation)
            .expect("open descendant-owning scheduler parent");
        let parent = parent_child.owner();
        let expected = frontier
            .store()
            .scoped_type(
                parent,
                InternedType::fresh_canonical(Type::Product {
                    left: Box::new(goal_type(descendant)),
                    right: Box::new(unit_ty()),
                    meta: Meta::new(sp()),
                }),
                sp(),
            )
            .expect("scope descendant-dependent leaf expectation");
        let prepared = PreparedOrdinaryValue {
            source: &source,
            synth: Synth::value_interned(InternedType::fresh_canonical(goal_type(ancestor))),
            binders: Vec::new(),
            retained_type: None,
        };

        {
            let mut parent_frontier = frontier.retained_value_frontier(&mut parent_child);
            let (leaf_reservation, planned) = parent_frontier
                .reserve_ordinary_child_with(source_span, &tcx, |store, owner| {
                    OrdinaryValueCursor::plan(
                        &source,
                        OrdinaryValueSeed::Leaf(prepared),
                        store,
                        owner,
                        &tcx,
                    )
                })
                .expect("reserve prepared retained leaf");
            let cursor = OrdinaryValueCursor::bind(
                &source,
                OwnerBoundType::Retained {
                    owner: parent,
                    ty: expected,
                },
                planned,
            );
            let leaf = parent_frontier
                .open_ordinary_child(leaf_reservation)
                .expect("open prepared retained leaf");
            let mut continuation = OrdinaryChildContinuation {
                child: leaf,
                cursor: Box::new(cursor),
                next_mode: frontier::FrontierMode::ExpectedOnly,
                suspension: OrdinarySuspension::Mode,
            };

            reset_retained_leaf_work();
            for mode in [
                frontier::FrontierMode::ExpectedOnly,
                frontier::FrontierMode::LexicalFallback,
                frontier::FrontierMode::FinalPreflight,
            ] {
                continuation = match OrdinaryValueCursor::advance_child_for_test(
                    continuation,
                    mode,
                    &mut parent_frontier,
                    &mut tcx,
                )
                .expect("an unchanged non-final mode must retain the prepared leaf")
                {
                    OrdinaryChildAdvance::Pending(continuation) => continuation,
                    OrdinaryChildAdvance::Complete(_) => {
                        panic!("the descendant-dependent leaf completed in {mode:?}")
                    }
                };
                assert_eq!(
                    retained_leaf_work(),
                    RetainedLeafWork {
                        equation_attempts: 1,
                        publication_stages: 0,
                    },
                    "changing mode without structural progress retried or published the leaf"
                );
            }

            let mut gather = parent_frontier
                .begin_gather(sp(), &tcx)
                .expect("open the causal sibling gather");
            let store = parent_frontier.store();
            let descendant_at_gather = store
                .scoped_goal_at(descendant, Vec::new(), gather.owner(), sp())
                .expect("scope descendant in the sibling gather");
            let unit_at_gather = store
                .scoped_type(
                    gather.owner(),
                    InternedType::fresh_canonical(unit_ty()),
                    sp(),
                )
                .expect("scope the sibling's concrete solution");
            assert_eq!(
                store
                    .try_constrain_gather_equation(
                        gather.delta_mut(),
                        descendant_at_gather,
                        unit_at_gather,
                        sp(),
                        &tcx,
                    )
                    .expect("solve the retained leaf's descendant goal"),
                CloseReadyEquationConstraint::Applied
            );
            parent_frontier
                .close_gather(gather, &tcx)
                .expect("commit structural progress from the sibling gather");

            match OrdinaryValueCursor::advance_child_for_test(
                continuation,
                frontier::FrontierMode::Final,
                &mut parent_frontier,
                &mut tcx,
            )
            .expect("structural progress should release the prepared leaf")
            {
                OrdinaryChildAdvance::Complete(_) => {}
                OrdinaryChildAdvance::Pending(_) => {
                    panic!("the prepared leaf remained pending after structural progress")
                }
            }
            assert_eq!(
                retained_leaf_work(),
                RetainedLeafWork {
                    equation_attempts: 2,
                    publication_stages: 1,
                },
                "the released leaf needs exactly one retry and one publication stage"
            );
        }
    }

    #[cfg(feature = "surface")]
    #[test]
    fn final_deferred_result_equations_report_canonical_error_in_both_orientations() {
        for reverse in [false, true] {
            let module = parse("module main;").expect("parse Final deferral witness");
            let (modules, _) =
                FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                    .expect("lower Final deferral witness");
            let package =
                Package::build(Path::new(""), modules, None).expect("build resolved package shell");
            let module = &package.module("main").expect("main module").module;
            let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
                .expect("module environment");
            let mut elaborations = Elaborations::new();
            let mut tcx = TypeCtx::new(&env, &mut elaborations);
            let goal_type = |goal| Type::Goal {
                goal,
                args: Vec::new(),
                meta: Meta::new(sp()),
                ext: (),
            };

            let (mut frontier, ancestor) =
                frontier::OrdinaryFrontier::begin_root_with(sp(), &tcx, |store, owner| {
                    store.alloc_goal(
                        owner,
                        crate::ast::Kind::Star,
                        GoalSolutionPolicy::Monotype,
                        GoalOrigin::named(sp(), GoalRole::TypeArgument, "T"),
                    )
                })
                .expect("open Final deferral root");
            let root = frontier.owner();
            let (reservation, (descendant, call)) = frontier
                .reserve_root_child_with(
                    GoalOwnerKind::RetainedValue,
                    sp(),
                    &tcx,
                    |store, owner| {
                        let descendant = store.alloc_goal(
                            owner,
                            crate::ast::Kind::Star,
                            GoalSolutionPolicy::Monotype,
                            GoalOrigin::named(sp(), GoalRole::TypeArgument, "T"),
                        )?;
                        let call = OpenGoalCall::begin(
                            GoalCallShape {
                                binders: Vec::new(),
                                param: SemanticValueDomain::known(InternedType::fresh(unit_ty())),
                                ret: unit_ty(),
                                result_requirement_source: None,
                                abi_arity: 0,
                                has_value_layer: true,
                                type_args: Vec::new(),
                                value_args: Vec::new(),
                                explicit_prefix: 0,
                                identity_canonical: true,
                                result_is_pre_residual: false,
                            },
                            owner,
                            sp(),
                            fresh_site(sp()),
                            store,
                            &tcx,
                        )?;
                        Ok((descendant, call))
                    },
                )
                .expect("reserve Final deferral child");
            let mut call_child = frontier
                .open_reserved_child(reservation)
                .expect("open Final deferral child");
            let call_owner = call_child.owner();
            let publication_span = fresh_site(if reverse {
                Span::new(30, 31)
            } else {
                Span::new(20, 21)
            });
            call_child
                .publication_mut()
                .mark_value_at_type_slot(publication_span, 0);
            let ancestor_at_child = frontier
                .store()
                .scoped_goal_at(ancestor, Vec::new(), call_owner, sp())
                .expect("scope ancestor at child");
            let descendant_product = frontier
                .store()
                .scoped_type(
                    call_owner,
                    InternedType::fresh_canonical(Type::Product {
                        left: Box::new(goal_type(descendant)),
                        right: Box::new(unit_ty()),
                        meta: Meta::new(sp()),
                    }),
                    sp(),
                )
                .expect("scope descendant product");
            let (result, expected) = if reverse {
                (
                    ancestor_at_child,
                    OwnerBoundType::Retained {
                        owner: call_owner,
                        ty: descendant_product,
                    },
                )
            } else {
                let ancestor_at_root = frontier
                    .store()
                    .scoped_goal_at(ancestor, Vec::new(), root, sp())
                    .expect("scope ancestor at root");
                (
                    descendant_product,
                    OwnerBoundType::Retained {
                        owner: root,
                        ty: ancestor_at_root,
                    },
                )
            };
            let advancing = AdvancingOrdinaryCall {
                call,
                result,
                result_inferred_type_arg_suffix: 0,
                destination: call_owner,
                pending: Vec::new(),
                pending_expected_result: Some(PendingExpectedResult::new(expected.clone())),
            };
            let source = Expr::Unit {
                occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
                meta: Meta::new(sp()),
            };
            let mut continuation = OrdinaryChildContinuation {
                child: call_child,
                cursor: Box::new(OrdinaryValueCursor {
                    source: &source,
                    expected: Some(expected),
                    planned: PlannedOrdinaryValue::Call(OrdinaryCallContinuation::Advancing(
                        Box::new(advancing),
                    )),
                }),
                next_mode: frontier::FrontierMode::ExpectedOnly,
                suspension: OrdinarySuspension::Mode,
            };

            reset_ordinary_planning_work();
            for mode in [
                frontier::FrontierMode::ExpectedOnly,
                frontier::FrontierMode::LexicalFallback,
                frontier::FrontierMode::FinalPreflight,
            ] {
                continuation = match OrdinaryValueCursor::advance_child_for_test(
                    continuation,
                    mode,
                    &mut frontier,
                    &mut tcx,
                )
                .expect("a non-final mode must retain the unresolved result equation")
                {
                    OrdinaryChildAdvance::Pending(continuation) => continuation,
                    OrdinaryChildAdvance::Complete(_) => {
                        panic!("an unresolved result equation completed in {mode:?}")
                    }
                };
                assert_eq!(
                    ordinary_planning_work().expected_result_equations,
                    1,
                    "changing frontier mode without inference progress retried the equation"
                );
            }
            let outcome = catch_unwind(AssertUnwindSafe(|| {
                OrdinaryValueCursor::advance_child_for_test(
                    continuation,
                    frontier::FrontierMode::Final,
                    &mut frontier,
                    &mut tcx,
                )
            }))
            .expect("Final deferral must report an input error, not panic");
            let error = match outcome {
                Ok(_) => panic!("Final must not discard a deferred result equation"),
                Err(error) => error,
            };
            assert_eq!(
                error.diagnostic().message,
                "cannot infer type argument `T` from the available type information"
            );
            assert_eq!(ordinary_planning_work().expected_result_equations, 1);
            assert!(
                !tcx.elaborations
                    .is_value_at_type_slot("main", publication_span.id, 0),
                "a failed Final deferral published child metadata"
            );
        }
    }

    #[cfg(feature = "surface")]
    #[test]
    fn deep_expectation_chain_classifies_and_supplies_on_bounded_stack() {
        with_bounded_stack(|| {
            const DEPTH: usize = 4096;
            let module = parse("module main;").expect("parse expectation-chain module");
            let (modules, _) =
                FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                    .expect("lower expectation-chain module");
            let package = Package::build(Path::new(""), modules, None)
                .expect("build expectation-chain package");
            let module = &package.module("main").expect("main module").module;
            let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
                .expect("expectation-chain module environment");
            let mut elaborations = Elaborations::new();
            let tcx = TypeCtx::new(&env, &mut elaborations);
            let source = Expr::Unit {
                occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
                meta: Meta::new(sp()),
            };
            let (mut frontier, ()) =
                frontier::OrdinaryFrontier::begin_root_with(sp(), &tcx, |_store, _owner| Ok(()))
                    .expect("begin expectation-chain root");
            let mut cursor = Box::new(OrdinaryValueCursor {
                source: &source,
                expected: None,
                planned: PlannedOrdinaryValue::Literal,
            });
            for _ in 0..DEPTH {
                let (reservation, ()) = frontier
                    .reserve_root_child_with(
                        GoalOwnerKind::RetainedValue,
                        sp(),
                        &tcx,
                        |_store, _owner| Ok(()),
                    )
                    .expect("reserve expectation-chain successor");
                let child = frontier
                    .open_reserved_child(reservation)
                    .expect("open expectation-chain successor");
                cursor = Box::new(OrdinaryValueCursor {
                    source: &source,
                    expected: None,
                    planned: PlannedOrdinaryValue::Call(OrdinaryCallContinuation::Successor(
                        OrdinaryChildContinuation {
                            child,
                            cursor,
                            next_mode: frontier::FrontierMode::ExpectedOnly,
                            suspension: OrdinarySuspension::Mode,
                        },
                    )),
                });
            }

            assert!(cursor.awaits_expected());
            cursor.supply_expected(OwnerBoundType::Plain(InternedType::fresh(unit_ty())));

            let mut attached = 0;
            loop {
                let OrdinaryValueCursor {
                    expected, planned, ..
                } = *cursor;
                assert!(
                    expected.is_some(),
                    "a successor lost the supplied expectation"
                );
                match planned {
                    PlannedOrdinaryValue::Call(OrdinaryCallContinuation::Successor(child)) => {
                        attached += 1;
                        cursor = child.cursor;
                    }
                    PlannedOrdinaryValue::Literal => break,
                    _ => panic!("the expectation fixture changed continuation family"),
                }
            }
            assert_eq!(attached, DEPTH);
        });
    }

    #[cfg(feature = "surface")]
    #[test]
    fn deep_successor_chain_finds_user_elaborator_transcript_on_bounded_stack() {
        with_bounded_stack(|| {
            const DEPTH: usize = 4096;
            let module = parse("module main;").expect("parse transcript-chain module");
            let (modules, _) =
                FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                    .expect("lower transcript-chain module");
            let package = Package::build(Path::new(""), modules, None)
                .expect("build transcript-chain package");
            let module = &package.module("main").expect("main module").module;
            let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
                .expect("transcript-chain module environment");
            let mut elaborations = Elaborations::new();
            let tcx = TypeCtx::new(&env, &mut elaborations);
            let action = crate::ast::NodeId(9191);
            let transcript = UserElaboratorCallTranscript {
                action,
                source_span: sp(),
                layers: Vec::new(),
                next_source_index: 0,
                terminal_type_layer: None,
            };
            let (mut frontier, call) =
                frontier::OrdinaryFrontier::begin_root_with(sp(), &tcx, |store, owner| {
                    OpenGoalCall::begin_at_slot_offset_with_transcript(
                        GoalCallShape {
                            binders: Vec::new(),
                            param: SemanticValueDomain::known(InternedType::fresh(unit_ty())),
                            ret: unit_ty(),
                            result_requirement_source: None,
                            abi_arity: 0,
                            has_value_layer: true,
                            type_args: Vec::new(),
                            value_args: Vec::new(),
                            explicit_prefix: 0,
                            identity_canonical: true,
                            result_is_pre_residual: false,
                        },
                        owner,
                        sp(),
                        fresh_site(sp()),
                        0,
                        Some(transcript),
                        store,
                        &tcx,
                    )
                })
                .expect("begin transcript-chain root");
            let result = frontier
                .store()
                .scoped_type(
                    frontier.owner(),
                    InternedType::fresh_canonical(unit_ty()),
                    sp(),
                )
                .expect("scope transcript-chain result");
            let source = Expr::Unit {
                occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
                meta: Meta::new(sp()),
            };
            let mut continuation =
                OrdinaryCallContinuation::AwaitingExpected(Box::new(CompletedPathUnitGoalCall {
                    call,
                    result,
                    result_inferred_type_arg_suffix: 0,
                }));
            for _ in 0..DEPTH {
                let (reservation, ()) = frontier
                    .reserve_root_child_with(
                        GoalOwnerKind::RetainedValue,
                        sp(),
                        &tcx,
                        |_store, _owner| Ok(()),
                    )
                    .expect("reserve transcript-chain successor");
                let child = frontier
                    .open_reserved_child(reservation)
                    .expect("open transcript-chain successor");
                continuation = OrdinaryCallContinuation::Successor(OrdinaryChildContinuation {
                    child,
                    cursor: Box::new(OrdinaryValueCursor {
                        source: &source,
                        expected: None,
                        planned: PlannedOrdinaryValue::Call(continuation),
                    }),
                    next_mode: frontier::FrontierMode::ExpectedOnly,
                    suspension: OrdinarySuspension::Mode,
                });
            }

            assert_eq!(
                continuation
                    .user_elaborator_transcript()
                    .expect("deep successor chain must retain its transcript")
                    .action,
                action
            );

            let mut traversed = 0;
            loop {
                match continuation {
                    OrdinaryCallContinuation::Successor(child) => {
                        let OrdinaryValueCursor { planned, .. } = *child.cursor;
                        let PlannedOrdinaryValue::Call(next) = planned else {
                            panic!("the transcript fixture changed continuation family")
                        };
                        traversed += 1;
                        continuation = next;
                    }
                    OrdinaryCallContinuation::AwaitingExpected(completed) => {
                        assert_eq!(
                            completed
                                .call
                                .user_elaborator_transcript
                                .as_ref()
                                .expect("terminal call must retain its transcript")
                                .action,
                            action
                        );
                        break;
                    }
                    _ => panic!("the transcript fixture changed terminal state"),
                }
            }
            assert_eq!(traversed, DEPTH);
        });
    }

    #[cfg(feature = "surface")]
    #[test]
    fn ordinary_value_cursor_preserves_whole_function_scheme_completion() {
        let module = parse(
            "module main;
             pure fn identity[A](value: A) -> A { value }",
        )
        .expect("parse polymorphic path module");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower Kio");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        let module = &package.module("main").expect("main module").module;
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("module environment");
        let source_span = Span::new(10, 18);
        let source = Expr::Path {
            occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
            segments: vec![crate::ast::PathSegment::new("identity", source_span)],
            meta: Meta::new(source_span),
            ext: (),
        };
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations);
        let prepared = PreparedOrdinaryValue::path_or_unit(&source, &mut tcx)
            .expect("prepare polymorphic path premise")
            .expect("Path is a selected ordinary premise");
        assert!(prepared.synth.is_scheme);
        let expected = OwnerBoundType::Plain(prepared.synth.ty.clone());

        let mut store = GoalStore::new();
        let owner = store
            .begin_owner(
                None,
                store.scope_from_type_ctx(&tcx),
                GoalOwnerKind::Application,
                source_span,
            )
            .expect("open cursor owner");
        let mut delta = store
            .begin_delta(owner, source_span)
            .expect("open cursor delta");
        let mut publication = PublicationBuilder::new(&store, &delta);
        let cursor = OrdinaryValueCursor::new(&source, expected);
        let mut context = SimpleGoalLeafContext {
            equation_owner: owner,
            publication_owner: owner,
            store: &store,
            delta: &mut delta,
            publication: &mut publication,
        };

        let advanced = cursor
            .advance_selected_path_unit(
                frontier::FrontierMode::Final,
                prepared,
                &mut context,
                &mut tcx,
            )
            .expect("advance polymorphic Path premise once");
        let OrdinaryValueAdvance::Complete(CompletedInFrame::FunctionScheme(completed, _)) =
            advanced
        else {
            panic!("a polymorphic Path must preserve whole-function-scheme completion")
        };
        assert!(matches!(
            completed.ty().as_type(),
            crate::ast::Type::Forall { .. }
        ));
    }

    #[cfg(feature = "surface")]
    #[test]
    fn connected_call_planning_bounds_common_and_dynamic_work() {
        let module = parse(
            "module main;
             host type Tag;
             host type I32;
             fn hold[A](value: A) -> Tag -> A { .(_tag: Tag) { value } }
             fn unary(value: I32) -> I32 { value }
             fn common(tag: Tag) -> I32 -> I32 { hold(unary)(tag) }
             fn dynamic(tag: Tag, value: I32) -> I32 { hold(unary)(tag)(value) }",
        )
        .expect("parse connected-planning work witnesses");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower connected-planning work witnesses");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let module = &package.module("main").expect("main module").module;
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("module environment");

        // The selected structural walk is also its execution: the common
        // route opens two calls and prepares two values, while the dynamic
        // route opens all three calls and prepares all three values.  Neither
        // route replays a discarded prefix.
        for (name, expected_work) in [
            (
                "common",
                OrdinaryPlanningWork {
                    open_goal_calls: 2,
                    prepared_values: 2,
                    expected_result_equations: 0,
                    rec_order_source_visits: 0,
                    lambda_headers: 0,
                    semantic_packet_decodes: 2,
                    semantic_successor_advances: 2,
                    max_driver_frames: 2,
                },
            ),
            (
                "dynamic",
                OrdinaryPlanningWork {
                    open_goal_calls: 3,
                    prepared_values: 3,
                    expected_result_equations: 0,
                    rec_order_source_visits: 0,
                    lambda_headers: 0,
                    semantic_packet_decodes: 3,
                    semantic_successor_advances: 3,
                    max_driver_frames: 3,
                },
            ),
        ] {
            let (item_index, def) = module
                .items
                .iter()
                .enumerate()
                .find_map(|(index, item)| match item {
                    Item::FnDef(def) if def.name == name => Some((index, def)),
                    _ => None,
                })
                .unwrap_or_else(|| panic!("missing `{name}` planning-work witness"));
            let mut elaborations = Elaborations::new();
            let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
            for param in def.sig.value_params() {
                tcx.push_value(
                    param.name.clone(),
                    param.ty.clone().expect("value parameter annotation"),
                );
            }
            reset_ordinary_planning_work();
            <crate::pass::typecheck_full::LoweredTyper as Typer<Lowered>>::synth_expr(
                &def.body, &mut tcx,
            )
            .unwrap_or_else(|error| panic!("typecheck `{name}` work witness: {error:?}"));
            assert_eq!(
                ordinary_planning_work(),
                expected_work,
                "`{name}` must keep structural replay bounded and prepare only executing values"
            );
        }
    }

    #[cfg(feature = "surface")]
    #[test]
    fn natural_boundary_ordinary_scaling_matrix() {
        const SCALING_STACK_BYTES: usize = 16 * 1024 * 1024;

        #[cfg(feature = "parallel")]
        rayon::ThreadPoolBuilder::new()
            .num_threads(1)
            .stack_size(SCALING_STACK_BYTES)
            .build()
            .expect("build natural-boundary scaling worker pool")
            .install(run_natural_boundary_ordinary_scaling_matrix);

        #[cfg(not(feature = "parallel"))]
        let result = std::thread::Builder::new()
            .name("natural-boundary-ordinary-scaling".to_owned())
            .stack_size(SCALING_STACK_BYTES)
            .spawn(run_natural_boundary_ordinary_scaling_matrix)
            .expect("spawn natural-boundary ordinary scaling matrix")
            .join();
        #[cfg(not(feature = "parallel"))]
        if let Err(payload) = result {
            std::panic::resume_unwind(payload);
        }
    }

    #[cfg(feature = "surface")]
    fn run_natural_boundary_ordinary_scaling_matrix() {
        use crate::pass::typecheck_core::goals::{
            GoalStoreWork, finish_goal_store_work, reset_goal_store_work,
        };

        #[derive(Debug, PartialEq, Eq)]
        struct Observation {
            goals: GoalStoreWork,
            planning: OrdinaryPlanningWork,
        }

        fn scaling_package(source: &str) -> Package {
            let module = parse(source).expect("parse natural-boundary scaling witness");
            let mut sources = vec![(PathBuf::from("main.kio"), module)];
            if source.contains("import control(if)") {
                sources.push((
                    PathBuf::from("control.kio"),
                    parse(include_str!(
                        "../../../../test-data/poc/elab/workdir/control.kio"
                    ))
                    .expect("ordinary control provider"),
                ));
            }
            let (modules, _) = FullPipeline::lower_package(sources, None)
                .expect("lower natural-boundary scaling witness");
            let package = Package::build(Path::new(""), modules, None)
                .expect("build natural-boundary scaling witness");
            package
                .resolve_imports()
                .expect("resolve natural-boundary scaling witness");
            crate::pass::alpha_normalize::normalize_package(&package)
                .into_parts()
                .0
        }

        fn observe(source: &str) -> Observation {
            let package = scaling_package(source);
            let module = &package.module("main").expect("main module").module;
            let (item_index, run) = module
                .items
                .iter()
                .enumerate()
                .find_map(|(index, item)| match item {
                    Item::FnDef(def) if def.name == "run" => Some((index, def)),
                    _ => None,
                })
                .expect("natural-boundary scaling witness has a run function");
            let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
                .expect("natural-boundary scaling module environment");
            let mut elaborations = Elaborations::new();
            let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
            for parameter in run.sig.value_params() {
                tcx.push_value(
                    parameter.name.clone(),
                    parameter.ty.clone().expect("run parameter annotation"),
                );
            }

            reset_goal_store_work();
            reset_ordinary_planning_work();
            <crate::pass::typecheck_full::LoweredTyper as Typer<Lowered>>::check_value_against_interned(
                &run.body,
                &InternedType::fresh(run.ret.clone()),
                &mut tcx,
            )
            .expect("typecheck natural-boundary run body");
            let goals = finish_goal_store_work();
            let planning = ordinary_planning_work();
            Observation { goals, planning }
        }

        fn validate(source: &str) {
            let package = scaling_package(source);
            let checked =
                crate::pass::typecheck_full::check_package_preserving_normalization(&package)
                    .expect("typecheck representative natural-boundary scaling package");
            crate::pass::typecheck_full::validate_substituted_package(checked.substituted())
                .expect("representative natural-boundary witness must pass standalone Prime");
        }

        fn prelude(extra: &str) -> String {
            format!(
                "module main; \
                 host type Bool role(bool); \
                 host fn make[A]() -> A; \
                 fn id[A](value: A) -> A {{ value }} \
                 fn same[A](_left: A, _right: A) -> . {{ () }} \
                 {extra}"
            )
        }

        fn control_prelude(extra: &str) -> String {
            prelude(extra).replacen("module main;", "module main; import control(if);", 1)
        }

        fn let_prefixes(width: usize) -> String {
            let prefixes = (0..width)
                .map(|index| format!("let .(value{index}: .) = id(());"))
                .collect::<Vec<_>>()
                .join(" ");
            prelude(&format!("fn run() -> . {{ {prefixes} () }}"))
        }

        fn statement_prefixes(width: usize) -> String {
            let prefixes = std::iter::repeat_n("id(());", width)
                .collect::<Vec<_>>()
                .join(" ");
            prelude(&format!("fn run() -> . {{ {prefixes} () }}"))
        }

        fn connected_wide_call(width: usize) -> String {
            let params = (0..width)
                .map(|index| format!("_value{index}: A"))
                .collect::<Vec<_>>()
                .join(", ");
            let mut args =
                std::iter::repeat_n("make()", width.saturating_sub(1)).collect::<Vec<_>>();
            args.push("()");
            prelude(&format!(
                "fn connect[A]({params}) -> . {{ () }} \
                 fn run() -> . {{ connect({}) }}",
                args.join(", ")
            ))
        }

        fn independent_nested_calls(depth: usize) -> String {
            let call = (0..depth).fold("()".to_owned(), |call, _| format!("id(., {call})"));
            prelude(&format!("fn run() -> . {{ {call} }}"))
        }

        fn connected_deep_calls(depth: usize) -> String {
            let call = (0..depth).fold("make()".to_owned(), |call, _| format!("id({call})"));
            prelude(&format!("fn run() -> . {{ same({call}, ()) }}"))
        }

        fn sequential_conditionals(width: usize) -> String {
            let prefixes = (0..width)
                .map(|index| {
                    format!("let value{index} = if! condition {{ make() }} else {{ () }};")
                })
                .collect::<Vec<_>>()
                .join(" ");
            control_prelude(&format!("fn run(condition: Bool) -> . {{ {prefixes} () }}"))
        }

        fn deep_conditionals(depth: usize) -> String {
            let body = (0..depth).fold("()".to_owned(), |body, _| {
                format!("if! condition {{ make() }} else {{ {body} }}")
            });
            control_prelude(&format!(
                "fn run(condition: Bool) -> . {{ let value = {body}; () }}"
            ))
        }

        fn goal_work(
            owners: usize,
            goals: usize,
            equations: usize,
            max_owners: usize,
            max_goals: usize,
            max_depth: usize,
        ) -> GoalStoreWork {
            GoalStoreWork {
                owners_opened: owners,
                owners_committed: owners,
                owners_discarded: 0,
                goals_reserved: goals,
                equation_attempts: equations,
                max_live_domains: 1,
                max_live_owners: max_owners,
                max_live_goals: max_goals,
                max_owner_depth: max_depth,
            }
        }

        fn planning_work(
            calls: usize,
            prepared: usize,
            expected_equations: usize,
            advances: usize,
            max_frames: usize,
        ) -> OrdinaryPlanningWork {
            OrdinaryPlanningWork {
                open_goal_calls: calls,
                prepared_values: prepared,
                expected_result_equations: expected_equations,
                rec_order_source_visits: 0,
                lambda_headers: 0,
                semantic_packet_decodes: calls,
                semantic_successor_advances: advances,
                max_driver_frames: max_frames,
            }
        }

        fn expected_observation(label: &str, width: usize) -> Observation {
            match label {
                "let" => Observation {
                    goals: goal_work(5 * width, width, 3 * width, 3, 1, 3),
                    planning: planning_work(width, width, width, width, 1),
                },
                "statement" => Observation {
                    goals: goal_work(4 * width, width, 2 * width, 3, 1, 3),
                    planning: planning_work(width, width, 0, width, 1),
                },
                "connected-wide" => {
                    let max_owners = if width == 1 { 3 } else { 4 };
                    let max_goals = if width == 1 { 1 } else { 2 };
                    Observation {
                        goals: goal_work(
                            3 * width + 2,
                            width,
                            3 * width,
                            max_owners,
                            max_goals,
                            max_owners,
                        ),
                        planning: planning_work(width, 1, width, width, 1),
                    }
                }
                "independent-deep" => Observation {
                    goals: goal_work(3 * width + 2, 0, 2 * width + 1, width + 2, 0, width + 2),
                    planning: planning_work(width, 1, width, width, width),
                },
                "connected-deep" => Observation {
                    goals: goal_work(
                        3 * width + 8,
                        width + 2,
                        2 * width + 6,
                        width + 4,
                        width + 2,
                        width + 4,
                    ),
                    planning: planning_work(width + 2, 1, width + 2, width + 2, width + 1),
                },
                _ => panic!("unknown natural-boundary scaling row `{label}`"),
            }
        }

        for width in [1, 8, 32, 128] {
            for (label, source) in [
                ("let", let_prefixes(width)),
                ("statement", statement_prefixes(width)),
                ("connected-wide", connected_wide_call(width)),
                ("independent-deep", independent_nested_calls(width)),
                ("connected-deep", connected_deep_calls(width)),
            ] {
                let observed = observe(&source);
                assert_eq!(
                    observed,
                    expected_observation(label, width),
                    "natural-boundary `{label}` work changed at width {width}"
                );
            }
        }

        for source in [
            let_prefixes(32),
            statement_prefixes(32),
            connected_wide_call(32),
            independent_nested_calls(32),
            connected_deep_calls(32),
            sequential_conditionals(8),
            deep_conditionals(8),
        ] {
            validate(&source);
        }
    }

