    #[cfg(feature = "surface")]
    fn module_alias_call_binder_outcome(source: &str, case: &str) -> Result<(), String> {
        let module = parse(source)
            .unwrap_or_else(|error| panic!("parse {case} call-binder witness: {error:?}"));
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .unwrap_or_else(|error| panic!("lower {case} call-binder witness: {error:?}"));
        let package = Package::build(Path::new(""), modules, None)
            .unwrap_or_else(|error| panic!("build {case} package: {error:?}"));
        package
            .resolve_imports()
            .unwrap_or_else(|error| panic!("resolve {case} package: {error:?}"));
        let result = catch_unwind(AssertUnwindSafe(|| FullPipeline::typecheck(&package)))
            .unwrap_or_else(|_| {
                panic!("typechecking the {case} call-binder witness must not panic")
            });
        result
            .map(|_| ())
            .map_err(|error| error.error.diagnostic().message.clone())
    }

    #[cfg(feature = "surface")]
    fn assert_module_alias_does_not_capture_call_binder(source: &str, case: &str) {
        module_alias_call_binder_outcome(source, case)
            .unwrap_or_else(|error| panic!("typecheck {case} call-binder witness: {error}"));
    }

    #[cfg(feature = "surface")]
    #[test]
    fn product_call_binder_control_without_same_named_module_alias() {
        let outcome = module_alias_call_binder_outcome(
            "module main;
             host type X;
             host type Y;
             host type P;
             host type Q;
             fn witness(source: [A] A -> . -> A, left: P, right: Q) -> (P & Q) {
               let .(local: [A] A -> . -> A) = source;
               local(left, right)(())
            }",
            "product control without alias",
        );
        assert_eq!(
            outcome,
            Err("type mismatch: expected `.`, found `Q`".to_owned())
        );
    }

