    #[cfg(feature = "surface")]
    #[test]
    fn selecting_empty_call_distinguishes_residual_from_unit_application() {
        let module = parse(
            "module main;
             host type N;
             fn identity[A](value: A) -> A { value }
             host fn make[A]() -> A;
             fn unary(value: N) -> N { value }
             fn consume(_function: N -> N) -> . { () }
             fn residual() -> N -> N { identity(_) }
             fn implicit_unit() -> . { identity() }
             fn applied() -> N { make() }
             fn residual_argument() -> . { consume(identity(_)) }
             fn rejected() -> N { unary() }
             fn unit_argument() -> . { consume(identity()) }",
        )
        .expect("parse empty-call selector witnesses");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower empty-call selector witnesses");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let module = &package.module("main").expect("main module").module;
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("module environment");
        let find = |name: &str| {
            module
                .items
                .iter()
                .enumerate()
                .find_map(|(index, item)| match item {
                    Item::FnDef(def) if def.name == name => Some((index, def)),
                    _ => None,
                })
                .unwrap_or_else(|| panic!("missing `{name}` empty-call witness"))
        };

        for (name, open_goal_calls) in [
            ("residual", 1),
            ("implicit_unit", 1),
            ("applied", 1),
            ("residual_argument", 2),
        ] {
            let (item_index, def) = find(name);
            let mut elaborations = Elaborations::new();
            let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
            assert!(matches!(
                OrdinaryValueCursor::seed(&def.body, &mut tcx)
                    .unwrap_or_else(|error| panic!("seed `{name}` selector: {error:?}")),
                OrdinaryValueSeed::DirectSelecting { .. }
            ));
            reset_ordinary_planning_work();
            let expected = InternedType::fresh(def.ret.clone());
            let actual = run_general_ordinary_value(&def.body, Some(&expected), &mut tcx)
                .unwrap_or_else(|error| panic!("advance `{name}` selector: {error:?}"));
            crate::pass::typecheck_core::require_type_equiv_state(
                actual.ty.as_type(),
                expected.as_type(),
                def.body.span(),
                &tcx.env.alias_ctx(),
                actual.ty.identity_is_canonical(),
                expected.identity_is_canonical(),
            )
            .unwrap_or_else(|error| panic!("result type for `{name}`: {error:?}"));
            assert_eq!(ordinary_planning_work().open_goal_calls, open_goal_calls);
        }

        let (item_index, def) = find("rejected");
        let Expr::Call {
            occurrence: meta_occurrence,
            callee,
            meta,
            ..
        } = &def.body
        else {
            panic!("the rejected witness must be one direct call")
        };
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
        assert!(matches!(
            OrdinaryValueCursor::seed(&def.body, &mut tcx)
                .expect("seed rejected empty-call selector"),
            OrdinaryValueSeed::DirectSelecting { .. }
        ));
        reset_ordinary_planning_work();
        let expected = InternedType::fresh(def.ret.clone());
        let error = match run_general_ordinary_value(&def.body, Some(&expected), &mut tcx) {
            Ok(_) => panic!("a monomorphic non-Unit function cannot be called without a value"),
            Err(error) => error,
        };
        assert!(
            error.diagnostic().message.contains("type mismatch")
                && error.diagnostic().message.contains("expected `N`")
                && error.diagnostic().message.contains("found `.`"),
            "the implicit Unit argument must be checked against the monomorphic domain: {error:?}"
        );
        assert_eq!(ordinary_planning_work().open_goal_calls, 1);
        for span in [callee.span(), meta.span] {
            assert!(
                tcx.elaborations
                    .position_index()
                    .type_at("main", span)
                    .is_none(),
                "the rejected selector published a position type at {span:?}"
            );
            assert!(
                tcx.elaborations
                    .position_index()
                    .binder_at("main", span)
                    .is_none(),
                "the rejected selector published a binder at {span:?}"
            );
        }
        assert!(
            tcx.elaborations
                .type_resolution_for("main", meta_occurrence.key(), 0)
                .is_none(),
            "the rejected selector published a type argument"
        );

        let (item_index, def) = find("unit_argument");
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
        let expected = InternedType::fresh(def.ret.clone());
        let error = match run_general_ordinary_value(&def.body, Some(&expected), &mut tcx) {
            Ok(_) => panic!("`identity()` must be Unit, not a residual function"),
            Err(error) => error,
        };
        assert!(
            error.diagnostic().message.contains("type mismatch")
                && error.diagnostic().message.contains("expected `N -> N`")
                && error.diagnostic().message.contains("found `.`"),
            "the outer function slot must reject the Unit-valued empty call: {error:?}"
        );
    }

    #[cfg(feature = "surface")]
    #[test]
    fn only_a_source_empty_packet_applies_an_instantiated_unit_domain() {
        assert_module_alias_does_not_capture_call_binder(
            "module main;
             host type N;
             type Unit_alias = .;
             fn identity[A](value: A) -> A { value }
             fn consume(_function: N -> N) -> . { () }
             fn consume_unit_product(_function: (. & .) -> .) -> . { () }
             host fn make[A]() -> A;
             fn product[A](value: A, tail: .) -> . { tail }
             fn direct() -> . { identity() }
             fn residual_argument() -> . { consume(identity(_)) }
             fn written_residual_argument() -> . { consume(identity(N)) }
             fn written_unit_argument() -> . -> . { identity(.) }
             fn written_unit_alias_argument() -> Unit_alias -> Unit_alias { identity(Unit_alias) }
             fn written_unit_domain() -> . -> N { make(N) }
             fn explicit_unit_domain() -> N { make(N, ()) }
             fn product_domain_remains_residual() -> . { consume_unit_product(product(.)) }",
            "empty Unit application controls",
        );

        let error = module_alias_call_binder_outcome(
            "module main;
             host type N;
             fn identity[A](value: A) -> A { value }
             fn consume(_function: N -> N) -> . { () }
             fn rejected() -> . { consume(identity()) }",
            "empty Unit application rejection",
        )
        .expect_err("an empty generic identity call must not be a residual function");
        assert_eq!(error, "type mismatch: expected `N -> N`, found `.`");

        let error = module_alias_call_binder_outcome(
            "module main;
             host type N;
             fn identity[A](value: A) -> A { value }
             fn consume(_function: N -> N) -> . { () }
             fn rejected() -> . { consume(identity) }",
            "bare polymorphic function rejection",
        )
        .expect_err("a bare polymorphic function must not enter a monomorphic slot");
        assert_eq!(
            error,
            "polymorphic value used in a monomorphic position; apply it with type arguments first"
        );
    }

