    #[cfg(feature = "surface")]
    #[test]
    fn tuple_direct_intrinsic_and_ordinary_pair_calls_share_exact_prime_types() {
        let module = parse(
            "module main;
             import __intrinsics__;
             host type N;
             fn identity[A](value: A) -> A { value }
             fn construct[Left][Right](left: Left, right: Right) -> Left & Right {
                 (left, right)
             }
             fn tuple_form(tail: N) -> ([A] A -> A) & N { (identity, tail) }
             fn intrinsic_form(tail: N) -> ([A] A -> A) & N {
                 __pair__(identity, tail)
             }
             fn ordinary_form(tail: N) -> ([A] A -> A) & N {
                 construct(identity, tail)
             }",
        )
        .expect("parse pair-call parity witnesses");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower pair-call parity witnesses");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let prime = FullPipeline::typecheck(&package)
            .expect("all product-construction spellings should typecheck through ordinary calls");

        for name in ["tuple_form", "intrinsic_form", "ordinary_form"] {
            let function = prime
                .module("main")
                .expect("Prime main module")
                .module
                .items
                .iter()
                .find_map(|item| match item {
                    Item::FnDef(def) if def.name == name => Some(def),
                    _ => None,
                })
                .unwrap_or_else(|| panic!("Prime `{name}` function"));
            let crate::ast::Expr::Call { args, .. } = &function.body else {
                panic!("Prime `{name}` body should remain an ordinary call")
            };
            let [
                crate::ast::CallArg::Type(left),
                crate::ast::CallArg::Type(right),
                crate::ast::CallArg::Value(_),
                crate::ast::CallArg::Value(_),
            ] = args.as_slice()
            else {
                panic!("Prime `{name}` call should materialize two exact type arguments")
            };
            assert!(
                matches!(left, crate::ast::Type::Forall { .. })
                    && !type_contains_goal(left)
                    && !type_contains_infer(left),
                "Prime `{name}` left type argument must be the exact polymorphic scheme: {left:?}"
            );
            assert!(
                matches!(right, crate::ast::Type::Path { segments, args, .. }
                    if segments.last().is_some_and(|segment| segment.as_str() == "N")
                        && args.is_empty())
                    && !type_contains_goal(right)
                    && !type_contains_infer(right),
                "Prime `{name}` right type argument must be exact and hole-free: {right:?}"
            );
        }
    }

    #[cfg(feature = "surface")]
    #[test]
    fn failed_later_sibling_does_not_publish_a_retained_nested_call() {
        let module = parse(
            "module main;
             host type I32;
             host type String;
             host fn make[A]() -> A;
             fn same3[T](_first: T, _second: T, _third: T) -> . { () }
             fn bad(bad_left: I32, bad_right: String) -> . {
                 same3(make(), bad_left, bad_right)
             }
             fn good(good_left: I32, good_right: I32) -> . {
                 same3(make(), good_left, good_right)
             }",
        )
        .expect("parse retained nested-call witness");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower retained nested-call witness");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let module = &package.module("main").expect("main module").module;
        let def = |name: &str| {
            module
                .items
                .iter()
                .enumerate()
                .find_map(|(index, item)| match item {
                    Item::FnDef(def) if def.name == name => Some((index, def)),
                    _ => None,
                })
                .unwrap_or_else(|| panic!("missing `{name}` witness function"))
        };
        let nested_call_spans = |body: &Expr| {
            let Expr::Call { args, .. } = body else {
                panic!("witness body should be an ordinary call")
            };
            let [
                CallArg::Value(Expr::Call {
                    occurrence: meta_occurrence,
                    callee,
                    meta,
                    ..
                }),
                CallArg::Value(Expr::Path {
                    segments: left_segments,
                    ..
                }),
                CallArg::Value(Expr::Path {
                    segments: right_segments,
                    ..
                }),
            ] = args.as_slice()
            else {
                panic!("witness should have one nested call and two path siblings")
            };
            let Expr::Path { segments, .. } = callee.as_ref() else {
                panic!("nested ordinary call should retain its path callee")
            };
            let [segment] = segments.as_slice() else {
                panic!("bounded nested ordinary call should have one callee segment")
            };
            let [left_segment] = left_segments.as_slice() else {
                panic!("left sibling should have one path segment")
            };
            let [right_segment] = right_segments.as_slice() else {
                panic!("right sibling should have one path segment")
            };
            (
                crate::ast::ExpressionSite {
                    id: meta_occurrence.key(),
                    span: meta.span,
                },
                segment.span,
                [left_segment.span, right_segment.span],
            )
        };
        let (bad_index, bad_def) = def("bad");
        let (good_index, good_def) = def("good");
        let bad = &bad_def.body;
        let good = &good_def.body;
        let (bad_nested_span, bad_callee_span, bad_sibling_spans) = nested_call_spans(bad);
        let (good_nested_span, good_callee_span, good_sibling_spans) = nested_call_spans(good);
        let [
            crate::ast::SignatureParam::Value(bad_left),
            crate::ast::SignatureParam::Value(bad_right),
        ] = bad_def.sig.params.as_slice()
        else {
            panic!("bad witness should have two typed siblings")
        };
        let [
            crate::ast::SignatureParam::Value(good_left),
            crate::ast::SignatureParam::Value(good_right),
        ] = good_def.sig.params.as_slice()
        else {
            panic!("good witness should have two typed siblings")
        };

        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("module environment");
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(bad_index);
        for param in [bad_left, bad_right] {
            tcx.push_value(
                param.name.clone(),
                param.ty.clone().expect("bad sibling annotation"),
            );
        }

        let error = match <crate::pass::typecheck_full::LoweredTyper as Typer<Lowered>>::synth_expr(
            bad, &mut tcx,
        ) {
            Ok(_) => panic!("the later String sibling should reject the I32 application"),
            Err(error) => error,
        };
        assert!(
            error.diagnostic().message.contains("type mismatch"),
            "unexpected diagnostic: {}",
            error.diagnostic().message
        );
        assert!(
            tcx.elaborations
                .type_resolution_for("main", bad_nested_span.id, 0)
                .is_none(),
            "a failed later sibling must not publish the retained child call"
        );
        for span in std::iter::once(bad_callee_span).chain(bad_sibling_spans) {
            assert!(
                tcx.elaborations
                    .position_index()
                    .binder_at("main", span)
                    .is_none(),
                "a failed later sibling must not publish any retained path binder"
            );
        }

        for param in [good_left, good_right] {
            tcx.push_value(
                param.name.clone(),
                param.ty.clone().expect("good sibling annotation"),
            );
        }
        tcx = tcx.at_item(good_index);
        let completed = <crate::pass::typecheck_full::LoweredTyper as Typer<Lowered>>::synth_expr(
            good, &mut tcx,
        )
        .expect("the failed sibling must leave the typer usable");
        assert!(matches!(completed.ty.as_type(), Type::Unit { .. }));
        assert!(
            tcx.elaborations
                .type_resolution_for("main", good_nested_span.id, 0)
                .is_some(),
            "the successful parent should publish the retained child call"
        );
        assert!(matches!(
            tcx.elaborations
                .position_index()
                .binder_at("main", good_callee_span),
            Some(crate::pass::typecheck_full::ResolvedBinder::HostEnvFn { name, .. })
                if name == "make"
        ));
        for (span, name) in good_sibling_spans
            .into_iter()
            .zip(["good_left", "good_right"])
        {
            assert!(matches!(
                tcx.elaborations.position_index().binder_at("main", span),
                Some(crate::pass::typecheck_full::ResolvedBinder::Local {
                    name: resolved,
                    ..
                }) if resolved == name
            ));
        }
    }

