    #[cfg(feature = "surface")]
    #[test]
    fn rejected_direct_pair_immediate_lambda_argument_does_not_publish_metadata() {
        let module = parse(
            "module main;
             host type I32;
             host type String;
             host type N;
             fn bad(left: I32, right: String, later: I32) -> N {
                 .(pair: I32 & String, tail: N) -> N { tail }((left, right), later)
             }",
        )
        .expect("parse direct-pair immediate-lambda witness");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower direct-pair immediate-lambda witness");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let module = &package.module("main").expect("main module").module;
        let (item_index, bad) = module
            .items
            .iter()
            .enumerate()
            .find_map(|(index, item)| match item {
                Item::FnDef(def) if def.name == "bad" => Some((index, def)),
                _ => None,
            })
            .expect("bad direct-pair witness");
        let Expr::Call {
            occurrence: _,
            callee,
            args,
            meta: call_meta,
            ..
        } = &bad.body
        else {
            panic!("bad witness should be one direct lambda call")
        };
        let Expr::FnExpr {
            occurrence: _,
            sig,
            body,
            meta: lambda_meta,
            ..
        } = callee.as_ref()
        else {
            panic!("bad witness callee should be one lambda")
        };
        let lambda_params = sig.value_params().collect::<Vec<_>>();
        assert_eq!(lambda_params.len(), 2);
        let Expr::Path {
            segments: body_segments,
            ..
        } = body.as_ref()
        else {
            panic!("bad lambda body should be one path")
        };
        let [body_path] = body_segments.as_slice() else {
            panic!("bad lambda body should contain one path segment")
        };
        let [
            CallArg::Value(Expr::Call {
                occurrence: pair_meta_occurrence,
                callee: pair_callee,
                args: pair_args,
                meta: pair_meta,
                ..
            }),
            CallArg::Value(Expr::Path {
                segments: later_segments,
                ..
            }),
        ] = args.as_slice()
        else {
            panic!("bad call should contain one direct pair followed by one path")
        };
        let [later_path] = later_segments.as_slice() else {
            panic!("later argument should contain one path segment")
        };

        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("module environment");
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
        for param in bad.sig.value_params() {
            tcx.push_value(
                param.name.clone(),
                param.ty.clone().expect("bad parameter annotation"),
            );
        }
        let Expr::Path {
            segments: pair_segments,
            ..
        } = pair_callee.as_ref()
        else {
            panic!("the first argument should call the lowered pair constructor")
        };
        assert_eq!(
            pair_segments.as_slice(),
            ["__pair__"],
            "the first argument should call the lowered pair constructor"
        );
        let mut pair_values = pair_args.iter().filter_map(|argument| match argument {
            CallArg::Value(value) => Some(value),
            CallArg::Type(_) => None,
        });
        let pair_left = pair_values
            .next()
            .expect("the lowered pair should contain a left value");
        let pair_right = pair_values
            .next()
            .expect("the lowered pair should contain a right value");
        assert!(
            pair_values.next().is_none(),
            "the lowered pair should contain exactly two values"
        );
        let error = match <crate::pass::typecheck_full::LoweredTyper as Typer<
            Lowered,
        >>::check_value_against_interned(
            &bad.body,
            &InternedType::fresh(bad.ret.clone()),
            &mut tcx,
        ) {
            Ok(_) => panic!("the later I32 argument must reject the expected nominal N"),
            Err(error) => error,
        };
        assert!(
            error.diagnostic().message.contains("type mismatch"),
            "unexpected diagnostic: {}",
            error.diagnostic().message
        );
        assert_eq!(
            error.diagnostic().span,
            later_path.span,
            "the direct pair must typecheck before the later argument fails"
        );

        let mut leaked = Vec::new();
        for slot in 0..2 {
            if tcx
                .elaborations
                .type_resolution_for("main", pair_meta_occurrence.key(), slot)
                .is_some()
            {
                leaked.push(format!("pair type-resolution slot {slot}"));
            }
        }
        for (label, span) in [
            ("pair left binder", pair_left.span()),
            ("pair right binder", pair_right.span()),
            ("lambda body binder", body_path.span),
            ("later argument binder", later_path.span),
        ] {
            if tcx
                .elaborations
                .position_index()
                .binder_at("main", span)
                .is_some()
            {
                leaked.push(label.to_owned());
            }
        }
        for (label, span) in [
            ("pair left type", pair_left.span()),
            ("pair right type", pair_right.span()),
            ("pair expression type", pair_meta.span),
            ("lambda type", lambda_meta.span),
            ("lambda body type", body_path.span),
            ("later argument type", later_path.span),
            ("call result type", call_meta.span),
        ] {
            if tcx
                .elaborations
                .position_index()
                .type_at("main", span)
                .is_some()
            {
                leaked.push(label.to_owned());
            }
        }
        for parameter in lambda_params {
            if tcx
                .elaborations
                .position_index()
                .local_decl_at("main", &parameter.name)
                .is_some()
            {
                leaked.push(format!("lambda local `{}`", parameter.name));
            }
        }
        assert!(
            leaked.is_empty(),
            "a rejected direct-pair immediate call published speculative metadata: {leaked:?}"
        );
    }

    #[cfg(feature = "surface")]
    #[test]
    fn product_packed_immediate_lambdas_round_trip_to_prime() {
        let module = parse(
            "module main;
             host type I32;
             host type String;
             host type N;
             type Suffix = String & N;
             fn distinct(first: I32, suffix: String & N) -> N {
                 .(kept, label: String, tail: _) -> N { tail }(first, suffix)
             }
             fn whole(domain: I32 & (String & N)) -> N {
                 .(kept: I32, label: String, tail: N) -> N { tail }(domain)
             }
             fn aliased(first: I32, suffix: Suffix) -> N {
                 .(kept, label: String, tail: _) -> N { tail }(first, suffix)
             }
             fn non_final_product_then_packed(
                 pair: I32 & I32,
                 suffix: String & N
             ) -> N {
                 .(whole: I32 & I32, label: String, tail: N) -> N { tail }(pair, suffix)
             }
             fn rank_n(packed: ([A] A -> A) & N) -> N {
                 .(function, tail: N) -> N { tail }(packed)
             }",
        )
        .expect("parse product-packed round-trip witnesses");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower product-packed round-trip witnesses");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let checked = crate::pass::typecheck_full::check_package_preserving_normalization(&package)
            .expect("product-packed immediate lambdas should typecheck");
        let prime =
            crate::pass::typecheck_full::validate_substituted_package(checked.substituted())
                .expect("product-packed immediate lambdas should pass standalone Prime");

        for function in ["distinct", "whole", "aliased"] {
            assert_prime_three_parameter_lambda(&prime, function, ["I32", "String", "N", "N"]);
        }

        let non_final = prime
            .module("main")
            .expect("Prime main module")
            .module
            .items
            .iter()
            .find_map(|item| match item {
                Item::FnDef(def) if def.name == "non_final_product_then_packed" => Some(def),
                _ => None,
            })
            .expect("Prime non-final-product function");
        let crate::ast::Expr::Call { callee, .. } = &non_final.body else {
            panic!("Prime non-final-product body should remain one immediate call")
        };
        let crate::ast::Expr::FnExpr { sig, .. } = callee.as_ref() else {
            panic!("Prime non-final-product callee should remain one lambda")
        };
        let [
            crate::ast::SignatureParam::Value(whole),
            crate::ast::SignatureParam::Value(label),
            crate::ast::SignatureParam::Value(tail),
        ] = sig.params.as_slice()
        else {
            panic!("Prime non-final-product lambda should retain three value parameters")
        };
        let whole_ty = whole.ty.as_ref().expect("whole product parameter type");
        let crate::ast::Type::Product { left, right, .. } = whole_ty else {
            panic!("the non-final product argument must fill one product-typed parameter")
        };
        for ty in [left.as_ref(), right.as_ref()] {
            assert!(
                matches!(
                    ty,
                    crate::ast::Type::Path { segments, args, .. }
                        if segments.last().is_some_and(|segment| segment.as_str() == "I32")
                            && args.is_empty()
                ),
                "the non-final product parameter must remain I32 & I32: {whole_ty:?}"
            );
        }
        for (ty, expected) in [
            (label.ty.as_ref().expect("label parameter type"), "String"),
            (tail.ty.as_ref().expect("tail parameter type"), "N"),
        ] {
            assert!(
                matches!(
                    ty,
                    crate::ast::Type::Path { segments, args, .. }
                        if segments.last().is_some_and(|segment| segment.as_str() == expected)
                            && args.is_empty()
                ),
                "the final packet must fill the scalar {expected} slot: {ty:?}"
            );
        }

        let rank_n = prime
            .module("main")
            .expect("Prime main module")
            .module
            .items
            .iter()
            .find_map(|item| match item {
                Item::FnDef(def) if def.name == "rank_n" => Some(def),
                _ => None,
            })
            .expect("Prime rank-N function");
        let crate::ast::Expr::Call { callee, .. } = &rank_n.body else {
            panic!("Prime rank-N body should remain one immediate call")
        };
        let crate::ast::Expr::FnExpr { sig, ret_ty, .. } = callee.as_ref() else {
            panic!("Prime rank-N callee should remain one lambda")
        };
        let [
            crate::ast::SignatureParam::Value(function),
            crate::ast::SignatureParam::Value(tail),
        ] = sig.params.as_slice()
        else {
            panic!("Prime rank-N lambda should retain two value parameters")
        };
        let function_ty = function
            .ty
            .as_ref()
            .expect("packed rank-N parameter should gain its exact annotation");
        assert!(
            matches!(function_ty, crate::ast::Type::Forall { .. })
                && !type_contains_goal(function_ty)
                && !type_contains_infer(function_ty),
            "the packed first slot must retain its written rank-N type: {function_ty:?}"
        );
        for ty in [
            tail.ty.as_ref().expect("concrete tail type"),
            ret_ty.as_ref().expect("concrete lambda result"),
        ] {
            assert!(
                matches!(
                    ty,
                    crate::ast::Type::Path { segments, args, .. }
                        if segments.last().is_some_and(|segment| segment.as_str() == "N")
                            && args.is_empty()
                ) && !type_contains_goal(ty)
                    && !type_contains_infer(ty),
                "the rank-N lambda tail and result must remain N: {ty:?}"
            );
        }
    }

