    #[cfg(feature = "surface")]
    #[test]
    fn direct_pair_lambda_bodies_round_trip_to_prime() {
        let module =
            parse(DIRECT_PAIR_LAMBDA_BODY_SOURCE).expect("parse direct-pair lambda-body witnesses");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower direct-pair lambda-body witnesses");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let checked = crate::pass::typecheck_full::check_package_preserving_normalization(&package)
            .expect("direct-pair lambda bodies should typecheck");
        let prime =
            crate::pass::typecheck_full::validate_substituted_package(checked.substituted())
                .expect("direct-pair lambda bodies should pass standalone Prime");

        let function = |name: &str| {
            prime
                .module("main")
                .expect("Prime main module")
                .module
                .items
                .iter()
                .find_map(|item| match item {
                    Item::FnDef(def) if def.name == name => Some(def),
                    _ => None,
                })
                .unwrap_or_else(|| panic!("Prime `{name}` function"))
        };
        let lambda = |name: &str| {
            let crate::ast::Expr::Call { callee, .. } = &function(name).body else {
                panic!("Prime `{name}` body should remain one immediate call")
            };
            let crate::ast::Expr::FnExpr { sig, ret_ty, .. } = callee.as_ref() else {
                panic!("Prime `{name}` callee should remain one lambda")
            };
            (sig, ret_ty)
        };

        let (rank_sig, rank_ret) = lambda("rank_n_round_trip");
        let [
            crate::ast::SignatureParam::Value(rank_function),
            crate::ast::SignatureParam::Value(done),
        ] = rank_sig.params.as_slice()
        else {
            panic!("Prime rank-N lambda should retain two value parameters")
        };
        let function_ty = rank_function
            .ty
            .as_ref()
            .expect("rank-N parameter annotation");
        assert!(
            matches!(function_ty, crate::ast::Type::Forall { .. })
                && !type_contains_goal(function_ty)
                && !type_contains_infer(function_ty),
            "the pair body's first slot must retain its structural rank-N type: {function_ty:?}"
        );
        let done_ty = done.ty.as_ref().expect("rank-N tail annotation");
        assert!(
            matches!(
                done_ty,
                crate::ast::Type::Path { segments, args, .. }
                    if segments.last().is_some_and(|segment| segment.as_str() == "N")
                        && args.is_empty()
            ) && !type_contains_goal(done_ty)
                && !type_contains_infer(done_ty),
            "the pair body's scalar tail must remain N: {done_ty:?}"
        );
        assert!(
            rank_ret.is_none(),
            "an inferred lambda return must not materialize a source annotation in Prime"
        );

        let (_, alias_ret) = lambda("alias_expected");
        assert!(
            matches!(
                alias_ret.as_ref(),
                Some(crate::ast::Type::Path { segments, args, .. })
                    if segments.last().is_some_and(|segment| segment.as_str() == "Scalar_packet")
                        && args.is_empty()
            ),
            "the written expected alias should survive into Prime: {alias_ret:?}"
        );

        for (name, parameter_count) in
            [("final_suffix", 3), ("non_final_pair", 2), ("unit_leaf", 1)]
        {
            let (sig, ret_ty) = lambda(name);
            assert_eq!(
                sig.value_param_count(),
                parameter_count,
                "`{name}` must retain its source parameter shape"
            );
            assert!(
                ret_ty.is_none(),
                "Prime `{name}` must preserve the absent source return annotation"
            );
            assert!(
                sig.value_params().all(|parameter| parameter
                    .ty
                    .as_ref()
                    .is_some_and(|ty| !type_contains_goal(ty) && !type_contains_infer(ty))),
                "Prime `{name}` parameters must contain neither goals nor `_`: {sig:?}"
            );
        }

        let nested = function("nested_consumer");
        let crate::ast::Expr::Call { args, .. } = &nested.body else {
            panic!("Prime nested consumer should remain one ordinary call")
        };
        assert!(
            args.iter().any(|arg| matches!(
                arg,
                crate::ast::CallArg::Value(crate::ast::Expr::FnExpr { .. })
            )),
            "the nested consumer must retain its inferred pair-body lambda"
        );
    }

