    #[cfg(feature = "surface")]
    #[test]
    fn immediate_lambda_concrete_return_preserves_nominal_identity() {
        let module = parse(
            "module main;
             host type N;
             fn keep(value: N) -> N {
                 .(item) -> N { item }(value)
             }",
        )
        .expect("parse immediate nominal-return witness");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower immediate nominal-return witness");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let checked = crate::pass::typecheck_full::check_package_preserving_normalization(&package)
            .expect("a source-context nominal return should typecheck");
        let prime =
            crate::pass::typecheck_full::validate_substituted_package(checked.substituted())
                .expect("the nominal-return lambda should pass standalone Prime");
        let keep = prime
            .module("main")
            .expect("Prime main module")
            .module
            .items
            .iter()
            .find_map(|item| match item {
                Item::FnDef(def) if def.name == "keep" => Some(def),
                _ => None,
            })
            .expect("Prime nominal-return function");
        let crate::ast::Expr::Call { callee, .. } = &keep.body else {
            panic!("Prime nominal-return body should remain one immediate call")
        };
        let crate::ast::Expr::FnExpr { sig, ret_ty, .. } = callee.as_ref() else {
            panic!("Prime nominal-return callee should remain one lambda")
        };
        let [crate::ast::SignatureParam::Value(parameter)] = sig.params.as_slice() else {
            panic!("Prime nominal-return lambda should retain one value parameter")
        };
        for ty in [
            parameter.ty.as_ref().expect("inferred parameter type"),
            ret_ty.as_ref().expect("concrete return annotation"),
        ] {
            assert!(
                matches!(
                    ty,
                    crate::ast::Type::Path { segments, args, .. }
                        if segments.last().is_some_and(|segment| segment.as_str() == "N")
                            && args.is_empty()
                ),
                "the Prime lambda must retain nominal type N: {ty:?}"
            );
            assert!(
                !type_contains_goal(ty) && !type_contains_infer(ty),
                "the Prime nominal type must contain neither goals nor `_`"
            );
        }
    }

