    #[test]
    fn application_holes_reject_cycles_and_chase_acyclic_solutions() {
        let param = |name: &str| crate::ast::TypeParam {
            name: name.to_owned(),
            span: sp(),
            kind: None,
        };
        let mut holes = ApplicationHoleState::<Lowered> {
            params: vec![param("\0expected0"), param("\0expected1")],
            subst: HashMap::from([
                ("\0expected0".into(), path_ty("\0expected1")),
                ("\0expected1".into(), path_ty("\0expected0")),
            ]),
        };
        assert_eq!(holes.unresolved_names().len(), 2);

        holes
            .subst
            .insert("\0expected1".into(), path_ty("Concrete"));
        assert_eq!(holes.solution("\0expected0"), Some(path_ty("Concrete")));
    }

    #[test]
    fn application_holes_discard_reflexive_non_solutions() {
        let name = "\0expected0";
        let mut holes = ApplicationHoleState::<Lowered> {
            params: vec![crate::ast::TypeParam {
                name: name.to_owned(),
                span: sp(),
                kind: None,
            }],
            subst: HashMap::from([(name.to_owned(), path_ty(name))]),
        };

        holes.normalize_solutions();

        assert!(
            !holes.subst.contains_key(name),
            "a reflexive private-hole equation is not a solution"
        );
    }

    #[cfg(feature = "surface")]
    #[test]
    fn written_nominal_type_arguments_publish_only_after_ordinary_root_close() {
        for (label, binders, value_type, body, result_type, succeeds, owner) in [
            (
                "path/unit",
                "",
                "Token",
                "identity(Token, value)",
                "Token",
                true,
                Some("main"),
            ),
            (
                "general",
                "",
                "Token",
                "identity(Token, Token.mk(()))",
                "Token",
                true,
                Some("main"),
            ),
            (
                "qualified",
                "",
                "p.Token",
                "identity(p.Token, value)",
                "p.Token",
                true,
                Some("aux"),
            ),
            (
                "caller binder",
                "[Token]",
                "Token",
                "identity(Token, value)",
                "Token",
                true,
                None,
            ),
            (
                "later sibling",
                "",
                "Token",
                "choose(Token, value, ())",
                "Token",
                false,
                None,
            ),
            (
                "nested child before failing sibling",
                "",
                "Token",
                "choose(Token, identity(Token, value), ())",
                "Token",
                false,
                None,
            ),
            (
                "result",
                "",
                "Token",
                "identity(Token, value)",
                ".",
                false,
                None,
            ),
            (
                "wrong kind",
                "",
                "Token",
                "higher(Token, ())",
                ".",
                false,
                None,
            ),
        ] {
            let source = format!(
                "module main;
                 import aux as p;
                 newtype Token : . {{ constructor mk; projector get; }};
                 fn identity[A](value: A) -> A {{ value }}
                 fn choose[A](left: A, _right: A) -> A {{ left }}
                 fn higher[*F](_value: .) -> . {{ () }}
                 fn witness{binders}(value: {value_type}) -> {result_type} {{ {body} }}"
            );
            let (modules, _) = FullPipeline::lower_package(
                vec![
                    (PathBuf::from("main.kio"), parse(&source).expect("main source")),
                    (PathBuf::from("aux.kio"), parse(
                        "module aux; pub newtype Token : . { pub constructor mk; pub projector get; };"
                    ).expect("nominal provider")),
                ],
                None,
            ).expect("lower publication witness");
            let package = Package::build(Path::new(""), modules, None).expect("build package");
            package
                .resolve_imports()
                .expect("resolve qualified provider");
            let package = crate::pass::alpha_normalize::normalize_package(&package)
                .into_parts()
                .0;
            let module = &package.module("main").expect("main module").module;
            let (index, definition) = module
                .items
                .iter()
                .enumerate()
                .find_map(|(index, item)| match item {
                    Item::FnDef(definition) if definition.name == "witness" => {
                        Some((index, definition))
                    }
                    _ => None,
                })
                .expect("witness declaration");
            let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
                .expect("caller environment");
            let mut elaborations = Elaborations::new();
            let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(index);
            for parameter in &definition.sig.params {
                match parameter {
                    crate::ast::SignatureParam::Type(parameter) => tcx.push_type_param_kinded(
                        &parameter.name,
                        parameter.effective_kind(),
                        parameter.span,
                    ),
                    crate::ast::SignatureParam::Value(parameter) => tcx.push_value(
                        parameter.name.clone(),
                        parameter.ty.clone().expect("written value type"),
                    ),
                }
            }
            let offset = source.rfind(body).expect("body source")
                + body.find("Token").expect("written type argument");
            let span = Span::new(offset as u32, offset as u32 + 5);
            assert!(
                tcx.elaborations
                    .position_index()
                    .binder_at("main", span)
                    .is_none()
            );
            let result = OrdinaryValueCursor::run_root(
                &definition.body,
                Some(&InternedType::fresh(definition.ret.clone())),
                &mut tcx,
            );
            assert_eq!(
                result.is_ok(),
                succeeds,
                "{label}: {:?}",
                result.as_ref().err()
            );
            if !succeeds {
                let body_offset = source.rfind(body).expect("body source");
                for (offset, _) in body.match_indices("Token") {
                    let start = (body_offset + offset) as u32;
                    let recorded = tcx
                        .elaborations
                        .position_index()
                        .binder_at("main", Span::new(start, start + 5));
                    assert!(
                        recorded.is_none(),
                        "{label} retained {recorded:?} at {start}"
                    );
                }
                continue;
            }
            let recorded = tcx.elaborations.position_index().binder_at("main", span);
            match owner {
                Some(owner) => assert!(
                    matches!(
                        recorded,
                        Some(crate::pass::typecheck_full::ResolvedBinder::Newtype { module_path, name })
                            if module_path == owner && name == "Token"
                    ),
                    "{label}: {recorded:?}"
                ),
                None => assert!(
                    !matches!(
                        recorded,
                        Some(crate::pass::typecheck_full::ResolvedBinder::Newtype { .. })
                    ),
                    "{label} published a nominal reference: {recorded:?}"
                ),
            }
        }
    }

    #[cfg(feature = "surface")]
    #[test]
    fn written_nominal_type_arguments_publish_on_legacy_completion_routes() {
        let package = resolved_lowered_test_package(
            "module main; newtype Token : . { constructor mk; projector get; };",
        );
        let module = &package.module("main").expect("main module").module;
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("legacy publication environment");
        let span = Span::new(100, 105);
        let written = Type::synth_path(vec!["Token".to_owned()], Vec::new(), span);
        let binder = crate::ast::TypeParam {
            name: "A".to_owned(),
            span: sp(),
            kind: None,
        };
        for non_function in [false, true] {
            let mut elaborations = Elaborations::new();
            let mut tcx = TypeCtx::new(&env, &mut elaborations);
            assert!(
                tcx.elaborations
                    .position_index()
                    .binder_at("main", span)
                    .is_none()
            );
            if non_function {
                apply_polymorphic_non_function(
                    std::slice::from_ref(&binder),
                    &path_ty("A"),
                    &[CallArgRef::Type(&written)],
                    fresh_site(span),
                    Some(0),
                    false,
                    &mut tcx,
                )
                .expect("successful polymorphic non-function type application");
            } else {
                let plan = PlannedApplication::empty_layer(
                    vec![binder.clone()],
                    vec![CallArgRef::Type(&written)],
                    InternedType::fresh(path_ty("A")),
                    false,
                    PlannedApplicationCompletion::Explicit,
                );
                plan.record_type_arguments(
                    &HashMap::from([("A".to_owned(), written.clone())]),
                    sp(),
                    fresh_site(span),
                    0,
                    &mut tcx,
                )
                .expect("successful legacy argument metadata publication");
            }
            assert!(
                matches!(
                    tcx.elaborations.position_index().binder_at("main", span),
                    Some(crate::pass::typecheck_full::ResolvedBinder::Newtype { module_path, name })
                        if module_path == "main" && name == "Token"
                ),
                "non-function route: {non_function}"
            );
        }
    }

