    fn product(left: Type, right: Type) -> Type {
        Type::Product {
            left: Box::new(left),
            right: Box::new(right),
            meta: Meta::new(sp()),
        }
    }

    fn func(params: Vec<Type>, ret: Type) -> Type {
        Type::synth_function(params, ret, sp())
    }

    fn func_with_abi(param: Type, ret: Type, abi_arity: usize) -> Type {
        Type::Function {
            param: Box::new(param),
            ret: Box::new(ret),
            meta: Meta::new(sp()),
            abi_arity,
            caps: (),
        }
    }

    fn forall(binders: &[&str], body: Type) -> Type {
        binders.iter().rev().fold(body, |acc, name| Type::Forall {
            param: crate::ast::TypeParam {
                name: (*name).to_owned(),
                span: sp(),
                kind: None,
            },
            body: Box::new(acc),
            meta: Meta::new(sp()),
        })
    }

    /// Build an `Expr::FnExpr` with the given value-params and a
    /// unit-returning unit body. The expression's shape is what the
    /// predicates under test inspect; the body never executes.
    fn fn_expr(params: Vec<crate::ast::SignatureParam<Lowered>>) -> Expr {
        Expr::FnExpr {
            occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
            sig: crate::ast::Signature::new(params),
            ret_ty: None,
            body: Box::new(Expr::Unit {
                occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
                meta: Meta::new(sp()),
            }),
            meta: Meta::new(sp()),
            caps: (),
        }
    }

    fn vp_annotated(name: &str, ty: Type) -> crate::ast::SignatureParam<Lowered> {
        crate::ast::SignatureParam::Value(crate::ast::Param {
            name: name.to_owned(),
            ty: Some(ty),
            pattern: Default::default(),
            meta: Meta::new(sp()),
        })
    }

    fn empty_alias_ctx<'a, 'm>() -> AliasCtx<'a, 'm, Lowered> {
        // Leaks two empty HashMaps for the lifetime of the test. The
        // unifier consumes only references; the leaked memory is
        // bounded per-test and dwarfed by other test fixtures.
        let local = Box::leak(Box::new(HashMap::new()));
        let cross = Box::leak(Box::new(HashMap::new()));
        AliasCtx {
            local,
            cross_module: cross,
            type_interner: None,
            source_module: None,
            package: None,
            binder_locals: None,
        }
    }

    #[cfg(feature = "surface")]
    #[test]
    fn diagnostic_carrier_retains_whole_written_packet_and_drops_opaque_slices() {
        let solver = InternedType::fresh_canonical(product(path_ty("I32"), path_ty("String")));
        let written = InternedType::fresh_canonical(path_ty("Packet"));
        let aliases = empty_alias_ctx();

        let whole = ExpectedValuePacket {
            solver: solver.clone(),
            written: Some(written.clone()),
        }
        .take_arg(true, &aliases)
        .expect("the whole packet is one admitted source value");
        assert_eq!(display_type(whole.solver.as_type()), "(I32 & String)");
        assert_eq!(
            display_type(
                whole
                    .written
                    .as_ref()
                    .expect("whole selection retains its written alias")
                    .as_type()
            ),
            "Packet"
        );

        let mut partial = ExpectedValuePacket {
            solver,
            written: Some(written),
        };
        let first = partial
            .take_arg(false, &aliases)
            .expect("the canonical product exposes its first slot");
        assert_eq!(display_type(first.solver.as_type()), "I32");
        assert!(
            first.written.is_none() && partial.written.is_none(),
            "a whole-alias spelling must not be reused for either strict slice"
        );
    }

