    fn higher_kinded_value_types_require_saturated_structural_leaves() {
        assert_module_alias_does_not_capture_call_binder(
            "module main;
             newtype Monad[*F] : . { constructor mk_monad; projector un_monad; };
             fn product[*F][*G][A](value: F(A) & G(A)) -> F(A) & G(A) { value }
             fn sum[*F][*G][A](value: F(A) | G(A)) -> F(A) | G(A) { value }
             fn dictionary[*F](value: Monad(F)) -> Monad(F) { value }",
            "saturated higher-kinded product and sum",
        );

        for (case, ty) in [
            ("bare higher-kinded value", "F"),
            ("bare higher-kinded product members", "F & G"),
            ("bare higher-kinded sum members", "F | G"),
        ] {
            let source = format!(
                "module main;
                 fn invalid[*F][*G](value: {ty}) -> {ty} {{ value }}"
            );
            let error = module_alias_call_binder_outcome(&source, case)
                .expect_err("an unsaturated higher-kinded value type must be rejected");
            assert!(
                error.contains("value type requires kind `*`"),
                "unexpected {case} diagnostic: {error}"
            );
        }
    }

