    #[cfg(feature = "surface")]
    #[test]
    fn empty_inner_polymorphic_call_rejects_before_outer_value_and_publication() {
        let module = parse(
            "module main;
             host type I32;
             host fn arbitrary[A]() -> A;
             fn witness(value: I32) -> I32 { arbitrary()(value) }",
        )
        .expect("parse empty-inner-call boundary witness");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower empty-inner-call boundary witness");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let module = &package.module("main").expect("main module").module;
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("module environment");
        let (item_index, def) = module
            .items
            .iter()
            .enumerate()
            .find_map(|(index, item)| match item {
                Item::FnDef(def) if def.name == "witness" => Some((index, def)),
                _ => None,
            })
            .expect("empty-inner-call witness function");
        let Expr::Call {
            occurrence: meta_occurrence,
            callee,
            args,
            meta,
            ..
        } = &def.body
        else {
            panic!("empty-inner-call witness must contain an outer call")
        };
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
        for parameter in def.sig.value_params() {
            tcx.push_value(
                parameter.name.clone(),
                parameter.ty.clone().expect("value parameter annotation"),
            );
        }
        let selected = select_path_unit_call_chain(
            callee,
            args,
            crate::ast::ExpressionSite {
                id: meta_occurrence.key(),
                span: meta.span,
            },
            &tcx,
        )
        .expect("the empty-inner-call witness must select two syntactic layers");
        assert_eq!(selected.layers.len(), 2);
        let inner_call_span = selected.layers[0].call_site;
        let call_spans = selected
            .layers
            .iter()
            .map(|layer| layer.call_site)
            .collect::<Vec<_>>();
        let staged_spans = std::iter::once(selected.direct_callee.span())
            .chain(selected.layers.iter().flat_map(|layer| {
                std::iter::once(layer.call_site.span)
                    .chain(layer.args.iter().map(|arg| arg.meta().span))
            }))
            .collect::<Vec<_>>();
        let error = match <crate::pass::typecheck_full::LoweredTyper as Typer<Lowered>>::synth_expr(
            &def.body, &mut tcx,
        ) {
            Err(error) => error,
            Ok(_) => panic!("an outer value must not solve the empty inner call's type goal"),
        };
        assert!(
            error
                .diagnostic()
                .message
                .contains("cannot infer type argument `A`"),
            "unexpected empty-inner-call diagnostic: {}",
            error.diagnostic().message
        );
        assert_eq!(
            error.diagnostic().span,
            inner_call_span.span,
            "the inner empty call must fail before the outer value is considered"
        );
        for span in staged_spans {
            assert!(
                tcx.elaborations
                    .position_index()
                    .type_at("main", span)
                    .is_none(),
                "rejected empty inner call published a type at {span:?}"
            );
            assert!(
                tcx.elaborations
                    .position_index()
                    .binder_at("main", span)
                    .is_none(),
                "rejected empty inner call published a binder at {span:?}"
            );
        }
        for span in call_spans {
            for slot in 0..=2 {
                assert!(
                    tcx.elaborations
                        .type_resolution_for("main", span.id, slot)
                        .is_none(),
                    "rejected empty inner call published inferred type slot {slot}"
                );
            }
        }
    }

    #[cfg(feature = "surface")]
    #[test]
    fn dynamic_successor_reports_structural_errors_without_panicking() {
        let module = parse(
            "module main;
             host type Tag;
             host type I32;
             fn hold[A](value: A) -> Tag -> A { .(_tag: Tag) { value } }
             fn unary(value: I32) -> I32 { value }
             host fn returned(tag: Tag) -> [B] B;
             fn bad_non_function(tag: Tag, value: I32) -> . { hold(value)(tag)(tag) }
             fn bad_arity(tag: Tag, left: I32, right: I32) -> . {
               hold(unary)(tag)(left, right)
             }
             fn bad_poly_value(tag: Tag, value: I32) -> . {
               hold(returned)(tag)(tag)(value)
             }
             fn bad_poly_arity(tag: Tag, left: I32, right: I32) -> . {
               hold(returned)(tag)(tag)(left, right)
             }",
        )
        .expect("parse dynamic structural-error witnesses");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower dynamic structural-error witnesses");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let module = &package.module("main").expect("main module").module;
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("module environment");
        for (name, expected, expected_span_kind) in [
            (
                "bad_non_function",
                "this is applied like a function, but its type is `I32`",
                "callee",
            ),
            (
                "bad_arity",
                "this is applied like a function, but its type is `I32`",
                "call",
            ),
            (
                "bad_poly_value",
                "expected a type argument here, got a value argument",
                "value",
            ),
            (
                "bad_poly_arity",
                "callee is a polymorphic non-function type; only type arguments are accepted here",
                "call",
            ),
        ] {
            let (item_index, def) = module
                .items
                .iter()
                .enumerate()
                .find_map(|(index, item)| match item {
                    Item::FnDef(def) if def.name == name => Some((index, def)),
                    _ => None,
                })
                .unwrap_or_else(|| panic!("missing dynamic `{name}` witness"));
            let mut elaborations = Elaborations::new();
            let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
            for param in def.sig.value_params() {
                tcx.push_value(
                    param.name.clone(),
                    param.ty.clone().expect("value parameter annotation"),
                );
            }
            let Expr::Call {
                occurrence: meta_occurrence,
                callee,
                args,
                meta,
                ..
            } = &def.body
            else {
                panic!("dynamic `{name}` witness must contain an outer call")
            };
            let selected = select_path_unit_call_chain(
                callee,
                args,
                crate::ast::ExpressionSite {
                    id: meta_occurrence.key(),
                    span: meta.span,
                },
                &tcx,
            )
            .unwrap_or_else(|| panic!("dynamic `{name}` must select the unified route"));
            let final_layer = selected.layers.last().expect("one final dynamic layer");
            let expected_span = match expected_span_kind {
                "callee" => final_layer.callee_span,
                "call" => final_layer.call_site.span,
                "value" => {
                    final_layer
                        .args
                        .first()
                        .expect("one offending final value")
                        .meta()
                        .span
                }
                _ => unreachable!("unknown dynamic diagnostic span kind"),
            };
            let call_spans = selected
                .layers
                .iter()
                .map(|layer| layer.call_site)
                .collect::<Vec<_>>();
            let staged_spans = std::iter::once(selected.direct_callee.span())
                .chain(selected.layers.iter().flat_map(|layer| {
                    std::iter::once(layer.call_site.span)
                        .chain(layer.args.iter().map(|arg| arg.meta().span))
                }))
                .collect::<Vec<_>>();
            let error =
                match <crate::pass::typecheck_full::LoweredTyper as Typer<Lowered>>::synth_expr(
                    &def.body, &mut tcx,
                ) {
                    Err(error) => error,
                    Ok(_) => panic!("dynamic `{name}` must be rejected"),
                };
            assert_eq!(
                error.diagnostic().message,
                expected,
                "unexpected `{name}` diagnostic"
            );
            assert_eq!(
                error.diagnostic().span,
                expected_span,
                "unexpected `{name}` diagnostic span"
            );
            for span in staged_spans {
                assert!(
                    tcx.elaborations
                        .position_index()
                        .type_at("main", span)
                        .is_none(),
                    "rejected dynamic `{name}` must not publish a type at {span:?}"
                );
                assert!(
                    tcx.elaborations
                        .position_index()
                        .binder_at("main", span)
                        .is_none(),
                    "rejected dynamic `{name}` must not publish a binder at {span:?}"
                );
            }
            for span in call_spans {
                for slot in 0..=4 {
                    assert!(
                        tcx.elaborations
                            .type_resolution_for("main", span.id, slot)
                            .is_none(),
                        "rejected dynamic `{name}` must not publish inferred type slot {slot}"
                    );
                }
            }
        }
    }

