    #[cfg(feature = "surface")]
    #[test]
    fn retained_rank_n_layer_rejects_late_outer_mismatch_without_publication() {
        let module = parse(
            "module main;
             host type I32;
             host type String;
             fn poly_id[A](value: A) -> A { value }
             host fn carry[F][T](function: F, first: T) -> T -> I32;
             fn witness(first: I32, wrong: String) -> I32 {
                 carry(poly_id, first)(wrong)
             }",
        )
        .expect("parse rank-N rollback witness");
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .expect("lower rank-N rollback witness");
        let package =
            Package::build(Path::new(""), modules, None).expect("build resolved package shell");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let module = &package.module("main").expect("main module").module;
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .expect("module environment");
        let (item_index, def) = module
            .items
            .iter()
            .enumerate()
            .find_map(|(index, item)| match item {
                Item::FnDef(def) if def.name == "witness" => Some((index, def)),
                _ => None,
            })
            .expect("rank-N rollback witness function");
        let Expr::Call {
            occurrence: meta_occurrence,
            callee,
            args,
            meta,
            ..
        } = &def.body
        else {
            panic!("rank-N rollback witness must contain an outer call")
        };
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
        for parameter in def.sig.value_params() {
            tcx.push_value(
                parameter.name.clone(),
                parameter.ty.clone().expect("value parameter annotation"),
            );
        }
        let selected = select_path_unit_call_chain(
            callee,
            args,
            crate::ast::ExpressionSite {
                id: meta_occurrence.key(),
                span: meta.span,
            },
            &tcx,
        )
        .expect("rank-N rollback witness must select two ordinary layers");
        let first_call_span = selected.layers[0].call_site;
        let first_value_spans = selected.layers[0]
            .args
            .iter()
            .filter_map(|arg| match arg {
                CallArg::Value(value) => Some(value.span()),
                CallArg::Type(_) => None,
            })
            .collect::<Vec<_>>();
        let CallArg::Value(wrong) = &selected.layers[1].args[0] else {
            panic!("outer rank-N rollback layer must pass one wrong value")
        };
        let wrong_span = wrong.span();
        let error = match run_general_ordinary_value(
            &def.body,
            Some(&InternedType::fresh(def.ret.clone())),
            &mut tcx,
        ) {
            Err(error) => error,
            Ok(_) => panic!("the outer String value must reject the inferred I32 layer"),
        };
        assert!(
            error.diagnostic().message.contains("type mismatch"),
            "unexpected retained rank-N diagnostic: {}",
            error.diagnostic().message
        );
        assert_eq!(error.diagnostic().span, wrong_span);
        assert!(
            tcx.elaborations
                .type_resolution_for("main", first_call_span.id, 0)
                .is_none(),
            "the rejected outer sibling must not publish the inferred polytype solution"
        );
        for span in first_value_spans.into_iter().chain([wrong_span]) {
            assert!(
                tcx.elaborations
                    .position_index()
                    .type_at("main", span)
                    .is_none(),
                "the rejected outer sibling must not publish a value type at {span:?}"
            );
            assert!(
                tcx.elaborations
                    .position_index()
                    .binder_at("main", span)
                    .is_none(),
                "the rejected outer sibling must not publish a value binder at {span:?}"
            );
        }
        assert!(
            tcx.elaborations
                .position_index()
                .type_at("main", first_call_span.span)
                .is_none(),
            "the rejected outer sibling must not publish the inner layer result"
        );
    }

