    #[cfg(feature = "surface")]
    fn assert_unresolved_retained_abstraction(source: &str, case: &str) {
        let module = parse(source)
            .unwrap_or_else(|error| panic!("parse {case} unresolved witness: {error:?}"));
        let (modules, _) =
            FullPipeline::lower_package(vec![(PathBuf::from("main.kio"), module)], None)
                .unwrap_or_else(|error| panic!("lower {case} unresolved witness: {error:?}"));
        let package = Package::build(Path::new(""), modules, None)
            .unwrap_or_else(|error| panic!("build {case} package: {error:?}"));
        package
            .resolve_imports()
            .unwrap_or_else(|error| panic!("resolve {case} uses: {error:?}"));
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let module = &package.module("main").expect("main module").module;
        let env = super::super::ModuleEnv::build(module, None, None, Some(&package))
            .unwrap_or_else(|error| panic!("build {case} module environment: {error:?}"));
        let (item_index, def) = module
            .items
            .iter()
            .enumerate()
            .find_map(|(index, item)| match item {
                Item::FnDef(def) if def.name == "witness" => Some((index, def)),
                _ => None,
            })
            .unwrap_or_else(|| panic!("missing {case} unresolved witness function"));
        let Expr::Call {
            occurrence: meta_occurrence,
            callee,
            args,
            meta,
            ..
        } = &def.body
        else {
            panic!("{case} unresolved witness must contain an outer call")
        };
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
        for parameter in def.sig.value_params() {
            tcx.push_value(
                parameter.name.clone(),
                parameter.ty.clone().expect("value parameter annotation"),
            );
        }
        let selected = select_path_unit_call_chain(
            callee,
            args,
            crate::ast::ExpressionSite {
                id: meta_occurrence.key(),
                span: meta.span,
            },
            &tcx,
        )
        .unwrap_or_else(|| panic!("the {case} witness must expose two written layers"));
        let call_spans = selected
            .layers
            .iter()
            .map(|layer| layer.call_site)
            .collect::<Vec<_>>();
        let value_spans = selected
            .layers
            .iter()
            .flat_map(|layer| layer.args)
            .filter_map(|arg| match arg {
                CallArg::Value(value) => Some(value.span()),
                CallArg::Type(_) => None,
            })
            .collect::<Vec<_>>();
        let error = match OrdinaryValueCursor::run_root(&def.body, None, &mut tcx) {
            Err(error) => error,
            Ok(_) => panic!("unresolved retained abstraction must be rejected"),
        };
        assert!(
            error.diagnostic().message.contains("cannot infer"),
            "unexpected {case} diagnostic: {}",
            error.diagnostic().message
        );
        for span in call_spans
            .into_iter()
            .map(|site| site.span)
            .chain(value_spans)
        {
            assert!(
                tcx.elaborations
                    .position_index()
                    .type_at("main", span)
                    .is_none(),
                "an unresolved {case} chain published a type at {span:?}"
            );
        }
    }

